/**
 * Furina Agent Web - 前端交互逻辑
 */

// ============= 全局常量 =============

const CONFIG = {
    TTS_MAX_CHARS: 5000,
    TTS_TIMEOUT: 180000,
    WS_RECONNECT_DELAY: 3000,
    WS_MAX_RETRIES: 10,
    SCROLL_THRESHOLD: 100,
    NOTIFICATION_DURATION: 3000,
    TTS_DEFAULT_SPEED: 1.0,
    TTS_DEFAULT_LANG: 'zh',
    FETCH_TIMEOUT: 30000,
};

// ============= 全局变量 =============

let ws = null;
let isConnected = false;
let currentAiMessage = null;
let ttsEnabled = true;
let _currentAgentMessage = null;  // 当前流式输出的 Agent 消息元素
let _agentAbortController = null; // 当前 Agent 流的终止控制器

// ============= 初始化 =============

document.addEventListener('DOMContentLoaded', () => {
    try {
        // 防止主内容区域意外触发窗口拖动（frameless 窗口兼容）
        initDragPrevention();
        initWebSocket();
        initEventListeners();
        loadSettings();
        loadLlmPresets();
        loadAgentToolScenarios();
        // 会话抽屉：保存欢迎语模板（空会话时恢复），绑定列表事件
        _captureWelcome();
        _initSessionListEvents();
        loadSessions();
        // 聊天页外壳：更多菜单、空白态、侧栏收起偏好
        try {
            if (localStorage.getItem('chatSidebarCollapsed') === '1') toggleSessionDrawer(false);
        } catch (e) {}
        initChatShell();
        initMusicPlayer();
        initLanguages();
        initScrollbar();
        initSliderListeners();
        initTtsSynthesis();
        initScrollToBottomBtn();
    } catch (e) {
        console.error('[Init] 初始化过程发生错误:', e);
    }
});

function initDragPrevention() {
    // 防止主内容区域意外触发窗口拖动（frameless 窗口兼容）
    // 防止在内容区域 mousedown 时触发窗口拖拽
    const app = document.querySelector('.app');
    if (app) {
        app.addEventListener('mousedown', (e) => {
            // 仅在非标题栏区域阻止可能触发拖动的默认行为
            const target = e.target;
            const isInTitlebar = target.closest('.titlebar');
            if (!isInTitlebar) {
                // 非交互元素（如文本区域）的 mousedown 可能被 webview 视为拖拽手势
                // 使用 preventDefault 阻止这种误判，同时不影响交互元素的功能
                const tag = target.tagName.toLowerCase();
                const interactive = ['input', 'textarea', 'button', 'select', 'a', 'label', 'img'];
                if (!interactive.includes(tag) && !target.isContentEditable && !target.draggable) {
                    e.preventDefault();
                }
            }
        }, { passive: false });

        // 专门捕获 textarea/input 的 mousedown，阻止事件冒泡到 pywebview 的拖拽层
        // 确保长按文本选择时不会触发窗口拖动
        document.addEventListener('mousedown', (e) => {
            const tag = e.target.tagName.toLowerCase();
            if (tag === 'textarea' || tag === 'input') {
                e.stopPropagation();
            }
        }, true); // 使用 capture 阶段尽早拦截
    }
}

function initScrollbar() {
    const mainContent = document.querySelector('.main-content');
    const contentArea = document.querySelector('.content-area');
    
    function updateMainContentHeight() {
        if (mainContent && contentArea) {
            const contentAreaHeight = contentArea.offsetHeight;
            mainContent.style.height = contentAreaHeight + 'px';
        }
    }
    
    updateMainContentHeight();
    window.addEventListener('resize', updateMainContentHeight);
}

// ============= WebSocket 连接 =============

function initWebSocket() {
    const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
    const wsUrl = `${protocol}//${window.location.host}/api/chat/ws`;
    
    ws = new WebSocket(wsUrl);
    
    ws.onopen = () => {
        console.log('WebSocket 连接已建立');
        isConnected = true;
        // 连接建立后加载聊天历史
        loadChatHistory();
    };
    
    ws.onmessage = (event) => {
        const data = JSON.parse(event.data);
        
        switch (data.type) {
            case 'user_message':
                addMessage(data.message);
                break;
            case 'ai_chunk':
                appendAiChunk(data.chunk);
                break;
            case 'reasoning_chunk':
                appendReasoningChunk(data.content);
                break;
            case 'ai_message':
                finalizeAiMessage(data.message);
                // 一轮结束：会话标题/预览可能已更新
                _refreshSessionListIfOpen();
                break;
            case 'context_info':
                updateContextInfo(data.context);
                break;
            case 'emotion_update':
                if (data.emotion) {
                    const emo = data.emotion;
                    const moodEmoji = document.getElementById('mood-emoji');
                    const moodName = document.getElementById('mood-name');
                    const moodIntensity = document.getElementById('mood-intensity');
                    const moodDesc = document.getElementById('mood-description');
                    if (moodEmoji) moodEmoji.textContent = emo.emoji || '😊';
                    if (moodName) moodName.textContent = emo.mood || '平和';
                    if (moodIntensity) moodIntensity.textContent = emo.intensity || '温和';
                    if (moodDesc) moodDesc.textContent = emo.description || '心情平和，神态自然';
                }
                break;
            case 'bond_update':
                if (data.bond) {
                    const bondLevel = document.getElementById('bond-level');
                    if (bondLevel) bondLevel.textContent = data.bond.level || '熟悉';
                }
                break;
            case 'likability_update':
                if (data.likability && data.likability.success) {
                    updateLikabilityUI(data.likability);
                }
                break;
            case 'voice_message':
                addVoiceMessage(data);
                break;
            case 'voice_synthesizing':
                showVoiceSynthesizing(data.text);
                break;
            case 'agent_chunk':
                appendAgentChunk(data);
                break;
            case 'agent_message':
                finalizeAgentMessage(data);
                break;
            case 'decision_request':
                showDecisionCard(data);
                break;
            case 'error':
                showError(data.message);
                break;
        }
    };
    
    ws.onclose = () => {
        console.log('WebSocket 连接已关闭');
        isConnected = false;
        setTimeout(initWebSocket, CONFIG.WS_RECONNECT_DELAY);
    };
    
    ws.onerror = (error) => {
        console.error('WebSocket 错误:', error);
    };
}

// ============= 事件监听 =============

function initEventListeners() {
    document.getElementById('send-btn')?.addEventListener('click', sendMessage);
    
    document.getElementById('message-input')?.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            sendMessage();
            return;
        }
        // ↑ / ↓ 回溯已发送消息（仅在输入框为空或正在浏览历史时生效）
        if (e.key === 'ArrowUp' && !e.shiftKey && !e.ctrlKey && !e.altKey && !e.metaKey) {
            if (recallSentMessage(-1)) e.preventDefault();
        } else if (e.key === 'ArrowDown' && !e.shiftKey && !e.ctrlKey && !e.altKey && !e.metaKey) {
            if (recallSentMessage(1)) e.preventDefault();
        }
    });
    
    // 发送并合成语音按钮
    const sendWithTts = document.getElementById('send-with-tts');
    if (sendWithTts) {
        sendWithTts.addEventListener('click', sendWithTtsMessage);
    }
    
    // 语音输入
    if (typeof initVoiceInput === 'function') initVoiceInput();

    // 附加文件
    const attachBtn = document.getElementById('attach-btn');
    const fileInput = document.getElementById('chat-file-input');
    if (attachBtn && fileInput) {
        attachBtn.addEventListener('click', function () { fileInput.click(); });
        fileInput.addEventListener('change', handleFileSelect);
    }
    
    // 命令提示符面板开关
    const cmdToggleBtn = document.getElementById('cmd-prompt-toggle-btn');
    if (cmdToggleBtn) {
        cmdToggleBtn.addEventListener('click', toggleCmdPromptPanel);
    }
    
    // 图片粘贴支持 + 输入自适应 + 发送按钮状态
    const msgInput = document.getElementById('message-input');
    if (msgInput) {
        msgInput.addEventListener('paste', handleImagePaste);
        msgInput.addEventListener('input', function () {
            _historyIndex = -1;   // 手动编辑后退出历史浏览
            autoGrowInput(msgInput);
            updateSendState();
            if (_draftTimer) clearTimeout(_draftTimer);
            _draftTimer = setTimeout(saveChatDraft, 400);
        });
    }
    initChatDropzone();
    initAttachPreview();
    updateSendState();
    loadSentHistory();
    loadChatDraft();
    // 首屏就把上下文用量环画出来（否则要等到第一轮结束才出现）
    if (typeof fetchContextInfo === 'function') fetchContextInfo();
    
    document.querySelectorAll('.quick-btn').forEach(btn => {
        btn.addEventListener('click', (e) => {
            const action = e.currentTarget.dataset.action;
            switchView(action);
        });
    });
    
    document.getElementById('tts-toggle')?.addEventListener('click', toggleTts);
    document.getElementById('music-btn')?.addEventListener('click', () => switchView('music'));
    document.getElementById('settings-btn')?.addEventListener('click', showSettings);
}

// ============= 附加文件 =============

// 已选择待发送的文件（上传成功后记录 url）
let _attachedFiles = [];
let _attachSeq = 0;

// 图片扩展名判断
function isImageFile(name) {
    return /\.(png|jpe?g|gif|webp|bmp|svg|ico)$/i.test(name || '');
}

// 文件扩展名 → 图标与配色
function attachIconFor(name) {
    const ext = String(name || '').split('.').pop().toLowerCase();
    if (/^(png|jpe?g|gif|webp|bmp|svg|ico)$/.test(ext)) return { icon: 'fa-file-image', cls: 'is-image' };
    if (ext === 'pdf') return { icon: 'fa-file-pdf', cls: 'is-pdf' };
    if (/^(docx?|rtf|odt)$/.test(ext)) return { icon: 'fa-file-word', cls: 'is-doc' };
    if (/^(xlsx?|csv|ods)$/.test(ext)) return { icon: 'fa-file-excel', cls: 'is-xls' };
    if (/^(pptx?|odp)$/.test(ext)) return { icon: 'fa-file-powerpoint', cls: 'is-ppt' };
    if (/^(zip|rar|7z|tar|gz)$/.test(ext)) return { icon: 'fa-file-zipper', cls: 'is-zip' };
    if (/^(mp3|wav|flac|m4a|aac|ogg)$/.test(ext)) return { icon: 'fa-file-audio', cls: 'is-audio' };
    if (/^(mp4|mov|mkv|avi|webm)$/.test(ext)) return { icon: 'fa-file-video', cls: 'is-video' };
    if (/^(txt|md|json|log|ya?ml|py|js|ts|html?|css|xml)$/.test(ext)) return { icon: 'fa-file-code', cls: 'is-code' };
    return { icon: 'fa-file-alt', cls: 'is-file' };
}

// 剪贴板/拖拽来的文件可能没有扩展名，按 MIME 补一个，便于识别与渲染
function normalizeFileName(file) {
    let name = file.name || 'file';
    if (!/\.[a-z0-9]{1,12}$/i.test(name) && file.type) {
        const ext = (file.type.split('/')[1] || '').split(';')[0].replace('jpeg', 'jpg');
        if (ext) name = name + '.' + ext;
    }
    return name;
}

function _attachListEl() {
    return document.getElementById('chat-attach-list');
}

function _syncAttachList() {
    const list = _attachListEl();
    const bar = document.getElementById('chat-attach-bar');
    const summary = document.getElementById('chat-attach-summary');
    const count = _attachedFiles.length;
    if (list) list.style.display = count ? 'flex' : 'none';
    if (bar) bar.style.display = count ? 'flex' : 'none';
    if (summary) {
        const total = _attachedFiles.reduce((sum, f) => sum + ((f.file && f.file.size) || 0), 0);
        summary.textContent = count + ' 个附件 · 共 ' + formatFileSize(total);
    }
}

// 统一入口：文件选择 / 拖拽 / 粘贴 都走这里，追加到列表并逐个上传
function addFiles(fileList) {
    const files = Array.from(fileList || []).filter(Boolean);
    const list = _attachListEl();
    if (!files.length || !list) return;

    // 预检：单文件 20MB、图片最多 6 张（DSH 式的数量/体积守卫）
    const MAX_ATTACH_SIZE = 20 * 1024 * 1024;
    const MAX_IMAGES = 6;
    const rejected = [];
    const accepted = [];
    let imageCount = _attachedFiles.filter(function (f) {
        return f.file && (f.file.type || '').indexOf('image/') === 0;
    }).length;
    files.forEach(function (file) {
        if (file.size > MAX_ATTACH_SIZE) { rejected.push(file.name + '（超过 20MB）'); return; }
        if ((file.type || '').indexOf('image/') === 0) {
            if (imageCount >= MAX_IMAGES) { rejected.push(file.name + '（图片最多 ' + MAX_IMAGES + ' 张）'); return; }
            imageCount++;
        }
        accepted.push(file);
    });
    if (rejected.length) {
        showToast('已跳过：' + rejected.slice(0, 3).join('、') +
            (rejected.length > 3 ? ' 等' : ''), 'error');
    }
    if (!accepted.length) return;

    accepted.forEach((file) => {
        const entry = {
            id: 'att_' + (++_attachSeq),
            file,
            name: normalizeFileName(file),
            url: '',
            status: 'uploading',
            preview: '',
        };
        if (file.type && file.type.startsWith('image/')) {
            try { entry.preview = URL.createObjectURL(file); } catch (err) { entry.preview = ''; }
        }
        _attachedFiles.push(entry);

        const item = document.createElement('div');
        item.className = 'chat-attach-item uploading';
        item.dataset.id = entry.id;
        item.innerHTML = renderAttachItem(entry);
        list.appendChild(item);
        var thumbEl = item.querySelector('.attach-thumb');
        if (thumbEl && entry.preview) {
            thumbEl.onclick = function () { _openAttachLightbox(entry.preview, entry.name); };
        }
        uploadAttachedFile(item, entry);
    });

    _syncAttachList();
    updateSendState();
}

// 图片灯箱：点缩略图看大图（原来是死提示「点击查看大图」）
function _openAttachLightbox(src, name) {
    if (!src) return;
    var old = document.getElementById('attach-lightbox');
    if (old) old.remove();
    var box = document.createElement('div');
    box.id = 'attach-lightbox';
    box.className = 'attach-lightbox';
    box.innerHTML = '<div class="attach-lightbox-inner"><img src="' + src + '" alt="">' +
        '<div class="attach-lightbox-name">' + escapeHtml(name || '') + '</div></div>';
    box.onclick = function () { box.remove(); };
    document.body.appendChild(box);
}

// 附件卡片内容
function renderAttachItem(entry) {
    const meta = attachIconFor(entry.name);
    const thumb = entry.preview
        ? '<div class="attach-thumb" title="点击查看大图"><img src="' + entry.preview + '" alt=""></div>'
        : '<div class="attach-thumb attach-thumb-icon ' + meta.cls + '"><i class="fas ' + meta.icon + '"></i></div>';
    return thumb +
        '<div class="attach-meta">' +
        '<span class="attach-filename" title="' + escapeHtml(entry.name) + '">' + escapeHtml(entry.name) + '</span>' +
        '<span class="attach-sub">' +
        '<span class="attach-filesize">' + formatFileSize(entry.file.size) + '</span>' +
        '<i class="fas fa-spinner fa-spin chat-attach-spinner"></i>' +
        '</span>' +
        '</div>' +
        '<button class="attach-retry" onclick="retryAttachedFile(this)" title="重试上传">' +
        '<i class="fas fa-rotate-right"></i></button>' +
        '<button class="attach-remove" onclick="removeAttachedFile(this)" title="移除">' +
        '<i class="fas fa-times"></i></button>' +
        '<div class="attach-progress"><span class="attach-progress-fill"></span></div>';
}

// 文件选择
function handleFileSelect(e) {
    addFiles(e.target.files);
    // 清空 input 值，允许重复选择同一文件
    e.target.value = '';
}

// 上传单个附件（XMLHttpRequest，带真实上传进度）
function uploadAttachedFile(item, entry) {
    const icon = item.querySelector('.chat-attach-spinner');
    const fill = item.querySelector('.attach-progress-fill');
    const xhr = new XMLHttpRequest();
    entry.xhr = xhr;

    xhr.open('POST', '/api/chat/upload_file', true);

    xhr.upload.onprogress = function (e) {
        if (fill && e.lengthComputable && e.total > 0) {
            fill.style.width = Math.round((e.loaded / e.total) * 100) + '%';
        }
    };

    xhr.onload = function () {
        entry.xhr = null;
        let data = null;
        try { data = JSON.parse(xhr.responseText); } catch (err) { data = null; }
        if (xhr.status >= 200 && xhr.status < 300 && data && data.success && data.url) {
            entry.url = data.url;
            entry.status = 'done';
            if (fill) fill.style.width = '100%';
            if (icon) icon.className = 'fas fa-check chat-attach-done';
            item.classList.remove('uploading', 'error');
            item.classList.add('uploaded');
        } else {
            entry.status = 'error';
            _markAttachError(item, icon, (data && data.message) || ('上传失败 ' + xhr.status));
        }
        updateSendState();
    };

    xhr.onerror = function () {
        entry.xhr = null;
        entry.status = 'error';
        _markAttachError(item, icon, '网络错误');
        updateSendState();
    };

    const formData = new FormData();
    formData.append('file', entry.file, entry.name);
    xhr.send(formData);
}

// 标记附件上传失败
function _markAttachError(item, icon, message) {
    if (icon) {
        icon.className = 'fas fa-exclamation-triangle chat-attach-error';
        icon.title = message || '上传失败';
    }
    item.classList.remove('uploading', 'uploaded');
    item.classList.add('error');
    const fill = item.querySelector('.attach-progress-fill');
    if (fill) fill.style.width = '0';
}

// 重试上传
function retryAttachedFile(btn) {
    const item = btn.closest('.chat-attach-item');
    const entry = _attachedFiles.find((f) => f.id === (item && item.dataset.id));
    if (!entry || !item) return;
    if (entry.xhr) {
        try { entry.xhr.abort(); } catch (err) { /* ignore */ }
        entry.xhr = null;
    }
    entry.url = '';
    entry.status = 'uploading';
    item.classList.remove('error', 'uploaded');
    item.classList.add('uploading');
    const icon = item.querySelector('.chat-attach-spinner, .chat-attach-error, .chat-attach-done');
    if (icon) icon.className = 'fas fa-spinner fa-spin chat-attach-spinner';
    const fill = item.querySelector('.attach-progress-fill');
    if (fill) fill.style.width = '0';
    uploadAttachedFile(item, entry);
}

// 移除单个附件
function removeAttachedFile(btn) {
    const item = btn.closest('.chat-attach-item');
    const id = item && item.dataset.id;
    const entry = _attachedFiles.find((f) => f.id === id);
    if (entry && entry.preview) {
        try { URL.revokeObjectURL(entry.preview); } catch (err) { /* ignore */ }
    }
    _attachedFiles = _attachedFiles.filter((f) => f.id !== id);
    if (item) item.remove();
    _syncAttachList();
    updateSendState();
}

// 由已上传文件生成消息正文（追加到用户输入之后）
// 附件使用 [file]名称|url[/file] / [img]名称|url[/img] 哨兵格式，
// 由 renderUserContent 渲染为文件气泡/图片，后端与 LLM 也能读到文件名与链接。
function buildAttachContent(content) {
    const files = _attachedFiles.filter((f) => f.status === 'done' && f.url);
    if (files.length === 0) return content;
    let extra = content;
    files.forEach((f) => {
        const isImage = isImageFile(f.name || f.file.name);
        // 清理特殊字符，避免破坏哨兵格式
        const name = (f.name || f.file.name)
            .replace(/\|/g, '｜')
            .replace(/\[/g, '【')
            .replace(/\]/g, '】')
            .replace(/[\r\n]/g, ' ')
            .trim();
        if (isImage) {
            extra += '\n\n[img]' + name + '|' + f.url + '[/img]';
        } else {
            extra += '\n\n[file]' + name + '|' + f.url + '[/file]';
        }
    });
    return extra;
}

// 用户消息渲染：先转义，再识别附件哨兵格式渲染为文件气泡/图片
function renderUserContent(text) {
    if (!text) return '';
    let html = escapeHtml(text);

    // 引用回复 [quote]作者|原文[/quote]
    const Q_OPEN = '[quote]';
    const Q_CLOSE = '[/quote]';
    let qStart = html.indexOf(Q_OPEN);
    while (qStart !== -1) {
        const qEnd = html.indexOf(Q_CLOSE, qStart);
        if (qEnd === -1) break;
        const inner = html.slice(qStart + Q_OPEN.length, qEnd);
        const sep = inner.indexOf('|');
        const qAuthor = sep === -1 ? '' : inner.slice(0, sep);
        const qText = sep === -1 ? inner : inner.slice(sep + 1);
        html = html.slice(0, qStart) +
            '<div class="quote-block" onclick="scrollToQuotedMessage(this)">' +
            '<div class="quote-author">' + qAuthor + '</div>' +
            '<div class="quote-text">' + qText + '</div>' +
            '</div>' + html.slice(qEnd + Q_CLOSE.length);
        qStart = html.indexOf(Q_OPEN, qStart + 1);
    }

    // 图片附件 [img]名称|url[/img]
    html = html.replace(/\[img\]([^\]]*?)\|([^\]]*?)\[\/img\]/g, function(m, name, url) {
        const safeUrl = url.replace(/'/g, "\\'");
        return '<div class="chat-image-wrapper">' +
            '<img src="' + safeUrl + '" alt="' + name + '" class="chat-image loaded" loading="lazy"' +
            ' onclick="showChatImagePreview(\'' + safeUrl + '\')">' +
            '</div>';
    });

    // 文件附件 [file]名称|url[/file]
    html = html.replace(/\[file\]([^\]]*?)\|([^\]]*?)\[\/file\]/g, function(m, name, url) {
        const isPdf = /\.pdf$/i.test(name);
        return '<div class="file-bubble">' +
            '<div class="file-icon"><i class="fas ' + (isPdf ? 'fa-file-pdf' : 'fa-file-alt') + '"></i></div>' +
            '<div class="file-info"><div class="file-name">' + name + '</div></div>' +
            '<button class="file-download-btn" onclick="event.stopPropagation(); downloadFile(\'' + url + '\')">' +
            '<i class="fas fa-download"></i></button>' +
            '</div>';
    });

    // 其余文本换行
    return html.replace(/\n/g, '<br>');
}

// 发送完成后清空附加列表
function clearAttachedFiles() {
    _attachedFiles.forEach((f) => {
        if (f.xhr) {
            try { f.xhr.abort(); } catch (err) { /* ignore */ }
        }
        if (f.preview) {
            try { URL.revokeObjectURL(f.preview); } catch (err) { /* ignore */ }
        }
    });
    _attachedFiles = [];
    const list = _attachListEl();
    if (list) list.innerHTML = '';
    _hideAttachPreview();
    _syncAttachList();
    updateSendState();
}

// ============= 输入框辅助（拖拽 / 自动增高 / 发送态） =============

// 根据输入内容与附件状态切换发送按钮可用性
function updateSendState() {
    const btn = document.getElementById('send-btn');
    const input = document.getElementById('message-input');
    if (!btn) return;
    const hasText = !!(input && input.value.trim());
    const doneCount = _attachedFiles.filter((f) => f.status === 'done').length;
    const uploading = _attachedFiles.some((f) => f.status === 'uploading');
    btn.disabled = (!hasText && doneCount === 0) || uploading;
    btn.title = uploading ? '文件上传中…' : '发送';
}

// 输入框随内容自动增高（高度上限见 CSS 的 max-height）
function autoGrowInput(el) {
    if (!el) return;
    el.style.height = 'auto';
    el.style.height = Math.min(el.scrollHeight, 160) + 'px';
}

// ============= 草稿保存 & 已发送消息回溯 =============

const CHAT_DRAFT_KEY = 'zhiyan_chat_draft';
const CHAT_SENT_KEY = 'zhiyan_chat_sent_history';
const CHAT_SENT_MAX = 50;

let _sentHistory = [];   // 已发送文本，最近的在末尾
let _historyIndex = -1;  // -1 表示未在浏览历史
let _draftTimer = null;

// 把当前输入写入本地存储（输入后防抖调用）
function saveChatDraft() {
    const input = document.getElementById('message-input');
    if (!input) return;
    try {
        const val = input.value;
        if (val) localStorage.setItem(CHAT_DRAFT_KEY, val);
        else localStorage.removeItem(CHAT_DRAFT_KEY);
    } catch (e) { /* 隐私模式等场景忽略 */ }
}

// 发送成功或清空后移除草稿
function _clearChatDraft() {
    if (_draftTimer) { clearTimeout(_draftTimer); _draftTimer = null; }
    try { localStorage.removeItem(CHAT_DRAFT_KEY); } catch (e) { /* ignore */ }
}

// 启动时恢复未发送的草稿
function loadChatDraft() {
    const input = document.getElementById('message-input');
    if (!input || input.value) return;
    let val = '';
    try { val = localStorage.getItem(CHAT_DRAFT_KEY) || ''; } catch (e) { val = ''; }
    if (!val) return;
    input.value = val;
    autoGrowInput(input);
    updateSendState();
    if (typeof showToast === 'function') showToast('已恢复上次未发送的草稿', 'info');
}

// 读取本地保存的已发送历史
function loadSentHistory() {
    try {
        const raw = localStorage.getItem(CHAT_SENT_KEY);
        const arr = raw ? JSON.parse(raw) : [];
        _sentHistory = Array.isArray(arr)
            ? arr.filter((s) => typeof s === 'string' && s.trim()).slice(-CHAT_SENT_MAX)
            : [];
    } catch (e) { _sentHistory = []; }
    _historyIndex = -1;
}

function _saveSentHistory() {
    try { localStorage.setItem(CHAT_SENT_KEY, JSON.stringify(_sentHistory)); } catch (e) { /* ignore */ }
}

// 记录一条已发送消息（供 ↑ 回溯），并清除草稿
function _markMessageSent(text) {
    const t = (text || '').trim();
    if (t && _sentHistory[_sentHistory.length - 1] !== t) {
        _sentHistory.push(t);
        if (_sentHistory.length > CHAT_SENT_MAX) _sentHistory.shift();
        _saveSentHistory();
    }
    _historyIndex = -1;
    _clearChatDraft();
}

// ↑ / ↓ 在已发送消息间回溯；dir = -1 更早、1 更近
function recallSentMessage(dir) {
    const input = document.getElementById('message-input');
    if (!input || !_sentHistory.length) return false;
    // 仅在输入框为空或已在浏览历史时响应，避免打断正常光标移动
    if (_historyIndex === -1 && dir === 1) return false;
    if (_historyIndex === -1 && input.value.trim() !== '') return false;

    // 未在浏览历史时以「草稿位」（长度值）为起点，再按方向走一格
    let idx = (_historyIndex === -1 ? _sentHistory.length : _historyIndex) + dir;
    if (idx < 0) idx = 0;
    if (idx > _sentHistory.length) idx = _sentHistory.length;

    _historyIndex = idx === _sentHistory.length ? -1 : idx;
    input.value = idx === _sentHistory.length ? '' : _sentHistory[idx];
    input.setSelectionRange(input.value.length, input.value.length);
    autoGrowInput(input);
    updateSendState();
    return true;
}

// 附件图片：悬停大图预览 / 点击查看原图
function initAttachPreview() {
    const list = _attachListEl();
    if (!list) return;

    let preview = document.getElementById('chat-attach-preview');
    if (!preview) {
        preview = document.createElement('div');
        preview.id = 'chat-attach-preview';
        preview.className = 'chat-attach-preview';
        preview.innerHTML = '<img alt="">';
        document.body.appendChild(preview);
    }

    const show = (thumb) => {
        const img = thumb.querySelector('img');
        if (!img) return;
        preview.querySelector('img').src = img.src;
        preview.classList.add('visible');
        const rect = thumb.getBoundingClientRect();
        const pw = 272;
        const ph = 272;
        let left = rect.left + rect.width / 2 - pw / 2;
        let top = rect.top - ph;
        left = Math.max(8, Math.min(left, window.innerWidth - pw - 8));
        if (top < 8) top = rect.bottom + 10;
        preview.style.left = left + 'px';
        preview.style.top = top + 'px';
    };

    list.addEventListener('mouseover', (e) => {
        const thumb = e.target.closest ? e.target.closest('.attach-thumb') : null;
        if (thumb && thumb.querySelector('img')) show(thumb);
    });

    list.addEventListener('mouseout', (e) => {
        const thumb = e.target.closest ? e.target.closest('.attach-thumb') : null;
        if (thumb && !thumb.contains(e.relatedTarget)) _hideAttachPreview();
    });

    list.addEventListener('click', (e) => {
        const thumb = e.target.closest ? e.target.closest('.attach-thumb') : null;
        const img = thumb ? thumb.querySelector('img') : null;
        if (img && typeof showChatImagePreview === 'function') {
            e.preventDefault();
            showChatImagePreview(img.src);
        }
    });

    list.addEventListener('scroll', _hideAttachPreview, true);
}

function _hideAttachPreview() {
    const preview = document.getElementById('chat-attach-preview');
    if (preview) preview.classList.remove('visible');
}

// 拖拽文件到聊天页即可添加附件
function initChatDropzone() {
    const view = document.getElementById('chat-view');
    const area = document.getElementById('chat-input-area');
    if (!view || !area) return;

    const hasFiles = (e) => !!(e.dataTransfer && Array.from(e.dataTransfer.types || []).indexOf('Files') !== -1);

    view.addEventListener('dragenter', (e) => {
        if (!hasFiles(e)) return;
        e.preventDefault();
        area.classList.add('drag-over');
    });

    view.addEventListener('dragover', (e) => {
        if (!hasFiles(e)) return;
        e.preventDefault();
        e.dataTransfer.dropEffect = 'copy';
        area.classList.add('drag-over');
    });

    view.addEventListener('dragleave', (e) => {
        if (!view.contains(e.relatedTarget)) area.classList.remove('drag-over');
    });

    view.addEventListener('drop', (e) => {
        if (!hasFiles(e)) return;
        e.preventDefault();
        area.classList.remove('drag-over');
        if (e.dataTransfer.files && e.dataTransfer.files.length) {
            addFiles(e.dataTransfer.files);
        }
    });
}

// ============= 视图切换 =============

function switchView(viewName) {
    if (viewName === 'chat') {
        showChatBase();
        return;
    }
    // 功能页面统一以悬浮桌面挂件的形式打开
    if (_isWidgetView(viewName)) {
        openWidget(viewName);
        _runViewHooks(viewName);
        return;
    }

    // 兼容：未注册为挂件的页面仍走整页切换
    document.querySelectorAll('.view').forEach(view => {
        if (!view.closest('.widget')) view.classList.remove('active');
    });

    const targetView = document.getElementById(`${viewName}-view`);
    if (targetView) {
        targetView.classList.add('active');
    }

    // 修复"降半屏"问题：当切换到 .app 外部的视图时，隐藏 .app
    const appEl = document.querySelector('.app');
    if (targetView && appEl) {
        const isInsideApp = appEl.contains(targetView);
        appEl.style.display = viewName === 'chat' ? '' : (isInsideApp ? '' : 'none');
    }

    _syncRailActive(viewName);
    _runViewHooks(viewName);
}

// 同步 quick 导航的选中态
function _syncRailActive(viewName) {
    document.querySelectorAll('.quick-btn').forEach(btn => {
        btn.classList.toggle('active', btn.dataset.action === viewName);
    });
}

// 视图激活后的数据加载钩子
function _runViewHooks(viewName) {
    if (viewName === 'music') {
        loadPlaylist();
    } else if (viewName === 'music-mini') {
        miniPlayerInit();
    } else if (viewName === 'usage') {
        loadUsageStats();
    } else if (viewName === 'tts') {
        ttsRefreshHistory();
        ttsCheckEngineStatus();
    } else if (viewName === 'memory') {
        loadMemories();
    } else if (viewName === 'knowledge') {
        loadKnowledge();
        loadKnowledgeTags();
    } else if (viewName === 'edu') {
        loadEduView();
    } else if (viewName === 'teach') {
        loadTeachView();
    } else if (viewName === 'likability') {
        loadLikability();
    } else if (viewName === 'promises') {
        loadPromises();
    } else if (viewName === 'emotion') {
        loadEmotionStatus();
        loadBondStatus();
        loadDriftStatus();
    } else if (viewName === 'proactive') {
        loadProactiveStatus();
        loadTasks();
    } else if (viewName === 'bettergi') {
        bgiLoadPage();
        bgiStartPolling();
    } else if (viewName === 'extensions') {
        loadExtensions();
    } else if (viewName === 'plugins') {
        loadPlugins();
    } else if (viewName === 'history') {
        refreshConversations();
    } else if (viewName === 'profile') {
        loadUserProfile();
    } else if (viewName === 'agent-manage') {
        refreshAgentList();
    } else if (viewName === 'skills') {
        loadSkillsPage();
    } else if (viewName === 'qq') {
        qqRefreshStatus();
        qqLoadConfig();
        qqLoadPermission();
        qqSwitchTab('status');
    }
}

// 回到聊天桌面：显示聊天并最小化所有挂件
function showChatBase() {
    document.querySelectorAll('.view').forEach(view => {
        if (!view.closest('.widget')) view.classList.remove('active');
    });
    const chatView = document.getElementById('chat-view');
    if (chatView) chatView.classList.add('active');
    const appEl = document.querySelector('.app');
    if (appEl) appEl.style.display = '';
    _syncRailActive('chat');
    _minimizeAllWidgets();
}

// ============= 深色模式切换 =============

function toggleDarkMode() {
    const html = document.documentElement;
    const isDark = html.classList.toggle('dark');
    localStorage.setItem('darkMode', isDark);
    
    const label = document.getElementById('dark-mode-label');
    if (label) {
        label.textContent = isDark ? '浅色模式' : '深色模式';
    }
    // 浅色/深色各存一份文字颜色，切换后立刻套用
    if (typeof _applyFontColors === 'function') _applyFontColors();
    // Mermaid 图表跟随主题重绘
    if (typeof _refreshMermaidBlocks === 'function') {
        try { _refreshMermaidBlocks(); } catch (e) { console.warn(e); }
    }
}

// ============= 字体颜色自定义（浅色 / 深色各存一份） =============

const FONT_COLOR_KEY = 'zhiyan_font_colors';
const FONT_COLOR_DEFAULTS = {
    light: { ink: '#1B2333', ink2: '#5B6B80' },
    dark: { ink: '#EDF1FE', ink2: '#AEB8D6' },
};

function _fontColorTheme() {
    return document.documentElement.classList.contains('dark') ? 'dark' : 'light';
}

function _loadFontColors() {
    var data = {};
    try {
        data = JSON.parse(localStorage.getItem(FONT_COLOR_KEY) || '{}') || {};
    } catch (e) {
        data = {};
    }
    function pick(theme) {
        var base = FONT_COLOR_DEFAULTS[theme];
        var got = data[theme] || {};
        return {
            ink: got.ink || base.ink,
            ink2: got.ink2 || base.ink2,
        };
    }
    return { light: pick('light'), dark: pick('dark') };
}

function _saveFontColors(cfg) {
    try { localStorage.setItem(FONT_COLOR_KEY, JSON.stringify(cfg)); } catch (e) { /* ignore */ }
}

function _applyFontColors() {
    var cfg = _loadFontColors();
    var theme = _fontColorTheme();
    var c = cfg[theme];
    var root = document.documentElement;
    root.style.setProperty('--ink', c.ink);
    root.style.setProperty('--ink-2', c.ink2);
    // 三级文字跟随次要文字，避免「次要文字改了、更淡的那层还是看不清」
    root.style.setProperty('--ink-3', c.ink2);
    _syncFontColorInputs(c, theme);
}

function _syncFontColorInputs(c, theme) {
    var pairs = [
        ['font-color-ink', 'font-color-ink-hex', c.ink],
        ['font-color-ink2', 'font-color-ink2-hex', c.ink2],
    ];
    pairs.forEach(function (p) {
        var picker = document.getElementById(p[0]);
        var hex = document.getElementById(p[1]);
        if (picker && document.activeElement !== picker) picker.value = p[2];
        if (hex && document.activeElement !== hex) hex.value = p[2];
    });
    var nameEl = document.getElementById('font-color-theme-name');
    if (nameEl) nameEl.textContent = theme === 'dark' ? '深色' : '浅色';
}

function _setFontColor(which, value) {
    if (!/^#[0-9a-fA-F]{6}$/.test(String(value || ''))) {
        showToast('颜色格式应为 #RRGGBB', 'error');
        return;
    }
    var cfg = _loadFontColors();
    var theme = _fontColorTheme();
    cfg[theme][which] = value;
    _saveFontColors(cfg);
    _applyFontColors();
    var status = document.getElementById('font-color-status');
    if (status) status.textContent = '已应用（' + (theme === 'dark' ? '深色' : '浅色') + '主题）';
}

function resetFontColors() {
    var cfg = _loadFontColors();
    var theme = _fontColorTheme();
    cfg[theme] = {
        ink: FONT_COLOR_DEFAULTS[theme].ink,
        ink2: FONT_COLOR_DEFAULTS[theme].ink2,
    };
    _saveFontColors(cfg);
    _applyFontColors();
    var status = document.getElementById('font-color-status');
    if (status) status.textContent = '已恢复默认';
}

function boostFontContrast() {
    var theme = _fontColorTheme();
    var preset = (theme === 'dark')
        ? { ink: '#FFFFFF', ink2: '#D6E0F5' }
        : { ink: '#0B1622', ink2: '#2A3B52' };
    var cfg = _loadFontColors();
    cfg[theme] = preset;
    _saveFontColors(cfg);
    _applyFontColors();
    var status = document.getElementById('font-color-status');
    if (status) status.textContent = '已加深（' + (theme === 'dark' ? '深色' : '浅色') + '主题）';
}

function previewFontColors() {
    _applyFontColors();
    var status = document.getElementById('font-color-status');
    if (status) status.textContent = '预览已刷新';
}

function initFontColorSettings() {
    var picker = document.getElementById('font-color-ink');
    var hex = document.getElementById('font-color-ink-hex');
    var picker2 = document.getElementById('font-color-ink2');
    var hex2 = document.getElementById('font-color-ink2-hex');
    if (picker) picker.addEventListener('input', function () { _setFontColor('ink', picker.value); });
    if (picker2) picker2.addEventListener('input', function () { _setFontColor('ink2', picker2.value); });
    if (hex) hex.addEventListener('change', function () { _setFontColor('ink', hex.value.trim()); });
    if (hex2) hex2.addEventListener('change', function () { _setFontColor('ink2', hex2.value.trim()); });
    _applyFontColors();
}

// 初始化深色模式
(function initDarkMode() {
    if (localStorage.getItem('darkMode') === 'true') {
        document.documentElement.classList.add('dark');
    }
    if (typeof _applyFontColors === 'function') _applyFontColors();
})();

// 初始化安全管控模式
(function initSecurityMode() {
    fetchSecurityInfo();
})();

// ============= 安全管控模式 =============

let securityModeInfo = null;

async function fetchSecurityInfo() {
    try {
        const resp = await fetch('/api/security/info');
        const data = await resp.json();
        securityModeInfo = data;
        updateSecurityUI(data);
    } catch (e) {
        console.warn('获取安全管控信息失败:', e);
    }
}

function updateSecurityUI(info) {
    if (!info) return;
    const label = document.getElementById('security-mode-label');
    const btn = document.getElementById('security-toggle-btn');
    if (!label || !btn) return;

    label.textContent = info.mode_name || '普通';

    // 更新图标和按钮样式
    const icon = btn.querySelector('i');
    if (icon) {
        // 清空所有 class
        icon.className = 'fas';
        if (info.mode === 'full_control') {
            icon.classList.add('fa-unlock');
            btn.style.color = '#ef4444';
            btn.style.background = 'rgba(239, 68, 68, 0.1)';
        } else if (info.mode === 'high_security') {
            icon.classList.add('fa-shield');
            btn.style.color = '#f59e0b';
            btn.style.background = 'rgba(245, 158, 11, 0.1)';
        } else {
            icon.classList.add('fa-shield-halved');
            btn.style.color = '';
            btn.style.background = '';
        }
    }
}

async function toggleSecurityMode() {
    if (!securityModeInfo) {
        await fetchSecurityInfo();
    }
    if (!securityModeInfo) return;

    // 显示模式选择弹窗
    showSecurityModeModal();
}

function showSecurityModeModal() {
    // 移除已有弹窗
    const existing = document.getElementById('security-mode-modal');
    if (existing) existing.remove();

    const info = securityModeInfo || {};

    const modal = document.createElement('div');
    modal.className = 'security-modal-overlay';
    modal.id = 'security-mode-modal';
    modal.innerHTML = `
        <div class="security-modal">
            <div class="security-modal-header">
                <h3><i class="fas fa-shield-halved"></i> 安全管控模式</h3>
                <button class="security-modal-close" onclick="this.closest('.security-modal-overlay').remove()">
                    <i class="fas fa-times"></i>
                </button>
            </div>
            <div class="security-modal-body">
                <p class="security-modal-desc">选择 AI 的文件操作权限范围：</p>
                <div class="security-mode-list" id="security-mode-list">
                    ${(info.available_modes || []).map(m => `
                        <div class="security-mode-item ${info.mode === m.id ? 'active' : ''}" data-mode="${m.id}" onclick="selectSecurityMode('${m.id}')">
                            <div class="security-mode-icon ${m.risk_level}">
                                <i class="fas ${m.icon}"></i>
                            </div>
                            <div class="security-mode-info">
                                <div class="security-mode-name">${m.name}</div>
                                <div class="security-mode-desc">${m.description}</div>
                            </div>
                            <div class="security-mode-check">
                                ${info.mode === m.id ? '<i class="fas fa-check-circle"></i>' : ''}
                            </div>
                        </div>
                    `).join('')}
                </div>
                <div id="security-mode-warning" class="security-mode-warning hidden"></div>
            </div>
            <div class="security-modal-footer">
                <button class="btn btn-sm" onclick="this.closest('.security-modal-overlay').remove()">取消</button>
                <button class="btn btn-primary" id="security-mode-confirm-btn" onclick="confirmSecurityMode()" style="display:none">确认切换</button>
            </div>
        </div>
    `;
    document.body.appendChild(modal);
}

let pendingSecurityMode = null;

function selectSecurityMode(mode) {
    pendingSecurityMode = mode;

    // 更新选中状态
    document.querySelectorAll('.security-mode-item').forEach(el => {
        el.classList.toggle('active', el.dataset.mode === mode);
        const check = el.querySelector('.security-mode-check');
        if (check) {
            check.innerHTML = el.dataset.mode === mode ? '<i class="fas fa-check-circle"></i>' : '';
        }
    });

    // 显示警告
    const warningEl = document.getElementById('security-mode-warning');
    const confirmBtn = document.getElementById('security-mode-confirm-btn');
    if (!warningEl || !confirmBtn) return;

    if (mode === 'full_control') {
        warningEl.classList.remove('hidden');
        warningEl.innerHTML = '<i class="fas fa-exclamation-triangle"></i> ⚠️ 高危警告：此模式下 AI 拥有对您电脑的完全控制权限！可以对整台电脑进行任何读写操作。请在使用完毕后立即切换回普通模式。<br><br><strong>此模式不会永久保存，重启软件后自动恢复为普通模式。</strong>';
        confirmBtn.style.display = 'inline-block';
    } else if (mode === 'high_security') {
        warningEl.classList.remove('hidden');
        warningEl.innerHTML = '<i class="fas fa-info-circle"></i> 高安全模式下，AI 仅能读写非关键系统位置，危险命令（如格式化、删除系统文件等）将被禁止。';
        confirmBtn.style.display = 'inline-block';
    } else {
        warningEl.classList.add('hidden');
        confirmBtn.style.display = 'none';
        // 普通模式直接切换
        confirmSecurityMode();
    }
}

async function confirmSecurityMode() {
    if (!pendingSecurityMode) return;

    try {
        const resp = await fetch('/api/security/set-mode', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({mode: pendingSecurityMode})
        });
        const data = await resp.json();

        if (data.success) {
            // 更新 UI
            await fetchSecurityInfo();

            // 关闭弹窗
            const modal = document.getElementById('security-mode-modal');
            if (modal) modal.remove();

            // 显示提示
            if (data.warning) {
                showToast(data.warning, 'warning');
            } else {
                showToast(data.message, 'success');
            }
        } else {
            showToast(data.message || '切换失败', 'error');
        }
    } catch (e) {
        showToast('切换安全模式失败: ' + e.message, 'error');
    }
    pendingSecurityMode = null;
}

// ============= 聊天功能 =============

// 代码语法高亮关键词映射（用于 highlight.js 不可用时的降级方案）
const CODE_KEYWORDS = {
    javascript: ['async', 'await', 'break', 'case', 'catch', 'class', 'const', 'continue', 'debugger', 'default', 'delete', 'do', 'else', 'export', 'extends', 'finally', 'for', 'function', 'if', 'import', 'in', 'instanceof', 'let', 'new', 'of', 'return', 'static', 'super', 'switch', 'this', 'throw', 'try', 'typeof', 'var', 'void', 'while', 'with', 'yield', 'true', 'false', 'null', 'undefined', 'from', 'as'],
    python: ['False', 'None', 'True', 'and', 'as', 'assert', 'async', 'await', 'break', 'class', 'continue', 'def', 'del', 'elif', 'else', 'except', 'finally', 'for', 'from', 'global', 'if', 'import', 'in', 'is', 'lambda', 'nonlocal', 'not', 'or', 'pass', 'raise', 'return', 'try', 'while', 'with', 'yield', 'self', 'print'],
    java: ['abstract', 'assert', 'boolean', 'break', 'byte', 'case', 'catch', 'char', 'class', 'const', 'continue', 'default', 'do', 'double', 'else', 'enum', 'extends', 'final', 'finally', 'float', 'for', 'goto', 'if', 'implements', 'import', 'instanceof', 'int', 'interface', 'long', 'native', 'new', 'package', 'private', 'protected', 'public', 'return', 'short', 'static', 'strictfp', 'super', 'switch', 'synchronized', 'this', 'throw', 'throws', 'transient', 'try', 'void', 'volatile', 'while', 'true', 'false', 'null'],
    html: ['!DOCTYPE', 'html', 'head', 'body', 'div', 'span', 'class', 'id', 'style', 'src', 'href', 'rel', 'type', 'meta', 'link', 'script', 'title', 'header', 'footer', 'nav', 'main', 'section', 'article', 'aside', 'ul', 'ol', 'li', 'table', 'tr', 'td', 'th', 'form', 'input', 'button', 'select', 'option', 'textarea', 'img', 'a', 'p', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'br', 'hr', 'iframe', 'video', 'audio', 'canvas', 'svg', 'path', 'circle', 'rect', 'line', 'text', 'g', 'defs', 'use'],
    css: ['@import', '@media', '@keyframes', '@font-face', '@supports', 'body', 'html', 'div', 'span', 'class', 'id', 'margin', 'padding', 'border', 'background', 'color', 'font', 'display', 'position', 'flex', 'grid', 'width', 'height', 'top', 'left', 'right', 'bottom', 'transform', 'transition', 'animation', 'box-shadow', 'opacity', 'overflow', 'z-index', 'float', 'clear', 'text-align', 'vertical-align', 'important', 'none', 'auto', 'inherit', 'initial', 'unset'],
};

// 语言别名映射
const LANG_ALIASES = {
    js: 'javascript', py: 'python', rb: 'ruby', go: 'go', rs: 'rust',
    ts: 'typescript', tsx: 'typescript', jsx: 'javascript',
    sh: 'bash', bash: 'bash', zsh: 'bash', powershell: 'powershell',
    pug: 'jade', styl: 'stylus', coffee: 'coffeescript',
    yml: 'yaml', yaml: 'yaml', md: 'markdown',
    cpp: 'cpp', c: 'c', cs: 'csharp', h: 'c', hpp: 'cpp',
    vue: 'html', svelte: 'html',
};

// 代码着色函数（highlight.js 不可用时的降级方案）
function highlightCode(code, language) {
    if (!language) return escapeHtml(code);
    
    const lang = LANG_ALIASES[language] || language;
    const keywords = CODE_KEYWORDS[lang] || [];
    let escaped = escapeHtml(code);
    
    // 1. 高亮字符串（单引号、双引号、反引号）
    escaped = escaped.replace(/(["'`])(?:(?!\1|\\).|\\.)*\1/g, '<span class="hljs-string">$&</span>');
    
    // 2. 高亮注释（// 和 /* */）
    escaped = escaped.replace(/\/\/.*$/gm, '<span class="hljs-comment">$&</span>');
    escaped = escaped.replace(/\/\*[\s\S]*?\*\//g, '<span class="hljs-comment">$&</span>');
    escaped = escaped.replace(/#.*$/gm, '<span class="hljs-comment">$&</span>');
    
    // 3. 高亮数字
    escaped = escaped.replace(/\b(\d+\.?\d*)\b/g, '<span class="hljs-number">$1</span>');
    
    // 4. 高亮关键词
    if (keywords.length > 0) {
        const kwPattern = new RegExp('\\b(' + keywords.join('|') + ')\\b', 'g');
        escaped = escaped.replace(kwPattern, '<span class="hljs-keyword">$1</span>');
    }
    
    // 5. 高亮函数调用（单词后跟括号）
    escaped = escaped.replace(/\b([a-zA-Z_$][\w$]*)\s*\(/g, '<span class="hljs-title">$1</span>(');
    
    // 6. HTML 标签高亮
    if (lang === 'html') {
        escaped = escaped.replace(/(&lt;\/?)([\w-]+)/g, '$1<span class="hljs-name">$2</span>');
        escaped = escaped.replace(/([\w-]+)(=)(["'])/g, '<span class="hljs-attr">$1</span>$2$3');
    }
    
    // 7. CSS 属性高亮
    if (lang === 'css') {
        escaped = escaped.replace(/([\w-]+)\s*:/g, '<span class="hljs-attr">$1</span>:');
        escaped = escaped.replace(/\.([\w-]+)/g, '<span class="hljs-selector-class">.$1</span>');
        escaped = escaped.replace(/#([\w-]+)/g, '<span class="hljs-selector-id">#$1</span>');
    }
    
    return escaped;
}

// 生成带行号和复制按钮的代码块 HTML
function renderCodeBlock(code, language) {
    const lang = language ? (LANG_ALIASES[language] || language) : '';
    const langLabel = language ? language.toUpperCase() : 'CODE';
    const lines = code.split('\n');
    const lineCount = lines.length;
    
    // 生成行号
    let lineNumbersHtml = '';
    for (let i = 1; i <= lineCount; i++) {
        lineNumbersHtml += `<span class="code-line-num">${i}</span>`;
    }
    
    // 尝试使用 highlight.js 进行高亮
    let highlightedCode = code;
    try {
        if (window.hljs && lang && hljs.getLanguage(lang)) {
            const result = hljs.highlight(code, { language: lang });
            highlightedCode = result.value;
        } else {
            highlightedCode = highlightCode(code, lang);
        }
    } catch (e) {
        highlightedCode = highlightCode(code, lang);
    }
    
    return `
        <div class="code-block-wrapper">
            <div class="code-block-header">
                <span class="code-block-lang">
                    <i class="fas fa-code"></i> ${langLabel}
                </span>
                <button class="code-copy-btn" onclick="copyCodeBlock(this)" title="复制代码">
                    <i class="fas fa-copy"></i> 复制
                </button>
            </div>
            <div class="code-block-body">
                <div class="code-line-numbers">${lineNumbersHtml}</div>
                <pre class="code-block-pre"><code class="code-block-content${lang ? ' language-' + lang : ''}">${highlightedCode}</code></pre>
            </div>
        </div>
    `;
}

// ===== 语音输入（浏览器 Web Speech API）=====
var _voiceRec = null;
var _voiceActive = false;

function initVoiceInput() {
    var btn = document.getElementById('voice-input-btn');
    if (!btn) return;
    var SR = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SR) {
        btn.title = '当前浏览器不支持语音输入（需要 Edge / Chrome）';
        btn.addEventListener('click', function () {
            showToast('当前浏览器不支持语音输入，请使用 Edge 或 Chrome', 'error');
        });
        return;
    }
    btn.addEventListener('click', function () {
        if (_voiceActive) { _stopVoiceInput(); return; }
        _startVoiceInput(SR, btn);
    });
}

function _startVoiceInput(SR, btn) {
    try {
        _voiceRec = new SR();
        _voiceRec.lang = 'zh-CN';
        _voiceRec.continuous = false;
        _voiceRec.interimResults = true;
        var input = document.getElementById('message-input');
        var baseText = input ? input.value : '';

        _voiceRec.onstart = function () {
            _voiceActive = true;
            btn.classList.add('recording');
            btn.title = '正在聆听…（点击停止）';
        };
        _voiceRec.onresult = function (ev) {
            var finalText = '';
            var interim = '';
            for (var i = ev.resultIndex; i < ev.results.length; i++) {
                var r = ev.results[i];
                if (r.isFinal) finalText += r[0].transcript;
                else interim += r[0].transcript;
            }
            if (input) {
                input.value = (baseText ? baseText + ' ' : '') + (finalText || interim);
                input.dispatchEvent(new Event('input'));
            }
        };
        _voiceRec.onerror = function (ev) {
            if (ev.error === 'not-allowed') showToast('麦克风权限被拒绝', 'error');
            else if (ev.error !== 'aborted') showToast('语音识别失败：' + ev.error, 'error');
            _stopVoiceInput();
        };
        _voiceRec.onend = function () { _stopVoiceInput(); };
        _voiceRec.start();
    } catch (e) {
        showToast('语音输入启动失败: ' + e.message, 'error');
        _stopVoiceInput();
    }
}

function _stopVoiceInput() {
    _voiceActive = false;
    var btn = document.getElementById('voice-input-btn');
    if (btn) {
        btn.classList.remove('recording');
        btn.title = '语音输入（按住说话 / 点击开始）';
    }
    try { if (_voiceRec) _voiceRec.stop(); } catch (e) {}
    _voiceRec = null;
}

// ===== 正文 [n] 角标 → 跳到参考来源 =====
function _linkifyCitations(root) {
    if (!root) return;
    var srcBox = root.querySelector('.msg-sources');
    if (!srcBox || !srcBox.querySelectorAll('.msg-source').length) return;
    var walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
        acceptNode: function (node) {
            if (!node.nodeValue || node.nodeValue.indexOf('[') < 0) return NodeFilter.FILTER_REJECT;
            var p = node.parentElement;
            if (!p) return NodeFilter.FILTER_REJECT;
            if (p.closest('pre, code, a, .msg-sources, .katex, .mermaid-block')) return NodeFilter.FILTER_REJECT;
            return NodeFilter.FILTER_ACCEPT;
        }
    });
    var targets = [];
    var n;
    while ((n = walker.nextNode())) targets.push(n);

    targets.forEach(function (textNode) {
        var text = textNode.nodeValue;
        if (!/\[\d{1,2}\]/.test(text)) return;
        var frag = document.createDocumentFragment();
        var last = 0;
        text.replace(/\[(\d{1,2})\]/g, function (m, num, offset) {
            var idx = parseInt(num, 10) - 1;
            if (idx < 0 || idx >= srcBox.querySelectorAll('.msg-source').length) return m;
            if (offset > last) frag.appendChild(document.createTextNode(text.slice(last, offset)));
            var sup = document.createElement('sup');
            sup.className = 'msg-cite';
            sup.textContent = String(idx + 1);
            sup.title = '查看参考来源 ' + (idx + 1);
            sup.addEventListener('click', function (e) {
                e.stopPropagation();
                var rows = srcBox.querySelectorAll('.msg-source');
                if (rows[idx]) {
                    rows[idx].scrollIntoView({ block: 'center', behavior: 'smooth' });
                    rows[idx].classList.add('flash');
                    setTimeout(function () { rows[idx].classList.remove('flash'); }, 1200);
                }
            });
            frag.appendChild(sup);
            last = offset + m.length;
            return m;
        });
        if (last < text.length) frag.appendChild(document.createTextNode(text.slice(last)));
        if (textNode.parentNode) textNode.parentNode.replaceChild(frag, textNode);
    });
}

// ===== 参考来源（web_search / web_fetch 结果里的链接）=====
var _SOURCE_TOOL_RE = /web_search|web_fetch|web_browse|search_web|fetch_url|deepseek_web_search|deepseek_read_url/i;
var _pendingSources = [];

function _extractSourceUrls(text) {
    var out = [];
    if (!text) return out;
    var re = /https?:\/\/[^\s"'<>)\]}]+/g;
    var m;
    while ((m = re.exec(String(text))) !== null) {
        var u = m[0].replace(/[.,;:!?]+$/, "");
        if (u.indexOf("api.") >= 0 && u.length > 120) continue;
        if (out.indexOf(u) < 0) out.push(u);
        if (out.length >= 12) break;
    }
    return out;
}

function _mergeSources(list, urls) {
    (urls || []).forEach(function (u) {
        if (list.indexOf(u) < 0) list.push(u);
    });
    return list;
}

function _sourcesBlockHtml(urls) {
    if (!urls || !urls.length) return "";
    var items = urls.map(function (u, i) {
        var domain = u;
        try { domain = new URL(u).hostname.replace(/^www\./, ""); } catch (e) {}
        var shortUrl = u.length > 78 ? u.slice(0, 78) + "…" : u;
        return '<a class="msg-source" href="' + escapeHtml(u) + '" target="_blank" rel="noopener">'
            + '<span class="msg-source-idx">' + (i + 1) + '</span>'
            + '<span class="msg-source-domain">' + escapeHtml(domain) + '</span>'
            + '<span class="msg-source-url">' + escapeHtml(shortUrl) + '</span></a>';
    }).join("");
    return '<div class="msg-sources"><div class="msg-sources-head"><i class="fas fa-link"></i>'
        + ' 参考来源 · ' + urls.length + '</div>' + items + '</div>';
}

// ===== 富内容增强：KaTeX 公式 + Mermaid 图表 =====
var _mermaidInited = false;
var _mermaidTheme = "";

function _initMermaid(force) {
    if (typeof mermaid === "undefined") return false;
    var dark = document.documentElement.classList.contains("dark");
    var theme = dark ? "dark" : "default";
    if (_mermaidInited && !force && _mermaidTheme === theme) return true;
    try {
        mermaid.initialize({
            startOnLoad: false,
            securityLevel: "strict",
            theme: theme,
            fontFamily: "inherit",
            flowchart: { htmlLabels: true, useMaxWidth: true },
            sequence: { useMaxWidth: true },
        });
        _mermaidInited = true;
        _mermaidTheme = theme;
        return true;
    } catch (e) {
        console.warn("mermaid 初始化失败", e);
        return false;
    }
}

/**
 * 把消息内容里的公式与 Mermaid 代码块渲染成图形。
 * 在「消息最终定稿」后调用（流式过程中不调用，避免重复渲染）。
 */
function enhanceRichContent(root) {
    if (!root) return;

    // 1) Mermaid：把 ```mermaid 代码块替换成图表容器
    try {
        var codes = root.querySelectorAll("code.language-mermaid");
        if (codes.length && _initMermaid(false)) {
            var nodes = [];
            codes.forEach(function (code) {
                var text = (code.textContent || "").trim();
                if (!text) return;
                var wrapper = code.closest(".code-block-wrapper") || code.closest("pre") || code;
                var box = document.createElement("div");
                box.className = "mermaid-block";
                var inner = document.createElement("div");
                inner.className = "mermaid";
                inner.textContent = text;
                box.appendChild(inner);
                if (wrapper.parentNode) wrapper.parentNode.replaceChild(box, wrapper);
                nodes.push(inner);
            });
            if (nodes.length) {
                Promise.resolve(mermaid.run({ nodes: nodes, suppressErrors: true })).catch(function (e) {
                    console.warn("mermaid 渲染失败", e);
                });
            }
        }
    } catch (e) {
        console.warn("mermaid 处理异常", e);
    }

    // 2) KaTeX：正文里的 $...$ / $$...$$ / \(...\) / \[...\]
    try {
        if (typeof renderMathInElement === "function") {
            renderMathInElement(root, {
                delimiters: [
                    { left: "$$", right: "$$", display: true },
                    { left: "\\[", right: "\\]", display: true },
                    { left: "\\(", right: "\\)", display: false },
                    { left: "$", right: "$", display: false },
                ],
                throwOnError: false,
                ignoredTags: ["script", "noscript", "style", "textarea", "pre", "code"],
                ignoredClasses: ["katex", "code-block-wrapper", "mermaid-block"],
            });
        }
    } catch (e) {
        console.warn("KaTeX 渲染异常", e);
    }
}

/** 主题切换后重绘现有图表 */
function _refreshMermaidBlocks() {
    if (typeof mermaid === "undefined" || !_mermaidInited) return;
    _initMermaid(true);
    var blocks = document.querySelectorAll(".mermaid-block .mermaid");
    if (!blocks.length) return;
    blocks.forEach(function (el) {
        if (!el.dataset.src) el.dataset.src = el.textContent || "";
    });
    blocks.forEach(function (el) {
        el.removeAttribute("data-processed");
        el.innerHTML = "";
        el.textContent = el.dataset.src;
    });
    Promise.resolve(mermaid.run({ nodes: Array.prototype.slice.call(blocks), suppressErrors: true }))
        .catch(function () {});
}

// 复制代码块内容
function copyCodeBlock(btn) {
    const wrapper = btn.closest('.code-block-wrapper');
    const codeContent = wrapper.querySelector('.code-block-content');
    if (codeContent) {
        const text = codeContent.textContent || codeContent.innerText;
        navigator.clipboard.writeText(text).then(() => {
            const originalHtml = btn.innerHTML;
            btn.innerHTML = '<i class="fas fa-check"></i> 已复制';
            btn.classList.add('copied');
            setTimeout(() => {
                btn.innerHTML = originalHtml;
                btn.classList.remove('copied');
            }, 2000);
        }).catch(() => {
            // 降级方案
            const textarea = document.createElement('textarea');
            textarea.value = text;
            document.body.appendChild(textarea);
            textarea.select();
            document.execCommand('copy');
            document.body.removeChild(textarea);
            const originalHtml = btn.innerHTML;
            btn.innerHTML = '<i class="fas fa-check"></i> 已复制';
            btn.classList.add('copied');
            setTimeout(() => {
                btn.innerHTML = originalHtml;
                btn.classList.remove('copied');
            }, 2000);
        });
    }
}

// 增强的 Markdown 渲染函数
/**
 * 检测文本是否包含 Markdown 特征
 * 用于判断是否从纯文本模式切换到 Markdown 渲染模式
 */
function detectMarkdown(text) {
    if (!text) return false;
    // 按行分割检测
    const lines = text.split('\n');
    for (let i = 0; i < lines.length; i++) {
        const line = lines[i];
        const trimmed = line.trim();
        
        // 代码块（```）
        if (trimmed.startsWith('```')) return true;
        
        // 表格（| 分隔的列，至少 2 个 |）
        if (trimmed.startsWith('|') && trimmed.endsWith('|') && (trimmed.match(/\|/g) || []).length >= 3) return true;
        // 分隔线表格行（| --- | --- |）
        if (/^\|[\s\-:]+\|[\s\-:]+\|/.test(trimmed)) return true;
        
        // 标题（# 开头，且不是 Markdown 链接语法中的 #）
        if (/^#{1,6}\s/.test(trimmed)) return true;
        
        // 引用
        if (trimmed.startsWith('> ')) return true;
        
        // 无序列表（-、*、+ 开头后跟空格）
        if (/^[-*+]\s/.test(trimmed)) return true;
        
        // 有序列表（数字. 开头）
        if (/^\d+\.\s/.test(trimmed)) return true;
        
        // 任务列表（- [ ] 或 - [x]）
        if (/^[-*+]\s\[[ x]\]/i.test(trimmed)) return true;
        
        // 水平分割线（---、***、___ 单独一行）
        if (/^(-{3,}|\*{3,}|_{3,})$/.test(trimmed)) return true;
        
        // 图片（![alt](url)）
        if (/!\[([^\]]*)\]\(([^)]+)\)/.test(trimmed)) return true;
        
        // 粗体/斜体（**text** 或 *text*，但需排除单个 * 包围的普通斜体，避免误判）
        if (/\*\*[^*]+\*\*/.test(trimmed)) return true;
        
        // 删除线
        if (/~~[^~]+~~/.test(trimmed)) return true;
        
        // 行内代码（`code`，但排除普通文本中的单个反引号）
        if ((trimmed.match(/`/g) || []).length >= 2) return true;
        
        // 折叠标记
        if (/\[fold=.*?\]/.test(trimmed)) return true;
    }
    return false;
}

function _fileRefIcon(name) {
    const ext = (name.split('.').pop() || '').toLowerCase();
    if (['png','jpg','jpeg','gif','webp','bmp','svg','ico','avif'].includes(ext)) return 'fa-file-image';
    if (['mp3','wav','flac','aac','ogg','m4a','wma','opus'].includes(ext)) return 'fa-file-audio';
    if (['mp4','mkv','avi','mov','webm','flv','wmv','m4v'].includes(ext)) return 'fa-file-video';
    if (ext === 'pdf') return 'fa-file-pdf';
    if (['zip','rar','7z','tar','gz','bz2'].includes(ext)) return 'fa-file-archive';
    if (['doc','docx'].includes(ext)) return 'fa-file-word';
    if (['xls','xlsx','csv'].includes(ext)) return 'fa-file-excel';
    if (['ppt','pptx'].includes(ext)) return 'fa-file-powerpoint';
    if (['txt','md','markdown','log','json','py','js','ts','tsx','jsx','html','css','c','cpp',
         'h','java','go','rs','yml','yaml','toml','ini','xml','sh','bat','cmd','ps1','sql','vue'].includes(ext)) return 'fa-file-code';
    return 'fa-file';
}

// 从文本中提取本地文件引用（绝对路径），替换为占位符，返回处理后的文本
function _extractFileRefs(text, out) {
    // 1) 反引号 / 引号包裹的绝对路径（允许含空格）
    //    盘符分支用 /(?!\/) 排除 "x://" 的网址协议形式（如 http://），避免把网页地址误判为本地路径
    text = text.replace(/[`"']((?:[A-Za-z]:\/(?!\/)|[A-Za-z]:\\(?!\\)|\\\\[^\\/\s]+[\\/])[^`"']*?)[`"']/g, function(m, p) {
        const path = _trimPathPunct(p);
        if (!_looksLikeFilePath(path)) return m;
        return _pushFileRef(out, path);
    });
    // 2) 纯文本绝对路径（不含空格与句读）— 同样排除网址协议形式
    text = text.replace(/(?:[A-Za-z]:\/(?!\/)|[A-Za-z]:\\(?!\\)|\\\\[^\\/\s]+[\\/])[^\s`"'，。；：！？、()\[\]{}<>“”‘’…]+/g, function(m) {
        const path = _trimPathPunct(m);
        if (!_looksLikeFilePath(path)) return m;
        return _pushFileRef(out, path);
    });
    return text;
}

function _trimPathPunct(p) {
    return p.replace(/[.,;:!?，。；：！？、'")\]}»]+$/, '');
}

function _looksLikeFilePath(p) {
    // 排除网址形式：带协议的 URL，或 "域名.tld" 形态的裸链接，避免误判为本地文件
    if (/^[A-Za-z][A-Za-z0-9+.-]*:\/\//.test(p)) return false;
    if (/^[\w-]+(\.[\w-]+)+/.test(p) && !/[\\/]/.test(p)) return false;
    // 至少含一层路径分隔符，避免把孤立盘符误判为文件
    return /[\\/]/.test(p);
}

function _pushFileRef(out, path) {
    out.push(path);
    return '\x00FILEREF' + (out.length - 1) + '\x00';
}

function _fileRefChip(path) {
    const name = path.split(/[\\/]/).pop() || path;
    const enc = encodeURIComponent(path);
    return '<span class="file-ref" data-path="' + enc + '" onclick="showFileDetail(this)" title="' + name.replace(/"/g, '&quot;') + '">' +
        '<i class="fas ' + _fileRefIcon(name) + '"></i>' +
        '<span class="file-ref-name">' + name.replace(/</g, '&lt;').replace(/>/g, '&gt;') + '</span>' +
        '<i class="fas fa-external-link-alt file-ref-open"></i></span>';
}

function renderMarkdown(text) {
    if (!text) return '';
    
    // 0. 提取本地文件引用（绝对路径）→ 占位符，渲染末尾恢复为可点击文件卡片
    const fileRefs = [];
    text = _extractFileRefs(text, fileRefs);

    // 0.5 先把 ``` 代码块抽出来（用原始文本渲染），避免后续转义/换行处理破坏代码
    const _codeBlocks = [];
    text = text.replace(/```(\w*)\n([\s\S]*?)```/g, function (m, lang, code) {
        _codeBlocks.push({ lang: lang || '', code: code });
        return '\x00CODEBLOCK' + (_codeBlocks.length - 1) + '\x00';
    });
    
    // 1. 提取折叠标记 ([fold=title]content[/fold])，转换为占位符
    const folds = [];
    text = text.replace(/\[fold=([^\]]*)\]([\s\S]*?)\[\/fold\]/g, function(m, title, content) {
        const idx = folds.length;
        // 渲染折叠内容中的 markdown，但保留 HTML 结构
        const renderedContent = content
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
            .replace(/\*([^*]+)\*/g, '<em>$1</em>')
            .replace(/`([^`]+)`/g, '<code class="inline-code">$1</code>')
            .replace(/\n/g, '<br>');
        const detailsHtml = `<details class="fold-details"><summary>${title}</summary><div class="fold-content">${renderedContent}</div></details>`;
        folds.push(detailsHtml);
        return '\x00FOLD' + idx + '\x00';
    });
    
    // 1. 先转义 HTML（代码块和图片由专用处理函数内部处理转义）
    let html = text
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;');
    
    // 图片（![alt](url)）— 必须在代码块之前处理，但已经在转义后的文本中
    // 由于图片 URL 中的特殊字符已被转义，需要特殊处理
    // 先把图片标记还原为未转义状态再处理
    html = html.replace(/!\[(&amp;|)([^\]]*?)(&amp;|)\]\(((?:[^()]|\([^()]*\))*)\)/g, function(match, p1, alt, p3, url) {
        const decodedAlt = alt.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>');
        const decodedUrl = url.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>');
        const safeUrl = decodedUrl.replace(/'/g, "\\'");
        const loadingId = 'img-load-' + (decodedUrl.length + decodedUrl.charCodeAt(0) || 0);
        return `<div class="chat-image-wrapper">
            <div class="chat-image-loading" id="${loadingId}">
                <i class="fas fa-circle-notch"></i> 加载中...
            </div>
            <img src="${decodedUrl}" alt="${decodedAlt}" 
                 class="chat-image loading" loading="lazy"
                 onclick="showChatImagePreview('${safeUrl}')"
                 onload="this.classList.remove('loading');this.classList.add('loaded');this.previousElementSibling.style.display='none'"
                 onerror="this.style.display='none';var fb=this.nextElementSibling;if(fb)fb.style.display='flex'">
            <div class="chat-image-fallback" style="display:none;">
                <i class="fas fa-image"></i> 图片加载失败
                <button class="retry-btn" onclick="retryChatImage(this)">重新加载</button>
            </div>
        </div>`;
    });
    
    // 语音消息（[voice]url[/voice]）— 渲染为可播放的语音气泡
    html = html.replace(/\[voice\]((?:https?:\/\/)[^\s\[\]]+?)\[\/voice\]/g, function(match, url) {
        const decodedUrl = url.replace(/&amp;/g, '&');
        return `<div class="voice-msg-bubble inline-voice" onclick="playInlineVoice(this, '${decodedUrl}')">
            <div class="voice-msg-icon">
                <i class="fas fa-play"></i>
            </div>
            <div class="voice-msg-wave">
                <span class="voice-wave-bar"></span>
                <span class="voice-wave-bar"></span>
                <span class="voice-wave-bar"></span>
                <span class="voice-wave-bar"></span>
                <span class="voice-wave-bar"></span>
            </div>
            <div class="voice-msg-text">语音消息</div>
            <div class="voice-msg-duration">~</div>
        </div>`;
    });
    
    // 行内代码（`...`）
    html = html.replace(/`([^`]+)`/g, '<code class="inline-code">$1</code>');

    // 显示公式（$$...$$ / \[...\]），代码块已提前抽出，不会被误判
    const _mathBlocks = [];
    html = html.replace(/\$\$([\s\S]+?)\$\$/g, function (m, tex) {
        _mathBlocks.push(tex);
        return '\x00MATH' + (_mathBlocks.length - 1) + '\x00';
    });
    html = html.replace(/\\\[([\s\S]+?)\\\]/g, function (m, tex) {
        _mathBlocks.push(tex);
        return '\x00MATH' + (_mathBlocks.length - 1) + '\x00';
    });
    
    // 链接（[文本](url)）— 绝对 http(s) 直接可用，相对路径补全站点地址（供插件下发本地文件下载/浏览链接）
    html = html.replace(/\[([^\[\]]+?)\]\(((?:https?:\/\/|\/)[^)\s]*?)\)/g, function(match, text, url) {
        let finalUrl = url.replace(/&amp;/g, '&');
        if (/^\//.test(finalUrl)) finalUrl = location.origin + finalUrl;
        const safeHref = finalUrl.replace(/'/g, "\\'").replace(/"/g, '&quot;');
        const safeText = text.replace(/'/g, "\\'");
        return '<a href="' + safeHref + '" target="_blank" rel="noopener" class="chat-link" onclick="event.stopPropagation()">' + safeText + '</a>';
    });
    
    // 加粗（**...**）
    html = html.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
    
    // 斜体（*...*）
    html = html.replace(/\*([^*]+)\*/g, '<em>$1</em>');
    
    // 删除线（~~...~~）
    html = html.replace(/~~([^~]+)~~/g, '<del>$1</del>');
    
    // 换行处理
    html = html.replace(/\n\n/g, '</p><p>');
    html = html.replace(/\n/g, '<br>');
    
    // 包裹段落
    if (html.includes('</p>')) {
        html = '<p>' + html + '</p>';
    }
    
    // 恢复折叠标记
    for (let i = 0; i < folds.length; i++) {
        html = html.split('\x00FOLD' + i + '\x00').join(folds[i]);
    }
    
    // 恢复代码块（原始文本 → 语法高亮渲染）
    for (let i = 0; i < _codeBlocks.length; i++) {
        const item = _codeBlocks[i];
        html = html.split('\x00CODEBLOCK' + i + '\x00').join(renderCodeBlock(item.code.trim(), item.lang));
    }

    // 恢复文件引用占位符 → 可点击文件卡片
    for (let i = 0; i < fileRefs.length; i++) {
        html = html.split('\x00FILEREF' + i + '\x00').join(_fileRefChip(fileRefs[i]));
    }

    // 还原显示公式：有 KaTeX 就直接渲染，没有则退回等宽源码
    for (let i = 0; i < _mathBlocks.length; i++) {
        const tex = _mathBlocks[i];
        let out;
        if (typeof katex !== 'undefined') {
            try {
                out = '<div class="math-display">' + katex.renderToString(tex, { displayMode: true, throwOnError: false }) + '</div>';
            } catch (e) {
                out = '<pre class="math-src">' + tex.replace(/&/g, '&amp;').replace(/</g, '&lt;') + '</pre>';
            }
        } else {
            out = '<pre class="math-src">' + tex.replace(/&/g, '&amp;').replace(/</g, '&lt;') + '</pre>';
        }
        html = html.split('\x00MATH' + i + '\x00').join(out);
    }

    return html;
}

// ===== 实时频谱（Web Audio AnalyserNode → canvas） =====

var _viz = { ctx: null, analyser: null, source: null, raf: 0, data: null, canvas: null };

function _vizCanvas() {
    return _viz.canvas || (_viz.canvas = document.getElementById('np-visualizer'));
}

// 必须在一次用户手势后初始化；createMediaElementSource 只能调用一次
function _ensureVizAnalyser() {
    if (_viz.analyser) return _viz.analyser;
    if (!audioPlayer) return null;
    try {
        var AC = window.AudioContext || window.webkitAudioContext;
        if (!AC) return null;
        _viz.ctx = new AC();
        _viz.source = _viz.ctx.createMediaElementSource(audioPlayer);
        _viz.analyser = _viz.ctx.createAnalyser();
        _viz.analyser.fftSize = 128;
        _viz.analyser.smoothingTimeConstant = 0.82;
        _viz.source.connect(_viz.analyser);
        // 必须接回输出，否则音频会被 MediaElementSource 吃掉变成静音
        _viz.analyser.connect(_viz.ctx.destination);
        _viz.data = new Uint8Array(_viz.analyser.frequencyBinCount);
        return _viz.analyser;
    } catch (e) {
        console.warn('[Viz] 初始化失败:', e);
        return null;
    }
}

function _vizResize() {
    var cv = _vizCanvas();
    if (!cv) return;
    var rect = cv.getBoundingClientRect();
    var dpr = window.devicePixelRatio || 1;
    if (!rect.width || !rect.height) return;
    if (cv.width !== Math.round(rect.width * dpr) || cv.height !== Math.round(rect.height * dpr)) {
        cv.width = Math.round(rect.width * dpr);
        cv.height = Math.round(rect.height * dpr);
    }
}

function _vizFrame() {
    var cv = _vizCanvas();
    var analyser = _viz.analyser;
    if (!cv || !analyser) return;
    _vizResize();
    var ctx2d = cv.getContext('2d');
    if (!ctx2d) return;
    var w = cv.width, h = cv.height;
    analyser.getByteFrequencyData(_viz.data);

    ctx2d.clearRect(0, 0, w, h);
    var bars = 48;
    var gap = 2 * (window.devicePixelRatio || 1);
    var bw = Math.max(2, (w - gap * (bars - 1)) / bars);
    var accent = getComputedStyle(document.documentElement).getPropertyValue('--accent').trim() || '#4c9ef0';
    for (var i = 0; i < bars; i++) {
        var idx = Math.floor(i * (_viz.data.length / bars / 1.6));
        var v = (_viz.data[idx] || 0) / 255;
        var bh = Math.max(2, v * h * 0.92);
        var x = i * (bw + gap);
        var grad = ctx2d.createLinearGradient(0, h, 0, h - bh);
        grad.addColorStop(0, accent);
        grad.addColorStop(1, 'rgba(255,255,255,0.12)');
        ctx2d.fillStyle = grad;
        ctx2d.globalAlpha = 0.55 + v * 0.45;
        ctx2d.beginPath();
        var r = Math.min(3, bw / 2);
        var y = h - bh;
        ctx2d.moveTo(x + r, y);
        ctx2d.arcTo(x + bw, y, x + bw, y + bh, r);
        ctx2d.arcTo(x + bw, y + bh, x, y + bh, r);
        ctx2d.arcTo(x, y + bh, x, y, r);
        ctx2d.arcTo(x, y, x + bw, y, r);
        ctx2d.closePath();
        ctx2d.fill();
    }
    ctx2d.globalAlpha = 1;
    _viz.raf = requestAnimationFrame(_vizFrame);
}

function startAudioVisualizer() {
    if (!_ensureVizAnalyser()) return;
    if (_viz.ctx && _viz.ctx.state === 'suspended') {
        _viz.ctx.resume().catch(function () {});
    }
    if (_viz.raf) return;
    _viz.raf = requestAnimationFrame(_vizFrame);
}

function stopAudioVisualizer() {
    if (_viz.raf) {
        cancelAnimationFrame(_viz.raf);
        _viz.raf = 0;
    }
    var cv = _vizCanvas();
    if (cv) {
        var c = cv.getContext('2d');
        if (c) c.clearRect(0, 0, cv.width, cv.height);
    }
}

// ===== 队列拖拽排序 + 封面墙 =====

var _dragSongFile = '';

function _bindPlaylistDrag() {
    var list = document.getElementById('playlist');
    if (!list || list._dragBound) return;
    list._dragBound = true;

    list.addEventListener('dragstart', function (e) {
        var item = e.target.closest('.playlist-item');
        if (!item) return;
        _dragSongFile = item.dataset.filename || '';
        item.classList.add('dragging');
        try { e.dataTransfer.effectAllowed = 'move'; e.dataTransfer.setData('text/plain', _dragSongFile); } catch (err) {}
    });
    list.addEventListener('dragend', function (e) {
        var item = e.target.closest('.playlist-item');
        if (item) item.classList.remove('dragging');
        list.querySelectorAll('.drop-target').forEach(function (el) { el.classList.remove('drop-target'); });
    });
    list.addEventListener('dragover', function (e) {
        var item = e.target.closest('.playlist-item');
        if (!item || !_dragSongFile) return;
        e.preventDefault();
        list.querySelectorAll('.drop-target').forEach(function (el) { el.classList.remove('drop-target'); });
        item.classList.add('drop-target');
    });
    list.addEventListener('drop', function (e) {
        var item = e.target.closest('.playlist-item');
        if (!item) return;
        e.preventDefault();
        var target = item.dataset.filename || '';
        if (target && _dragSongFile && target !== _dragSongFile) {
            _reorderPlaylist(_dragSongFile, target);
        }
        _dragSongFile = '';
    });
}

// 把 from 移到 to 的位置，保存到后端（自定义顺序）
function _reorderPlaylist(fromFile, toFile) {
    if (!currentPlaylist || !currentPlaylist.length) return;
    var fromIdx = currentPlaylist.findIndex(function (s) { return s.filename === fromFile; });
    var toIdx = currentPlaylist.findIndex(function (s) { return s.filename === toFile; });
    if (fromIdx < 0 || toIdx < 0 || fromIdx === toIdx) return;
    var moved = currentPlaylist.splice(fromIdx, 1)[0];
    currentPlaylist.splice(toIdx, 0, moved);
    filteredPlaylist = currentPlaylist.slice();
    sortBy = 'custom';
    var sel = document.getElementById('playlist-sort');
    if (sel) sel.value = 'custom';
    renderPlaylist();
    fetch('/api/music/playlist/save', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ songs: currentPlaylist }),
    }).then(function (r) { return r.json(); }).then(function (d) {
        if (d && d.success) showToast('队列顺序已保存');
        else showToast('顺序保存失败', 'error');
    }).catch(function () { showToast('顺序保存失败', 'error'); });
}

function togglePlaylistWall() {
    var list = document.getElementById('playlist');
    if (!list) return;
    var on = list.classList.toggle('cover-wall');
    var btn = document.getElementById('playlist-wall-btn');
    if (btn) btn.classList.toggle('active', on);
    try { localStorage.setItem('musicPlaylistWall', on ? '1' : '0'); } catch (e) {}
}

// ===== 桌面歌词：向 /api/music/now-playing 上报当前行 ---------
var _npPostAt = 0;

function _postNowPlaying() {
    if (!audioPlayer) return;
    var now = Date.now();
    if (now - _npPostAt < 600) return;
    _npPostAt = now;
    var t = Number(audioPlayer.currentTime) || 0;
    var idx = -1;
    for (var i = 0; i < currentLyrics.length; i++) {
        if (t >= (Number(currentLyrics[i].time) || 0)) idx = i; else break;
    }
    var line = idx >= 0 ? currentLyrics[idx] : { text: '', words: [] };
    var nextText = (idx >= 0 && idx + 1 < currentLyrics.length) ? (currentLyrics[idx + 1].text || '') : '';
    var titleEl = document.getElementById('song-title');
    var artistEl = document.getElementById('song-artist');
    fetch('/api/music/now-playing', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            title: titleEl ? titleEl.textContent.trim() : '',
            artist: (artistEl && artistEl.textContent.trim() !== 'Furina Music Player') ? artistEl.textContent.trim() : '',
            playing: !!isPlaying,
            time: Math.round(t * 1000) / 1000,
            line: { text: line.text || '', words: line.words || [] },
            next: nextText,
        }),
    }).catch(function () { /* 上报失败不影响播放 */ });
}

function openDesktopLyrics() {
    var url = location.origin + '/static/lyrics_overlay.html';
    try {
        var api = window.pywebview && window.pywebview.api;
        if (api && typeof api.open_lyrics_overlay === 'function') {
            api.open_lyrics_overlay(url).then(function (r) {
                showToast((r && r.message) || '桌面歌词已打开', r && r.success === false ? 'error' : 'success');
            }).catch(function () { showToast('桌面歌词打开失败', 'error'); });
            return;
        }
    } catch (e) { /* 浏览器环境继续走 window.open */ }
    var win = window.open(url, 'furina-lyrics',
        'width=920,height=180,menubar=no,toolbar=no,location=no,status=no');
    if (win) showToast('已打开歌词浮窗（浏览器窗口无法置顶）');
    else showToast('浏览器拦截了弹窗，请允许后再试', 'error');
}

// ===== 底栏当前曲目信息（与主封面/歌名同步，Kugou 式底栏） =====

function _syncNowPlayingBar() {
    var titleEl = document.getElementById('song-title');
    var artistEl = document.getElementById('song-artist');
    var coverEl = document.getElementById('album-cover');
    var t = titleEl ? (titleEl.textContent || '').trim() : '';
    var a = artistEl ? (artistEl.textContent || '').trim() : '';
    var npTitle = document.getElementById('np-bar-title');
    var npArtist = document.getElementById('np-bar-artist');
    if (npTitle) npTitle.textContent = (t && t !== '选择一首歌曲...') ? t : '未在播放';
    if (npArtist) {
        npArtist.textContent = (a && a !== 'Furina Music Player') ? a : '选一首歌开始';
    }
    var img = document.getElementById('np-cover-img');
    if (img && coverEl) {
        var src = coverEl.getAttribute('src') || '';
        if (src) {
            if (img.getAttribute('src') !== src) img.src = src;
            img.style.display = '';
        } else {
            img.style.display = 'none';
        }
    }
}

function initNowPlayingBar() {
    _syncNowPlayingBar();
    ['song-title', 'song-artist', 'album-cover'].forEach(function (id) {
        var el = document.getElementById(id);
        if (!el || el._npObserved) return;
        el._npObserved = true;
        try {
            new MutationObserver(_syncNowPlayingBar).observe(el, {
                attributes: true, childList: true, subtree: true, characterData: true,
            });
        } catch (e) { /* 老内核不支持就算了，视图切换时会再同步一次 */ }
    });
}

// ===== 忙时消息队列（DSH 式：排队 / 插话 / 自动续发） =====

function _enqueuePendingMessage(content) {
    if (!content) return;
    _pendingMessages.push({
        id: 'q' + Date.now() + Math.random().toString(16).slice(2, 6),
        content: content,
    });
    _renderPendingQueue();
}

function _renderPendingQueue() {
    var box = document.getElementById('chat-queue');
    var list = document.getElementById('chat-queue-list');
    var countEl = document.getElementById('chat-queue-count');
    if (!box || !list) return;
    if (!_pendingMessages.length) {
        box.style.display = 'none';
        list.innerHTML = '';
        if (countEl) countEl.textContent = '0';
        return;
    }
    box.style.display = 'block';
    if (countEl) countEl.textContent = String(_pendingMessages.length);
    list.innerHTML = _pendingMessages.map(function (m) {
        var text = String(m.content || '').replace(/\s+/g, ' ').trim();
        if (text.length > 60) text = text.slice(0, 60) + '…';
        return '<div class="chat-queue-item">' +
            '<i class="fas fa-clock"></i>' +
            '<span class="chat-queue-text">' + escapeHtml(text) + '</span>' +
            '<button type="button" class="chat-queue-interrupt" onclick="_interruptWithQueued(\'' + m.id + '\')" title="停止当前回答，立刻改发这条">插话</button>' +
            '<button type="button" class="chat-queue-remove" onclick="_removeQueued(\'' + m.id + '\')" title="从队列移除"><i class="fas fa-times"></i></button>' +
            '</div>';
    }).join('');
}

function _removeQueued(id) {
    _pendingMessages = _pendingMessages.filter(function (m) { return m.id !== id; });
    _renderPendingQueue();
}

// 插话：中止当前回合，立刻把这条发出去（DSH 的 steering 语义）
function _interruptWithQueued(id) {
    var idx = -1;
    for (var i = 0; i < _pendingMessages.length; i++) {
        if (_pendingMessages[i].id === id) { idx = i; break; }
    }
    if (idx < 0) return;
    var item = _pendingMessages.splice(idx, 1)[0];
    _renderPendingQueue();
    if (_currentAgentStream) stopAgentStream();
    setTimeout(function () { sendMessage(item.content); }, 80);
}

// 当前回合结束后自动续发下一条
function _flushPendingQueue() {
    if (!_pendingMessages.length) { _renderPendingQueue(); return; }
    if (_currentAgentStream) return;
    var next = _pendingMessages.shift();
    _renderPendingQueue();
    var input = document.getElementById('message-input');
    var draft = input ? input.value : '';
    sendMessage(next.content);
    if (input && input.value !== draft) {
        input.value = draft;
        if (typeof autoGrowInput === 'function') autoGrowInput(input);
    }
}

function sendMessage(overrideContent) {
    const input = document.getElementById('message-input');
    if (!input) return;
    // overrideContent 用于「队列自动续发」：不读输入框，也不清空用户正在写的新草稿
    const fromQueue = typeof overrideContent === 'string';
    const rawContent = (fromQueue ? overrideContent : input.value).trim();
    const hasAttach = !fromQueue && _attachedFiles.length > 0;
    const quotePrefix = fromQueue ? '' : _peekQuotePrefix();
    
    // 只引用不输入文字也允许发送（引用块会成为正文）
    if (!rawContent && !hasAttach && !quotePrefix) return;

    // 斜杠命令：命中注册表时本地执行，不进入模型/管道
    if (!hasAttach && !quotePrefix && tryRunSlashCommand(rawContent)) return;
    
    // 有文件仍在上传：提示等待，不发送
    const uploading = _attachedFiles.filter((f) => f.status === 'uploading');
    if (uploading.length > 0) {
        showError('文件还在上传中，请稍候再发送');
        return;
    }
    
    // 引用内容放在正文最前面，再追加附件
    const body = quotePrefix ? (rawContent ? quotePrefix + '\n\n' + rawContent : quotePrefix) : rawContent;
    let content = buildAttachContent(body);
    // `@路径` 在发送前展开成引用清单，模型据此用 read_file 精读
    content = _expandAtFileRefs(content);

    // 忙时排队（DSH 行为）：当前回合还没结束就先入队，done 之后自动续发
    if (!fromQueue && _currentAgentStream) {
        _enqueuePendingMessage(content);
        input.value = '';
        input.style.height = 'auto';
        clearAttachedFiles();
        _clearQuoteReplyBar();
        updateSendState();
        return;
    }
    
    // DSH 内核模式：使用独立的 DSH runtime 流式对话
    if (window._dshMode) {
        _markMessageSent(rawContent);
        _clearQuoteReplyBar();
        sendDshMessage(content);
        clearAttachedFiles();
        return;
    }
    
    // 如果 Agent 模式开启，使用 HTTP API 发送
    if (window._agentMode) {
        _markMessageSent(rawContent);
        _clearQuoteReplyBar();
        sendAgentMessage(content);
        clearAttachedFiles();
        return;
    }
    
    if (!isConnected) {
        showError('WebSocket 连接未建立，请稍候重试');
        return;
    }
    
    // 禁用发送按钮，防止重复发送
    const sendBtn = document.getElementById('send-btn');
    if (sendBtn) {
        sendBtn.disabled = true;
        sendBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i>';
    }
    
    input.value = '';
    input.style.height = 'auto';
    clearAttachedFiles();
    
    try {
        ws.send(JSON.stringify({ content, session_id: _currentSessionId() }));
        _markMessageSent(rawContent);
        _clearQuoteReplyBar();
        createAiMessagePlaceholder();
    } catch (e) {
        showError('发送消息失败: ' + e.message);
        // 发送失败时把内容退回输入框，避免丢失
        if (rawContent) {
            input.value = rawContent;
            autoGrowInput(input);
            saveChatDraft();
            updateSendState();
        }
    }
    
    // 恢复发送按钮
    setTimeout(() => {
        if (sendBtn) {
            sendBtn.innerHTML = '<i class="fas fa-arrow-up"></i>';
        }
        updateSendState();
    }, 500);
}

// ============= Agent 模式流式消息 =============

let _currentAgentStream = null;  // 当前 Agent 流式消息状态
let _pendingMessages = [];       // 忙时排队的待发消息（DSH 式队列）
let _questionState = null;       // 当前交互式提问卡片状态

// 创建一条流式助手消息的容器与状态对象（Agent / DSH 内核共用）
function _createStreamMessage(roleLabel, badge) {
    const container = document.getElementById('chat-messages');
    const messageDiv = document.createElement('div');
    messageDiv.className = 'message assistant';
    messageDiv.id = 'agent-stream-' + Date.now();
    const tsId = Date.now();
    messageDiv.innerHTML = `
        <div class="message-avatar">
            <img src="/api/avatar/zhiyan" alt="Furina"
                 onerror="this.style.display='none'; this.nextElementSibling.style.display='flex';"
                 class="avatar-img">
            <div class="avatar-fallback">🌊</div>
        </div>
        <div class="message-body">
            <div class="message-meta">
                <span class="message-role-label">${roleLabel}</span>
                <span class="role-badge">${badge}</span>
                <span class="message-time">${formatTime(new Date().toISOString())}</span>
                <span class="message-elapsed" style="display:none">
                    <i class="fas fa-stopwatch"></i>
                    <span class="think-timer-text"></span>
                </span>
                <span class="message-usage" style="display:none"></span>
            </div>
            <div class="agent-tool-status" id="agent-tool-status-${tsId}"></div>
            <div class="message-content">
                <div class="agent-thinking">
                    <i class="fas fa-spinner fa-spin"></i>
                    <span>正在思考...</span>
                </div>
            </div>
            <div class="message-actions" style="display:none">
                <button class="msg-action-btn" onclick="copyMessage(this)" title="复制">
                    <i class="fas fa-copy"></i>
                </button>
                <button class="msg-action-btn" onclick="quoteReplyMessage(this)" title="引用回复">
                    <i class="fas fa-quote-right"></i>
                </button>
                <button class="msg-action-btn" onclick="deleteMessage(this)" title="删除">
                    <i class="fas fa-trash-alt"></i>
                </button>
                <button class="msg-action-btn" onclick="resendMessage(this)" title="重新发送">
                    <i class="fas fa-redo"></i>
                </button>
            </div>
        </div>
    `;
    container.appendChild(messageDiv);
    scrollToBottom();
    const stream = {
        element: messageDiv,
        contentEl: messageDiv.querySelector('.message-content'),
        toolStatusEl: messageDiv.querySelector('.agent-tool-status'),
        actionsEl: messageDiv.querySelector('.message-actions'),
        timerEl: messageDiv.querySelector('.message-elapsed'),
        usageEl: messageDiv.querySelector('.message-usage'),
        callCards: {},
        content: '',
        hasToolCalls: false,
        toolsCount: 0,
        toolsDone: 0,
        usage: { input: 0, output: 0, model: '' },
        sources: [],
    };
    _startThinkTimer(stream);
    return stream;
}

// 启动思考计时器（每 100ms 刷新，显示在气泡下方）
function _startThinkTimer(stream) {
    if (!stream || !stream.timerEl) return;
    _stopThinkTimer(stream, true);   // 先清理可能存在的旧计时器
    stream.timerStart = Date.now();
    stream.timerElapsed = 0;
    stream.timerEl.style.display = '';
    stream.timerEl.classList.add('running');
    const textEl = stream.timerEl.querySelector('.think-timer-text');
    const tick = () => {
        const sec = (Date.now() - stream.timerStart) / 1000;
        stream.timerElapsed = sec;
        if (textEl) textEl.textContent = '思考中 ' + sec.toFixed(1) + 's';
    };
    tick();
    stream.timerIntervalId = setInterval(tick, 100);
}

// 停止思考计时器并定格耗时（label 可自定义，如“等待回答”；msOverride 用后端回传的落盘值）
function _stopThinkTimer(stream, silent, label, msOverride) {
    if (!stream || !stream.timerEl) return;
    if (stream.timerIntervalId) {
        clearInterval(stream.timerIntervalId);
        stream.timerIntervalId = null;
    }
    if (silent) return;
    const sec = (msOverride > 0)
        ? msOverride / 1000
        : (stream.timerStart ? (Date.now() - stream.timerStart) / 1000 : (stream.timerElapsed || 0));
    stream.timerElapsed = sec;
    stream.timerEl.classList.remove('running');
    const textEl = stream.timerEl.querySelector('.think-timer-text');
    if (textEl) textEl.textContent = (label || '思考耗时') + ' ' + sec.toFixed(1) + 's';
}

// 渲染消息 meta 的 token 用量与模型（DSH：hover 消息时才显示）
function _renderStreamUsage(stream) {
    if (!stream || !stream.usageEl) return;
    var u = stream.usage || {};
    var parts = [];
    if (u.model) parts.push(u.model);
    if (u.input || u.output) parts.push('↑' + u.input + ' ↓' + u.output);
    if (!parts.length) {
        stream.usageEl.style.display = 'none';
        return;
    }
    stream.usageEl.innerHTML = '<i class="fas fa-coins"></i> ' + escapeHtml(parts.join(' · '));
    stream.usageEl.style.display = '';
}

// 消费一段 SSE 响应体，逐事件交还 _processAgentEvent 处理
async function _streamConsume(res) {
    const reader = res.body.getReader();
    const decoder = new TextDecoder();
    let buffer = '';
    while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        buffer += decoder.decode(value, { stream: true });
        const parts = buffer.split('\n\n');
        buffer = parts.pop();
        for (const part of parts) {
            const trimmed = part.trim();
            if (!trimmed) continue;
            const lines = trimmed.split('\n');
            let eventType = '';
            let eventData = '';
            for (const line of lines) {
                if (line.startsWith('event: ')) eventType = line.slice(7).trim();
                else if (line.startsWith('data: ')) eventData = line.slice(6).trim();
            }
            if (eventType && eventData) {
                try { _processAgentEvent(eventType, JSON.parse(eventData)); }
                catch (e) { console.warn('[Stream] SSE 解析错误:', e); }
            }
        }
    }
}

// DSH 内核模式发送消息（流式 SSE）
async function sendDshMessage(content) {
    const input = document.getElementById('message-input');
    const sendBtn = document.getElementById('send-btn');

    _agentAbortController = new AbortController();
    if (sendBtn) {
        sendBtn.disabled = false;
        sendBtn.innerHTML = '<span class="stop-icon"><span class="stop-square"></span></span>';
        sendBtn.title = '停止生成';
        sendBtn.onclick = stopAgentStream;
    }

    input.value = '';
    input.style.height = 'auto';

    addMessage({ role: 'user', content: content });
    _currentAgentStream = _createStreamMessage('芙宁娜', 'DSH 内核');

    let sessionId = window._dshSessionId;
    if (!sessionId) {
        sessionId = 'zhiyan_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
        window._dshSessionId = sessionId;
        try { localStorage.setItem('dshSessionId', sessionId); } catch (e) {}
    }

    try {
        const res = await fetch('/api/dsh/chat/stream', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ message: content, session_id: sessionId }),
            signal: _agentAbortController.signal,
        });
        if (!res.ok) {
            // runtime 未就绪等后端错误
            let detail = 'HTTP ' + res.status;
            try {
                const j = await res.json();
                if (j && j.detail) detail = j.detail;
            } catch (e) {}
            throw new Error(detail);
        }
        await _streamConsume(res);
        // 兜底：流已结束却没收到 done/error（例如内核只回了 idle），
        // 必须把计时器定格，否则它会一直空转，看起来「计时器坏了」
        if (_currentAgentStream && _currentAgentStream.timerIntervalId) {
            _stopThinkTimer(_currentAgentStream);
            _currentAgentStream.contentEl.classList.remove('typing');
            _currentAgentStream.actionsEl.style.display = '';
            _currentAgentStream = null;
        }
    } catch (e) {
        if (e.name === 'AbortError') {
            console.log('[DSH] 用户终止了生成');
            if (_currentAgentStream) {
                if (_currentAgentStream.content) {
                    _currentAgentStream.content += '\n\n*（生成已终止）*';
                } else {
                    _currentAgentStream.contentEl.innerHTML = '<div class="agent-cancelled"><i class="fas fa-stop-circle"></i> 已终止</div>';
                }
                _currentAgentStream.contentEl.classList.remove('typing');
                _stopThinkTimer(_currentAgentStream);
                _currentAgentStream.actionsEl.style.display = '';
            }
        } else {
            console.error('[DSH] 流式请求失败:', e);
            if (_currentAgentStream) {
                _currentAgentStream.contentEl.innerHTML = '<div class="error-message">请求失败: ' + escapeHtml(e.message) + '</div>';
                _currentAgentStream.contentEl.classList.remove('typing');
                _stopThinkTimer(_currentAgentStream);
                _currentAgentStream.actionsEl.style.display = '';
            }
        }
    }
    _restoreSendButton();
}

// Agent 模式发送消息（流式 SSE）
async function sendAgentMessage(content) {
    const input = document.getElementById('message-input');
    const sendBtn = document.getElementById('send-btn');
    
    // 切换发送键为停止键
    _agentAbortController = new AbortController();
    if (sendBtn) {
        sendBtn.disabled = false;
        sendBtn.innerHTML = '<span class="stop-icon"><span class="stop-square"></span></span>';
        sendBtn.title = '停止生成';
        sendBtn.onclick = stopAgentStream;
    }
    
    input.value = '';
    input.style.height = 'auto';
    
    // 在聊天中添加用户消息
    addMessage({ role: 'user', content: content });
    
    // 创建 Agent 流式消息容器
    const myStream = _createStreamMessage('芙宁娜', '水神 芙宁娜');
    _currentAgentStream = myStream;
    
    try {
        const res = await fetch('/api/chat/agent-send-stream', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ content, session_id: _currentSessionId() }),
            signal: _agentAbortController.signal,
        });
        
        if (!res.ok) {
            throw new Error('HTTP ' + res.status);
        }
        
        const reader = res.body.getReader();
        const decoder = new TextDecoder();
        let buffer = '';
        
        while (true) {
            const { done, value } = await reader.read();
            if (done) break;
            
            buffer += decoder.decode(value, { stream: true });
            
            // 解析 SSE 事件（按双换行分割）
            const parts = buffer.split('\n\n');
            buffer = parts.pop(); // 保留不完整的部分
            
            for (const part of parts) {
                const trimmed = part.trim();
                if (!trimmed) continue;
                
                const lines = trimmed.split('\n');
                let eventType = '';
                let eventData = '';
                
                for (const line of lines) {
                    if (line.startsWith('event: ')) {
                        eventType = line.slice(7).trim();
                    } else if (line.startsWith('data: ')) {
                        eventData = line.slice(6).trim();
                    }
                }
                
                if (eventType && eventData) {
                    try {
                        const data = JSON.parse(eventData);
                        _processAgentEvent(eventType, data);
                    } catch (e) {
                        console.warn('[Agent] SSE 解析错误:', e);
                    }
                }
            }
        }
    } catch (e) {
        if (e.name === 'AbortError') {
            // 用户主动终止，显示终止提示
            console.log('[Agent] 用户终止了生成');
            if (_currentAgentStream) {
                // 在内容末尾添加终止标记
                if (_currentAgentStream.content) {
                    _currentAgentStream.content += '\n\n*（生成已终止）*';
                } else {
                    _currentAgentStream.contentEl.innerHTML = '<div class="agent-cancelled"><i class="fas fa-stop-circle"></i> 已终止</div>';
                }
                _currentAgentStream.contentEl.classList.remove('typing');
                _stopThinkTimer(_currentAgentStream);
                _currentAgentStream.actionsEl.style.display = '';
            }
        } else {
            console.error('[Agent] 流式请求失败:', e);
            if (_currentAgentStream) {
                _currentAgentStream.contentEl.innerHTML = '<div class="error-message">请求失败: ' + escapeHtml(e.message) + '</div>';
                _currentAgentStream.contentEl.classList.remove('typing');
                _stopThinkTimer(_currentAgentStream);
                _currentAgentStream.actionsEl.style.display = '';
            }
        }
    }
    
    // 恢复发送键；并复位本轮流（用户终止 / 请求失败时不会收到 done）
    if (_currentAgentStream === myStream) _currentAgentStream = null;
    _restoreSendButton();
    _flushPendingQueue();
}

// 终止当前 Agent 流
function stopAgentStream() {
    if (_agentAbortController) {
        _agentAbortController.abort();
        _agentAbortController = null;
    }
    _restoreSendButton();
}

// 恢复发送键为初始状态
function _restoreSendButton() {
    const sendBtn = document.getElementById('send-btn');
    if (sendBtn) {
        sendBtn.innerHTML = '<i class="fas fa-arrow-up"></i>';
        sendBtn.onclick = sendMessage;
        sendBtn.disabled = false;
        sendBtn.title = '发送';
    }
    updateSendState();
    _agentAbortController = null;
}

