// 获取工具显示名称（中文别名 + 缩写后的工具名）
function _getToolDisplayName(name) {
    const alias = _TOOL_NAME_ALIASES[name];
    if (alias) return alias;
    // 默认：将下划线/驼峰转为空格分隔的简短显示
    return name.replace(/_/g, ' ').replace(/([a-z])([A-Z])/g, '$1 $2');
}

// 将工具参数渲染为美观的键值对列表
function _renderToolArgs(args) {
    if (!args || Object.keys(args).length === 0) {
        return '<div class="tool-args-empty">无参数</div>';
    }
    
    // 需要截断或隐藏的长文本参数名
    const LONG_TEXT_KEYS = ['content', 'file_content', 'text', 'code', 'prompt', 'query', 'command'];
    
    var html = '<div class="tool-args-list">';
    for (var key in args) {
        if (!args.hasOwnProperty(key)) continue;
        var val = args[key];
        var displayVal = '';
        var isLong = false;
        
        if (val === null || val === undefined) {
            displayVal = '<span class="tool-arg-null">null</span>';
        } else if (typeof val === 'boolean') {
            displayVal = '<span class="tool-arg-bool">' + (val ? 'true' : 'false') + '</span>';
        } else if (typeof val === 'number') {
            displayVal = '<span class="tool-arg-number">' + val + '</span>';
        } else if (typeof val === 'string') {
            var strVal = val;
            if (strVal.length > 4000) strVal = strVal.slice(0, 4000);
            isLong = LONG_TEXT_KEYS.indexOf(key) !== -1 && strVal.length > 60;
            if (isLong) {
                // 展开工具行时看完整输入（限高滚动），不再截成 60 字
                displayVal = '<div class="tool-arg-long-full">' + escapeHtml(strVal) +
                    (strVal.length > 4000 ? '<div class="dsh-tool-output-more">… 共 ' + strVal.length + ' 字符</div>' : '') +
                    '</div>';
            } else {
                displayVal = '<span class="tool-arg-string">"' + escapeHtml(strVal) + '"</span>';
            }
        } else if (Array.isArray(val)) {
            displayVal = '<span class="tool-arg-array">[' + val.length + ' 项]</span>';
        } else if (typeof val === 'object') {
            var str = JSON.stringify(val).slice(0, 80);
            displayVal = '<span class="tool-arg-object" title="' + escapeHtml(JSON.stringify(val)) + '">{' + escapeHtml(str) + (str.length >= 80 ? '...' : '') + '}</span>';
        }
        
        // 参数名美化
        var displayKey = key.replace(/_/g, ' ');
        displayKey = displayKey.charAt(0).toUpperCase() + displayKey.slice(1);
        
        html += '<div class="tool-arg-row">';
        html += '<span class="tool-arg-key">' + escapeHtml(displayKey) + '</span>';
        html += '<span class="tool-arg-value">' + displayVal + '</span>';
        html += '</div>';
    }
    html += '</div>';
    return html;
}

// ============= 增强型工具结果渲染 =============

// 渲染 diff 卡片（文件编辑）
// deepseek-harness 风格 DiffBlock 渲染
function renderDiffCard(filePath, oldText, newText) {
    if (!oldText && !newText) return '';
    var oldLines = (oldText || '').split('\n');
    var newLines = (newText || '').split('\n');
    var maxLines = Math.max(oldLines.length, newLines.length);
    var added = 0, removed = 0;
    var diffRows = [];
    for (var i = 0; i < maxLines; i++) {
        var oLine = oldLines[i] !== undefined ? oldLines[i] : null;
        var nLine = newLines[i] !== undefined ? newLines[i] : null;
        var cls = '';
        var content = '';
        if (oLine !== null && nLine !== null && oLine === nLine) {
            cls = 'context';
            content = escapeHtml(oLine);
        } else if (nLine !== null && (oLine === null || oLine !== nLine)) {
            cls = 'add';
            content = escapeHtml(nLine);
            added++;
        } else if (oLine !== null && (nLine === null || oLine !== nLine)) {
            cls = 'del';
            content = escapeHtml(oLine);
            removed++;
        }
        if (content !== '') {
            diffRows.push({ cls: cls, content: content });
        }
    }
    // 高度截断
    var MAX_LINES = 16;
    var hidden = diffRows.length - MAX_LINES;
    var capped = hidden > 0;
    var headLines = Math.ceil(MAX_LINES / 2);
    var tailLines = MAX_LINES - headLines;
    var head = capped ? diffRows.slice(0, headLines) : diffRows;
    var tail = capped ? diffRows.slice(diffRows.length - tailLines) : [];
    
    var bodyHtml = '';
    head.forEach(function(r) {
        bodyHtml += '<div class="dsh-diff-line dsh-diff-' + r.cls + '">' + r.content + '</div>';
    });
    if (capped) {
        bodyHtml += '<div class="dsh-diff-expand" onclick="this.nextElementSibling.style.display=\'\';this.style.display=\'none\';">… 其余 ' + hidden + ' 行</div>';
        bodyHtml += '<div class="dsh-diff-tail" style="display:none;">';
        tail.forEach(function(r) {
            bodyHtml += '<div class="dsh-diff-line dsh-diff-' + r.cls + '">' + r.content + '</div>';
        });
        bodyHtml += '</div>';
    }
    
    var html = '<div class="dsh-diff-block">';
    html += '<div class="dsh-diff-header">';
    html += '<span class="dsh-diff-path"><i class="fas fa-pen"></i> ' + escapeHtml(filePath) + '</span>';
    html += '</div>';
    html += '<div class="dsh-diff-body">' + bodyHtml + '</div>';
    html += '<div class="dsh-diff-footer">└ +' + added + ' -' + removed + ' · 1 file</div>';
    html += '</div>';
    return html;
}

// deepseek-harness 风格 TerminalBlock 渲染
function renderTerminalCard(command, output, exitCode) {
    var status = exitCode === 0 ? 'success' : 'error';
    var statusText = exitCode === 0 ? '成功' : '失败 (exit ' + exitCode + ')';
    var outputLines = output ? output.split('\n') : [];
    // 高度截断
    var MAX_LINES = 16;
    var totalLines = outputLines.length + 1; // +1 for command line
    var hidden = totalLines - MAX_LINES;
    var capped = hidden > 0;
    var headLines = Math.ceil(MAX_LINES / 2);
    var tailLines = MAX_LINES - headLines;
    
    var bodyHtml = '';
    bodyHtml += '<div class="dsh-term-line"><span class="dsh-term-prompt">$</span> ' + escapeHtml(command) + '</div>';
    if (capped) {
        var showHead = outputLines.slice(0, headLines - 1);
        var showTail = outputLines.slice(outputLines.length - tailLines);
        showHead.forEach(function(l) { bodyHtml += '<div class="dsh-term-line">' + escapeHtml(l) + '</div>'; });
        bodyHtml += '<div class="dsh-diff-expand" onclick="this.nextElementSibling.style.display=\'\';this.style.display=\'none\';">… 其余 ' + hidden + ' 行</div>';
        bodyHtml += '<div class="dsh-term-tail" style="display:none;">';
        showTail.forEach(function(l) { bodyHtml += '<div class="dsh-term-line">' + escapeHtml(l) + '</div>'; });
        bodyHtml += '</div>';
    } else {
        outputLines.forEach(function(l) { bodyHtml += '<div class="dsh-term-line">' + escapeHtml(l) + '</div>'; });
    }
    
    var html = '<div class="dsh-term-block">';
    html += '<div class="dsh-term-header">';
    html += '<span class="dsh-term-icon"><i class="fas fa-terminal"></i></span>';
    html += '<span class="dsh-term-cmd">' + escapeHtml(command) + '</span>';
    html += '<span class="dsh-term-status ' + status + '">' + statusText + '</span>';
    html += '</div>';
    html += '<div class="dsh-term-body">' + bodyHtml + '</div>';
    html += '</div>';
    return html;
}

// deepseek-harness 风格 ReadBlock 渲染
function renderReadCard(filePath, lines, offset, totalLines) {
    offset = offset || 0;
    totalLines = totalLines || (lines ? lines.length : 0);
    // 高度截断
    var MAX_LINES = 16;
    var hidden = lines ? lines.length - MAX_LINES : 0;
    var capped = hidden > 0 && lines;
    var headLines = Math.ceil(MAX_LINES / 2);
    var tailLines = MAX_LINES - headLines;
    var slice = lines || [];
    var head = capped ? slice.slice(0, headLines) : slice;
    var tail = capped ? slice.slice(slice.length - tailLines) : [];
    var windowed = lines && lines.length < totalLines;
    
    var bodyHtml = '';
    head.forEach(function(line, i) {
        var lineNum = offset + i + 1;
        bodyHtml += '<div class="dsh-read-line"><span class="dsh-read-gutter">' + lineNum + '</span><span class="dsh-read-content">' + escapeHtml(line) + '</span></div>';
    });
    if (capped) {
        bodyHtml += '<div class="dsh-diff-expand" onclick="this.nextElementSibling.style.display=\'\';this.style.display=\'none\';">… 其余 ' + hidden + ' 行</div>';
        bodyHtml += '<div class="dsh-read-tail" style="display:none;">';
        tail.forEach(function(line, i) {
            var lineNum = offset + slice.length - tailLines + i + 1;
            bodyHtml += '<div class="dsh-read-line"><span class="dsh-read-gutter">' + lineNum + '</span><span class="dsh-read-content">' + escapeHtml(line) + '</span></div>';
        });
        bodyHtml += '</div>';
    }
    
    var html = '<div class="dsh-read-block">';
    html += '<div class="dsh-read-banner">';
    html += '<span class="dsh-read-label"><i class="fas fa-file-alt"></i> ' + escapeHtml(filePath) + '</span>';
    if (windowed) {
        html += '<span class="dsh-read-count">显示 ' + (lines ? lines.length : 0) + ' / ' + totalLines + ' 行</span>';
    }
    html += '</div>';
    html += '<div class="dsh-read-body">' + bodyHtml + '</div>';
    html += '</div>';
    return html;
}

// 检测工具结果类型并渲染适当的卡片
function renderToolResultEnhanced(name, result) {
    if (!result) return '';
    
    // 检测是否为文件编辑工具
    if (name === 'edit' || name === 'edit_file' || name === 'write_file') {
        // 尝试解析 JSON 结果
        try {
            var parsed = typeof result === 'string' ? JSON.parse(result) : result;
            if (parsed.path && parsed.before !== undefined && parsed.after !== undefined) {
                return renderDiffCard(parsed.path, parsed.before, parsed.after);
            }
        } catch (e) {}
    }
    
    // 检测是否为 shell 命令工具
    if (name === 'execute_command' || name === 'execute' || name === 'run_command' || name === 'bash') {
        try {
            var parsed = typeof result === 'string' ? JSON.parse(result) : result;
            if (parsed.command || parsed.output !== undefined) {
                return renderTerminalCard(
                    parsed.command || name,
                    parsed.output || parsed.stdout || '',
                    parsed.exit_code !== undefined ? parsed.exit_code : (parsed.success ? 0 : 1)
                );
            }
        } catch (e) {
            // 非 JSON 结果，按纯文本输出显示
            return renderTerminalCard(name, result, 0);
        }
    }
    
    // 检测是否为文件读取工具
    if (name === 'read' || name === 'read_file' || name === 'read_files') {
        try {
            var parsed = typeof result === 'string' ? JSON.parse(result) : result;
            if (parsed.path && parsed.lines) {
                return renderReadCard(parsed.path, parsed.lines.map(function(l) { return l.text || l; }), parsed.offset, parsed.totalLines);
            }
        } catch (e) {}
    }
    
    return '';
}

// ============= Todo List 管理 =============

// SVG 状态图标（deepseek-harness 风格）
function _todoSvgGlyph(status) {
    if (status === 'completed') {
        return '<svg width="14" height="14" viewBox="0 0 14 14" fill="none"><circle cx="7" cy="7" r="6.4" stroke="#22c55e" stroke-width="1.2"/><path d="M10.9631 5.71411L7.70154 8.97571C7.48011 9.19714 7.27736 9.40099 7.09229 9.54993C6.89742 9.70669 6.66314 9.85279 6.3634 9.90027C6.2049 9.92534 6.04339 9.92534 5.88489 9.90027C5.58515 9.85279 5.35087 9.70669 5.15601 9.54993C4.97093 9.40099 4.76818 9.19714 4.54675 8.97571L3.03516 7.46411L3.96313 6.53613L5.47473 8.04773C5.7169 8.28989 5.86196 8.43389 5.97888 8.52795C6.08597 8.61409 6.10875 8.60701 6.08997 8.604C6.11259 8.60758 6.13571 8.60758 6.15833 8.604C6.13954 8.60701 6.16232 8.61409 6.26941 8.52795C6.38633 8.43389 6.53139 8.28989 6.77356 8.04773L10.0352 4.78613L10.9631 5.71411Z" fill="#22c55e"/></svg>';
    }
    if (status === 'in_progress') {
        return '<svg width="14" height="14" viewBox="0 0 14 14" fill="none" style="animation:todo-spin 1s linear infinite;"><circle cx="7" cy="7" r="6.4" stroke="var(--primary-color)" stroke-width="1.2" stroke-dasharray="4 4"/></svg>';
    }
    // pending
    return '<svg width="14" height="14" viewBox="0 0 14 14" fill="none"><circle cx="7" cy="7" r="6.4" stroke="var(--ink-3)" stroke-width="1.2" stroke-dasharray="2.4 2.4"/></svg>';
}

// 更新 Todo List（deepseek-harness 风格）
// 最近一次计划项的本地副本（手动勾选/编辑只改界面，不反向驱动模型）
var _todoItems = [];

function _normalizeTodoItems(items) {
    return (items || []).map(function (item) {
        if (typeof item === 'string') return { text: item, done: false, status: 'pending' };
        var done = item && item.done === true;
        return {
            text: (item && item.text) || '',
            done: done,
            status: (item && item.status) || (done ? 'completed' : 'pending'),
        };
    });
}

function _toggleTodoItem(index) {
    var item = _todoItems[index];
    if (!item) return;
    item.done = !item.done;
    item.status = item.done ? 'completed' : 'pending';
    updateTodoList(_todoItems.slice());
}

function _editTodoItem(index, el) {
    var item = _todoItems[index];
    if (!item || !el) return;
    el.setAttribute('contenteditable', 'true');
    el.focus();
    el.classList.add('editing');
    var finish = function (save) {
        el.removeAttribute('contenteditable');
        el.classList.remove('editing');
        if (save) {
            var text = (el.textContent || '').trim();
            if (text) item.text = text;
        }
        updateTodoList(_todoItems.slice());
    };
    el.onblur = function () { finish(true); };
    el.onkeydown = function (ev) {
        if (ev.key === 'Enter') { ev.preventDefault(); el.blur(); }
        else if (ev.key === 'Escape') { ev.preventDefault(); el.onblur = null; finish(false); }
    };
}

function updateTodoList(items) {
    var panel = document.getElementById('chat-todo-panel');
    var list = document.getElementById('chat-todo-list');
    if (!panel || !list) return;
    
    _todoItems = _normalizeTodoItems(items);

    if (!_todoItems.length) {
        // 清空 todo list 并隐藏面板
        list.innerHTML = '';
        panel.style.display = 'none';
        if (_currentAgentStream && _currentAgentStream.planEl) {
            _currentAgentStream.planEl.remove();
            _currentAgentStream.planEl = null;
        }
        return;
    }
    
    // 显示面板
    panel.style.display = 'flex';
    
    // 计算进度摘要
    var doneCount = items.filter(function(item) {
        return typeof item === 'object' && item.done === true;
    }).length;
    var activeCount = items.filter(function(item) {
        return typeof item === 'object' && item.status === 'in_progress';
    }).length;
    var pendingCount = items.length - doneCount - activeCount;
    var progressParts = [];
    if (doneCount > 0) progressParts.push(doneCount + ' 完成');
    if (activeCount > 0) progressParts.push(activeCount + ' 进行中');
    if (pendingCount > 0) progressParts.push(pendingCount + ' 待处理');
    var progressText = progressParts.length > 0 ? progressParts.join(' · ') : items.length + ' 项';
    
    // 更新头部进度
    var header = panel.querySelector('.chat-todo-header');
    var progressEl = panel.querySelector('.chat-todo-progress');
    if (progressEl) progressEl.textContent = progressText;
    
    // 构建 todo items
    var html = '';
    for (var i = 0; i < items.length; i++) {
        var item = items[i];
        var text = typeof item === 'string' ? item : (item.text || '');
        var done = typeof item === 'object' && item.done === true;
        var status = typeof item === 'object' && item.status ? item.status : (done ? 'completed' : 'pending');
        var cls = 'chat-todo-item' + (done ? ' done' : '');
        if (status === 'in_progress') cls += ' in-progress';
        html += '<div class="' + cls + '" data-index="' + i + '">' +
            '<span class="todo-check" onclick="_toggleTodoItem(' + i + ')" title="点击切换完成状态">' + _todoSvgGlyph(status) + '</span>' +
            '<span class="todo-text" ondblclick="_editTodoItem(' + i + ', this)" title="双击修改这条计划">' + escapeHtml(text) + '</span>' +
            '</div>';
    }
    list.innerHTML = html;
    
    // 展开列表
    list.classList.remove('collapsed');
    var chevron = panel.querySelector('.chat-todo-chevron');
    if (chevron) chevron.classList.remove('open');
    
    // 检查是否所有项都已完成 → 自动隐藏
    var allDone = items.every(function(item) {
        return typeof item === 'object' && item.done === true;
    });

    // 同时在当前消息流顶部渲染一份计划块（DSH 的位置），全部完成时收成一行。
    // 有活跃回合时以消息流内的计划块为准，隐藏顶部 dock，避免同一份计划出现两次。
    if (_syncPlanToStream(html, progressText, allDone)) {
        panel.style.display = 'none';
    }
    if (allDone) {
        // 给一点动画完成时间，然后清空
        setTimeout(function() {
            list.innerHTML = '';
            panel.style.display = 'none';
        }, 1200);
    }
}

// 把计划块同步到当前回合的消息流顶部
function _syncPlanToStream(rowsHtml, progressText, allDone) {
    var stream = _currentAgentStream;
    if (!stream || !stream.toolStatusEl) return false;
    var card = stream.planEl;
    if (!card || !card.isConnected) {
        card = document.createElement('div');
        card.className = 'dsh-plan-card';
        stream.toolStatusEl.insertBefore(card, stream.toolStatusEl.firstChild);
        stream.planEl = card;
    }
    card.classList.toggle('collapsed', !!allDone);
    card.innerHTML = '<div class="dsh-plan-head"><i class="fas fa-list-check"></i> 计划 · ' +
        escapeHtml(progressText) + '</div>' +
        (allDone ? '' : '<div class="dsh-plan-body">' + rowsHtml + '</div>');
    return true;
}

// 标记某个 todo 项为完成
function markTodoDone(index) {
    var panel = document.getElementById('chat-todo-panel');
    var list = document.getElementById('chat-todo-list');
    if (!list) return;
    
    var items = list.querySelectorAll('.chat-todo-item');
    if (index >= 0 && index < items.length) {
        var item = items[index];
        item.classList.add('done', 'completing');
        // 更新 SVG 图标为完成状态
        var check = item.querySelector('.todo-check');
        if (check) check.innerHTML = _todoSvgGlyph('completed');
        // 更新进度摘要
        updateTodoProgress(panel);
        // 检查是否所有都已完成
        var allDone = true;
        for (var i = 0; i < items.length; i++) {
            if (!items[i].classList.contains('done')) {
                allDone = false;
                break;
            }
        }
        if (allDone && panel) {
            setTimeout(function() {
                list.innerHTML = '';
                panel.style.display = 'none';
            }, 1200);
        }
    }
}

// 更新 Todo 进度摘要
function updateTodoProgress(panel) {
    if (!panel) panel = document.getElementById('chat-todo-panel');
    if (!panel) return;
    var list = panel.querySelector('.chat-todo-list');
    if (!list) return;
    var items = list.querySelectorAll('.chat-todo-item');
    var doneCount = 0;
    var activeCount = 0;
    for (var i = 0; i < items.length; i++) {
        if (items[i].classList.contains('done')) doneCount++;
        if (items[i].classList.contains('in-progress')) activeCount++;
    }
    var pendingCount = items.length - doneCount - activeCount;
    var progressParts = [];
    if (doneCount > 0) progressParts.push(doneCount + ' 完成');
    if (activeCount > 0) progressParts.push(activeCount + ' 进行中');
    if (pendingCount > 0) progressParts.push(pendingCount + ' 待处理');
    var progressEl = panel.querySelector('.chat-todo-progress');
    if (progressEl) progressEl.textContent = progressParts.length > 0 ? progressParts.join(' · ') : items.length + ' 项';
}

// 切换 Todo 列表折叠/展开
function toggleTodoCollapse() {
    var list = document.getElementById('chat-todo-list');
    var chevron = document.getElementById('chat-todo-chevron');
    if (list) {
        list.classList.toggle('collapsed');
    }
    if (chevron) {
        chevron.classList.toggle('open');
    }
}

// 清空 Todo List
function clearTodoList() {
    var panel = document.getElementById('chat-todo-panel');
    var list = document.getElementById('chat-todo-list');
    if (list) list.innerHTML = '';
    if (panel) panel.style.display = 'none';
}

// ============= 处理 Agent SSE 事件（deepseek-harness 风格） =============

// DSH 工具行图标（细线框，14px，与 DeepSeek Harness 视觉一致）
function _dshToolIcon(toolName) {
    var name = String(toolName || '').toLowerCase();
    var groups = {
        run: ['bash', 'execute_command', 'execute', 'run_command', 'command_prompt_execute'],
        read: ['read', 'read_file', 'read_files', 'read_file_lines', 'list_files', 'list_directory',
               'list_tree', 'get_file_info', 'csv_preview', 'zip_list', 'file_hash', 'diff_files'],
        write: ['write', 'write_file', 'write_files', 'append_file', 'edit', 'edit_file', 'edit_files',
                'rename_file', 'unzip_file'],
        search: ['grep', 'grep_files', 'search', 'search_files', 'search_codebase', 'glob', 'web_search', 'web_fetch'],
        remove: ['delete_file', 'move_file', 'copy_file'],
        todo: ['todo_list', 'todo_write'],
        image: ['show_image', 'display_image', 'view_image', 'take_screenshot', 'screenshot', 'capture_screen']
    };
    var kind = 'default';
    for (var k in groups) {
        if (groups[k].indexOf(name) !== -1) { kind = k; break; }
    }
    var head = '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.2" ' +
        'stroke-linecap="round" stroke-linejoin="round">';
    var paths = {
        run: '<path d="M3.2 4.4 6.8 8l-3.6 3.6"/><path d="M8.8 11.6h4"/>',
        read: '<path d="M4 2.6h5.1L12 5.5v7.9H4z"/><path d="M9.1 2.6v3h2.9"/>',
        write: '<path d="M9.6 2.8H4.2c-.8 0-1.4.6-1.4 1.4v7.6c0 .8.6 1.4 1.4 1.4h7.6c.8 0 1.4-.6 1.4-1.4V7.2"/>' +
               '<path d="m7.9 8.9 4.6-4.6 1.2 1.2-4.6 4.6-1.6.4z"/>',
        search: '<circle cx="7.2" cy="7.2" r="3.6"/><path d="m10 10 3.2 3.2"/>',
        remove: '<path d="M3.4 4.6h9.2M6.4 4.6V3h3.2v1.6M4.8 4.6l.6 8h5.2l.6-8"/>',
        todo: '<path d="m2.6 4.4.9.9 1.5-1.7"/><path d="M6.8 4.6h6.6M6.8 8h6.6M6.8 11.4h6.6"/>' +
              '<path d="m2.6 7.8.9.9 1.5-1.7M2.6 11.2l.9.9 1.5-1.7"/>',
        image: '<rect x="2.6" y="3.4" width="10.8" height="9.2" rx="1.6"/><circle cx="6" cy="6.4" r="1"/>' +
               '<path d="m3.6 11.6 3-3 2.4 2.4 1.8-1.8 1.6 1.6"/>',
        default: '<rect x="3.2" y="3.2" width="9.6" height="9.6" rx="2.4"/>'
    };
    return head + paths[kind] + '</svg>';
}

// 写入类工具的大小与增删行统计（DSH 的 1KB +8 -0）
function _renderWriteStats(toolName, args) {
    if (!args) return '';
    var name = String(toolName || '').toLowerCase();
    if (!/write|edit|create/.test(name)) return '';
    var isEdit = /edit/.test(name);
    var text = isEdit
        ? (args.new_text || args.new_string || args.content || '')
        : (args.content || args.text || '');
    if (!text) return '';
    var oldText = isEdit ? (args.old_text || args.old_string || '') : '';
    var bytes = 0;
    try {
        bytes = new TextEncoder().encode(text).length;
    } catch (e) {
        bytes = text.length;
    }
    var size = bytes >= 1024 ? (bytes / 1024).toFixed(1).replace(/\.0$/, '') + 'KB' : bytes + 'B';
    var added = text.split('\n').length;
    var removed = oldText ? oldText.split('\n').length : 0;
    return '<span class="dsh-tool-meta">' + size + '</span>' +
        '<span class="dsh-tool-stat add">+' + added + '</span>' +
        '<span class="dsh-tool-stat del">-' + removed + '</span>';
}

// 创建 DisclosureRow 风格的工具行（deepseek-harness 模式）
function _createToolCard(toolName, toolArgs, running) {
    var card = document.createElement('div');
    card.className = 'dsh-tool-row' + (running ? ' running' : '');
    card._toolName = toolName;

    // 构建摘要文本（运行中/完成后都保留同一句意图描述）
    var summary = _renderToolArgsSummary(toolName, toolArgs);
    card._intentSummary = summary;
    var isPath = /[\\/]/.test(summary) && !/\s/.test(summary.trim());
    var statsHtml = _renderWriteStats(toolName, toolArgs);

    card.innerHTML = `
        <div class="dsh-tool-row-header" onclick="_toggleToolCardBody(this)">
            <span class="dsh-tool-leading">${_dshToolIcon(toolName)}</span>
            <span class="dsh-tool-title">${escapeHtml(_getToolDisplayName(toolName))}</span>
            <span class="dsh-tool-sep">·</span>
            <span class="dsh-tool-summary${isPath ? ' path' : ''}">${escapeHtml(summary)}</span>
            ${statsHtml}
            <span class="dsh-tool-chevron"><i class="fas fa-chevron-down"></i></span>
        </div>
        <div class="dsh-tool-body">
            <div class="dsh-io-section">
                <span class="dsh-io-label">IN</span>
                <span class="dsh-io-text">${_renderToolArgs(toolArgs || {})}</span>
            </div>
        </div>
    `;
    return card;
}

// 工具分组徽标：同一行内连续同类调用显示 ×N
function _updateToolGroupBadge(row, count) {
    var header = row.querySelector('.dsh-tool-row-header');
    if (!header) return;
    var badge = header.querySelector('.dsh-tool-count');
    if (!badge) {
        badge = document.createElement('span');
        badge.className = 'dsh-tool-count';
        var chevron = header.querySelector('.dsh-tool-chevron');
        header.insertBefore(badge, chevron || null);
    }
    badge.textContent = '×' + count;
}

// 切换工具卡片的展开/折叠
function _toggleToolCardBody(headerEl) {
    var body = headerEl.nextElementSibling;
    if (!body) return;
    body.classList.toggle('open');
    var chevron = headerEl.querySelector('.dsh-tool-chevron');
    if (chevron) chevron.classList.toggle('open');
}

// 从工具结果里提取可展示的错误文本（优先结构化字段）
function _toolResultErrorText(result) {
    var obj = result;
    if (typeof result === 'string') {
        var trimmed = result.trim();
        if (trimmed.charAt(0) === '{' || trimmed.charAt(0) === '[') {
            try { obj = JSON.parse(trimmed); } catch (e) { obj = null; }
        } else {
            obj = null;
        }
        if (obj === null) {
            var lines = trimmed.split('\n').filter(function (l) { return l.trim(); });
            return lines[0] || '';
        }
    }
    if (obj && typeof obj === 'object') {
        var t = obj.error || obj.message || obj.stderr || '';
        if (!t && obj.output) t = String(obj.output);
        if (t) {
            var out = String(t).trim().split('\n').filter(function (l) { return l.trim(); });
            return out[0] || '';
        }
    }
    return '';
}

// 提取退出码（结果文本或结构化字段里的 exit_code / 退出码 N）
function _extractExitCode(result) {
    var obj = result;
    if (typeof result === 'string') {
        try { obj = JSON.parse(result); } catch (e) { obj = null; }
    }
    if (obj && typeof obj === 'object') {
        var code = obj.exit_code != null ? obj.exit_code : (obj.exitCode != null ? obj.exitCode : obj.code);
        if (typeof code === 'number' && code !== 0) return code;
    }
    var text = typeof result === 'string' ? result : JSON.stringify(result || '');
    var m = text.match(/退出码\s*(\d+)/) || text.match(/exit(?:ed)?\s*(?:with\s*)?(?:code)?\s*[:=]?\s*(\d+)/i);
    if (m) {
        var n = parseInt(m[1], 10);
        if (n) return n;
    }
    return 0;
}

// 按工具类型挑富渲染（renderReadCard 等原来都是死代码）
function _renderRichToolBody(toolName, result) {
    var name = String(toolName || '').toLowerCase();
    var parsed = result;
    if (typeof result === 'string') {
        var t = result.trim();
        if (t.charAt(0) === '{' || t.charAt(0) === '[') {
            try { parsed = JSON.parse(t); } catch (e) { parsed = null; }
        } else {
            parsed = null;
        }
    }
    if (!parsed || typeof parsed !== 'object') return '';

    if (name === 'read_file' || name === 'read' || name === 'read_text_file') {
        var content = parsed.content;
        if (typeof content !== 'string' || !content) return '';
        var lines = content.split('\n');
        return renderReadCard(parsed.path || '', lines, 0, parsed.lines || lines.length);
    }

    if (name === 'read_file_lines') {
        var chunk = parsed.content;
        if (typeof chunk !== 'string' || !chunk) return '';
        var startLine = Math.max(1, parseInt(parsed.start || 1, 10) || 1);
        return renderReadCard(parsed.path || '', chunk.split('\n'),
            startLine - 1, parsed.total_lines || (startLine + chunk.split('\n').length - 1));
    }

    if (name === 'grep_files') {
        var hits = parsed.matches || [];
        if (!hits.length) return '';
        var rows = hits.slice(0, 40).map(function (m) {
            return '<div class="dsh-grep-line">' +
                '<span class="dsh-grep-loc">' + escapeHtml(m.path || '') + ':' + (m.line || 0) + '</span>' +
                '<span class="dsh-grep-text">' + escapeHtml(String(m.text || '')) + '</span></div>';
        }).join('');
        var more = hits.length > 40 ? '<div class="dsh-tool-output-more">… 共 ' + hits.length + ' 条命中</div>' : '';
        return '<div class="dsh-grep-block">' + rows + more + '</div>';
    }

    if (name === 'diff_files') {
        var dtext = String(parsed.diff || '');
        if (parsed.identical || !dtext) {
            return '<div class="dsh-diff-block"><div class="dsh-diff-header">两文件内容一致</div></div>';
        }
        var lines = dtext.split('\n').slice(0, 400).map(function (line) {
            var cls = 'dsh-diff-line';
            if (line.indexOf('+++') === 0 || line.indexOf('---') === 0 || line.indexOf('@@') === 0) cls += ' meta';
            else if (line.charAt(0) === '+') cls += ' add';
            else if (line.charAt(0) === '-') cls += ' del';
            return '<div class="' + cls + '">' + escapeHtml(line) + '</div>';
        }).join('');
        return '<div class="dsh-diff-block"><div class="dsh-diff-header">' +
            '<span class="dsh-tool-stat add">+' + (parsed.added || 0) + '</span>' +
            '<span class="dsh-tool-stat del">-' + (parsed.removed || 0) + '</span></div>' +
            '<div class="dsh-diff-body">' + lines + '</div></div>';
    }

    if (name === 'list_tree') {
        var tree = parsed.entries || [];
        if (!tree.length) return '';
        var treeHtml = tree.slice(0, 200).map(function (e) {
            var pad = 8 + (e.depth - 1) * 14;
            var icon = e.type === 'dir' ? 'fa-folder' : 'fa-file-lines';
            return '<div class="dsh-tree-line" style="padding-left:' + pad + 'px">' +
                '<i class="fas ' + icon + '"></i> ' + escapeHtml(e.path || '') + '</div>';
        }).join('');
        return '<div class="dsh-tree-block">' + treeHtml + '</div>';
    }

    if (name === 'file_hash') {
        return '<div class="dsh-read-block"><div class="dsh-read-banner">' +
            '<span class="dsh-read-label"><i class="fas fa-fingerprint"></i> ' +
            escapeHtml(parsed.path || '') + '</span>' +
            '<span class="dsh-read-count">' + escapeHtml(parsed.algorithm || '') + '</span></div>' +
            '<div class="dsh-read-body"><code class="dsh-hash">' + escapeHtml(parsed.hash || '') + '</code></div></div>';
    }

    if (name === 'write_file' || name === 'edit_file' || name === 'edit') {
        if (!parsed.path) return '';
        var size = parsed.size;
        var unit = (typeof size === 'number') ? ' · ' + formatFileSize(size) : '';
        return '<div class="dsh-read-block">' +
            '<div class="dsh-read-banner">' +
            '<span class="dsh-read-label"><i class="fas fa-file-pen"></i> ' + escapeHtml(parsed.path) + '</span>' +
            '<span class="dsh-read-count">已写入' + unit + '</span>' +
            '</div></div>';
    }

    return '';
}

// 毫秒 → 人读耗时（DSH 工具行尾部的 0.8s / 1.4s）
function _formatDurationMs(ms) {
    if (typeof ms !== 'number' || !isFinite(ms) || ms < 0) return '';
    if (ms < 1000) return Math.round(ms) + 'ms';
    if (ms < 60000) return (ms / 1000).toFixed(1) + 's';
    var m = Math.floor(ms / 60000);
    var s = Math.round((ms % 60000) / 1000);
    return m + 'm' + s + 's';
}

// 更新工具行结果：成功保留意图摘要，失败改为错误首行 + 退出码徽标
function _updateToolCardResult(card, toolName, result, success, meta) {
    meta = meta || {};
    card.classList.remove('running');
    var header = card.querySelector('.dsh-tool-row-header');
    var summaryEl = card.querySelector('.dsh-tool-summary');

    if (!success) {
        var errLine = _toolResultErrorText(result) || '执行失败';
        if (summaryEl) {
            summaryEl.textContent = errLine;
            summaryEl.classList.add('error');
            summaryEl.classList.remove('path');
        }
        if (header) header.classList.add('failed');
        var code = (typeof meta.exit_code === 'number' && meta.exit_code !== 0)
            ? meta.exit_code
            : _extractExitCode(result);
        if (code && header && !header.querySelector('.dsh-tool-badge')) {
            var badge = document.createElement('span');
            badge.className = 'dsh-tool-badge';
            badge.textContent = '退出码 ' + code;
            var chevron = header.querySelector('.dsh-tool-chevron');
            header.insertBefore(badge, chevron || null);
        }
    }

    // 耗时徽标：DSH 工具行尾部显示本次执行耗时（成功/失败都有）
    if (header && typeof meta.duration_ms === 'number' && !header.querySelector('.dsh-tool-duration')) {
        var durText = _formatDurationMs(meta.duration_ms);
        if (durText) {
            var durEl = document.createElement('span');
            durEl.className = 'dsh-tool-duration';
            durEl.textContent = durText;
            var durChevron = header.querySelector('.dsh-tool-chevron');
            header.insertBefore(durEl, durChevron || null);
        }
    }

    // 添加结果到展开体
    var body = card.querySelector('.dsh-tool-body');
    if (body && result) {
        var resultText = typeof result === 'string' ? result : JSON.stringify(result, null, 2);
        // 检查是否已有结果部分
        var existingResult = body.querySelector('.dsh-io-section.result');
        // 分组行每次调用都要单独留一份 OUT，不能互相覆盖
        var isGroup = (parseInt(card.dataset.count || '1', 10) || 1) > 1;
        if (!existingResult || isGroup) {
            var divider = document.createElement('div');
            divider.className = 'dsh-io-divider';
            var resultSection = document.createElement('div');
            resultSection.className = 'dsh-io-section result';
            // 完整输出给到 6000 字符，超出部分明确标注（原来只给 1000 且无提示）
            var TRUNC_LIMIT = 6000;
            var clipped = resultText.length > TRUNC_LIMIT;
            var shown = clipped ? resultText.slice(0, TRUNC_LIMIT) : resultText;
            // 按工具类型富渲染（读取 → 带行号卡片，写入 → 路径卡），否则退回纯文本
            var richHtml = _renderRichToolBody(toolName, result);
            resultSection.innerHTML = '<span class="dsh-io-label">OUT</span>' +
                (richHtml || ('<span class="dsh-io-text dsh-tool-output">' + escapeHtml(shown) +
                    (clipped ? '<div class="dsh-tool-output-more">… 已截断，共 ' + resultText.length + ' 字符</div>' : '') +
                    '</span>'));
            body.appendChild(divider);
            body.appendChild(resultSection);
        }
        // 图片展示工具：直接在工具行内渲染图片
        var imgInfo = _parseImageResult(result);
        if (imgInfo && success) {
            var imgWrap = document.createElement('div');
            imgWrap.className = 'dsh-tool-image';
            var imgHtml = '<img src="' + encodeURI(imgInfo.url) + '" alt="' + escapeHtml(imgInfo.name) + '" loading="lazy" />';
            if (imgInfo.caption) {
                imgHtml = '<div class="dsh-tool-image-caption">' + escapeHtml(imgInfo.caption) + '</div>' + imgHtml;
            }
            imgWrap.innerHTML = imgHtml;
            body.appendChild(imgWrap);
        }
    }
}

// 解析图片展示工具的结果，返回 {url,name,caption,path}（非图片工具返回 null）
function _parseImageResult(result) {
    if (!result) return null;
    var obj = result;
    if (typeof result === 'string') {
        try { obj = JSON.parse(result); } catch (e) { return null; }
    }
    if (!obj || typeof obj !== 'object') return null;
    var url = obj.url || '';
    // 兼容没有显式 url 但给了 path 的场景
    if (!url && obj.path && typeof obj.path === 'string') {
        url = '/api/computer/image/view?path=' + encodeURIComponent(obj.path);
    }
    if (!url) return null;
    return {
        url: url,
        name: obj.name || (obj.path ? String(obj.path).split(/[\\/]/).pop() : '图片'),
        caption: obj.caption || '',
        path: obj.path || '',
    };
}

// 工具参数摘要生成
function _renderToolArgsSummary(toolName, args) {
    if (!args) return '';
    if (typeof args === 'string') {
        try { args = JSON.parse(args); } catch (e) { return args.slice(0, 60); }
    }
    var name = String(toolName || '').toLowerCase();
    var isCommand = /command|bash|shell|exec|terminal/.test(name);
    // 命令类优先用描述（DSH 行显示的是「这句话在干什么」而不是整条命令）
    if (isCommand && args.description) return String(args.description);
    // 对比类工具
    if (args.path_a) {
        var pair = String(args.path_a);
        if (args.path_b) pair += ' ↔ ' + String(args.path_b);
        return pair;
    }
    // 检索类优先显示正则 + 范围
    if (name === 'grep_files' && args.pattern) {
        return '/' + String(args.pattern) + '/  ' + (args.path || '当前目录');
    }
    // 文件路径类工具
    if (args.path) return args.path;
    if (args.file_path) return args.file_path;
    if (args.file) return args.file;
    if (args.old_path) return args.old_path;
    // 命令类工具
    if (args.command) return args.command.slice(0, 80);
    if (args.cmd) return args.cmd.slice(0, 80);
    // 搜索类
    if (args.query) return args.query.slice(0, 60);
    if (args.pattern) return args.pattern.slice(0, 60);
    // 其他
    return JSON.stringify(args).slice(0, 60);
}

// 创建 Think 风格推理显示（deepseek-harness ReasoningRow）
// 内容不直接写入，而是进打字机缓冲，实现逐字展示
function _createReasoningRow(content, running) {
    var row = document.createElement('div');
    row.className = 'dsh-reasoning-row' + (running ? ' running' : '');
    row._acc = '';
    row._buf = '';
    row._timer = null;

    // 第一行作为摘要
    var firstLine = content.split('\n')[0] || '正在思考...';

    row.innerHTML = `
        <div class="dsh-reasoning-header" onclick="var b=this.nextElementSibling;b.classList.toggle('open');var c=this.querySelector('.dsh-tool-chevron');if(c)c.classList.toggle('open');">
            <span class="dsh-reasoning-icon">${_dshThinkIcon()}</span>
            <span class="dsh-reasoning-title">思考</span>
            <span class="dsh-reasoning-sep">·</span>
            <span class="dsh-reasoning-summary">${escapeHtml(firstLine)}</span>
            <button type="button" class="dsh-reasoning-copy" title="复制思考" onclick="event.stopPropagation();copyReasoning(this)"><i class="fas fa-copy"></i></button>
            <span class="dsh-tool-chevron"><i class="fas fa-chevron-down"></i></span>
        </div>
        <div class="dsh-reasoning-body"></div>
    `;
    // 首帧内容交给打字机（正文默认折叠，展开后可见完整内容）
    _updateReasoningContent(row, content);
    return row;
}

// 历史消息里的思考行（静态版：默认折叠，点开看完整思考）
function _historyReasoningRowHtml(text, thinkMs) {
    var full = String(text || '');
    if (!full.trim()) return '';
    var firstLine = (full.split('\n')[0] || '思考').trim();
    if (firstLine.length > 80) firstLine = firstLine.slice(0, 80) + '…';
    var dur = (Number(thinkMs) > 0)
        ? '<span class="dsh-reasoning-dur">' + (Number(thinkMs) / 1000).toFixed(1) + 's</span>'
        : '';
    return '<div class="dsh-reasoning-row history">' +
        '<div class="dsh-reasoning-header" onclick="var b=this.nextElementSibling;b.classList.toggle(\'open\');var c=this.querySelector(\'.dsh-tool-chevron\');if(c)c.classList.toggle(\'open\');">' +
        '<span class="dsh-reasoning-icon">' + _dshThinkIcon() + '</span>' +
        '<span class="dsh-reasoning-title">思考</span>' +
        '<span class="dsh-reasoning-sep">·</span>' +
        '<span class="dsh-reasoning-summary">' + escapeHtml(firstLine) + '</span>' +
        dur +
        '<button type="button" class="dsh-reasoning-copy" title="复制思考" onclick="event.stopPropagation();copyReasoning(this)"><i class="fas fa-copy"></i></button>' +
        '<span class="dsh-tool-chevron"><i class="fas fa-chevron-down"></i></span>' +
        '</div>' +
        '<div class="dsh-reasoning-body"><div class="dsh-io-text">' + escapeHtml(full) + '</div></div>' +
        '</div>';
}

// 复制单条思考（实时行用累积文本，历史行读 DOM）
function copyReasoning(el) {
    var row = el && el.closest ? el.closest('.dsh-reasoning-row') : null;
    if (!row) return;
    var body = row.querySelector('.dsh-reasoning-body');
    var text = row._acc ? String(row._acc) : (body ? body.textContent : '');
    if (!text || !text.trim()) { showToast('这条思考还没有内容', 'error'); return; }
    if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(function () {
            showToast('思考内容已复制', 'success');
        }).catch(function () {
            showToast('复制失败：浏览器拒绝访问剪贴板', 'error');
        });
    } else {
        showToast('当前环境不支持剪贴板 API', 'error');
    }
}

// 批量展开 / 折叠所有思考行（实时 + 历史）
function _setAllReasoning(open) {
    var rows = document.querySelectorAll('.dsh-reasoning-row');
    var n = 0;
    rows.forEach(function (row) {
        var body = row.querySelector('.dsh-reasoning-body');
        if (!body) return;
        body.classList.toggle('open', !!open);
        var chev = row.querySelector('.dsh-tool-chevron');
        if (chev) chev.classList.toggle('open', !!open);
        n++;
    });
    showToast((open ? '已展开 ' : '已折叠 ') + n + ' 条思考', 'success');
}

function expandAllReasoning() { _setAllReasoning(true); }
function collapseAllReasoning() { _setAllReasoning(false); }

// 思考行图标（方框 + 叉，对应 DSH 的 Think 行）
function _dshThinkIcon() {
    return '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.2" ' +
        'stroke-linecap="round" stroke-linejoin="round">' +
        '<rect x="2.6" y="2.6" width="10.8" height="10.8" rx="2.2"/>' +
        '<path d="m6 6 4 4M10 6l-4 4"/></svg>';
}

// 打字机：把 row._buf 中的内容逐字渲染到 body
function _reasoningTypewriter(row) {
    if (row._timer) return;
    var body = row.querySelector('.dsh-reasoning-body');
    if (!body) return;
    row._timer = setInterval(function () {
        if (row._buf && row._buf.length > 0) {
            var n = Math.min(3, row._buf.length);
            body.textContent += row._buf.slice(0, n);
            row._buf = row._buf.slice(n);
            body.scrollTop = body.scrollHeight;
            scrollToBottom();
        } else {
            clearInterval(row._timer);
            row._timer = null;
        }
    }, 16);
}

// 更新推理内容（追加 delta 到打字机缓冲，实现逐字展示而非整块替换）
function _updateReasoningContent(row, content) {
    if (!row) return;
    row._acc = (row._acc || '') + content;
    row._buf = (row._buf || '') + content;
    _reasoningTypewriter(row);
    // 更新摘要为最新行
    var summary = row.querySelector('.dsh-reasoning-summary');
    if (summary && row._acc) {
        var lines = row._acc.trimEnd().split('\n');
        summary.textContent = lines[lines.length - 1] || lines[0] || '思考中...';
    }
}

// ============= 子代理卡片（spawn_subagent / delegate_to_agent 可视化） =============
// 设计上把子代理当成「一个会自己动手的嵌套面板」：头部是身份与实时状态，
// 中间滚动展示它自己的工具调用步骤，底部汇总轮次/耗时/工具数。
// 关键点是让用户看得见主 agent 把任务派出去之后，子代理到底做了什么。

function _subagentCards(stream) {
    if (!stream._subagentCards) stream._subagentCards = {};
    return stream._subagentCards;
}

function _appendSubagentCard(stream, data) {
    const id = data.id || ('sa_' + Math.random().toString(36).slice(2, 8));
    const isBg = !!data.background;
    const card = document.createElement('div');
    card.className = 'dsh-subagent-row running' + (isBg ? ' background' : '');
    card.dataset.subagentId = id;
    const depth = parseInt(data.depth || 0, 10);
    card.innerHTML =
        '<div class="dsh-subagent-head">' +
            '<span class="dsh-subagent-avatar">' + escapeHtml(data.avatar || '🧩') + '</span>' +
            '<span class="dsh-subagent-name">' + escapeHtml(data.label || data.name || '子代理') + '</span>' +
            '<span class="dsh-subagent-tag">' + (isBg ? '后台' : '子代理') + '</span>' +
            (depth > 1 ? '<span class="dsh-subagent-tag depth">第 ' + depth + ' 层</span>' : '') +
            '<span class="dsh-subagent-status">启动中…</span>' +
            (isBg ? '' : '<button type="button" class="dsh-subagent-cancel" title="中断这个子代理"' +
                ' onclick="_cancelSubagent(\'' + escapeHtml(id) + '\')">' +
                '<i class="fas fa-stop"></i> 中断</button>') +
        '</div>' +
        (data.title ? '<div class="dsh-subagent-title">' + escapeHtml(data.title) + '</div>' : '') +
        '<div class="dsh-subagent-steps"></div>' +
        '<div class="dsh-subagent-conclusion hidden"></div>' +
        '<div class="dsh-subagent-foot"></div>';
    stream.toolStatusEl.appendChild(card);
    _subagentCards(stream)[id] = card;
    return card;
}

// 结论逐字回传：往卡片底部的结论区追加文本
function _appendSubagentDelta(stream, id, text) {
    const card = _subagentCards(stream)[id];
    if (!card || !text) return;
    const box = card.querySelector('.dsh-subagent-conclusion');
    if (!box) return;
    if (box.classList.contains('hidden')) {
        box.classList.remove('hidden');
        box.textContent = '';
    }
    box.textContent += text;
    box.classList.add('typing');
}

// 中断一个正在跑的子代理
function _cancelSubagent(id) {
    if (!id) return;
    fetch('/api/subagent/runs/' + encodeURIComponent(id) + '/cancel', { method: 'POST' })
        .then(r => r.json())
        .then(d => {
            if (d && d.ok) showToast('已请求中断该子代理，它会在下一个检查点停下');
            else showToast('中断失败：' + ((d && d.error) || '该运行可能已结束'), 'error');
        })
        .catch(() => showToast('中断请求失败', 'error'));
}

function _updateSubagentStatus(stream, id, text) {
    const card = _subagentCards(stream)[id];
    if (!card) return;
    const el = card.querySelector('.dsh-subagent-status');
    if (el) el.textContent = text;
}

function _appendSubagentStep(stream, id, name, args) {
    const card = _subagentCards(stream)[id];
    if (!card) return;
    let argText = '';
    try {
        argText = JSON.stringify(args || {});
    } catch (e) {
        argText = '';
    }
    if (argText.length > 90) argText = argText.slice(0, 90) + '…';
    const line = document.createElement('div');
    line.className = 'dsh-subagent-step running';
    line.dataset.tool = name;
    line.innerHTML =
        '<span class="dsh-subagent-step-icon"><i class="fas fa-circle-notch fa-spin"></i></span>' +
        '<span class="dsh-subagent-step-name">' + escapeHtml(name) + '</span>' +
        (argText && argText !== '{}'
            ? '<span class="dsh-subagent-step-args">' + escapeHtml(argText) + '</span>'
            : '');
    const box = card.querySelector('.dsh-subagent-steps');
    if (box) box.appendChild(line);
    card._lastSubStep = line;
}

function _updateSubagentStep(stream, id, name, success, preview) {
    const card = _subagentCards(stream)[id];
    if (!card) return;
    const line = card._lastSubStep;
    if (!line) return;
    line.classList.remove('running');
    line.classList.add(success ? 'done' : 'error');
    const icon = line.querySelector('.dsh-subagent-step-icon');
    if (icon) {
        icon.innerHTML = success
            ? '<i class="fas fa-check"></i>'
            : '<i class="fas fa-times"></i>';
    }
    // 结果预览折一行挂在步骤下面，太长就截断（完整结论在子代理返回结果里）
    let brief = String(preview || '').replace(/\s+/g, ' ').trim();
    if (brief.length > 120) brief = brief.slice(0, 120) + '…';
    if (brief) {
        const out = document.createElement('div');
        out.className = 'dsh-subagent-step-out' + (success ? '' : ' error');
        out.textContent = brief;
        line.appendChild(out);
    }
}

function _finishSubagentCard(stream, id, ok, data) {
    const card = _subagentCards(stream)[id];
    if (!card) return;
    const cancelled = data.status === 'cancelled';
    card.classList.remove('running');
    card.classList.add(cancelled ? 'cancelled' : (ok ? 'done' : 'failed'));
    // 结束后收起中断按钮（任务已经不在跑了）
    const cancelBtn = card.querySelector('.dsh-subagent-cancel');
    if (cancelBtn) cancelBtn.remove();

    const statusEl = card.querySelector('.dsh-subagent-status');
    const foot = card.querySelector('.dsh-subagent-foot');
    const conclusion = card.querySelector('.dsh-subagent-conclusion');
    if (conclusion) conclusion.classList.remove('typing');

    if (ok) {
        if (statusEl) statusEl.textContent = '已完成';
    } else {
        if (statusEl) statusEl.textContent = cancelled ? '已中断' : '失败';
    }

    const bits = [];
    if (data.iterations) bits.push(data.iterations + ' 轮');
    if (typeof data.elapsed_sec === 'number') bits.push(data.elapsed_sec + 's');
    if (Array.isArray(data.tool_calls) && data.tool_calls.length) {
        bits.push(data.tool_calls.length + ' 次工具调用');
    }
    const tk = data.tokens || {};
    if (tk.total_tokens) {
        bits.push(tk.total_tokens + ' tokens（入 ' + (tk.prompt_tokens || 0) +
            ' / 出 ' + (tk.completion_tokens || 0) + '）');
    }
    if (foot) {
        if (bits.length) foot.textContent = bits.join(' · ');
        else foot.textContent = '';
    }
    if (!ok && !cancelled) {
        // 失败原因单独一行，比挤在 foot 里更好读
        const errLine = document.createElement('div');
        errLine.className = 'dsh-subagent-error';
        errLine.textContent = String(data.error || '执行失败');
        if (foot && foot.parentNode) foot.parentNode.insertBefore(errLine, foot);
    }
    const steps = card.querySelector('.dsh-subagent-steps');
    if (steps && !steps.children.length) steps.style.display = 'none';
}

// 后台任务跑完后的回灌卡片（在新一轮回复开头出现）
function _renderBackgroundResults(stream, jobs) {
    if (!jobs || !jobs.length) return;
    stream.hasToolCalls = true;
    jobs.forEach(function (job) {
        const ok = job.status === 'done';
        const card = document.createElement('div');
        card.className = 'dsh-subagent-row ' + (ok ? 'done' : 'failed') + ' background';
        card.innerHTML =
            '<div class="dsh-subagent-head">' +
                '<span class="dsh-subagent-avatar">📬</span>' +
                '<span class="dsh-subagent-name">后台任务已完成</span>' +
                '<span class="dsh-subagent-tag">' + escapeHtml(job.agent_type || '') + '</span>' +
                '<span class="dsh-subagent-status">' + (ok ? '已完成' : '未成功') + '</span>' +
            '</div>' +
            '<div class="dsh-subagent-title">' + escapeHtml(job.task || '') + '</div>' +
            '<div class="dsh-subagent-conclusion">' +
                escapeHtml(ok ? (job.result || '') : (job.error || '执行失败')) +
            '</div>';
        stream.toolStatusEl.appendChild(card);
    });
}

// ── 审批卡片（等待审批 · DeepSeek Harness 同款）──
function _renderApprovalCard(stream, data) {
    var card = document.createElement('div');
    card.className = 'dsh-approval-card';
    card.dataset.approvalId = data.id || '';
    var perm = data.permission || 'danger-full-access';
    var target = data.target || data.tool || '';
    var detail = data.detail || '';
    card.innerHTML =
        '<div class="dsh-approval-head">等待审批</div>' +
        '<div class="dsh-approval-title">允许本次操作使用 ' + escapeHtml(perm) + ' 权限：' + escapeHtml(target) + '</div>' +
        (detail ? '<div class="dsh-approval-detail">' + escapeHtml(detail) + '</div>' : '') +
        '<div class="dsh-approval-actions">' +
            '<button type="button" class="dsh-approval-btn" data-decision="deny">拒绝</button>' +
            '<button type="button" class="dsh-approval-btn primary" data-decision="allow">允许一次</button>' +
        '</div>';
    card.querySelectorAll('.dsh-approval-btn').forEach(function (btn) {
        btn.addEventListener('click', function () {
            _submitApprovalDecision(card, btn.dataset.decision);
        });
    });
    stream.toolStatusEl.appendChild(card);
    // 同时停靠到输入区上方：用户滚到历史里也看得见、点得到（DSH 的审批接管输入区）
    _showApprovalDock(data);
    scrollToBottom();
}

// 审批停靠区（Composer 上方，随消息流滚动不影响）
function _showApprovalDock(data) {
    var dock = document.getElementById('chat-approval-dock');
    if (!dock) return;
    var card = document.createElement('div');
    card.className = 'dsh-approval-card docked';
    card.dataset.approvalId = data.id || '';
    var perm = data.permission || 'danger-full-access';
    var target = data.target || data.tool || '';
    var detail = data.detail || '';
    card.innerHTML =
        '<div class="dsh-approval-head">需要你确认 · 等待审批</div>' +
        '<div class="dsh-approval-title">允许本次操作使用 ' + escapeHtml(perm) + ' 权限：' + escapeHtml(target) + '</div>' +
        (detail ? '<div class="dsh-approval-detail">' + escapeHtml(detail) + '</div>' : '') +
        '<div class="dsh-approval-actions">' +
            '<button type="button" class="dsh-approval-btn" data-decision="deny">拒绝</button>' +
            '<button type="button" class="dsh-approval-btn primary" data-decision="allow">允许一次</button>' +
        '</div>';
    card.querySelectorAll('.dsh-approval-btn').forEach(function (btn) {
        btn.addEventListener('click', function () {
            _submitApprovalDecision(card, btn.dataset.decision);
        });
    });
    dock.innerHTML = '';
    dock.appendChild(card);
    dock.style.display = 'block';
}

function _hideApprovalDock(id) {
    var dock = document.getElementById('chat-approval-dock');
    if (!dock) return;
    if (id) {
        var card = dock.querySelector('.dsh-approval-card');
        if (card && card.dataset.approvalId !== String(id)) return;
    }
    dock.style.display = 'none';
    dock.innerHTML = '';
}

function _submitApprovalDecision(card, decision) {
    var id = card.dataset.approvalId;
    if (!id || card.dataset.pending === '1') return;
    card.dataset.pending = '1';
    card.querySelectorAll('.dsh-approval-btn').forEach(function (b) { b.disabled = true; });
    fetch('/api/chat/approval-decision', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id: id, decision: decision })
    }).then(function (r) { return r.json(); }).then(function (d) {
        if (!d || !d.ok) throw new Error((d && d.error) || '提交失败');
        _resolveApprovalCard(id, decision);
    }).catch(function (e) {
        card.dataset.pending = '';
        card.querySelectorAll('.dsh-approval-btn').forEach(function (b) { b.disabled = false; });
        showToast('审批提交失败：' + e.message, 'error');
    });
}

function _resolveApprovalCard(id, decision) {
    if (!id) return;
    var sel = '.dsh-approval-card[data-approval-id="' + String(id).replace(/"/g, '') + '"]';
    var cards = document.querySelectorAll(sel);
    var text = decision === 'allow'
        ? '已允许本次操作'
        : (decision === 'deny' ? '已拒绝本次操作' : '审批已超时');
    cards.forEach(function (card) {
        card.classList.add('resolved');
        card.dataset.pending = '';
        var head = card.querySelector('.dsh-approval-head');
        if (head) head.textContent = text;
        card.querySelectorAll('.dsh-approval-btn').forEach(function (b) { b.disabled = true; });
    });
    _hideApprovalDock(id);
}

function _processAgentEvent(eventType, data) {
    if (!_currentAgentStream) return;
    
    const stream = _currentAgentStream;
    
    switch (eventType) {
        case 'thinking':
            // 占位：真正的过程展示交给思考行 / 工具行。
            // 不能在这里清空 contentEl —— DSH 内核每步都会发 thinking，
            // 清空会把已经流式出来的正文抹掉，最后只剩空白气泡。
            if (!stream.content) {
                stream.contentEl.innerHTML = '<div class="agent-thinking">' +
                    '<i class="fas fa-spinner fa-spin"></i><span>' +
                    escapeHtml(data.message || '正在思考...') + '</span></div>';
            }
            break;

        case 'engine_notice':
            // 引擎级提示（如「模拟模式下工具不会触发」），放在工具区顶部，不污染回复正文
            stream.hasToolCalls = true;
            var notice = document.createElement('div');
            notice.className = 'dsh-engine-notice' + (data.level === 'warn' ? ' warn' : '');
            notice.innerHTML =
                '<div class="dsh-engine-notice-title">' +
                '<i class="fas fa-triangle-exclamation"></i> ' +
                escapeHtml(data.title || '提示') + '</div>' +
                '<div class="dsh-engine-notice-body">' + escapeHtml(data.message || '') + '</div>';
            stream.toolStatusEl.appendChild(notice);
            scrollToBottom();
            break;
            
        case 'reasoning':
            // 显示 DeepSeek 思考过程 - deepseek-harness Think 风格
            stream.hasToolCalls = true;
            stream.lastToolRow = null;
            stream.lastToolName = '';
            const reasoningContent = data.content || '';
            // 只在「当前未收尾」的思考行上追加；工具调用后的思考另起一行（DSH 是每步一行）
            const existingReasoning = stream.toolStatusEl.querySelector('.dsh-reasoning-row:not([data-closed])');
            if (existingReasoning) {
                // 流式更新内容
                _updateReasoningContent(existingReasoning, reasoningContent);
                break;
            }
            const reasoningRow = _createReasoningRow(reasoningContent, true);
            stream.toolStatusEl.appendChild(reasoningRow);
            scrollToBottom();
            break;
            
        case 'interim':
            // 中途叙述文本（DSH 工作流中途的步骤小结），永久保留在工具区，不被工具调用覆盖
            stream.hasToolCalls = true;
            stream.lastToolRow = null;
            stream.lastToolName = '';
            var interimCard = document.createElement('div');
            interimCard.className = 'dsh-interim-row';
            interimCard.innerHTML = '<div class="dsh-interim-header">' +
                '<span class="dsh-reasoning-icon"><i class="fas fa-comment-dots" style="font-size:12px;"></i></span>' +
                '<span class="dsh-reasoning-title">小结</span>' +
                '<span class="dsh-reasoning-sep">·</span>' +
                '<span class="dsh-interim-body-text">' + escapeHtml(data.text || '') + '</span>' +
                '</div>';
            stream.toolStatusEl.appendChild(interimCard);
            scrollToBottom();
            break;

        case 'tool_call':
            // 显示工具调用 - deepseek-harness DisclosureRow 风格
            stream.hasToolCalls = true;
            stream.toolsCount = (stream.toolsCount || 0) + 1;
            // 本次思考到此为止：收尾并折回单行，后续思考另起一行
            stream.toolStatusEl.querySelectorAll('.dsh-reasoning-row:not([data-closed])').forEach(function (row) {
                row.dataset.closed = '1';
                row.classList.remove('running');
                var body = row.querySelector('.dsh-reasoning-body');
                if (body) body.classList.remove('open');
                var chevron = row.querySelector('.dsh-tool-chevron');
                if (chevron) chevron.classList.remove('open');
            });
            // 创建 DisclosureRow 风格工具行；同一回合连续同类工具合并成一行（DSH 式分组）
            const toolCard = _createToolCard(data.name || '', data.args || {}, true);
            const prevRow = stream.lastToolRow;
            const canGroup = prevRow && prevRow.isConnected
                && stream.lastToolName === (data.name || '')
                && !prevRow.classList.contains('failed');
            if (canGroup) {
                const groupCount = (parseInt(prevRow.dataset.count || '1', 10) || 1) + 1;
                prevRow.dataset.count = String(groupCount);
                prevRow.classList.add('running');
                const groupBody = prevRow.querySelector('.dsh-tool-body');
                if (groupBody) {
                    const inSec = document.createElement('div');
                    inSec.className = 'dsh-io-section';
                    inSec.innerHTML = '<span class="dsh-io-label">IN</span>' +
                        '<span class="dsh-io-text">' + _renderToolArgs(data.args || {}) + '</span>';
                    groupBody.appendChild(inSec);
                }
                _updateToolGroupBadge(prevRow, groupCount);
                if (data.call_id) stream.callCards[data.call_id] = prevRow;
            } else {
                stream.toolStatusEl.appendChild(toolCard);
                if (data.call_id) stream.callCards[data.call_id] = toolCard;
                stream.lastToolRow = toolCard;
                stream.lastToolName = data.name || '';
            }
            scrollToBottom();

            // Agent 主动调用命令行：不再弹出独立面板/终端，输出在 tool_result 时内联渲染到对话
            break;
            
        case 'tool_result':
            // 更新工具调用结果
            stream.toolsDone = (stream.toolsDone || 0) + 1;
            const toolCards = stream.toolStatusEl.querySelectorAll('.dsh-tool-row');
            // 优先按 call_id 精确回填；后端没给 call_id 时退回「最后一张卡」
            const matchedCard = (data.call_id && stream.callCards && stream.callCards[data.call_id])
                ? stream.callCards[data.call_id]
                : toolCards[toolCards.length - 1];
            var _toolOutput = data.output || data.result || data.preview || '';
            if (matchedCard) {
                _updateToolCardResult(
                    matchedCard,
                    data.name || '',
                    _toolOutput,
                    data.success,
                    data
                );
            }
            // 搜索/抓网页类工具：从结果里收集参考来源
            if (data.name && _SOURCE_TOOL_RE.test(data.name)) {
                _mergeSources(stream.sources, _extractSourceUrls(_toolOutput));
            }
            scrollToBottom();

            // 命令行工具执行完成：直接在工具卡片中内联展示输出（不再弹出独立 cmd 终端窗口）
            if (data.name === 'command_prompt_execute') {
                _handleCmdToolResult(data, matchedCard);
            }
            break;

        // ── 审批（等待用户放行越权操作）──
        case 'approval_request':
            stream.hasToolCalls = true;
            _renderApprovalCard(stream, data);
            scrollToBottom();
            break;

        case 'approval_result':
            _resolveApprovalCard(data.id, data.decision);
            break;
            
        case 'todo_list':
            // 更新 Todo List
            var todoItems = data.items || [];
            updateTodoList(todoItems);
            break;

        // ── 子代理事件（spawn_subagent / delegate_to_agent 的实时过程）──
        case 'subagent_start':
            stream.hasToolCalls = true;
            _appendSubagentCard(stream, data);
            scrollToBottom();
            break;

        case 'subagent_step':
            _updateSubagentStatus(stream, data.id, '第 ' + (data.iteration || 1) +
                (data.cap ? '/' + data.cap : '') + ' 轮');
            break;

        case 'subagent_tool_call':
            _appendSubagentStep(stream, data.id, data.name || '', data.args || {});
            scrollToBottom();
            break;

        case 'subagent_tool_result':
            _updateSubagentStep(stream, data.id, data.name || '',
                !!data.success, data.preview || '');
            scrollToBottom();
            break;

        case 'subagent_delta':
            // 子代理结论逐字回传
            _appendSubagentDelta(stream, data.id, data.text || '');
            scrollToBottom();
            break;

        case 'background_result':
            // 后台子代理任务跑完，新一轮回复开头回灌结果
            _renderBackgroundResults(stream, data.jobs || []);
            scrollToBottom();
            break;

        case 'subagent_done':
            _finishSubagentCard(stream, data.id, true, data);
            scrollToBottom();
            break;

        case 'subagent_error':
            _finishSubagentCard(stream, data.id, false, data);
            scrollToBottom();
            break;
            
        case 'todo_done':
            // 标记某个 Todo 项完成
            var todoIndex = data.index;
            if (typeof todoIndex === 'number') {
                markTodoDone(todoIndex);
            }
            break;

        case 'question':
            // 交互式提问：渲染提问卡片，等待用户回答
            stream.hasToolCalls = true;
            // 清空思考占位，渲染提问卡片
            stream.contentEl.classList.remove('typing');
            _renderQuestionCard(stream, data.questions || []);
            // 暂停计时：等待用户回答的时间不计入思考耗时
            _stopThinkTimer(stream, false, '等待回答');
            scrollToBottom();
            break;
            
        case 'usage':
            // DSH 式 meta：累计本轮 token 用量与模型名，hover 消息时可见
            var usageData = data.usage || {};
            stream.usage.input += Number(usageData.prompt_tokens || usageData.input_tokens || 0) || 0;
            stream.usage.output += Number(usageData.completion_tokens || usageData.output_tokens || 0) || 0;
            if (data.model) stream.usage.model = data.model;
            _renderStreamUsage(stream);
            break;

        case 'chunk':
            // 追加流式内容
            // 正文出现说明新一轮叙述，工具分组在此断开
            stream.lastToolRow = null;
            stream.lastToolName = '';
            const chunk = data.text || '';
            if (chunk) {
                stream.content += chunk;
                stream.contentEl.innerHTML = renderMarkdown(stream.content);
                stream.contentEl.classList.add('typing');
            }
            scrollToBottom();
            break;
            
        case 'done':
            // 完成
            stream.contentEl.classList.remove('typing');
            stream.actionsEl.style.display = '';
            // 兜底：thinking 抹掉过气泡且本步没有后续 chunk 时，用 done.content 补回正文
            if (!stream.content && data.content) {
                stream.content = data.content;
                stream.contentEl.innerHTML = renderMarkdown(stream.content);
            }
            _renderStreamUsage(stream);
            // 移除思考指示器（如果有）
            const thinkingEl = stream.contentEl.querySelector('.agent-thinking');
            if (thinkingEl) {
                thinkingEl.remove();
            }
            // 是否在等待用户回答（交互式提问已展示，等待提交）
            const awaitingInput = data.awaiting_input === true;

            // 收尾思考行：结束运行态并折回单行摘要（DSH 完成后的形态）
            if (stream.toolStatusEl) {
                stream.toolStatusEl.querySelectorAll('.dsh-reasoning-row').forEach(function (reasoningRow) {
                    reasoningRow.dataset.closed = '1';
                    reasoningRow.classList.remove('running');
                    const reasoningBody = reasoningRow.querySelector('.dsh-reasoning-body');
                    if (reasoningBody) reasoningBody.classList.remove('open');
                    const reasoningChevron = reasoningRow.querySelector('.dsh-tool-chevron');
                    if (reasoningChevron) reasoningChevron.classList.remove('open');
                });
            }
            // 定格思考计时（等待回答时暂停，不计入用户思考时间）
            if (awaitingInput) _stopThinkTimer(stream, false, '等待回答', data.think_ms);
            else _stopThinkTimer(stream, false, '', data.think_ms);
            // 一轮结束：会话标题/预览可能已更新，抽屉开着就顺手刷新
            _refreshSessionListIfOpen();
            _hideApprovalDock();
            if (typeof fetchContextInfo === 'function') fetchContextInfo();
            _currentAgentStream = null;
            _flushPendingQueue();
            break;
            
        case 'error':
            // 错误
            stream.contentEl.innerHTML = '<div class="error-message">' + escapeHtml(data.message || '未知错误') + '</div>';
            stream.actionsEl.style.display = '';
            _stopThinkTimer(stream);
            _hideApprovalDock();
            // 参考来源卡片
            try {
                if (stream.sources && stream.sources.length) {
                    var srcHtml = _sourcesBlockHtml(stream.sources);
                    if (srcHtml && !stream.contentEl.querySelector('.msg-sources')) {
                        stream.contentEl.insertAdjacentHTML('beforeend', srcHtml);
                        try { _linkifyCitations(stream.contentEl); } catch (e) { console.warn(e); }
                    }
                }
            } catch (e) { console.warn(e); }
            // 定稿后渲染公式与图表（流式过程中不渲染，避免反复重排）
            try { enhanceRichContent(stream.contentEl); } catch (e) { console.warn(e); }
            _currentAgentStream = null;
            _flushPendingQueue();
            break;
    }
}

// 渲染交互式提问卡片（text 输入 / choice 选项 / confirm 确认授权）
function _renderQuestionCard(stream, questions) {
    if (!questions || !questions.length) return;
    const contentEl = stream.contentEl;
    contentEl.innerHTML = '';

    const card = document.createElement('div');
    card.className = 'question-card';

    let html = `
        <div class="question-card-header">
            <i class="fas fa-comments"></i>
            <span>需要您确认以下内容</span>
        </div>
        <div class="question-card-body">
    `;

    questions.forEach(function (q) {
        const required = q.required ? ' <span class="question-required">*</span>' : '';
        html += '<div class="question-item" data-qid="' + escapeHtml(q.id || '') + '">';
        html += '<div class="question-label">' + escapeHtml(q.question || '') + required + '</div>';
        if (q.type === 'choice') {
            html += '<div class="question-options">';
            (q.options || []).forEach(function (opt) {
                html += '<button type="button" class="question-option" data-qid="' + escapeHtml(q.id || '') + '" data-value="' + escapeHtml(opt) + '">' + escapeHtml(opt) + '</button>';
            });
            html += '</div>';
        } else if (q.type === 'confirm') {
            html += '<div class="question-options">';
            html += '<button type="button" class="question-option confirm-yes" data-qid="' + escapeHtml(q.id || '') + '" data-value="同意">同意</button>';
            html += '<button type="button" class="question-option confirm-no" data-qid="' + escapeHtml(q.id || '') + '" data-value="拒绝">拒绝</button>';
            html += '</div>';
        } else {
            html += '<input type="text" class="question-text-input" data-qid="' + escapeHtml(q.id || '') + '" placeholder="请输入..." autocomplete="off">';
        }
        html += '</div>';
    });

    html += '</div>';
    html += '<div class="question-card-footer"><button type="button" class="question-submit-btn" onclick="submitAgentAnswers()"><i class="fas fa-paper-plane"></i> 提交回答</button></div>';

    card.innerHTML = html;
    contentEl.appendChild(card);

    // 选项单选交互
    card.querySelectorAll('.question-option').forEach(function (btn) {
        btn.addEventListener('click', function () {
            const qid = btn.dataset.qid;
            card.querySelectorAll('.question-option[data-qid="' + qid + '"]').forEach(function (b) {
                b.classList.remove('selected');
            });
            btn.classList.add('selected');
        });
    });

    // 输入框回车提交
    card.querySelectorAll('.question-text-input').forEach(function (inp) {
        inp.addEventListener('keydown', function (e) {
            if (e.key === 'Enter') {
                e.preventDefault();
                submitAgentAnswers();
            }
        });
    });

    // 保存状态供提交时收集答案
    _questionState = {
        messageDiv: stream.element,
        container: card,
        questions: questions,
        submitBtn: card.querySelector('.question-submit-btn'),
    };
}

// 收集单个问题的答案
function _getQuestionValue(q, container) {
    if (q.type === 'choice' || q.type === 'confirm') {
        const sel = container.querySelector('.question-option.selected[data-qid="' + q.id + '"]');
        return sel ? sel.dataset.value : '';
    }
    const input = container.querySelector('.question-text-input[data-qid="' + q.id + '"]');
    return input ? input.value.trim() : '';
}

// 提交交互式提问的回答，恢复 Agent 继续执行
async function submitAgentAnswers() {
    if (!_questionState) return;
    const qs = _questionState.questions;
    const answers = {};
    const missing = [];

    for (const q of qs) {
        const val = _getQuestionValue(q, _questionState.container);
        if (q.required && !val) missing.push(q.question);
        answers[q.id] = val;
    }

    if (missing.length) {
        showToast('请回答必答问题：' + missing.join('、'), 'warning');
        return;
    }

    const state = _questionState;
    state.submitBtn.disabled = true;
    state.submitBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> 提交中...';

    // 复用同一消息卡片，重建流式状态
    const msgDiv = state.messageDiv;
    _currentAgentStream = {
        element: msgDiv,
        contentEl: msgDiv.querySelector('.message-content'),
        toolStatusEl: msgDiv.querySelector('.agent-tool-status'),
        actionsEl: msgDiv.querySelector('.message-actions'),
        content: '',
        hasToolCalls: false,
        toolsCount: 0,
        toolsDone: 0,
    };
    _startThinkTimer(_currentAgentStream);
    // 显示“继续执行”占位
    _currentAgentStream.contentEl.innerHTML = '<div class="agent-thinking"><i class="fas fa-spinner fa-spin"></i><span>已收到回答，正在继续执行...</span></div>';
    scrollToBottom();

    try {
        const res = await fetch('/api/chat/agent-answer', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ answers: answers, session_id: _currentSessionId(), conv_id: _currentSessionId() }),
        });

        if (!res.ok) {
            let detail = 'HTTP ' + res.status;
            try {
                const errJson = await res.json();
                detail = errJson.detail || detail;
            } catch (e) { /* ignore */ }
            throw new Error(detail);
        }

        const reader = res.body.getReader();
        const decoder = new TextDecoder();
        let buffer = '';

        while (true) {
            const { done, value } = await reader.read();
            if (done) break;

            buffer += decoder.decode(value, { stream: true });

            const parts = buffer.split('\n\n');
            buffer = parts.pop();

            for (const part of parts) {
                const trimmed = part.trim();
                if (!trimmed) continue;

                const lines = trimmed.split('\n');
                let eventType = '';
                let eventData = '';

                for (const line of lines) {
                    if (line.startsWith('event: ')) {
                        eventType = line.slice(7).trim();
                    } else if (line.startsWith('data: ')) {
                        eventData = line.slice(6).trim();
                    }
                }

                if (eventType && eventData) {
                    try {
                        const data = JSON.parse(eventData);
                        _processAgentEvent(eventType, data);
                    } catch (e) {
                        console.warn('[Agent] SSE 解析错误:', e);
                    }
                }
            }
        }
    } catch (e) {
        console.error('[Agent] 回答请求失败:', e);
        if (_currentAgentStream) {
            _currentAgentStream.contentEl.innerHTML = '<div class="error-message">提交回答失败: ' + escapeHtml(e.message) + '</div>';
            _currentAgentStream.contentEl.classList.remove('typing');
            _stopThinkTimer(_currentAgentStream);
            _currentAgentStream.actionsEl.style.display = '';
        }
        // 失败时恢复卡片，允许重新提交
        state.submitBtn.disabled = false;
        state.submitBtn.innerHTML = '<i class="fas fa-paper-plane"></i> 提交回答';
        _questionState = state;
        return;
    }

    _questionState = null;
}

// 发送并合成语音
function sendWithTtsMessage() {
    const input = document.getElementById('message-input');
    if (!input) return;
    const content = input.value.trim();
    
    if (!content) return;
    if (!isConnected) {
        showError('WebSocket 连接未建立，请稍候重试');
        return;
    }
    
    input.value = '';
    input.style.height = 'auto';
    
    try {
        // 发送 /say 指令触发 TTS
        ws.send(JSON.stringify({ content: '/say ' + content }));
        _markMessageSent(content);
        createAiMessagePlaceholder();
    } catch (e) {
        showError('发送消息失败: ' + e.message);
        input.value = content;
        autoGrowInput(input);
        saveChatDraft();
        updateSendState();
    }
}

// 处理粘贴：图片或复制的文件统一进入附件流程（与拖拽 / 选择文件一致）
function handleImagePaste(e) {
    const items = e.clipboardData && e.clipboardData.items;
    if (!items) return;

    const files = [];
    for (let i = 0; i < items.length; i++) {
        const item = items[i];
        if (item.kind === 'file') {
            const file = item.getAsFile();
            if (file) files.push(file);
        }
    }
    if (!files.length) return;

    e.preventDefault();
    addFiles(files);
    showToast('已添加 ' + files.length + ' 个附件，可继续输入后发送', 'info');
}

function formatFileSize(bytes) {
    if (!bytes) return '';
    if (bytes < 1024) return bytes + ' B';
    if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
    return (bytes / (1024 * 1024)).toFixed(1) + ' MB';
}

function downloadFile(url) {
    if (!url) return;
    const a = document.createElement('a');
    a.href = url;
    a.download = url.split('/').pop();
    a.click();
}

function playVoiceMessage(btn, url) {
    if (!url) return;
    const icon = btn.querySelector('i');
    if (icon.classList.contains('fa-play')) {
        icon.className = 'fas fa-pause';
        const audio = new Audio(url);
        audio.play().catch(function() {});
        audio.onended = function() { icon.className = 'fas fa-play'; };
    } else {
        icon.className = 'fas fa-play';
    }
}

function scrollToMessage(msgId) {
    const el = document.querySelector('[data-msg-id="' + msgId + '"]');
    if (el) _flashMessage(el);
}

// 滚动到某个气泡并短暂高亮
function _flashMessage(el) {
    if (!el) return;
    el.scrollIntoView({ behavior: 'smooth', block: 'center' });
    el.classList.add('highlight');
    setTimeout(function() { el.classList.remove('highlight'); }, 2000);
}

// 点击气泡内的引用块：按消息 id 定位，找不到则按引用原文向前查找
function scrollToQuotedMessage(block) {
    if (!block) return;
    const selfMsg = block.closest('.message');
    const textEl = block.querySelector('.quote-text');
    const text = textEl ? (textEl.textContent || '').trim() : '';
    const msgId = block.dataset.quoteMsgId || '';
    if (msgId) {
        const target = document.querySelector('[data-msg-id="' + msgId + '"]');
        if (target) { _flashMessage(target); return; }
    }
    if (text) {
        const key = text.slice(0, 40);
        const nodes = Array.prototype.slice.call(document.querySelectorAll('#chat-messages .message'));
        const limit = selfMsg ? nodes.indexOf(selfMsg) : nodes.length;
        for (let i = limit - 1; i >= 0; i--) {
            const c = nodes[i].querySelector('.message-content');
            if (c && (c.textContent || '').indexOf(key) !== -1) { _flashMessage(nodes[i]); return; }
        }
    }
    showToast('未找到被引用的消息', 'info');
}

// 长按上下文菜单
function showMessageContextMenu(e, messageEl) {
    e.preventDefault();
    hideMessageContextMenu();
    
    const menu = document.createElement('div');
    menu.className = 'message-context-menu';
    menu.id = 'msg-context-menu';
    
    const isUser = messageEl.classList.contains('user');
    const contentEl = messageEl.querySelector('.message-content');
    const text = contentEl ? (contentEl.textContent || contentEl.innerText).trim() : '';
    const msgId = messageEl.dataset.msgId || '';
    
    menu.innerHTML = `
        <button class="ctx-menu-item" onclick="copyMessageFromMenu()">
            <span class="ctx-icon-wrap"><i class="fas fa-copy"></i></span>
            <span class="ctx-label">复制</span>
        </button>
        <button class="ctx-menu-item" onclick="quoteReplyFromMenu()">
            <span class="ctx-icon-wrap"><i class="fas fa-quote-right"></i></span>
            <span class="ctx-label">引用回复</span>
        </button>
        <div class="ctx-menu-divider"></div>
        <button class="ctx-menu-item" onclick="forwardMessageFromMenu()">
            <span class="ctx-icon-wrap"><i class="fas fa-share"></i></span>
            <span class="ctx-label">转发</span>
        </button>
        <button class="ctx-menu-item danger" onclick="deleteMessageFromMenu()">
            <span class="ctx-icon-wrap"><i class="fas fa-trash-alt"></i></span>
            <span class="ctx-label">删除</span>
        </button>
    `;
    
    // 保存上下文数据
    menu._msgText = text;
    menu._msgId = msgId;
    menu._msgTimestamp = messageEl.dataset.timestamp || '';
    menu._isUser = isUser;
    menu._messageEl = messageEl;
    
    document.body.appendChild(menu);
    
    // 定位菜单
    requestAnimationFrame(function() {
        var rect = menu.getBoundingClientRect();
        var x = e.clientX;
        var y = e.clientY;
        
        if (x + rect.width > window.innerWidth) x = window.innerWidth - rect.width - 10;
        if (y + rect.height > window.innerHeight) y = window.innerHeight - rect.height - 10;
        if (x < 10) x = 10;
        if (y < 10) y = 10;
        
        menu.style.left = x + 'px';
        menu.style.top = y + 'px';
        menu.classList.add('visible');
    });
    
    // 遮罩层
    var overlay = document.createElement('div');
    overlay.className = 'ctx-menu-overlay';
    overlay.id = 'msg-ctx-overlay';
    overlay.addEventListener('click', hideMessageContextMenu);
    overlay.addEventListener('contextmenu', function(ev) { ev.preventDefault(); hideMessageContextMenu(); });
    document.body.appendChild(overlay);
}

function hideMessageContextMenu() {
    var menu = document.getElementById('msg-context-menu');
    if (menu) {
        menu.classList.remove('visible');
        setTimeout(function() { menu.remove(); }, 150);
    }
    var overlay = document.getElementById('msg-ctx-overlay');
    if (overlay) overlay.remove();
}

function copyMessageFromMenu() {
    var menu = document.getElementById('msg-context-menu');
    var text = menu ? menu._msgText : '';
    hideMessageContextMenu();
    if (!text) return;
    navigator.clipboard.writeText(text).then(function() {
        showToast('已复制到剪贴板');
    }).catch(function() {
        var ta = document.createElement('textarea');
        ta.value = text;
        document.body.appendChild(ta);
        ta.select();
        document.execCommand('copy');
        document.body.removeChild(ta);
        showToast('已复制到剪贴板');
    });
}

function quoteReplyFromMenu() {
    var menu = document.getElementById('msg-context-menu');
    var text = menu ? menu._msgText : '';
    var isUser = menu ? menu._isUser : false;
    var msgId = menu ? menu._msgId : '';
    hideMessageContextMenu();
    if (!text) return;
    _showQuoteReplyBar(isUser ? '你' : '芙宁娜', text, msgId);
}

function forwardMessageFromMenu() {
    var menu = document.getElementById('msg-context-menu');
    var text = menu ? menu._msgText : '';
    hideMessageContextMenu();
    if (!text) return;
    showToast('已复制，可粘贴到其他对话中');
    navigator.clipboard.writeText(text).catch(function() {});
}

function deleteMessageFromMenu() {
    var menu = document.getElementById('msg-context-menu');
    var el = menu ? menu._messageEl : null;
    var timestamp = menu ? menu._msgTimestamp : '';
    hideMessageContextMenu();
    if (!el) return;
    el.style.transition = 'opacity 0.3s, transform 0.3s';
    el.style.opacity = '0';
    el.style.transform = 'translateX(20px)';
    setTimeout(function() {
        el.remove();
        if (timestamp) {
            fetch('/api/chat/history/delete-message', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({timestamp: timestamp})
            }).catch(function(e) {
                console.warn('删除后端消息失败:', e);
            });
        }
    }, 300);
}

// 气泡操作按钮：引用回复
function quoteReplyMessage(btn) {
    var messageDiv = btn.closest('.message');
    if (!messageDiv) return;
    var contentEl = messageDiv.querySelector('.message-content');
    var text = contentEl ? (contentEl.textContent || contentEl.innerText).trim() : '';
    if (!text) return;
    var isUser = messageDiv.classList.contains('user');
    _showQuoteReplyBar(isUser ? '你' : '芙宁娜', text, messageDiv.dataset.msgId || '');
}

// 在输入卡片顶部显示引用条
function _showQuoteReplyBar(author, text, msgId) {
    var input = document.getElementById('message-input');
    if (!input) return;
    var host = input.closest('.chat-input-wrapper') || input.parentNode;
    var bar = document.getElementById('quote-reply-bar');
    if (!bar) {
        bar = document.createElement('div');
        bar.id = 'quote-reply-bar';
        bar.className = 'quote-reply-bar';
        bar.innerHTML =
            '<i class="fas fa-quote-right quote-bar-icon"></i>' +
            '<div class="quote-bar-body">' +
                '<span class="quote-bar-author"></span>' +
                '<span class="quote-bar-text"></span>' +
            '</div>' +
            '<button class="quote-bar-close" type="button" title="取消引用"><i class="fas fa-times"></i></button>';
        bar.querySelector('.quote-bar-close').addEventListener('click', function (e) {
            e.preventDefault();
            _clearQuoteReplyBar();
        });
        host.insertBefore(bar, host.firstChild);
    }
    bar.querySelector('.quote-bar-author').textContent = author;
    bar.querySelector('.quote-bar-text').textContent = text.length > 80 ? text.slice(0, 80) + '…' : text;
    bar.dataset.quoteMsgId = msgId || '';
    bar.dataset.quoteText = text;
    input.focus();
}

// 取消当前引用
function _clearQuoteReplyBar() {
    var bar = document.getElementById('quote-reply-bar');
    if (bar) bar.remove();
}

// 读取引用条内容生成正文前缀（不清除引用条，便于发送失败时保留）
function _peekQuotePrefix() {
    var bar = document.getElementById('quote-reply-bar');
    if (!bar) return '';
    var text = bar.dataset.quoteText || '';
    if (!text) return '';
    var authorEl = bar.querySelector('.quote-bar-author');
    var author = authorEl ? authorEl.textContent.trim() : '';
    if (!author) author = '芙宁娜';
    // 清理会破坏哨兵格式的字符
    author = author.split('|').join('｜').split('[').join('').split(']').join('');
    return '[quote]' + author + '|' + text + '[/quote]';
}

function escapeHtml(text) {
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
}

function formatTime(timeStr) {
    if (!timeStr) return '';
    try {
        const date = new Date(timeStr);
        const now = new Date();
        const isToday = date.toDateString() === now.toDateString();
        const hours = date.getHours().toString().padStart(2, '0');
        const minutes = date.getMinutes().toString().padStart(2, '0');
        if (isToday) {
            return `${hours}:${minutes}`;
        }
        const month = (date.getMonth() + 1).toString().padStart(2, '0');
        const day = date.getDate().toString().padStart(2, '0');
        return `${month}-${day} ${hours}:${minutes}`;
    } catch {
        return '';
    }
}

// 复制消息内容
// 编辑用户消息并重发（DSH 式：改上一条 → 以新内容重新提问）
function editUserMessage(btn) {
    var messageDiv = btn.closest('.message');
    if (!messageDiv || messageDiv.classList.contains('editing')) return;
    var body = messageDiv.querySelector('.message-body');
    var contentEl = messageDiv.querySelector('.message-content');
    if (!body || !contentEl) return;

    var raw = messageDiv.dataset.rawContent;
    if (raw === undefined) raw = contentEl.innerText || '';

    messageDiv.classList.add('editing');
    contentEl.style.display = 'none';

    var editor = document.createElement('div');
    editor.className = 'msg-edit-box';
    editor.innerHTML =
        '<textarea class="msg-edit-input" rows="3"></textarea>' +
        '<div class="msg-edit-actions">' +
        '<button type="button" class="btn btn-sm btn-primary" data-act="send">保存并重发</button>' +
        '<button type="button" class="btn btn-sm" data-act="cancel">取消</button>' +
        '</div>';
    body.insertBefore(editor, contentEl.nextSibling);

    var ta = editor.querySelector('textarea');
    ta.value = raw;
    ta.focus();
    ta.style.height = Math.min(220, Math.max(64, ta.scrollHeight)) + 'px';

    function closeEditor() {
        editor.remove();
        contentEl.style.display = '';
        messageDiv.classList.remove('editing');
    }

    editor.querySelector('[data-act="cancel"]').onclick = closeEditor;
    editor.querySelector('[data-act="send"]').onclick = function () {
        var text = (ta.value || '').trim();
        if (!text) { showToast('内容不能为空', 'error'); return; }
        if (text === String(raw).trim()) { closeEditor(); return; }
        var ts = messageDiv.dataset.timestamp;
        closeEditor();
        // 原消息从界面与后端历史里删掉，再以新内容重发
        messageDiv.remove();
        if (ts) {
            fetch('/api/chat/history/delete-message', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ timestamp: ts })
            }).catch(function (e) { console.warn('删除原消息失败:', e); });
        }
        var input = document.getElementById('message-input');
        var draft = input ? input.value : '';
        sendMessage(text);
        if (input) {
            input.value = draft;
            if (typeof autoGrowInput === 'function') autoGrowInput(input);
        }
    };
}

function copyMessage(btn) {
    const messageBody = btn.closest('.message-body');
    const content = messageBody.querySelector('.message-content');
    if (content) {
        const text = content.textContent || content.innerText;
        navigator.clipboard.writeText(text).then(() => {
            showToast('已复制到剪贴板');
        }).catch(() => {
            // 降级方案
            const textarea = document.createElement('textarea');
            textarea.value = text;
            document.body.appendChild(textarea);
            textarea.select();
            document.execCommand('copy');
            document.body.removeChild(textarea);
            showToast('已复制到剪贴板');
        });
    }
}

// 删除消息（同步后端）
function deleteMessage(btn) {
    const messageDiv = btn.closest('.message');
    if (!messageDiv) return;
    
    const timestamp = messageDiv.dataset.timestamp;
    
    // 动画移除
    messageDiv.style.transition = 'opacity 0.3s, transform 0.3s';
    messageDiv.style.opacity = '0';
    messageDiv.style.transform = 'translateX(20px)';
    
    setTimeout(() => {
        messageDiv.remove();
        // 同步删除后端聊天历史中的消息
        if (timestamp) {
            fetch('/api/chat/history/delete-message', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({timestamp: timestamp})
            }).catch(function(e) {
                console.warn('删除后端消息失败:', e);
            });
        }
    }, 300);
}

// 重新发送消息（找到上一条用户消息并重新发送）
function resendMessage(btn) {
    const messageDiv = btn.closest('.message');
    const prevMessage = messageDiv.previousElementSibling;
    if (prevMessage && prevMessage.classList.contains('message', 'user')) {
        const content = prevMessage.querySelector('.message-content');
        if (content) {
            const text = content.textContent || content.innerText;
            const input = document.getElementById('message-input');
            input.value = text;
            input.focus();
            // 删除旧的用户消息和 AI 回复
            prevMessage.remove();
            messageDiv.remove();
            // 自动发送
            setTimeout(() => sendMessage(), 100);
        }
    }
}

function createAiMessagePlaceholder() {
    const container = document.getElementById('chat-messages');
    const messageDiv = document.createElement('div');
    messageDiv.className = 'message assistant';
    messageDiv.id = 'ai-typing';
    
    messageDiv.innerHTML = `
        <div class="message-avatar">
            <img src="/api/avatar/zhiyan" alt="Furina" 
                 onerror="this.style.display='none'; this.nextElementSibling.style.display='flex';"
                 class="avatar-img">
            <div class="avatar-fallback">🌊</div>
        </div>
        <div class="message-body">
            <div class="message-meta">
                <span class="message-role-label">芙宁娜</span>
                <span class="role-badge">水神 芙宁娜</span>
                <span class="message-time">正在输入...</span>
            </div>
            <div class="message-content">
                <div class="typing-indicator">
                    <span class="typing-dot"></span>
                    <span class="typing-dot"></span>
                    <span class="typing-dot"></span>
                </div>
            </div>
        </div>
    `;
    
    container.appendChild(messageDiv);
    scrollToBottom();
}

function appendAiChunk(chunk) {
    const typingDiv = document.getElementById('ai-typing');
    
    if (typingDiv) {
        // ---- 首次创建 AI 消息 DOM ----
        // 先保存可能存在的 reasoning 块和 tool-status 容器（防止被 innerHTML 替换覆盖）
        var savedToolStatusHtml = null;
        var savedToolStatus = typingDiv.querySelector('.agent-tool-status');
        if (savedToolStatus) {
            savedToolStatusHtml = savedToolStatus.outerHTML;
        }
        
        typingDiv.id = '';
        // 初始化流式状态
        typingDiv.dataset.fullText = chunk;
        typingDiv.dataset.markdownMode = 'false';
        
        const actionsHtml = `
            <div class="message-actions">
                <button class="msg-action-btn" onclick="copyMessage(this)" title="复制">
                    <i class="fas fa-copy"></i>
                </button>
                <button class="msg-action-btn" onclick="deleteMessage(this)" title="删除">
                    <i class="fas fa-trash-alt"></i>
                </button>
                <button class="msg-action-btn" onclick="resendMessage(this)" title="重新发送">
                    <i class="fas fa-redo"></i>
                </button>
            </div>
        `;
        
        // 判断是否需要用 Markdown 渲染
        const useMarkdown = detectMarkdown(chunk);
        const contentHtml = useMarkdown ? renderMarkdown(chunk) : '';
        
        typingDiv.innerHTML = `
            <div class="message-avatar">
                <img src="/api/avatar/zhiyan" alt="Furina" 
                     onerror="this.style.display='none'; this.nextElementSibling.style.display='flex';"
                     class="avatar-img">
                <div class="avatar-fallback">🌊</div>
            </div>
            <div class="message-body">
                <div class="message-meta">
                    <span class="message-role-label">芙宁娜</span>
                    <span class="role-badge">水神 芙宁娜</span>
                    <span class="message-time">${formatTime(new Date().toISOString())}</span>
                </div>
                <div class="message-content">${contentHtml}</div>
                ${actionsHtml}
            </div>
        `;
        currentAiMessage = typingDiv.querySelector('.message-content');
        
        // 如果是纯文本模式，追加文本节点
        if (!useMarkdown) {
            currentAiMessage.textContent = chunk;
            currentAiMessage.classList.add('plain-text');
            typingDiv.dataset.markdownMode = 'false';
        } else {
            currentAiMessage.classList.remove('plain-text');
            typingDiv.dataset.markdownMode = 'true';
        }
        
        // 恢复之前保存的 tool-status 容器（包含 reasoning 块）
        // 容器必须插到回复内容上方，避免思考过程被错误地放在内容下侧
        if (savedToolStatusHtml) {
            var messageBody = typingDiv.querySelector('.message-body');
            if (messageBody) {
                var tempContainer = document.createElement('div');
                tempContainer.innerHTML = savedToolStatusHtml;
                var restoredContainer = tempContainer.firstElementChild;
                if (restoredContainer) {
                    var contentEl = typingDiv.querySelector('.message-content');
                    if (contentEl) {
                        messageBody.insertBefore(restoredContainer, contentEl);
                    } else {
                        messageBody.appendChild(restoredContainer);
                    }
                }
            }
        }
    } else {
        // ---- 后续流式追加 ----
        const aiMessages = document.querySelectorAll('.message.assistant');
        const lastAiMsg = aiMessages[aiMessages.length - 1];
        if (!lastAiMsg) return;
        
        // 累积全文
        const prevFull = lastAiMsg.dataset.fullText || '';
        const newFull = prevFull + chunk;
        lastAiMsg.dataset.fullText = newFull;
        
        const contentEl = lastAiMsg.querySelector('.message-content');
        if (!contentEl) return;
        
        const isMarkdownMode = lastAiMsg.dataset.markdownMode === 'true';
        
        if (isMarkdownMode) {
            // 已在 Markdown 模式：直接重新渲染全文
            contentEl.classList.remove('plain-text');
            contentEl.innerHTML = renderMarkdown(newFull);
        } else {
            // 纯文本模式：检查新内容是否引入 Markdown 特征
            if (detectMarkdown(newFull)) {
                // 切换到 Markdown 模式，重新渲染全文
                lastAiMsg.dataset.markdownMode = 'true';
                contentEl.classList.remove('plain-text');
                contentEl.innerHTML = renderMarkdown(newFull);
            } else {
                // 继续保持纯文本模式，追加文本（保留换行符）
                contentEl.classList.add('plain-text');
                contentEl.textContent = newFull;
            }
        }
        currentAiMessage = contentEl;
    }
    
    scrollToBottom();
}

function appendReasoningChunk(content) {
    // 处理 DeepSeek 思考模式的流式 reasoning_content
    // 创建一个折叠的思考过程卡片添加到当前 AI 消息底部
    const aiMessages = document.querySelectorAll('.message.assistant');
    const lastAiMsg = aiMessages[aiMessages.length - 1];
    if (!lastAiMsg) return;

    // 查找或创建 agent-tool-status 容器
    let toolStatusEl = lastAiMsg.querySelector('.agent-tool-status');
    if (!toolStatusEl) {
        toolStatusEl = document.createElement('div');
        toolStatusEl.className = 'agent-tool-status';
        // 插入到回复内容上方（DeepSeek 手机端风格：思考链显示在气泡上方）
        const contentEl = lastAiMsg.querySelector('.message-content');
        if (contentEl) {
            contentEl.parentElement.insertBefore(toolStatusEl, contentEl);
        } else {
            lastAiMsg.querySelector('.message-body').appendChild(toolStatusEl);
        }
    }

    // 查找或创建 reasoning block（复用 DSH 风格的 Think 行）
    let reasoningBlock = toolStatusEl.querySelector('.agent-reasoning-block');
    if (!reasoningBlock) {
        reasoningBlock = document.createElement('div');
        reasoningBlock.className = 'dsh-reasoning-row running agent-reasoning-block';
        reasoningBlock.innerHTML = `
            <div class="dsh-reasoning-header" onclick="var b=this.nextElementSibling;b.classList.toggle('open');var c=this.querySelector('.dsh-tool-chevron');if(c)c.classList.toggle('open');">
                <span class="dsh-reasoning-icon">${_dshThinkIcon()}</span>
                <span class="dsh-reasoning-title">思考</span>
                <span class="dsh-reasoning-sep">·</span>
                <span class="dsh-reasoning-summary">正在思考…</span>
                <span class="dsh-tool-chevron"><i class="fas fa-chevron-down"></i></span>
            </div>
            <div class="dsh-reasoning-body"></div>
        `;
        toolStatusEl.appendChild(reasoningBlock);
    }

    // 追加内容并同步摘要
    const bodyEl = reasoningBlock.querySelector('.dsh-reasoning-body');
    if (bodyEl) {
        bodyEl.textContent += content;
        bodyEl.scrollTop = bodyEl.scrollHeight;
        const summaryEl = reasoningBlock.querySelector('.dsh-reasoning-summary');
        if (summaryEl) {
            const lines = bodyEl.textContent.trimEnd().split('\n');
            summaryEl.textContent = lines[lines.length - 1] || '正在思考…';
        }
    }

    scrollToBottom();
}

function finalizeAiMessage(message) {
    const aiMessages = document.querySelectorAll('.message.assistant');
    const lastAiMessage = aiMessages[aiMessages.length - 1];
    if (lastAiMessage) {
        const contentEl = lastAiMessage.querySelector('.message-content');
        if (contentEl) {
            contentEl.classList.remove('typing');
            // 最终检查：如果纯文本模式但全文实际包含 Markdown（如尾部语法补齐），切换渲染
            const isMarkdownMode = lastAiMessage.dataset.markdownMode === 'true';
            const fullText = lastAiMessage.dataset.fullText || '';
            if (!isMarkdownMode && fullText && detectMarkdown(fullText)) {
                lastAiMessage.dataset.markdownMode = 'true';
                contentEl.classList.remove('plain-text');
                contentEl.innerHTML = renderMarkdown(fullText);
            } else if (!isMarkdownMode) {
                // 保持纯文本模式：确保换行符正常显示
                contentEl.classList.add('plain-text');
            }
        }
        // 更新时间
        const timeEl = lastAiMessage.querySelector('.message-time');
        if (timeEl && message.time) {
            timeEl.textContent = formatTime(message.time);
        }
        // 思考行收尾：停止呼吸点，折叠为一行摘要（DSH 风格）
        var reasoningBlock = lastAiMessage.querySelector('.agent-reasoning-block');
        if (reasoningBlock) {
            reasoningBlock.classList.remove('running');
            var reasoningBody = reasoningBlock.querySelector('.dsh-reasoning-body');
            if (reasoningBody) {
                reasoningBody.classList.remove('open');
                if (!(reasoningBody.textContent || '').trim()) {
                    reasoningBody.textContent = '（本轮没有思考内容）';
                }
            }
            var reasoningChevron = reasoningBlock.querySelector('.dsh-tool-chevron');
            if (reasoningChevron) reasoningChevron.classList.remove('open');
            var reasoningSummary = reasoningBlock.querySelector('.dsh-reasoning-summary');
            if (reasoningSummary && !(reasoningSummary.textContent || '').trim()) {
                reasoningSummary.textContent = '思考完成';
            }
        }
    }
    // 更新上下文信息
    fetchContextInfo();
}

// ============= Agent 流式消息处理 =============

function appendAgentChunk(data) {
    const container = document.getElementById('chat-messages');
    
    // 如果当前没有 Agent 消息占位，创建新的
    if (!_currentAgentMessage || _currentAgentMessage.agent_id !== data.agent_id) {
        _currentAgentMessage = {
            agent_id: data.agent_id,
            agent_name: data.agent_name || data.agent_id,
            agent_avatar: data.agent_avatar || '🤖',
            agent_role: data.agent_role || 'Agent',
            element: null,
            content: '',
            markdownMode: false,
        };
        
        const messageDiv = document.createElement('div');
        messageDiv.className = 'message assistant agent-message';
        messageDiv.dataset.timestamp = new Date().toISOString();
        
        const avatarEmoji = data.agent_avatar || '🤖';
        const roleLabel = '<span class="agent-label">' + avatarEmoji + ' ' + escapeHtml(data.agent_name || data.agent_id) + '</span>';
        
        messageDiv.innerHTML = `
            <div class="message-avatar">
                <div class="avatar-fallback" style="display:flex">${avatarEmoji}</div>
            </div>
            <div class="message-body">
                <div class="message-meta">
                    <span class="message-role-label">${roleLabel}</span>
                    <span class="role-badge">Agent</span>
                    <span class="message-time">${formatTime(new Date().toISOString())}</span>
                </div>
                <div class="message-content typing"></div>
                <div class="message-actions">
                    <button class="msg-action-btn" onclick="copyMessage(this)" title="复制">
                        <i class="fas fa-copy"></i>
                    </button>
                    <button class="msg-action-btn" onclick="deleteMessage(this)" title="删除">
                        <i class="fas fa-trash-alt"></i>
                    </button>
                </div>
            </div>
        `;
        
        container.appendChild(messageDiv);
        _currentAgentMessage.element = messageDiv;
        scrollToBottom();
    }
    
    // 追加内容
    const contentEl = _currentAgentMessage.element.querySelector('.message-content');
    const chunk = data.chunk || '';
    const newContent = _currentAgentMessage.content + chunk;
    _currentAgentMessage.content = newContent;
    
    if (_currentAgentMessage.markdownMode) {
        // 已在 Markdown 模式：重新渲染全文
        contentEl.classList.remove('plain-text');
        contentEl.innerHTML = renderMarkdown(newContent);
    } else if (detectMarkdown(newContent)) {
        // 检测到 Markdown，切换模式
        _currentAgentMessage.markdownMode = true;
        contentEl.classList.remove('plain-text');
        contentEl.innerHTML = renderMarkdown(newContent);
    } else {
        // 纯文本模式：直接设置文本（保留换行符）
        contentEl.classList.add('plain-text');
        contentEl.textContent = newContent;
    }
    contentEl.classList.add('typing');
    scrollToBottom();
}

function finalizeAgentMessage(data) {
    if (_currentAgentMessage && _currentAgentMessage.element) {
        const contentEl = _currentAgentMessage.element.querySelector('.message-content');
        try { enhanceRichContent(contentEl); } catch (e) { console.warn(e); }
        if (contentEl) {
            contentEl.classList.remove('typing');
            // 最终检查：纯文本模式但全文实际包含 Markdown
            if (!_currentAgentMessage.markdownMode && _currentAgentMessage.content && detectMarkdown(_currentAgentMessage.content)) {
                _currentAgentMessage.markdownMode = true;
                contentEl.classList.remove('plain-text');
                contentEl.innerHTML = renderMarkdown(_currentAgentMessage.content);
            } else if (!_currentAgentMessage.markdownMode) {
                // 保持纯文本模式：确保换行符正常显示
                contentEl.classList.add('plain-text');
            }
        }
        // 更新时间
        const timeEl = _currentAgentMessage.element.querySelector('.message-time');
        if (timeEl && data.time) {
            timeEl.textContent = formatTime(data.time);
        }
        _currentAgentMessage = null;
    }
}

function showDecisionCard(data) {
    const container = document.getElementById('chat-messages');
    const card = document.createElement('div');
    card.className = 'decision-card';
    
    const optionsHtml = (data.options || []).map((opt, i) => 
        `<button class="decision-option-btn" onclick="sendDecision('${i}')">${escapeHtml(opt)}</button>`
    ).join('');
    
    card.innerHTML = `
        <div class="decision-prompt">${escapeHtml(data.prompt || '请选择一个选项：')}</div>
        <div class="decision-options">${optionsHtml}</div>
    `;
    
    container.appendChild(card);
    scrollToBottom();
}

function sendDecision(optionIndex) {
    // 发送决策到 WebSocket
    if (ws && ws.readyState === WebSocket.OPEN) {
        ws.send(JSON.stringify({
            type: 'decision',
            index: parseInt(optionIndex),
        }));
    }
    // 移除法决策卡片
    const cards = document.querySelectorAll('.decision-card');
    if (cards.length > 0) {
        cards[cards.length - 1].remove();
    }
}

// ============= 更新上下文信息 =============
// 上下文用量环（DSH 式：Composer 右侧小环 + 百分比）
var CONTEXT_WINDOW_FALLBACK = 131072;

function _fmtTokenCount(n) {
    n = Number(n) || 0;
    if (n >= 1000000) return (n / 1000000).toFixed(1) + 'M';
    if (n >= 1000) return (n / 1000).toFixed(1) + 'k';
    return String(n);
}

function _renderContextRing(tokens, windowSize) {
    var ring = document.getElementById('chat-ctx-ring');
    var fill = document.getElementById('chat-ctx-fill');
    var pctEl = document.getElementById('chat-ctx-pct');
    if (!ring || !fill || !pctEl) return;
    var total = Number(tokens) || 0;
    var win = Number(windowSize) || CONTEXT_WINDOW_FALLBACK;
    var pct = win > 0 ? Math.min(100, (total / win) * 100) : 0;
    var r = 8;
    var c = 2 * Math.PI * r;
    fill.style.strokeDasharray = c.toFixed(2);
    fill.style.strokeDashoffset = (c * (1 - pct / 100)).toFixed(2);
    pctEl.textContent = (pct > 0 && pct < 1) ? '<1%' : Math.round(pct) + '%';
    ring.classList.toggle('warn', pct >= 75 && pct < 90);
    ring.classList.toggle('danger', pct >= 90);
    ring.style.display = 'inline-flex';
    ring.title = '上下文 ' + _fmtTokenCount(total) + ' / ' + _fmtTokenCount(win) +
        '（' + pct.toFixed(1) + '%）';
}

function updateContextInfo(context) {
    // context_window 是“保留多少条消息”，不是 token 上限；优先用后端给的 context_tokens。
    var win = (context && (context.context_tokens || context.token_budget)) || CONTEXT_WINDOW_FALLBACK;
    _renderContextRing(context && context.estimated_tokens, win);
    const el = document.getElementById('chat-context-info');
    if (!el) return;
    if (context && context.message_count > 0) {
        el.innerHTML = `
            <span class="context-badge" title="消息数量"><i class="fas fa-comment-dots"></i> ${context.message_count}</span>
            <span class="context-badge" title="估算 Token"><i class="fas fa-chart-bar"></i> ${context.estimated_tokens || 0} tokens</span>
            ${context.summary ? `<span class="context-badge" title="上下文摘要"><i class="fas fa-align-left"></i> ${context.summary.substring(0, 30)}...</span>` : ''}
        `;
        el.style.display = 'flex';
    } else {
        el.style.display = 'none';
    }
}

// 获取上下文信息
function fetchContextInfo() {
    fetch('/api/chat/context')
        .then(r => r.json())
        .then(data => updateContextInfo(data))
        .catch(() => {});
}

function scrollToBottom() {
    const container = document.getElementById('chat-messages');
    container.scrollTop = container.scrollHeight;
    // 到达底部时自动隐藏按钮
    hideScrollToBottomBtn();
}

// ============= 返回底部悬浮按钮 =============

const SCROLL_TO_BOTTOM_THRESHOLD = 500; // 距离底部超过此值时显示按钮

function initScrollToBottomBtn() {
    const container = document.getElementById('chat-messages');
    const btn = document.getElementById('scroll-to-bottom-btn');
    if (!container || !btn) return;

    // 监听滚动事件
    container.addEventListener('scroll', () => {
        const distanceFromBottom = container.scrollHeight - container.scrollTop - container.clientHeight;
        if (distanceFromBottom > SCROLL_TO_BOTTOM_THRESHOLD) {
            btn.classList.add('visible');
        } else {
            btn.classList.remove('visible');
        }
    });

    // 点击按钮平滑滚动到底部
    btn.addEventListener('click', () => {
        container.scrollTo({
            top: container.scrollHeight,
            behavior: 'smooth'
        });
        // 滚动结束后隐藏按钮（smooth scroll 有延迟，用 setTimeout 兜底）
        setTimeout(() => {
            btn.classList.remove('visible');
        }, 400);
    });
}

function hideScrollToBottomBtn() {
    const btn = document.getElementById('scroll-to-bottom-btn');
    if (btn) {
        btn.classList.remove('visible');
    }
}

// 当前正在播放的语音消息
let currentPlayingVoice = null;
let currentVoiceAudio = null;

// 渲染语音消息气泡
function addVoiceMessage(data) {
    const container = document.getElementById('chat-messages');
    const messageDiv = document.createElement('div');
    messageDiv.className = 'message voice-message';
    messageDiv.dataset.audioUrl = data.audio_url || '';
    messageDiv.dataset.text = data.text;
    messageDiv.dataset.time = data.time || new Date().toISOString();
    
    const isTextOnly = data.mode === 'text_only';
    
    if (isTextOnly) {
        // TTS 禁用模式：文本保存气泡（无播放功能）
        messageDiv.innerHTML = `
            <div class="message-avatar">
                <img src="/api/avatar/zhiyan" alt="Furina" 
                     onerror="this.style.display='none'; this.nextElementSibling.style.display='flex';"
                     class="avatar-img">
                <div class="avatar-fallback">🌊</div>
            </div>
            <div class="message-body">
                <div class="message-meta">
                    <span class="message-role-label">芙宁娜</span>
                    <span class="role-badge">水神 芙宁娜</span>
                    <span class="message-time">${formatTime(data.time)}</span>
                </div>
                <div class="voice-msg-bubble text-only">
                    <div class="voice-msg-icon">
                        <i class="fas fa-file-alt"></i>
                    </div>
                    <div class="voice-msg-text" title="${escapeHtml(data.text)}">${escapeHtml(data.text)}</div>
                    <div class="voice-msg-duration">已保存</div>
                </div>
                <div class="message-actions">
                    <button class="msg-action-btn" onclick="deleteMessage(this)" title="删除">
                        <i class="fas fa-trash-alt"></i>
                    </button>
                </div>
            </div>
        `;
    } else {
        // TTS 启用模式：可播放的语音气泡
        messageDiv.innerHTML = `
            <div class="message-avatar">
                <img src="/api/avatar/zhiyan" alt="Furina" 
                     onerror="this.style.display='none'; this.nextElementSibling.style.display='flex';"
                     class="avatar-img">
                <div class="avatar-fallback">🌊</div>
            </div>
            <div class="message-body">
                <div class="message-meta">
                    <span class="message-role-label">芙宁娜</span>
                    <span class="role-badge">水神 芙宁娜</span>
                    <span class="message-time">${formatTime(data.time)}</span>
                </div>
                <div class="voice-msg-bubble" onclick="playVoiceMessage(this)">
                    <div class="voice-msg-icon">
                        <i class="fas fa-play"></i>
                    </div>
                    <div class="voice-msg-wave">
                        <span class="voice-wave-bar"></span>
                        <span class="voice-wave-bar"></span>
                        <span class="voice-wave-bar"></span>
                        <span class="voice-wave-bar"></span>
                        <span class="voice-wave-bar"></span>
                    </div>
                    <div class="voice-msg-text" title="${escapeHtml(data.text)}">${escapeHtml(data.text)}</div>
                    <div class="voice-msg-duration">~</div>
                </div>
                <div class="message-actions">
                    <button class="msg-action-btn" onclick="deleteMessage(this)" title="删除">
                        <i class="fas fa-trash-alt"></i>
                    </button>
                </div>
            </div>
        `;
    }
    
    container.appendChild(messageDiv);
    scrollToBottom();
    
    // 预加载音频获取时长（仅语音模式）
    if (data.audio_url) {
        preloadVoiceDuration(messageDiv, data.audio_url);
    }
}

// 预加载语音消息时长
function preloadVoiceDuration(messageDiv, audioUrl) {
    const audio = new Audio(audioUrl);
    audio.addEventListener('loadedmetadata', () => {
        const duration = Math.round(audio.duration);
        const durEl = messageDiv.querySelector('.voice-msg-duration');
        if (durEl) {
            const min = Math.floor(duration / 60);
            const sec = duration % 60;
            durEl.textContent = `${min}:${sec.toString().padStart(2, '0')}`;
        }
    });
    audio.addEventListener('error', () => {
        const durEl = messageDiv.querySelector('.voice-msg-duration');
        if (durEl) durEl.textContent = '0:00';
    });
    // 触发加载
    audio.load();
}

// 播放语音消息
function playVoiceMessage(bubble) {
    const messageDiv = bubble.closest('.message.voice-message');
    const audioUrl = messageDiv.dataset.audioUrl;
    const icon = bubble.querySelector('.voice-msg-icon i');
    const wave = bubble.querySelector('.voice-msg-wave');
    
    if (!audioUrl) return;
    
    // 如果正在播放当前语音，暂停
    if (currentPlayingVoice === messageDiv && currentVoiceAudio) {
        currentVoiceAudio.pause();
        currentVoiceAudio.currentTime = 0;
        currentVoiceAudio = null;
        currentPlayingVoice = null;
        if (icon) icon.className = 'fas fa-play';
        if (wave) wave.classList.remove('playing');
        return;
    }
    
    // 停止其他语音
    if (currentVoiceAudio) {
        currentVoiceAudio.pause();
        currentVoiceAudio.currentTime = 0;
        const prevIcon = currentPlayingVoice?.querySelector('.voice-msg-icon i');
        const prevWave = currentPlayingVoice?.querySelector('.voice-msg-wave');
        if (prevIcon) prevIcon.className = 'fas fa-play';
        if (prevWave) prevWave.classList.remove('playing');
    }
    
    // 播放新语音
    const audio = new Audio(audioUrl);
    currentVoiceAudio = audio;
    currentPlayingVoice = messageDiv;
    
    if (icon) icon.className = 'fas fa-pause';
    if (wave) wave.classList.add('playing');
    
    audio.addEventListener('ended', () => {
        if (icon) icon.className = 'fas fa-play';
        if (wave) wave.classList.remove('playing');
        currentVoiceAudio = null;
        currentPlayingVoice = null;
    });
    
    audio.addEventListener('error', () => {
        showError('语音播放失败');
        if (icon) icon.className = 'fas fa-play';
        if (wave) wave.classList.remove('playing');
        currentVoiceAudio = null;
        currentPlayingVoice = null;
    });
    
    audio.play().catch(err => {
        showError('语音播放失败: ' + err.message);
        if (icon) icon.className = 'fas fa-play';
        if (wave) wave.classList.remove('playing');
        currentVoiceAudio = null;
        currentPlayingVoice = null;
    });
}

// 播放内联语音消息（renderMarkdown 渲染的 [voice] 标记）
function playInlineVoice(bubble, audioUrl) {
    const icon = bubble.querySelector('.voice-msg-icon i');
    const wave = bubble.querySelector('.voice-msg-wave');
    
    if (!audioUrl) return;
    
    // 如果正在播放当前语音，暂停
    if (currentPlayingVoice === bubble && currentVoiceAudio) {
        currentVoiceAudio.pause();
        currentVoiceAudio.currentTime = 0;
        currentVoiceAudio = null;
        currentPlayingVoice = null;
        if (icon) icon.className = 'fas fa-play';
        if (wave) wave.classList.remove('playing');
        return;
    }
    
    // 停止其他语音
    if (currentVoiceAudio) {
        currentVoiceAudio.pause();
        currentVoiceAudio.currentTime = 0;
        const prevIcon = currentPlayingVoice?.querySelector('.voice-msg-icon i');
        const prevWave = currentPlayingVoice?.querySelector('.voice-msg-wave');
        if (prevIcon) prevIcon.className = 'fas fa-play';
        if (prevWave) prevWave.classList.remove('playing');
    }
    
    // 播放新语音
    const audio = new Audio(audioUrl);
    currentVoiceAudio = audio;
    currentPlayingVoice = bubble;
    
    if (icon) icon.className = 'fas fa-pause';
    if (wave) wave.classList.add('playing');
    
    audio.addEventListener('ended', () => {
        if (icon) icon.className = 'fas fa-play';
        if (wave) wave.classList.remove('playing');
        currentVoiceAudio = null;
        currentPlayingVoice = null;
    });
    
    audio.addEventListener('error', () => {
        if (icon) icon.className = 'fas fa-play';
        if (wave) wave.classList.remove('playing');
        currentVoiceAudio = null;
        currentPlayingVoice = null;
    });
    
    audio.crossOrigin = 'anonymous';
    audio.play().catch(function() {});
}

// 显示语音合成中提示
function showVoiceSynthesizing(text) {
    // 移除旧的合成中提示
    const oldTip = document.getElementById('voice-synthesizing-tip');
    if (oldTip) oldTip.remove();
    
    const container = document.getElementById('chat-messages');
    const tipDiv = document.createElement('div');
    tipDiv.id = 'voice-synthesizing-tip';
    tipDiv.className = 'message system voice-synth-tip';
    tipDiv.innerHTML = `
        <div class="message-content voice-synth-content">
            <i class="fas fa-volume-up"></i>
            <span class="voice-synth-text">生成语音: ${escapeHtml(text)}</span>
            <span class="voice-synth-spinner"><i class="fas fa-spinner fa-spin"></i></span>
        </div>
    `;
    container.appendChild(tipDiv);
    scrollToBottom();
}

function clearChat() {
    if (!confirm('确定清空当前会话的消息吗？\n（会话本身会保留，其它会话不受影响）')) return;
    fetch('/api/chat/history', { method: 'DELETE' })
        .then(response => response.json())
        .then(data => {
            if (data.status === 'success') {
                _renderSessionMessages([]);
                loadSessions();
            }
        })
        .catch(error => showError('清空聊天失败'));
}

// 加载聊天历史
// ============= 多轮会话管理（左侧抽屉） =============
// 真源在后端 ChatManager：一个会话 = 一段独立的 LLM 上下文 + 一段独立界面历史。
// 切会话时后端会把 LLM 上下文和界面消息一起换掉，所以两边不会脱节。

var _sessions = [];
var _activeSessionId = null;
var _welcomeHtml = null;

function _currentSessionId() {
    return _activeSessionId || 'default';
}

function _sessionTitle(sid) {
    for (var i = 0; i < _sessions.length; i++) {
        if (_sessions[i].id === sid) return _sessions[i].title || '新对话';
    }
    return '新对话';
}

function _findSessionItem(sid) {
    var box = document.getElementById('session-list');
    if (!box) return null;
    var items = box.querySelectorAll('.session-item');
    for (var i = 0; i < items.length; i++) {
        if (items[i].dataset.sid === sid) return items[i];
    }
    return null;
}

function _formatSessionTime(iso) {
    if (!iso) return '';
    var d = new Date(iso);
    if (isNaN(d.getTime())) return '';
    var now = new Date();
    var sameDay = d.toDateString() === now.toDateString();
    var pad = function (n) { return (n < 10 ? '0' : '') + n; };
    if (sameDay) return pad(d.getHours()) + ':' + pad(d.getMinutes());
    if (d.getFullYear() === now.getFullYear()) {
        return (d.getMonth() + 1) + '/' + d.getDate() + ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes());
    }
    return d.getFullYear() + '/' + (d.getMonth() + 1) + '/' + d.getDate();
}

function _applySidebarState(open, persist) {
    var view = document.getElementById('chat-view');
    var drawer = document.getElementById('session-drawer');
    if (!view || !drawer) return;
    view.classList.toggle('sidebar-collapsed', !open);
    drawer.classList.toggle('open', open);
    drawer.setAttribute('aria-hidden', open ? 'false' : 'true');
    var btn = document.getElementById('session-toggle-btn');
    if (btn) btn.classList.toggle('active', open);
    if (persist !== false) {
        try { localStorage.setItem('chatSidebarCollapsed', open ? '0' : '1'); } catch (e) {}
    }
    if (open) {
        loadSessions();
        var input = document.getElementById('session-search');
        if (input) setTimeout(function () { input.focus(); }, 120);
    }
}

function toggleSessionDrawer(force) {
    var view = document.getElementById('chat-view');
    if (!view) return;
    var open = (typeof force === 'boolean') ? force : view.classList.contains('sidebar-collapsed');
    _applySidebarState(open, true);
}

// 窄窗自动收起会话栏（不覆盖用户手动偏好）
function _autoCollapseSidebar() {
    var view = document.getElementById('chat-view');
    if (!view) return;
    if (window.innerWidth <= 1024) {
        if (!view.classList.contains('sidebar-collapsed')) _applySidebarState(false, false);
    } else {
        var pref = null;
        try { pref = localStorage.getItem('chatSidebarCollapsed'); } catch (e) {}
        if (pref !== '1' && view.classList.contains('sidebar-collapsed')) _applySidebarState(true, false);
    }
}

// 空白态切换：无用户/助手消息时显示主页 hero，Composer 垂直居中
function _syncChatBlankState() {
    var main = document.getElementById('chat-main');
    var box = document.getElementById('chat-messages');
    if (!main || !box) return;
    var hasMessage = box.querySelector('.message:not(.system)');
    main.classList.toggle('is-blank', !hasMessage);
}

// 顶栏显示当前会话标题
function _updateChatHeaderTitle() {
    var el = document.getElementById('chat-session-title');
    if (!el) return;
    el.textContent = _sessionTitle(_currentSessionId());
}

// 「更多」菜单
function toggleChatMoreMenu(force) {
    var menu = document.getElementById('chat-more-menu');
    if (!menu) return;
    var open = (typeof force === 'boolean') ? force : menu.hasAttribute('hidden');
    if (open) menu.removeAttribute('hidden');
    else menu.setAttribute('hidden', '');
    var btn = document.getElementById('chat-more-btn');
    if (btn) btn.setAttribute('aria-expanded', open ? 'true' : 'false');
    if (open) _syncChatDockChecks();
}

function _syncChatDockChecks() {
    var view = document.getElementById('chat-view');
    if (!view) return;
    var todoPanel = document.getElementById('chat-todo-panel');
    var todoOpen = !!(todoPanel && todoPanel.style.display !== 'none');
    document.querySelectorAll('#chat-more-menu .chat-more-check').forEach(function (el) {
        var on = el.dataset.dock === 'files'
            ? view.classList.contains('dock-files')
            : todoOpen;
        el.classList.toggle('on', on);
    });
}

// 右侧面板（项目文件 / 任务计划）
function toggleChatDock(which) {
    var view = document.getElementById('chat-view');
    if (!view) return;
    if (which === 'files') {
        var opened = view.classList.toggle('dock-files');
        var panel = document.getElementById('chat-filetree-panel');
        if (opened && panel && !panel.dataset.inited) {
            panel.dataset.inited = '1';
            if (typeof initChatFileTree === 'function') initChatFileTree();
        }
    } else if (which === 'todo') {
        var todo = document.getElementById('chat-todo-panel');
        var todoList = document.getElementById('chat-todo-list');
        var hasTodo = !!(todoList && todoList.children.length);
        if (todo && hasTodo) {
            todo.style.display = (todo.style.display === 'none') ? 'flex' : 'none';
        } else {
            showToast('当前没有任务计划');
        }
    }
    _syncChatDockChecks();
}

// 空白态建议 chip：填入输入框并聚焦
function chatHeroSuggest(text) {
    var input = document.getElementById('message-input');
    if (!input) return;
    input.value = text || '';
    input.focus();
    if (typeof autoGrowInput === 'function') autoGrowInput(input);
    if (typeof updateSendState === 'function') updateSendState();
    try { input.setSelectionRange(input.value.length, input.value.length); } catch (e) {}
}

// ============= 斜杠命令 =============

var CHAT_COMMANDS = [
    { cmd: '/commands', desc: '列出全部斜杠命令', run: chatCommandHelp },
    { cmd: '/new', desc: '新建一个会话', run: function () { createNewSession(); } },
    { cmd: '/clear', desc: '清空当前会话消息', run: function () { clearChat(); } },
    { cmd: '/compact', desc: '压缩当前会话历史，释放上下文', run: chatCommandCompact },
    { cmd: '/session', desc: '查看当前会话与 DSH 会话 ID', run: chatCommandSession },
    { cmd: '/model', desc: '打开模型 / 供应商设置', run: function () { showSettings(); } },
    { cmd: '/permission', desc: '切换安全管控模式', run: function () { toggleSecurityMode(); } },
    { cmd: '/agent', desc: '切换到 Agent 工具模式', run: function () { applyReplyEngine('agent', { toast: true, persist: true }); } },
    { cmd: '/dsh', desc: '切换到 DSH 内核模式', run: function () { applyReplyEngine('dsh', { toast: true, persist: true }); } },
    { cmd: '/normal', desc: '切换到普通对话模式', run: function () { applyReplyEngine('normal', { toast: true, persist: true }); } }
];

var _cmdPaletteIndex = 0;
var _cmdPaletteItems = [];

function chatCommandHelp() {
    var lines = ['可用斜杠命令：'];
    CHAT_COMMANDS.forEach(function (c) {
        lines.push('`' + c.cmd + '` — ' + c.desc);
    });
    addMessage({ role: 'assistant', content: lines.join('\n') });
}

function chatCommandCompact() {
    var sid = _currentSessionId();
    showToast('正在压缩当前会话历史…', 'info');
    fetch('/api/context-compress/history/' + encodeURIComponent(sid), { method: 'POST' })
        .then(function (r) { return r.json(); })
        .then(function (d) {
            if (d && d.status === 'success') showToast('上下文压缩完成');
            else if (d && d.status === 'skipped') showToast('当前会话未达到压缩阈值', 'info');
            else showToast((d && d.message) || '压缩失败', 'error');
        })
        .catch(function (e) { showToast('压缩失败: ' + e.message, 'error'); });
}

function chatCommandSession() {
    var dsh = '';
    try { dsh = localStorage.getItem('dshSessionId') || ''; } catch (e) {}
    addMessage({
        role: 'assistant',
        content: '当前会话：`' + _currentSessionId() + '`\nDSH 会话：' + (dsh ? '`' + dsh + '`' : '（尚未创建）')
    });
}

function _cmdPaletteEl() { return document.getElementById('cmd-palette'); }

function _hideCmdPalette() {
    var el = _cmdPaletteEl();
    if (el) el.style.display = 'none';
    _cmdPaletteItems = [];
}

function _renderCmdPalette(keyword) {
    var box = _cmdPaletteEl();
    var list = document.getElementById('cmd-palette-list');
    if (!box || !list) return;
    var kw = (keyword || '').toLowerCase();
    _cmdPaletteItems = CHAT_COMMANDS.filter(function (c) {
        return !kw || c.cmd.indexOf(kw) === 0 || c.desc.toLowerCase().indexOf(kw) >= 0;
    }).slice(0, 8);
    if (!_cmdPaletteItems.length) { _hideCmdPalette(); return; }
    if (_cmdPaletteIndex >= _cmdPaletteItems.length) _cmdPaletteIndex = 0;
    list.innerHTML = _cmdPaletteItems.map(function (c, i) {
        return '<button class="cmd-palette-item' + (i === _cmdPaletteIndex ? ' active' : '') + '" data-i="' + i + '">' +
            '<span class="cmd-palette-cmd">' + escapeHtml(c.cmd) + '</span>' +
            '<span class="cmd-palette-desc">' + escapeHtml(c.desc) + '</span></button>';
    }).join('');
    list.querySelectorAll('.cmd-palette-item').forEach(function (btn) {
        btn.addEventListener('mousedown', function (ev) { ev.preventDefault(); });
        btn.addEventListener('click', function () {
            _pickCmdPalette(parseInt(btn.dataset.i, 10));
        });
    });
    box.style.display = 'block';
}

function _pickCmdPalette(i) {
    var item = _cmdPaletteItems[i];
    var input = document.getElementById('message-input');
    if (!item || !input) return;
    input.value = item.cmd + ' ';
    input.focus();
    autoGrowInput(input);
    _hideCmdPalette();
}

function _onCmdInput() {
    var input = document.getElementById('message-input');
    if (!input) return;
    var v = input.value || '';
    if (!v.startsWith('/') || /\s/.test(v)) { _hideCmdPalette(); return; }
    _cmdPaletteIndex = 0;
    _renderCmdPalette(v);
}

function _onCmdKeydown(e) {
    var box = _cmdPaletteEl();
    if (!box || box.style.display === 'none') return false;
    if (e.key === 'ArrowDown') {
        _cmdPaletteIndex = (_cmdPaletteIndex + 1) % _cmdPaletteItems.length;
        _renderCmdPalette((document.getElementById('message-input').value || ''));
    } else if (e.key === 'ArrowUp') {
        _cmdPaletteIndex = (_cmdPaletteIndex - 1 + _cmdPaletteItems.length) % _cmdPaletteItems.length;
        _renderCmdPalette((document.getElementById('message-input').value || ''));
    } else if (e.key === 'Enter' || e.key === 'Tab') {
        _pickCmdPalette(_cmdPaletteIndex);
    } else if (e.key === 'Escape') {
        _hideCmdPalette();
    } else {
        return false;
    }
    e.preventDefault();
    e.stopPropagation();
    return true;
}

function initSlashCommands() {
    var input = document.getElementById('message-input');
    if (!input || input._cmdBound) return;
    input._cmdBound = true;
    input.addEventListener('input', _onCmdInput);
    input.addEventListener('keydown', _onCmdKeydown, true);
    input.addEventListener('blur', function () { setTimeout(_hideCmdPalette, 150); });
}

// ===== @ 文件引用（DSH 式：输入 @ 弹出工作区文件，回车插入） =====
var _atPaletteItems = [];
var _atPaletteIndex = 0;
var _atFetchTimer = null;
var _atFetchSeq = 0;
var _atFileCache = {};

function _atPaletteEl() { return document.getElementById('at-palette'); }

function _hideAtPalette() {
    var el = _atPaletteEl();
    if (el) el.style.display = 'none';
    _atPaletteItems = [];
}

// 光标前是否是 @xxx 片段（行首或空白后）
function _atTokenBeforeCaret(input) {
    var pos = input.selectionStart || 0;
    var before = input.value.slice(0, pos);
    var m = /(^|[\s(（])@([^\s@]*)$/.exec(before);
    if (!m) return null;
    return { query: m[2] || '', pos: pos };
}

function _fetchAtFiles(query) {
    var seq = ++_atFetchSeq;
    fetch('/api/chat/files?q=' + encodeURIComponent(query || '') + '&limit=20')
        .then(function (r) { return r.json(); })
        .then(function (data) {
            if (seq !== _atFetchSeq) return;   // 旧响应不覆盖新响应
            _atPaletteItems = (data && data.files) || [];
            _atPaletteItems.forEach(function (f) { _atFileCache[f.path] = f; });
            var titleEl = document.querySelector('#at-palette .cmd-palette-title');
            if (titleEl) {
                var root = String((data && data.root) || '');
                var short = root.split(/[\\/]/).filter(Boolean).pop() || root;
                titleEl.textContent = '引用工作区文件 · ' + short;
            }
            _atPaletteIndex = 0;
            _renderAtPalette();
        })
        .catch(function () { _hideAtPalette(); });
}

function _renderAtPalette() {
    var box = _atPaletteEl();
    var list = document.getElementById('at-palette-list');
    if (!box || !list) return;
    if (!_atPaletteItems.length) { _hideAtPalette(); return; }
    if (_atPaletteIndex >= _atPaletteItems.length) _atPaletteIndex = 0;
    list.innerHTML = _atPaletteItems.map(function (f, i) {
        return '<button class="cmd-palette-item' + (i === _atPaletteIndex ? ' active' : '') + '" data-i="' + i + '">' +
            '<span class="cmd-palette-cmd">' + escapeHtml(f.path) + '</span>' +
            '<span class="cmd-palette-desc">' + escapeHtml(formatFileSize(f.size || 0)) + '</span></button>';
    }).join('');
    list.querySelectorAll('.cmd-palette-item').forEach(function (btn) {
        btn.addEventListener('mousedown', function (ev) { ev.preventDefault(); });
        btn.addEventListener('click', function () { _pickAtPalette(parseInt(btn.dataset.i, 10)); });
    });
    box.style.display = 'block';
}

function _pickAtPalette(i) {
    var item = _atPaletteItems[i];
    var input = document.getElementById('message-input');
    if (!item || !input) return;
    var pos = input.selectionStart || 0;
    var before = input.value.slice(0, pos);
    var after = input.value.slice(pos);
    var m = /(^|[\s(（])@([^\s@]*)$/.exec(before);
    var start = m ? pos - (m[2] || '').length - 1 : pos;
    var insert = '@' + item.path + ' ';
    input.value = before.slice(0, start) + insert + after;
    var caret = start + insert.length;
    input.focus();
    try { input.setSelectionRange(caret, caret); } catch (e) { /* ignore */ }
    autoGrowInput(input);
    _atFileCache[item.path] = item;
    _hideAtPalette();
    updateSendState();
}

function _onAtInput() {
    var input = document.getElementById('message-input');
    if (!input) return;
    var token = _atTokenBeforeCaret(input);
    if (!token) { _hideAtPalette(); return; }
    if (_atFetchTimer) clearTimeout(_atFetchTimer);
    _atFetchTimer = setTimeout(function () { _fetchAtFiles(token.query); }, 120);
}

function _onAtKeydown(e) {
    var box = _atPaletteEl();
    if (!box || box.style.display === 'none') return false;
    if (!_atPaletteItems.length) return false;
    if (e.key === 'ArrowDown') {
        _atPaletteIndex = (_atPaletteIndex + 1) % _atPaletteItems.length;
        _renderAtPalette();
    } else if (e.key === 'ArrowUp') {
        _atPaletteIndex = (_atPaletteIndex - 1 + _atPaletteItems.length) % _atPaletteItems.length;
        _renderAtPalette();
    } else if (e.key === 'Enter' || e.key === 'Tab') {
        _pickAtPalette(_atPaletteIndex);
    } else if (e.key === 'Escape') {
        _hideAtPalette();
    } else {
        return false;
    }
    e.preventDefault();
    e.stopPropagation();
    return true;
}

// 发送前把 `@路径` 展开成一段引用说明（模型据此用 read_file 精确读取）
function _expandAtFileRefs(content) {
    if (!content || content.indexOf('@') === -1) return content;
    var refs = [];
    var re = /(^|[\s(（])@([^\s@，。、；：）)]+)/g;
    var m;
    while ((m = re.exec(content)) !== null) {
        var p = m[2];
        if (p && refs.indexOf(p) === -1) refs.push(p);
    }
    if (!refs.length) return content;
    var lines = refs.map(function (p) {
        var meta = _atFileCache[p];
        var size = (meta && meta.size) ? '（' + formatFileSize(meta.size) + '）' : '';
        return '- ' + p + size;
    });
    return content + '\n\n📎 引用工作区文件：\n' + lines.join('\n');
}

function initAtReferences() {
    var input = document.getElementById('message-input');
    if (!input || input._atBound) return;
    input._atBound = true;
    input.addEventListener('input', _onAtInput);
    input.addEventListener('keydown', _onAtKeydown, true);
    input.addEventListener('blur', function () { setTimeout(_hideAtPalette, 150); });
}

// 发送前拦截：命中注册表的斜杠命令直接执行，不进入模型
function tryRunSlashCommand(rawContent) {
    if (!rawContent || !rawContent.startsWith('/')) return false;
    var cmd = rawContent.split(/\s+/)[0].toLowerCase();
    var meta = CHAT_COMMANDS.find(function (c) { return c.cmd === cmd; });
    if (!meta) return false;
    var input = document.getElementById('message-input');
    if (input) { input.value = ''; input.style.height = 'auto'; }
    _hideCmdPalette();
    try {
        meta.run(rawContent.slice(cmd.length).trim());
    } catch (e) {
        showError('命令执行失败: ' + e.message);
    }
    return true;
}

// ============= 用量统计 =============

function _usageFmt(n) { return (Number(n) || 0).toLocaleString('zh-CN'); }
function _usageCost(v) { return '$' + (Number(v) || 0).toFixed(4); }

function loadUsageStats() {
    var daysEl = document.getElementById('usage-range');
    var days = daysEl ? daysEl.value : '30';
    var cards = document.getElementById('usage-cards');
    if (cards) cards.innerHTML = '<div class="usage-empty">加载中…</div>';
    fetch('/api/usage/summary?days=' + encodeURIComponent(days))
        .then(function (r) { return r.json(); })
        .then(function (d) { _renderUsage(d || {}); })
        .catch(function (e) {
            if (cards) cards.innerHTML = '<div class="usage-empty">加载失败：' + escapeHtml(e.message) + '</div>';
        });
}

function _renderUsage(d) {
    var t = d.totals || {};
    var cards = document.getElementById('usage-cards');
    if (cards) {
        cards.innerHTML = [
            ['总 Tokens', _usageFmt(t.tokens)],
            ['输入', _usageFmt(t.in)],
            ['输出', _usageFmt(t.out)],
            ['调用次数', _usageFmt(t.calls)],
            ['估算费用', _usageCost(t.cost)]
        ].map(function (x) {
            return '<div class="usage-card"><div class="usage-card-label">' + x[0] +
                '</div><div class="usage-card-value">' + x[1] + '</div></div>';
        }).join('');
    }
    var daysBox = document.getElementById('usage-days');
    if (daysBox) {
        var rows = (d.by_day || []).slice().reverse();
        if (!rows.length) {
            daysBox.innerHTML = '<div class="usage-empty">暂无数据，发送一次对话后再来看</div>';
        } else {
            var html = '<table><thead><tr><th>日期</th><th>输入</th><th>输出</th><th>调用</th><th>估算费用</th></tr></thead><tbody>';
            rows.forEach(function (r) {
                html += '<tr><td>' + escapeHtml(r.date) + '</td><td>' + _usageFmt(r.in) +
                    '</td><td>' + _usageFmt(r.out) + '</td><td>' + _usageFmt(r.calls) +
                    '</td><td>' + _usageCost(r.cost) + '</td></tr>';
            });
            daysBox.innerHTML = html + '</tbody></table>';
        }
    }
    var mb = document.getElementById('usage-models');
    if (mb) {
        var models = d.by_model || [];
        if (!models.length) {
            mb.innerHTML = '<div class="usage-empty">暂无数据</div>';
        } else {
            var h2 = '<table><thead><tr><th>模型</th><th>输入</th><th>输出</th><th>调用</th><th>估算费用</th></tr></thead><tbody>';
            models.forEach(function (m) {
                h2 += '<tr><td>' + escapeHtml(m.model) + '</td><td>' + _usageFmt(m.in) +
                    '</td><td>' + _usageFmt(m.out) + '</td><td>' + _usageFmt(m.calls) +
                    '</td><td>' + _usageCost(m.cost) + '</td></tr>';
            });
            mb.innerHTML = h2 + '</tbody></table>';
        }
    }
}

// 初始化聊天页外壳（菜单关闭、空白态观察、窄窗收起）
function initChatShell() {
    document.addEventListener('click', function (e) {
        var menu = document.getElementById('chat-more-menu');
        if (!menu || menu.hasAttribute('hidden')) return;
        if (e.target.closest && (e.target.closest('#chat-more-menu') || e.target.closest('#chat-more-btn'))) return;
        toggleChatMoreMenu(false);
    });
    document.addEventListener('keydown', function (e) {
        if (e.key === 'Escape') toggleChatMoreMenu(false);
    });

    var box = document.getElementById('chat-messages');
    if (box && !box._blankObserver) {
        box._blankObserver = new MutationObserver(function () { _syncChatBlankState(); });
        box._blankObserver.observe(box, { childList: true });
    }

    _autoCollapseSidebar();
    renderWidgetLauncher('');
    initSlashCommands();
    initAtReferences();
    initFontColorSettings();
    initNowPlayingBar();
    _cleanupRedundantViewButtons();
    _bindPlaylistDrag();
    // 酷狗面板必须在右栏里（历史 HTML 结构调整容易挂错层级，这里兜底纠正）
    (function () {
        var panel = document.getElementById('music-tab-kugou');
        var right = document.querySelector('#music-view .player-right');
        if (panel && right && panel.parentElement !== right) right.appendChild(panel);
    })();
    try {
        if (localStorage.getItem('musicPlaylistWall') === '1') {
            var pl = document.getElementById('playlist');
            if (pl) pl.classList.add('cover-wall');
            var wbtn = document.getElementById('playlist-wall-btn');
            if (wbtn) wbtn.classList.add('active');
        }
    } catch (e) { /* ignore */ }
    window.addEventListener('resize', function () {
        _autoCollapseSidebar();
        _clampWidgets();
    });
    _syncChatBlankState();
}


function loadSessions() {
    return fetch('/api/chat/sessions')
        .then(function (r) { return r.json(); })
        .then(function (d) {
            _sessions = (d && d.sessions) || [];
            if (d && d.active) _activeSessionId = d.active;
            renderSessionList();
            return _sessions;
        })
        .catch(function (e) { console.error('加载会话列表失败:', e); });
}

function _sessionGroupLabel(iso) {
    if (!iso) return '更早';
    var d = new Date(iso);
    if (isNaN(d.getTime())) return '更早';
    var now = new Date();
    var startToday = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
    var t = d.getTime();
    if (t >= startToday) return '今天';
    if (t >= startToday - 86400000) return '昨天';
    if (t >= startToday - 6 * 86400000) return '最近 7 天';
    return '更早';
}

function renderSessionList() {
    var box = document.getElementById('session-list');
    if (!box) return;
    var kw = ((document.getElementById('session-search') || {}).value || '').trim().toLowerCase();
    var list = kw ? _sessions.filter(function (s) {
        return (s.title || '').toLowerCase().indexOf(kw) >= 0 ||
            (s.preview || '').toLowerCase().indexOf(kw) >= 0;
    }) : _sessions;

    var foot = document.getElementById('session-drawer-foot');
    if (foot) foot.textContent = '共 ' + _sessions.length + ' 个会话';
    _updateChatHeaderTitle();

    if (!list.length) {
        box.innerHTML = '<div class="session-empty">' +
            (kw ? '没有匹配的会话' : '还没有会话，点上面新建一个') + '</div>';
        return;
    }

    var html = '';
    var lastGroup = '';
    list.forEach(function (s) {
        var group = _sessionGroupLabel(s.updated_at);
        if (group !== lastGroup) {
            html += '<div class="session-group-label">' + group + '</div>';
            lastGroup = group;
        }
        var active = (s.id === _currentSessionId()) ? ' active' : '';
        var count = (s.display_count === undefined ? 0 : s.display_count);
        html += '<div class="session-item' + active + '" data-sid="' + escapeHtml(s.id) + '">' +
            '<div class="session-item-title">' + escapeHtml(s.title || '新对话') + '</div>' +
            '<div class="session-item-preview">' + escapeHtml(s.preview || '（空白会话）') + '</div>' +
            '<div class="session-item-meta">' + count + ' 条 · ' + _formatSessionTime(s.updated_at) + '</div>' +
            '<div class="session-item-actions">' +
            '<button data-act="rename" title="重命名"><i class="fas fa-pen"></i></button>' +
            '<button data-act="delete" class="danger" title="删除"><i class="fas fa-trash"></i></button>' +
            '</div></div>';
    });
    box.innerHTML = html;
}

function _initSessionListEvents() {
    var box = document.getElementById('session-list');
    if (!box || box._sessionBound) return;
    box._sessionBound = true;
    box.addEventListener('click', function (ev) {
        var item = ev.target.closest ? ev.target.closest('.session-item') : null;
        if (!item) return;
        var sid = item.dataset.sid;
        var actBtn = ev.target.closest('[data-act]');
        if (actBtn) {
            ev.stopPropagation();
            if (actBtn.dataset.act === 'rename') renameSession(sid);
            else if (actBtn.dataset.act === 'delete') deleteSession(sid);
            return;
        }
        if (ev.target.closest('.session-item-title-input')) return;
        activateSession(sid);
    });
}

// 把后端的消息数组渲染进聊天区（空会话时恢复欢迎语）
function _renderSessionMessages(messages) {
    var container = document.getElementById('chat-messages');
    if (!container) return;
    container.innerHTML = '';
    if (!messages || !messages.length) {
        container.innerHTML = _welcomeHtml || '';
        _syncChatBlankState();
        return;
    }
    messages.forEach(function (m) { addMessage(m); });
    _syncChatBlankState();
    scrollToBottom();
}

function _refreshSessionListIfOpen() {
    var view = document.getElementById('chat-view');
    if (view && !view.classList.contains('sidebar-collapsed')) loadSessions();
}

function _captureWelcome() {
    var c = document.getElementById('chat-messages');
    if (c && _welcomeHtml === null) _welcomeHtml = c.innerHTML;
}

function createNewSession() {
    fetch('/api/chat/sessions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({}),
    })
        .then(function (r) { return r.json(); })
        .then(function (d) {
            if (!d || d.status !== 'success') {
                showToast((d && d.message) || '新建会话失败', 'error');
                return;
            }
            _activeSessionId = d.session_id;
            if (d.sessions) _sessions = d.sessions;
            _renderSessionMessages([]);
            renderSessionList();
            showToast('已新建会话');
            var input = document.getElementById('message-input');
            if (input) input.focus();
        })
        .catch(function () { showToast('新建会话失败', 'error'); });
}

// ===== 文件检查点（写操作前自动快照，可回滚） =====

function showCheckpoints() {
    var convId = _currentSessionId();
    fetch('/api/chat/checkpoints?conv_id=' + encodeURIComponent(convId) + '&limit=30')
        .then(function (r) { return r.json(); })
        .then(function (d) {
            var items = (d && d.checkpoints) || [];
            if (!items.length) {
                showDialog('文件检查点',
                    '<div class="form-tips">当前会话还没有检查点。</div>' +
                    '<div class="form-tips">Agent 每次调用写文件类工具前，都会自动把目标文件快照到 <code>data/checkpoints</code>，' +
                    '这里就能回滚。</div>', null);
                return;
            }
            var html = '<div class="ck-list">' + items.map(function (it) {
                var when = it.time ? new Date(it.time * 1000).toLocaleString('zh-CN', { hour12: false }) : '';
                var paths = (it.paths || []).map(function (p) { return escapeHtml(p); }).join('<br>');
                return '<div class="ck-item">' +
                    '<div class="ck-main">' +
                    '<div class="ck-head"><b>' + escapeHtml(it.tool || '写入') + '</b><span class="ck-time">' + escapeHtml(when) + '</span></div>' +
                    '<div class="ck-paths">' + paths + '</div>' +
                    '</div>' +
                    '<div class="ck-actions">' +
                    '<button class="btn btn-sm" onclick="restoreCheckpoint(\'' + it.id + '\')"><i class="fas fa-rotate-left"></i> 回滚</button>' +
                    '<button class="btn btn-sm" onclick="deleteCheckpoint(\'' + it.id + '\')"><i class="fas fa-trash"></i></button>' +
                    '</div></div>';
            }).join('') + '</div>';
            showDialog('文件检查点（' + items.length + ' 个）', html, null);
        })
        .catch(function () { showToast('读取检查点失败', 'error'); });
}

function restoreCheckpoint(id) {
    if (!confirm('回滚到这个检查点？\n会把文件恢复成快照内容，并删除当时还不存在的文件（进回收站，可再还原）。')) return;
    fetch('/api/chat/checkpoints/' + encodeURIComponent(id) + '/restore', { method: 'POST' })
        .then(function (r) { return r.json(); })
        .then(function (d) {
            if (!d || !d.ok) {
                showToast('回滚失败：' + ((d && d.error) || '未知错误'), 'error');
                return;
            }
            showToast('已回滚 ' + ((d.restored || []).length) + ' 个文件，清理 ' + ((d.removed || []).length) + ' 个');
            showCheckpoints();
        })
        .catch(function () { showToast('回滚失败', 'error'); });
}

function deleteCheckpoint(id) {
    if (!confirm('删除这个检查点？（只删快照，不动文件）')) return;
    fetch('/api/chat/checkpoints/' + encodeURIComponent(id), { method: 'DELETE' })
        .then(function (r) { return r.json(); })
        .then(function (d) {
            showToast(d && d.ok ? '已删除检查点' : '删除失败', d && d.ok ? 'success' : 'error');
            showCheckpoints();
        });
}

// 从某条消息分支出新会话（保留到这条为止的可见消息）
function forkFromMessage(btn) {
    var messageDiv = btn && btn.closest ? btn.closest('.message') : null;
    if (!messageDiv) return;
    var all = Array.prototype.slice.call(document.querySelectorAll('#chat-messages .message'));
    var keep = all.indexOf(messageDiv) + 1;
    if (keep <= 0) return;
    if (!confirm('从这条消息分支出新会话？\n会保留到此为止的 ' + keep + ' 条消息，原会话不受影响。')) return;
    fetch('/api/chat/sessions/' + encodeURIComponent(_currentSessionId()) + '/fork', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ keep_display: keep })
    }).then(function (r) { return r.json(); }).then(function (d) {
        if (!d || d.status !== 'success') {
            showToast((d && d.message) || '分支失败', 'error');
            return;
        }
        if (d.sessions) _sessions = d.sessions;
        activateSession(d.session_id, true);
        showToast('已创建分支会话');
    }).catch(function () { showToast('分支失败', 'error'); });
}

function activateSession(sid, force) {
    if (!sid) return;
    if (!force && sid === _currentSessionId()) return;
    fetch('/api/chat/sessions/' + encodeURIComponent(sid) + '/activate', { method: 'POST' })
        .then(function (r) { return r.json(); })
        .then(function (d) {
            if (!d || d.status !== 'success') {
                showToast((d && d.message) || '切换会话失败', 'error');
                return;
            }
            _activeSessionId = d.session_id;
            if (d.sessions) _sessions = d.sessions;
            _renderSessionMessages(d.messages || []);
            renderSessionList();
        })
        .catch(function () { showToast('切换会话失败', 'error'); });
}

function renameSession(sid) {
    var item = _findSessionItem(sid);
    if (!item) return;
    var titleEl = item.querySelector('.session-item-title');
    if (!titleEl) return;
    var current = titleEl.textContent;
    var input = document.createElement('input');
    input.className = 'session-item-title-input';
    input.value = current;
    titleEl.replaceWith(input);
    input.focus();
    input.select();

    var done = false;
    var commit = function (save) {
        if (done) return;
        done = true;
        var val = (input.value || '').trim();
        if (!save || !val || val === current) { renderSessionList(); return; }
        fetch('/api/chat/sessions/' + encodeURIComponent(sid), {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ title: val }),
        })
            .then(function (r) { return r.json(); })
            .then(function (d) {
                if (d && d.status === 'success') {
                    if (d.sessions) _sessions = d.sessions;
                    showToast('已重命名');
                } else {
                    showToast((d && d.message) || '重命名失败', 'error');
                }
                renderSessionList();
            })
            .catch(function () { showToast('重命名失败', 'error'); renderSessionList(); });
    };
    input.addEventListener('keydown', function (ev) {
        if (ev.key === 'Enter') { ev.preventDefault(); commit(true); }
        else if (ev.key === 'Escape') { ev.preventDefault(); commit(false); }
    });
    input.addEventListener('blur', function () { commit(true); });
}

function deleteSession(sid) {
    var title = _sessionTitle(sid);
    if (!confirm('确定删除会话「' + title + '」吗？\n该会话的消息会一并删除，且不可恢复。')) return;
    var wasActive = (sid === _currentSessionId());
    fetch('/api/chat/sessions/' + encodeURIComponent(sid), { method: 'DELETE' })
        .then(function (r) { return r.json(); })
        .then(function (d) {
            if (!d || d.status !== 'success') {
                showToast((d && d.message) || '删除失败', 'error');
                return;
            }
            if (d.sessions) _sessions = d.sessions;
            if (wasActive) {
                _activeSessionId = d.active || 'default';
                _renderSessionMessages(d.messages || []);
            } else if (d.active) {
                _activeSessionId = d.active;
            }
            renderSessionList();
            showToast('已删除会话');
        })
        .catch(function () { showToast('删除失败', 'error'); });
}

function loadChatHistory() {
    fetch('/api/chat/history')
        .then(response => response.json())
        .then(data => {
            if (data && data.session_id) _activeSessionId = data.session_id;
            if (data && data.sessions) {
                _sessions = data.sessions;
                renderSessionList();
            }
            var messages = (data && data.messages) || [];
            if (messages.length > 0) {
                var container = document.getElementById('chat-messages');
                container.innerHTML = '';
                messages.forEach(msg => { addMessage(msg); });
                scrollToBottom();
            }
        })
        .catch(error => console.error('加载聊天历史失败:', error));
}

// ============= 聊天历史管理（保存/导出/导入） =============

function saveChatHistory() {
    fetch('/api/chat/history/save', { method: 'POST' })
        .then(response => response.json())
        .then(data => {
            if (data.status === 'success') {
                showToast(`✅ 聊天历史已保存（${data.count} 条消息）`);
            } else {
                showToast(data.message || '保存失败');
            }
        })
        .catch(error => {
            console.error('保存聊天历史失败:', error);
            showToast('❌ 保存聊天历史失败');
        });
}

function exportChatHistory() {
    // 使用 fetch 获取文件流，然后创建下载链接
    fetch('/api/chat/history/export', { method: 'POST' })
        .then(response => {
            if (!response.ok) {
                throw new Error('导出失败');
            }
            // 从 Content-Disposition 头中提取文件名
            const disposition = response.headers.get('Content-Disposition') || '';
            const filenameMatch = disposition.match(/filename="?([^";\n]+)"?/);
            const filename = filenameMatch ? filenameMatch[1] : `chat_history_${new Date().toISOString().slice(0, 19).replace(/[:-]/g, '')}.json`;
            
            return response.blob().then(blob => ({ blob, filename }));
        })
        .then(({ blob, filename }) => {
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = filename;
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);
            showToast('✅ 聊天历史已导出');
        })
        .catch(error => {
            console.error('导出聊天历史失败:', error);
            showToast('❌ 导出聊天历史失败');
        });
}

function importChatHistory(input) {
    const file = input.files[0];
    if (!file) return;
    
    if (!file.name.endsWith('.json')) {
        showToast('❌ 只支持 JSON 格式文件');
        input.value = '';
        return;
    }
    
    // 确认导入操作
    if (!confirm('导入聊天记录将替换当前所有聊天内容，当前记录将被备份。\n确定要继续吗？')) {
        input.value = '';
        return;
    }
    
    const formData = new FormData();
    formData.append('file', file);
    
    fetch('/api/chat/history/import', {
        method: 'POST',
        body: formData
    })
        .then(response => response.json())
        .then(data => {
            if (data.status === 'success') {
                showToast(`✅ 成功导入 ${data.count} 条聊天记录`);
                // 重新加载聊天历史
                loadChatHistory();
            } else {
                showToast(`❌ ${data.detail || data.message || '导入失败'}`);
            }
        })
        .catch(error => {
            console.error('导入聊天历史失败:', error);
            showToast('❌ 导入聊天历史失败');
        })
        .finally(() => {
            input.value = '';
        });
}

// ============= 历史对话管理 =============

let _currentConversationId = null;

function refreshConversations() {
    const list = document.getElementById('history-list');
    list.innerHTML = '<div class="empty-state">加载中...</div>';

    fetch('/api/conversations/list')
        .then(response => response.json())
        .then(data => {
            if (data.success && data.data && data.data.length > 0) {
                const MAX_SHOWN = 50;
                const items = data.data;
                list.innerHTML = '';

                function buildItem(conv) {
                    const item = document.createElement('div');
                    item.className = 'history-list-item';

                    const created = conv.created_at ? new Date(conv.created_at).toLocaleString() : '未知';
                    const updated = conv.updated_at ? new Date(conv.updated_at).toLocaleString() : '未知';
                    const convId = conv.conversation_id || 'default';

                    item.innerHTML = `
                        <div class="history-list-item-info" onclick="openConversationDetail('${convId}')">
                            <div class="history-list-item-id">对话 ${convId.substring(0, 16)}...</div>
                            <div class="history-list-item-meta">
                                <span>📅 ${created}</span>
                                <span>🔄 ${updated}</span>
                            </div>
                        </div>
                        <div class="history-list-item-stats">${conv.message_count} 条消息</div>
                        <button class="btn btn-sm" onclick="event.stopPropagation(); deleteConversation('${convId}')" title="删除">
                            <i class="fas fa-trash"></i>
                        </button>
                    `;
                    return item;
                }

                // 前 MAX_SHOWN 条直接显示
                items.slice(0, MAX_SHOWN).forEach(conv => {
                    list.appendChild(buildItem(conv));
                });

                // 多余的折叠起来，默认不显示
                if (items.length > MAX_SHOWN) {
                    const extraCount = items.length - MAX_SHOWN;
                    const extraWrap = document.createElement('div');
                    extraWrap.id = 'history-extra-wrap';
                    extraWrap.style.display = 'none';
                    items.slice(MAX_SHOWN).forEach(conv => {
                        extraWrap.appendChild(buildItem(conv));
                    });
                    list.appendChild(extraWrap);

                    const toggle = document.createElement('div');
                    toggle.className = 'history-collapse-toggle';
                    toggle.innerHTML = `<button class="btn btn-sm" id="history-collapse-btn" onclick="toggleExtraConversations()">
                        <i class="fas fa-chevron-down"></i> 展开剩余 ${extraCount} 条记录
                    </button>`;
                    list.appendChild(toggle);
                }
            } else {
                list.innerHTML = '<div class="empty-state">暂无保存的历史对话</div>';
            }
        })
        .catch(error => {
            console.error('加载对话列表失败:', error);
            list.innerHTML = '<div class="empty-state">加载失败</div>';
        });
}

// 展开/折叠多余的历史记录
function toggleExtraConversations() {
    const wrap = document.getElementById('history-extra-wrap');
    const btn = document.getElementById('history-collapse-btn');
    if (!wrap || !btn) return;
    const isCollapsed = wrap.style.display === 'none';
    wrap.style.display = isCollapsed ? '' : 'none';
    btn.innerHTML = isCollapsed
        ? '<i class="fas fa-chevron-up"></i> 折叠多余记录'
        : '<i class="fas fa-chevron-down"></i> 展开剩余记录';
}

function searchConversations() {
    const query = document.getElementById('history-search-input').value.trim();
    const list = document.getElementById('history-list');
    
    if (!query) {
        refreshConversations();
        return;
    }
    
    list.innerHTML = '<div class="empty-state">搜索中...</div>';
    
    fetch('/api/conversations/search', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ query })
    })
        .then(response => response.json())
        .then(data => {
            if (data.success && data.data && data.data.length > 0) {
                list.innerHTML = '';
                data.data.forEach(item => {
                    const div = document.createElement('div');
                    div.className = 'history-list-item';
                    const role = item.role === 'user' ? '👤 用户' : '🤖 AI';
                    const time = item.time ? new Date(item.time).toLocaleString() : '';
                    div.innerHTML = `
                        <div class="history-list-item-info" onclick="openConversationDetail('${item.conversation_id}')">
                            <div class="history-list-item-id">${role}: ${item.content.substring(0, 60)}${item.content.length > 60 ? '...' : ''}</div>
                            <div class="history-list-item-meta">${time}</div>
                        </div>
                    `;
                    list.appendChild(div);
                });
            } else {
                list.innerHTML = '<div class="empty-state">未找到匹配的对话记录</div>';
            }
        })
        .catch(error => {
            console.error('搜索对话失败:', error);
            list.innerHTML = '<div class="empty-state">搜索失败</div>';
        });
}

function openConversationDetail(conversationId) {
    _currentConversationId = conversationId;
    document.getElementById('history-list').style.display = 'none';
    document.getElementById('history-toolbar').style.display = 'none';
    document.getElementById('history-detail').style.display = 'flex';
    document.getElementById('history-detail-title').textContent = `对话详情`;
    
    const messagesContainer = document.getElementById('history-detail-messages');
    messagesContainer.innerHTML = '<div class="empty-state">加载中...</div>';
    
    fetch(`/api/conversations/${conversationId}`)
        .then(response => response.json())
        .then(data => {
            if (data.success && data.data && data.data.length > 0) {
                messagesContainer.innerHTML = '';
                data.data.forEach(msg => {
                    const div = document.createElement('div');
                    div.className = `history-detail-message history-msg-${msg.role || 'user'}`;
                    const role = msg.role === 'user' ? '👤 用户' : '🤖 AI';
                    const time = msg.time ? new Date(msg.time).toLocaleString() : '';
                    const content = msg.content || '';
                    div.innerHTML = `
                        <div class="history-detail-message-role">${role}</div>
                        <div class="history-detail-message-content">${escapeHtml(content)}</div>
                        <div class="history-detail-message-time">${time}</div>
                    `;
                    messagesContainer.appendChild(div);
                });
            } else {
                messagesContainer.innerHTML = '<div class="empty-state">对话内容为空</div>';
            }
        })
        .catch(error => {
            console.error('加载对话详情失败:', error);
            messagesContainer.innerHTML = '<div class="empty-state">加载失败</div>';
        });
}

function closeHistoryDetail() {
    _currentConversationId = null;
    document.getElementById('history-list').style.display = 'flex';
    document.getElementById('history-toolbar').style.display = 'flex';
    document.getElementById('history-detail').style.display = 'none';
}

function deleteConversation(conversationId) {
    if (!confirm('确定要删除这条对话记录吗？')) return;
    
    fetch(`/api/conversations/${conversationId}`, { method: 'DELETE' })
        .then(response => response.json())
        .then(data => {
            if (data.success) {
                showToast('✅ 对话已删除');
                refreshConversations();
            } else {
                showToast('❌ 删除失败', 'error');
            }
        })
        .catch(error => {
            console.error('删除对话失败:', error);
            showToast('❌ 删除失败', 'error');
        });
}

function deleteCurrentConversation() {
    if (_currentConversationId) {
        deleteConversation(_currentConversationId);
        closeHistoryDetail();
    }
}
// ============= 用户画像管理 =============

function loadUserProfile() {
    const loading = document.getElementById('profile-loading');
    const content = document.getElementById('profile-content');
    loading.style.display = 'block';
    content.style.display = 'none';

    fetch('/api/profile')
        .then(response => response.json())
        .then(data => {
            loading.style.display = 'none';
            content.style.display = 'flex';

            if (!data.success || !data.data) {
                document.getElementById('profile-basic-info').innerHTML = '<div class="profile-stat"><span class="profile-stat-label">暂无数据</span></div>';
                return;
            }

            const profile = data.data;
            const prefs = profile.preferences || {};
            const personality = profile.personality || {};
            const keywords = profile.keywords || [];

            // 基本信息
            const basicInfo = document.getElementById('profile-basic-info');
            const totalMsgs = profile.total_messages || 0;
            const totalConvs = profile.total_conversations || 0;
            const firstTime = profile.first_interaction ? new Date(profile.first_interaction).toLocaleString() : '未知';
            const lastTime = profile.last_interaction ? new Date(profile.last_interaction).toLocaleString() : '未知';
            basicInfo.innerHTML = `
                <div class="profile-stat"><span class="profile-stat-label">总消息数</span><span class="profile-stat-value">${totalMsgs}</span></div>
                <div class="profile-stat"><span class="profile-stat-label">对话次数</span><span class="profile-stat-value">${totalConvs}</span></div>
                <div class="profile-stat"><span class="profile-stat-label">首次互动</span><span class="profile-stat-value">${firstTime}</span></div>
                <div class="profile-stat"><span class="profile-stat-label">最近互动</span><span class="profile-stat-value">${lastTime}</span></div>
            `;

            // 对话风格
            const styleInfo = document.getElementById('profile-style');
            const styleMap = { formal: '正式', casual: '随意', neutral: '中性' };
            const style = styleMap[prefs.style] || '中性';
            const emojiMap = { high: '频繁', medium: '适中', low: '较少' };
            const emojiUsage = emojiMap[prefs.emoji_usage] || '未知';
            const avgLen = prefs.avg_message_length || 0;
            styleInfo.innerHTML = `
                <div class="profile-stat"><span class="profile-stat-label">对话风格</span><span class="profile-stat-value">${style}</span></div>
                <div class="profile-stat"><span class="profile-stat-label">表情使用</span><span class="profile-stat-value">${emojiUsage}</span></div>
                <div class="profile-stat"><span class="profile-stat-label">平均消息长度</span><span class="profile-stat-value">${avgLen} 字符</span></div>
            `;

            // 个性特征
            const personalityInfo = document.getElementById('profile-personality');
            const curiosity = (personality.curiosity || 0.5) * 100;
            const expressiveness = (personality.expressiveness || 0.5) * 100;
            const emotionality = (personality.emotionality || 0.5) * 100;
            personalityInfo.innerHTML = `
                <div class="profile-personality-bar">
                    <span class="bar-label">好奇心</span>
                    <div class="bar-track"><div class="bar-fill" style="width:${curiosity}%"></div></div>
                    <span class="bar-value">${Math.round(curiosity)}%</span>
                </div>
                <div class="profile-personality-bar">
                    <span class="bar-label">表达欲</span>
                    <div class="bar-track"><div class="bar-fill" style="width:${expressiveness}%"></div></div>
                    <span class="bar-value">${Math.round(expressiveness)}%</span>
                </div>
                <div class="profile-personality-bar">
                    <span class="bar-label">情感倾向</span>
                    <div class="bar-track"><div class="bar-fill" style="width:${emotionality}%"></div></div>
                    <span class="bar-value">${Math.round(emotionality)}%</span>
                </div>
            `;

            // 关键词
            const keywordsInfo = document.getElementById('profile-keywords');
            if (keywords.length > 0) {
                keywordsInfo.innerHTML = keywords.map(k =>
                    `<span class="profile-tag">${k.word} (${k.count})</span>`
                ).join('');
            } else {
                keywordsInfo.innerHTML = '<div class="profile-stat"><span class="profile-stat-label">暂无数据，继续对话后自动生成</span></div>';
            }
        })
        .catch(error => {
            console.error('加载用户画像失败:', error);
            loading.innerHTML = '加载失败';
        });
}

function resetUserProfile() {
    if (!confirm('确定要重置用户画像吗？这将清除所有学习到的用户偏好数据。')) return;

    fetch('/api/profile/reset', { method: 'POST' })
        .then(response => response.json())
        .then(data => {
            if (data.success) {
                showToast('✅ 用户画像已重置');
                loadUserProfile();
            } else {
                showToast('❌ 重置失败', 'error');
            }
        })
        .catch(error => {
            console.error('重置用户画像失败:', error);
            showToast('❌ 重置失败', 'error');
        });
}

