var _widgets = {};
var _widgetZ = 100;
var _widgetCascade = 0;
var WIDGET_GEOM_KEY = 'chatWidgetGeometry';

function _widgetLayerEl() {
    return document.getElementById('widget-layer');
}

function _widgetCatalogItem(id) {
    for (var i = 0; i < WIDGET_CATALOG.length; i++) {
        var items = WIDGET_CATALOG[i].items;
        for (var j = 0; j < items.length; j++) {
            if (items[j].id === id) return items[j];
        }
    }
    return null;
}

function _isWidgetView(id) {
    var item = _widgetCatalogItem(id);
    return !!(item && !item.href && !item.special);
}

function _widgetSearchTerms(keyword) {
    return (keyword || '').trim().toLowerCase().split(/\s+/).filter(Boolean);
}

function _widgetMatchItem(it, groupName, terms) {
    if (!terms.length) return true;
    var hay = [it.name, it.py || '', it.keywords || '', groupName].join(' ').toLowerCase();
    return terms.every(function (t) { return hay.indexOf(t) >= 0; });
}

// 名称命中片段高亮
function _widgetHighlightName(name, terms) {
    var safeName = escapeHtml(name);
    for (var i = 0; i < terms.length; i++) {
        var t = terms[i].toLowerCase();
        var raw = String(name).toLowerCase();
        var pos = raw.indexOf(t);
        if (pos < 0) continue;
        var safeTerm = escapeHtml(name.substr(pos, t.length));
        if (!safeTerm) continue;
        return safeName.replace(safeTerm, '<mark class="widget-tile-hit">' + safeTerm + '</mark>');
    }
    return safeName;
}

function renderWidgetLauncher(keyword) {
    var box = document.getElementById('widget-groups');
    if (!box) return;
    var terms = _widgetSearchTerms(keyword);
    var html = '';
    var tileIndex = 0;
    var total = 0;
    WIDGET_CATALOG.forEach(function (group) {
        var items = group.items.filter(function (it) {
            return _widgetMatchItem(it, group.group, terms);
        });
        if (!items.length) return;
        total += items.length;
        html += '<div class="widget-group"><div class="widget-group-title">' + group.group + '</div><div class="widget-group-grid">';
        items.forEach(function (it) {
            var state = _widgets[it.id];
            var open = !!(state && state.el && !state.minimized);
            var icon = '<i class="' + (it.brand ? 'fab' : 'fas') + ' ' + it.icon + '"></i>';
            var onclick = it.href
                ? "location.href='" + it.href + "'"
                : (it.id === 'music'
                    ? "openMusicApp()"
                    : "openWidgetFromLauncher('" + it.id + "')");
            html += '<button class="widget-tile' + (open ? ' is-open' : '') + '" style="--tile-i:' + Math.min(tileIndex, 14) + '" onclick="' + onclick + ';toggleAppsPanel()" title="' + escapeHtml(it.name) + '">' +
                icon + '<span>' + _widgetHighlightName(it.name, terms) + '</span></button>';
            tileIndex++;
        });
        html += '</div></div>';
    });
    box.innerHTML = html || '<div class="widget-empty">没有匹配「' + escapeHtml((keyword || '').trim()) + '」的挂件</div>';

    var countEl = document.getElementById('widget-search-count');
    if (countEl) countEl.textContent = terms.length ? total + ' 个结果' : total + ' 个挂件';
    var clearEl = document.getElementById('widget-search-clear');
    if (clearEl) clearEl.hidden = !(keyword || '').trim();
}

// 清空搜索并保持焦点
function widgetClearSearch() {
    var input = document.getElementById('widget-search');
    if (!input) return;
    input.value = '';
    renderWidgetLauncher('');
    input.focus();
}

// 搜索框键盘：Esc 清空/关闭，Enter 打开第一个结果
function widgetSearchKeydown(e) {
    if (e.key === 'Escape') {
        e.preventDefault();
        var input = document.getElementById('widget-search');
        if (input && input.value) {
            widgetClearSearch();
        } else {
            toggleAppsPanel();
        }
        return;
    }
    if (e.key === 'Enter') {
        e.preventDefault();
        var first = document.querySelector('#widget-groups .widget-tile');
        if (first) first.click();
    }
}

// 音乐播放器：桌面壳里开独立窗口，避免主窗口跳转（如进 DSH 内核）时中断播放
function openMusicApp() {
    var url = location.origin + '/music';
    try {
        var api = window.pywebview && window.pywebview.api;
        if (api && typeof api.open_music_window === 'function') {
            api.open_music_window(url).then(function (r) {
                if (r && r.success === false && typeof showToast === 'function') {
                    showToast(r.message || '音乐窗口打开失败', 'error');
                }
            }).catch(function () {
                if (typeof showToast === 'function') showToast('音乐窗口打开失败', 'error');
            });
            return;
        }
    } catch (e) { /* 浏览器环境继续走整页跳转 */ }
    location.href = url;
}

function openWidgetFromLauncher(id) {
    if (id === 'chat') {
        showChatBase();
        return;
    }
    switchView(id);
}

function _widgetDefaultGeom(item) {
    var layer = _widgetLayerEl();
    var lw = layer ? layer.clientWidth : 1200;
    var lh = layer ? layer.clientHeight : 800;
    var w, h;
    if (item && item.mini) {
        // 迷你播放器：窄长条，默认贴右下
        w = Math.min(lw - 48, 420);
        h = Math.min(lh - 48, 560);
        return {
            left: Math.max(12, lw - w - 32),
            top: Math.max(12, lh - h - 32),
            width: Math.round(w),
            height: Math.round(h)
        };
    }
    w = item && item.big
        ? Math.min(lw - 32, Math.max(640, lw * 0.86))
        : Math.min(lw - 48, Math.max(480, Math.min(960, lw * 0.68)));
    h = item && item.big
        ? Math.min(lh - 32, Math.max(420, lh * 0.86))
        : Math.min(lh - 48, Math.max(360, Math.min(720, lh * 0.72)));
    var offset = (_widgetCascade % 6) * 24;
    var left = Math.max(12, Math.round((lw - w) / 2) + offset);
    var top = Math.max(12, Math.round((lh - h) / 2) + offset);
    return { left: left, top: top, width: Math.round(w), height: Math.round(h) };
}

function _loadWidgetGeom(id) {
    try {
        var all = JSON.parse(localStorage.getItem(WIDGET_GEOM_KEY) || '{}');
        return all[id] || null;
    } catch (e) {
        return null;
    }
}

function _saveWidgetGeom(id, el) {
    if (!el || el.classList.contains('is-max')) return;
    try {
        var all = JSON.parse(localStorage.getItem(WIDGET_GEOM_KEY) || '{}');
        all[id] = {
            left: el.offsetLeft,
            top: el.offsetTop,
            width: el.offsetWidth,
            height: el.offsetHeight
        };
        localStorage.setItem(WIDGET_GEOM_KEY, JSON.stringify(all));
    } catch (e) {}
}

function _applyWidgetGeom(el, geom) {
    var layer = _widgetLayerEl();
    if (!layer) return;
    var lw = layer.clientWidth;
    var lh = layer.clientHeight;
    var w = Math.min(geom.width || 720, lw - 16);
    var h = Math.min(geom.height || 520, lh - 16);
    // 音乐播放器需要足够版面：旧存档里的小窗口强制放大
    if (el && el.dataset && el.dataset.widgetId === 'music') {
        w = Math.max(w, Math.min(1320, lw - 32));
        h = Math.max(h, Math.min(840, lh - 32));
    }
    var left = Math.max(0, Math.min(geom.left || 0, lw - w));
    var top = Math.max(0, Math.min(geom.top || 0, lh - 48));
    el.style.left = left + 'px';
    el.style.top = top + 'px';
    el.style.width = w + 'px';
    el.style.height = h + 'px';
}

// 挂件层统一处理"点击哪个挂件就抬升哪个"，避免每个挂件各自绑定
function _bindLayerFocus() {
    var layer = _widgetLayerEl();
    if (!layer || layer._focusBound) return;
    layer._focusBound = true;
    layer.addEventListener('pointerdown', function (e) {
        var el = e.target.closest('.widget');
        if (el && el.dataset.widgetId) _focusWidget(el.dataset.widgetId);
    }, true);
}

function openWidget(id) {
    if (id === 'chat' || !_isWidgetView(id)) return false;
    var view = document.getElementById(id + '-view');
    if (!view) return false;
    _bindLayerFocus();

    if (_widgets[id] && _widgets[id].el) {
        _widgets[id].el.classList.remove('is-minimized', 'is-closing');
        _widgets[id].minimized = false;
        _focusWidget(id);
        _playWidgetRestore(id);
        _renderWidgetDock();
        return true;
    }

    var layer = _widgetLayerEl();
    if (!layer) return false;

    // 确保聊天桌面可见，但不清掉其他挂件
    document.querySelectorAll('.view').forEach(function (v) {
        if (!v.closest('.widget')) v.classList.remove('active');
    });
    var chatView = document.getElementById('chat-view');
    if (chatView) chatView.classList.add('active');
    var appEl = document.querySelector('.app');
    if (appEl) appEl.style.display = '';
    _syncRailActive('chat');

    var item = _widgetCatalogItem(id) || { name: id, icon: 'fa-window-maximize' };
    var el = document.createElement('div');
    // overlay：半透明悬浮窗样式（整窗透出页面背景）
    el.className = 'widget is-entering' + (item.overlay ? ' widget-overlay' : '');
    setTimeout(function () { el.classList.remove('is-entering'); }, 280);
    el.dataset.widgetId = id;
    el.style.zIndex = ++_widgetZ;
    el.innerHTML =
        '<div class="widget-bar">' +
            '<span class="widget-title"><i class="' + (item.brand ? 'fab' : 'fas') + ' ' + item.icon + '"></i><span>' + escapeHtml(item.name) + '</span></span>' +
            '<span class="widget-actions">' +
                '<button class="widget-btn" data-widget-act="min" title="最小化"><i class="fas fa-minus"></i></button>' +
                '<button class="widget-btn" data-widget-act="max" title="最大化"><i class="fas fa-expand"></i></button>' +
                '<button class="widget-btn close" data-widget-act="close" title="关闭"><i class="fas fa-times"></i></button>' +
            '</span>' +
        '</div>' +
        '<div class="widget-body"></div>';

    // 先记录原位置，再把页面移入挂件
    view._widgetHome = { parent: view.parentNode, next: view.nextSibling };
    el.querySelector('.widget-body').appendChild(view);
    view.classList.add('active');
    layer.appendChild(el);

    _applyWidgetGeom(el, _loadWidgetGeom(id) || _widgetDefaultGeom(item));
    _widgets[id] = { el: el, view: view, minimized: false, max: false };
    _widgetCascade++;

    _bindWidgetEvents(id, el);
    _focusWidget(id);
    _renderWidgetDock();
    return true;
}

function _focusWidget(id) {
    var w = _widgets[id];
    if (!w || !w.el) return;
    Object.keys(_widgets).forEach(function (other) {
        var o = _widgets[other];
        if (o && o.el && other !== id) o.el.classList.remove('is-focused');
    });
    w.el.style.zIndex = ++_widgetZ;
    w.el.classList.add('is-focused');
    w.el.classList.remove('is-minimized');
    w.minimized = false;
}

// 从停靠栏恢复时的回弹动效
function _playWidgetRestore(id) {
    var w = _widgets[id];
    if (!w || !w.el) return;
    var el = w.el;
    el.classList.remove('is-restoring');
    void el.offsetWidth;
    el.classList.add('is-restoring');
    setTimeout(function () { el.classList.remove('is-restoring'); }, 260);
}

function _minimizeWidget(id) {
    var w = _widgets[id];
    if (!w || !w.el) return;
    if (w.el.classList.contains('is-minimized')) return;
    var el = w.el;
    el.classList.add('is-minimizing');
    w.minimized = true;
    _renderWidgetDock();
    setTimeout(function () {
        el.classList.remove('is-minimizing');
        if (w.minimized) el.classList.add('is-minimized');
    }, 180);
}

function _minimizeAllWidgets() {
    Object.keys(_widgets).forEach(function (id) {
        if (_widgets[id] && _widgets[id].el) _minimizeWidget(id);
    });
}

function closeWidget(id) {
    var w = _widgets[id];
    if (!w || !w.el) return;
    if (w.closing) return;
    w.closing = true;
    var el = w.el;
    el.classList.remove('is-minimized', 'is-focused');
    el.classList.add('is-closing');
    setTimeout(function () {
        if (el._widgetRO) el._widgetRO.disconnect();
        var home = w.view._widgetHome;
        w.view.classList.remove('active');
        if (home && home.parent) {
            home.parent.insertBefore(w.view, home.next && home.next.parentNode === home.parent ? home.next : null);
        } else {
            var views = document.querySelector('.views');
            if (views) views.appendChild(w.view);
        }
        w.view._widgetHome = null;
        el.remove();
        delete _widgets[id];
        _renderWidgetDock();
    }, 160);
}

function _maximizeWidget(id) {
    var w = _widgets[id];
    if (!w || !w.el) return;
    var el = w.el;
    el.classList.add('is-animating');
    clearTimeout(el._widgetAnimTimer);
    el._widgetAnimTimer = setTimeout(function () {
        el.classList.remove('is-animating');
    }, 320);
    if (el.classList.contains('is-max')) {
        el.classList.remove('is-max');
        var geom = w.restoreGeom || _widgetDefaultGeom(_widgetCatalogItem(id));
        _applyWidgetGeom(el, geom);
        w.max = false;
        var btn = el.querySelector('[data-widget-act="max"] i');
        if (btn) btn.className = 'fas fa-expand';
    } else {
        w.restoreGeom = {
            left: el.offsetLeft,
            top: el.offsetTop,
            width: el.offsetWidth,
            height: el.offsetHeight
        };
        el.classList.add('is-max');
        w.max = true;
        var btn2 = el.querySelector('[data-widget-act="max"] i');
        if (btn2) btn2.className = 'fas fa-compress';
    }
    _focusWidget(id);
}

function _renderWidgetDock() {
    var dock = document.getElementById('widget-dock');
    if (!dock) return;
    var ids = Object.keys(_widgets).filter(function (id) {
        return _widgets[id] && _widgets[id].minimized;
    });
    if (!ids.length) {
        dock.style.display = 'none';
        dock.innerHTML = '';
        return;
    }
    dock.style.display = 'flex';
    dock.innerHTML = ids.map(function (id, i) {
        var item = _widgetCatalogItem(id) || { name: id, icon: 'fa-window-maximize' };
        return '<button class="widget-dock-chip" style="--chip-i:' + i + '" onclick="openWidget(\'' + id + '\')" title="恢复 ' + escapeHtml(item.name) + '">' +
            '<i class="' + (item.brand ? 'fab' : 'fas') + ' ' + item.icon + '"></i><span>' + escapeHtml(item.name) + '</span></button>';
    }).join('');
}

function _bindWidgetEvents(id, el) {
    el.addEventListener('click', function (e) {
        var btn = e.target.closest('[data-widget-act]');
        if (!btn) return;
        e.stopPropagation();
        var act = btn.dataset.widgetAct;
        if (act === 'min') _minimizeWidget(id);
        else if (act === 'max') _maximizeWidget(id);
        else if (act === 'close') closeWidget(id);
    });

    var bar = el.querySelector('.widget-bar');
    if (bar) {
        bar.addEventListener('pointerdown', function (e) {
            if (e.button !== 0) return;
            if (e.target.closest('button') || e.target.closest('input')) return;
            if (el.classList.contains('is-max')) return;
            var layer = _widgetLayerEl();
            if (!layer) return;
            var layerRect = layer.getBoundingClientRect();
            var rect = el.getBoundingClientRect();
            var startX = e.clientX;
            var startY = e.clientY;
            try { bar.setPointerCapture(e.pointerId); } catch (err) {}
            el.classList.add('is-dragging');

            function onMove(ev) {
                var nx = rect.left - layerRect.left + (ev.clientX - startX);
                var ny = rect.top - layerRect.top + (ev.clientY - startY);
                nx = Math.max(0, Math.min(nx, layerRect.width - el.offsetWidth));
                ny = Math.max(0, Math.min(ny, layerRect.height - 44));
                el.style.left = nx + 'px';
                el.style.top = ny + 'px';
            }
            function onUp() {
                bar.removeEventListener('pointermove', onMove);
                bar.removeEventListener('pointerup', onUp);
                bar.removeEventListener('pointercancel', onUp);
                el.classList.remove('is-dragging');
                _saveWidgetGeom(id, el);
            }
            bar.addEventListener('pointermove', onMove);
            bar.addEventListener('pointerup', onUp);
            bar.addEventListener('pointercancel', onUp);
        });
    }

    if (window.ResizeObserver) {
        var timer = null;
        el._widgetRO = new ResizeObserver(function () {
            clearTimeout(timer);
            timer = setTimeout(function () { _saveWidgetGeom(id, el); }, 320);
        });
        el._widgetRO.observe(el);
    }
}

// 窗口尺寸变化时把挂件夹回可视区
function _clampWidgets() {
    var layer = _widgetLayerEl();
    if (!layer) return;
    Object.keys(_widgets).forEach(function (id) {
        var w = _widgets[id];
        if (!w || !w.el || w.el.classList.contains('is-max')) return;
        _applyWidgetGeom(w.el, {
            left: w.el.offsetLeft,
            top: w.el.offsetTop,
            width: w.el.offsetWidth,
            height: w.el.offsetHeight
        });
    });
}

// ============= 迷你音乐挂件 =============
// 与完整播放器共用同一个 audioPlayer 与 currentLyrics，只做展示与基础控制

var _miniTimer = null;
var _miniLyricSig = '';
var _miniActiveLine = -1;

function _miniEl(id) {
    return document.getElementById(id);
}

function miniOpenFullPlayer() {
    switchView('music');
}

function miniToggle() {
    togglePlay();
    _miniSyncPlayIcon();
}

function miniPrev() {
    prevSong();
    setTimeout(_miniRefresh, 150);
}

function miniNext() {
    nextSong();
    setTimeout(_miniRefresh, 150);
}

function miniSeek(e) {
    if (!audioPlayer || !isFinite(audioPlayer.duration) || audioPlayer.duration <= 0) return;
    var bar = _miniEl('mm-bar');
    if (!bar) return;
    var rect = bar.getBoundingClientRect();
    var clientX = e.touches ? e.touches[0].clientX : e.clientX;
    var pct = Math.max(0, Math.min(1, (clientX - rect.left) / rect.width));
    audioPlayer.currentTime = pct * audioPlayer.duration;
    var fill = _miniEl('mm-fill');
    if (fill) fill.style.width = (pct * 100) + '%';
    _miniUpdateTime();
    _miniHighlightLyric(true);
}

function miniPlayerInit() {
    _miniRenderLyrics(true);
    _miniRefresh();
    if (_miniTimer) clearInterval(_miniTimer);
    _miniTimer = setInterval(_miniRefresh, 320);
}

function miniPlayerStop() {
    if (_miniTimer) {
        clearInterval(_miniTimer);
        _miniTimer = null;
    }
}

function _miniRefresh() {
    var view = _miniEl('music-mini-view');
    // 挂件关闭后视图会回到 .views，此时停止轮询
    if (!view || !view.closest('.widget')) {
        miniPlayerStop();
        return;
    }
    _miniSyncMeta();
    _miniSyncPlayIcon();
    _miniUpdateTime();
    _miniRenderLyrics(false);
    _miniHighlightLyric(false);
}

function _miniSyncMeta() {
    var srcTitle = _miniEl('song-title');
    var srcArtist = _miniEl('song-artist');
    var srcCover = _miniEl('album-cover');
    var title = ((srcTitle && srcTitle.textContent) || '').trim() || '未在播放';
    var artist = ((srcArtist && srcArtist.textContent) || '').trim() || 'Furina Music Player';
    var titleEl = _miniEl('mm-title');
    var artistEl = _miniEl('mm-artist');
    if (titleEl) titleEl.textContent = title;
    if (artistEl) artistEl.textContent = artist;

    var cover = _miniEl('mm-cover');
    var fallback = _miniEl('mm-cover-fallback');
    var url = '';
    if (srcCover && srcCover.style.display !== 'none' && srcCover.getAttribute('src')) {
        url = srcCover.getAttribute('src');
    }
    if (cover && cover.dataset.url !== url) {
        cover.dataset.url = url;
        if (url) {
            cover.src = url;
            cover.style.display = 'block';
            if (fallback) fallback.style.display = 'none';
        } else {
            cover.removeAttribute('src');
            cover.style.display = 'none';
            if (fallback) fallback.style.display = 'flex';
        }
    }
}

function _miniSyncPlayIcon() {
    var btn = _miniEl('mm-play');
    if (!btn) return;
    var icon = btn.querySelector('i');
    if (!icon) return;
    var playing = !!(audioPlayer && !audioPlayer.paused);
    icon.className = playing ? 'fas fa-pause' : 'fas fa-play';
}

function _miniUpdateTime() {
    var cur = _miniEl('mm-cur');
    var dur = _miniEl('mm-dur');
    var fill = _miniEl('mm-fill');
    if (!cur || !dur || !fill) return;
    var has = !!(audioPlayer && isFinite(audioPlayer.duration) && audioPlayer.duration > 0);
    var t = has ? audioPlayer.currentTime : 0;
    var d = has ? audioPlayer.duration : 0;
    cur.textContent = formatTime(t);
    dur.textContent = has ? formatTime(d) : '--:--';
    fill.style.width = has ? ((t / d) * 100) + '%' : '0%';
}

function _miniRenderLyrics(force) {
    var box = _miniEl('mm-lyrics');
    if (!box) return;
    var titleEl = _miniEl('song-title');
    var sig = [
        (titleEl && titleEl.textContent) || '',
        currentLyrics.length,
        currentLyrics.length ? currentLyrics[0].time : '',
        currentLyrics.length ? currentLyrics[currentLyrics.length - 1].time : ''
    ].join('|');
    if (!force && sig === _miniLyricSig) return;
    _miniLyricSig = sig;
    _miniActiveLine = -1;
    if (!currentLyrics.length) {
        box.innerHTML = '<div class="mm-lyric-empty"><i class="fas fa-microphone-slash"></i><span>暂无歌词</span></div>';
        return;
    }
    box.innerHTML = currentLyrics.map(function (line) {
        return '<div class="mm-lyric">' + escapeHtml(line.text || '') + '</div>';
    }).join('');
    box.scrollTop = 0;
}

function _miniHighlightLyric(force) {
    var lines = document.querySelectorAll('#mm-lyrics .mm-lyric');
    if (!lines.length || !audioPlayer) return;
    var t = audioPlayer.currentTime || 0;
    var idx = -1;
    for (var i = 0; i < currentLyrics.length; i++) {
        if (t >= currentLyrics[i].time) idx = i;
        else break;
    }
    if (!force && idx === _miniActiveLine) return;
    _miniActiveLine = idx;
    lines.forEach(function (el, i) {
        el.classList.toggle('active', i === idx);
        el.classList.toggle('near', Math.abs(i - idx) === 1);
    });
    if (idx >= 0 && lines[idx]) {
        var box = _miniEl('mm-lyrics');
        var line = lines[idx];
        var top = line.offsetTop - box.clientHeight / 2 + line.offsetHeight / 2;
        box.scrollTo({ top: Math.max(0, top), behavior: 'smooth' });
    }
}


function toggleDeepSeekSettings() {
    const provider = document.getElementById('provider-select').value;
    const dsSettings = document.getElementById('deepseek-settings');
    if (dsSettings) {
        dsSettings.style.display = provider === 'deepseek' ? 'block' : 'none';
    }
    // OpenRouter 设置区
    const orSettings = document.getElementById('openrouter-settings');
    if (orSettings) {
        orSettings.style.display = provider === 'openrouter' ? 'block' : 'none';
    }
}

// 切换服务商时自动填充对应预设的 API 地址与推荐模型
function onProviderChange() {
    toggleDeepSeekSettings();
    const provider = document.getElementById('provider-select').value;
    const preset = _llmPresets ? _llmPresets[provider] : null;
    renderProviderExtra(preset);
    if (!preset) return;
    // 自动填充 API 地址
    if (preset.api_url) {
        document.getElementById('api-url').value = preset.api_url;
    }
    // 若当前模型不属于该服务商预设，则切换为默认模型
    const currentModel = document.getElementById('model-select').value;
    const presetModels = (preset.models || []).concat(preset.deprecated_models || []);
    if (preset.default_model && presetModels.length && !presetModels.includes(currentModel)) {
        document.getElementById('model-select').value = preset.default_model;
        // 高亮对应快速按钮
        document.querySelectorAll('.btn-model-quick').forEach(b => {
            b.classList.toggle('active', b.dataset.model === preset.default_model);
        });
    }
}

// 渲染当前服务商的两类附加信息：
// 1) 官方已弃用、仅作兼容保留的旧模型名（按钮形式，点击即可回退到旧配置）
// 2) 预设自带的说明文案 note
function renderProviderExtra(preset) {
    const group = document.getElementById('deprecated-model-group');
    const box = document.getElementById('deprecated-model-list');
    const noteEl = document.getElementById('provider-note');
    const deprecated = (preset && preset.deprecated_models) || [];

    if (box) {
        box.innerHTML = deprecated.map(m => {
            const label = escapeHtml(m);
            return `<button type="button" class="btn btn-model-quick deprecated" data-model="${label}"`
                + ` title="该模型名已被官方标记为弃用，仅用于兼容已有配置，不建议新选"`
                + ` onclick="selectDeprecatedModel('${label}')">${label} · 已弃用</button>`;
        }).join('');
    }
    if (group) {
        group.style.display = deprecated.length ? 'block' : 'none';
    }

    if (noteEl) {
        const note = (preset && preset.note) || '';
        noteEl.textContent = note;
        noteEl.style.display = note ? 'block' : 'none';
    }
}

// 选中一个已弃用的模型名：填入输入框 + 高亮 + 明确提示
function selectDeprecatedModel(model) {
    const input = document.getElementById('model-select');
    if (input) input.value = model;
    document.querySelectorAll('#deprecated-model-list .btn-model-quick').forEach(b => {
        b.classList.toggle('active', b.dataset.model === model);
    });
    document.querySelectorAll('#deepseek-settings .btn-model-quick, #deprecated-model-list .btn-model-quick').forEach(b => {
        if (b.dataset.model !== model) b.classList.remove('active');
    });
    showToast('已填入已弃用的模型名 ' + model + '，仅建议用于兼容旧配置', 'error');
}

function selectDeepSeekModel(model) {
    document.getElementById('model-select').value = model;
    // 高亮选中的按钮
    document.querySelectorAll('.btn-model-quick').forEach(b => {
        b.classList.toggle('active', b.dataset.model === model);
    });
}

function selectOpenRouterModel(btn) {
    document.getElementById('model-select').value = btn.dataset.model;
    document.querySelectorAll('#openrouter-model-quick .btn-model-quick').forEach(b => {
        b.classList.toggle('active', b === btn);
    });
}

function saveSettings() {
    const statusEl = document.getElementById('settings-panel-status');
    statusEl.innerHTML = '<i class="fas fa-spinner fa-spin" style="color:var(--primary-color)"></i> <span>保存中...</span>';
    
    const provider = document.getElementById('provider-select').value;
    const apiKey = document.getElementById('api-key').value;
    const model = document.getElementById('model-select').value;
    const apiUrl = document.getElementById('api-url').value;
    const ttsEnabled = document.getElementById('tts-enabled').checked;
    
    // 构建可选的 GPT-SoVITS 配置
    const gptSovits = {
        host: document.getElementById('gpt-sovits-host').value,
        port: parseInt(document.getElementById('gpt-sovits-port').value) || 9880,
        path: document.getElementById('gpt-sovits-path').value,
        refer_wav: document.getElementById('gpt-sovits-refer-wav').value,
        prompt_text: document.getElementById('gpt-sovits-prompt-text').value,
        prompt_language: document.getElementById('gpt-sovits-prompt-lang').value,
        text_language: document.getElementById('gpt-sovits-text-lang').value,
        gpt_weights_path: document.getElementById('gpt-sovits-gpt-weights').value,
        sovits_weights_path: document.getElementById('gpt-sovits-sovits-weights').value,
        speed: parseFloat(document.getElementById('gpt-sovits-speed').value) || 1.0,
        temperature: parseFloat(document.getElementById('gpt-sovits-temperature').value) || 0.5,
        top_k: parseInt(document.getElementById('gpt-sovits-top-k').value) || 10,
        top_p: parseFloat(document.getElementById('gpt-sovits-top-p').value) || 0.8,
        seed: (function(){ const v = parseInt(document.getElementById('gpt-sovits-seed').value); return isNaN(v) ? -1 : v; })(),
        sample_steps: parseInt(document.getElementById('gpt-sovits-sample-steps').value) || 20,
        repetition_penalty: parseFloat(document.getElementById('gpt-sovits-repetition-penalty').value) || 1.15,
        batch_threshold: parseFloat(document.getElementById('gpt-sovits-batch-threshold').value) || 0.75,
        text_split_method: document.getElementById('gpt-sovits-text-split-method').value,
        media_type: document.getElementById('gpt-sovits-media-type').value,
        emotion_detection: document.getElementById('gpt-sovits-emotion-detection').checked,
        super_sampling: document.getElementById('gpt-sovits-super-sampling').checked,
        parallel_infer: document.getElementById('gpt-sovits-parallel-infer').checked,
        split_bucket: document.getElementById('gpt-sovits-split-bucket').checked,
        streaming_mode: document.getElementById('gpt-sovits-streaming-mode').checked,
        text_language_detection: document.getElementById('gpt-sovits-text-lang-detect').checked
    };
    
    // OpenRouter 专用 API 密钥（仅在用户填写时更新，留空保持已有密钥）
    const openrouterKeyInput = document.getElementById('openrouter-api-key');
    const openrouterApiKey = openrouterKeyInput ? openrouterKeyInput.value.trim() : '';

    const settings = {
        provider,
        api_key: apiKey,
        model,
        api_url: apiUrl,
        tts_enabled: ttsEnabled,
        max_tokens: parseInt(document.getElementById('max-tokens').value) || 2048,
        temperature: parseFloat(document.getElementById('temperature').value) || 0.7,
        top_p: parseFloat(document.getElementById('top-p').value) || 0.9,
        frequency_penalty: parseFloat(document.getElementById('frequency-penalty').value) || 0,
        presence_penalty: parseFloat(document.getElementById('presence-penalty').value) || 0,
        system_prompt: document.getElementById('system-prompt').value,
        response_format: document.getElementById('response-format').value,
        n: parseInt(document.getElementById('model-n').value) || 1,
        best_of: parseInt(document.getElementById('model-best-of').value) || 1,
        stream: document.getElementById('model-stream').checked,
        tts_engine: document.getElementById('tts-engine-select').value,
        tts_voice: document.getElementById('tts-voice-select').value,
        tts_rate: parseInt(document.getElementById('tts-rate').value) || 200,
        tts_volume: parseFloat(document.getElementById('tts-volume').value) || 1.0,
        tts_pitch: parseInt(document.getElementById('tts-pitch').value) || 0,
        tts_language: document.getElementById('tts-language').value || 'zh',
        tts_prompt_on_startup: document.getElementById('tts-prompt-on-startup').checked,
        tts_auto_clean: document.getElementById('tts-auto-clean').checked,
        tts_cache_enabled: document.getElementById('tts-cache-enabled').checked,
        tts_max_length: parseInt(document.getElementById('tts-max-length').value) || 500,
        gpt_sovits: gptSovits,
        tts_emotion: document.getElementById('tts-emotion-select').value,
        bilibili_cookie: document.getElementById('bilibili-cookie').value,
        // DeepSeek 设置
        deepseek_thinking_enabled: document.getElementById('deepseek-thinking').checked,
        deepseek_reasoning_effort: document.getElementById('reasoning-effort').value,
        // Agent 配置
        max_tool_iterations: parseInt(document.getElementById('max-tool-iterations').value) || 200,
        agent_workspace: document.getElementById('agent-workspace').value.trim() || '',
        agent_tool_scenario: (document.getElementById('agent-tool-scenario') || {}).value || 'full',
        // 子代理能力边界
        subagent_max_depth: parseInt((document.getElementById('subagent-max-depth') || {}).value, 10),
        subagent_max_runs: parseInt((document.getElementById('subagent-max-runs') || {}).value, 10),
        subagent_concurrency: parseInt((document.getElementById('subagent-concurrency') || {}).value, 10),
        subagent_max_iterations: parseInt((document.getElementById('subagent-max-iterations') || {}).value, 10),
        // GitHub 加速地址
        github_proxy: document.getElementById('github-proxy').value.trim() || '',
        // 对话回复引擎配置
        reply_engine: document.getElementById('reply-engine') ? document.getElementById('reply-engine').value : (getReplyEngine() || 'agent'),
        dsh_safe_delete: document.getElementById('dsh-safe-delete') ? document.getElementById('dsh-safe-delete').checked : true,
        // 聊天背景配置
        chat_bg: collectChatBg(),
        // 上下文压缩配置
        context_compress: collectContextCompress(),
        // DSH 内核配置
            dsh: collectDshConfig(),
        };

    // miao-plugin(喵喵)运行方式配置（随设置保存）
    const miaoModeEl = document.getElementById('miao-mode');
    if (miaoModeEl) {
        settings.miao_plugin = {
            mode: miaoModeEl.value,
            auto_start: !!document.getElementById('miao-auto-start').checked,
            yunzai: {
                path: (document.getElementById('miao-yunzai-path').value || '').trim(),
                port: parseInt(document.getElementById('miao-yunzai-port').value || '2536', 10) || 2536,
                redis_path: (document.getElementById('miao-yunzai-redis').value || '').trim(),
            },
        };
    }

    // 仅当用户填写了 OpenRouter 密钥时才更新，避免误清空已配置密钥
    if (openrouterApiKey) {
        settings.openrouter_api_key = openrouterApiKey;
    }

    // AI 授课配置（edu.teaching）：悬浮球 / 网络试题 / 视觉模型 / 点名默认值
    const teachCfg = collectEduTeaching();
    if (teachCfg) {
        settings.edu = { teaching: teachCfg };
    }
    
    fetch('/api/settings', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(settings)
    })
    .then(response => response.json())
    .then(data => {
        if (data.status === 'success') {
            statusEl.innerHTML = '<i class="fas fa-check-circle" style="color:#22c55e"></i> <span>配置已保存</span>';
            showToast('配置保存成功', 'success');
            setTimeout(() => hideSettings(), 800);
        } else {
            const errMsg = data.message || '未知错误';
            statusEl.innerHTML = '<i class="fas fa-exclamation-circle" style="color:#ef4444"></i> <span>保存失败: ' + errMsg + '</span>';
            showToast('保存失败: ' + errMsg, 'error');
        }
    })
    .catch(error => {
        const errMsg = '网络请求失败，请检查后端服务是否正常运行';
        statusEl.innerHTML = '<i class="fas fa-exclamation-circle" style="color:#ef4444"></i> <span>' + errMsg + '</span>';
        showToast(errMsg, 'error');
        showError(errMsg);
    });
}

// ============= JSON 高级编辑器 =============

function settingsReloadJson() {
    const editor = document.getElementById('settings-json-editor');
    if (!editor) return;
    fetch('/api/settings')
        .then(response => response.json())
        .then(data => {
            editor.value = JSON.stringify(data, null, 2);
        })
        .catch(() => {
            editor.value = '{\n  "error": "无法加载配置"\n}';
        });
}

function settingsFormatJson() {
    const editor = document.getElementById('settings-json-editor');
    if (!editor) return;
    try {
        const parsed = JSON.parse(editor.value);
        editor.value = JSON.stringify(parsed, null, 2);
        document.getElementById('settings-panel-status').innerHTML = 
            '<i class="fas fa-check-circle" style="color:#22c55e"></i> <span>JSON 格式化成功</span>';
    } catch (e) {
        document.getElementById('settings-panel-status').innerHTML = 
            '<i class="fas fa-exclamation-circle" style="color:#ef4444"></i> <span>JSON 格式错误: ' + e.message + '</span>';
    }
}

