function settingsResetToDefault() {
    const statusEl = document.getElementById('settings-panel-status');
    if (confirm('确定要恢复默认设置吗？所有自定义配置将被重置。')) {
        statusEl.innerHTML = '<i class="fas fa-spinner fa-spin" style="color:var(--primary-color)"></i> <span>正在重置...</span>';
        fetch('/api/settings', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ _reset: true })
        })
        .then(response => response.json())
        .then(data => {
            loadSettings();
            statusEl.innerHTML = '<i class="fas fa-check-circle" style="color:#22c55e"></i> <span>已恢复默认配置</span>';
        })
        .catch(() => {
            statusEl.innerHTML = '<i class="fas fa-exclamation-circle" style="color:#ef4444"></i> <span>重置失败</span>';
        });
    }
}

// ============= 旧版 TTS 设置弹窗（兼容） =============

function showTtsSettings() {
    // 重定向到统一设置面板的 GPT-SoVITS 标签页
    showSettings();
    switchSettingsTab('sovits');
}

// ============= TTS 预览和测试 =============

function previewTts() {
    const text = document.getElementById('tts-preview-text').value.trim();
    if (!text) {
        showError('请输入预览文本');
        return;
    }
    
    const statusDiv = document.getElementById('tts-preview-status');
    const audioDiv = document.getElementById('tts-preview-audio');
    const player = document.getElementById('tts-preview-player');
    
    statusDiv.innerHTML = '<div class="loading-spinner"><i class="fas fa-spinner fa-spin"></i> 正在合成语音...</div>';
    audioDiv.classList.add('hidden');
    
    fetch('/api/tts/synthesize', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ text })
    })
    .then(response => response.json())
    .then(data => {
        if (data.success && data.audio_url) {
            statusDiv.innerHTML = '<div class="success-message"><i class="fas fa-check-circle"></i> 合成成功</div>';
            player.src = data.audio_url;
            player.load();
            audioDiv.classList.remove('hidden');
            player.play();
        } else {
            statusDiv.innerHTML = '<div class="error-message"><i class="fas fa-exclamation-circle"></i> ' + (data.error || '合成失败') + '</div>';
        }
    })
    .catch(error => {
        statusDiv.innerHTML = '<div class="error-message"><i class="fas fa-exclamation-circle"></i> 合成请求失败</div>';
    });
}

function testTtsConnection() {
    const statusDiv = document.getElementById('tts-preview-status');
    statusDiv.innerHTML = '<div class="loading-spinner"><i class="fas fa-spinner fa-spin"></i> 正在测试 TTS 引擎连接...</div>';
    
    // 测试 GPT-SoVITS API v2 连接
    fetch('/api/tts/gpt-sovits/status')
        .then(response => response.json())
        .then(data => {
            if (data.status === 'connected') {
                const apiInfo = data.api_version ? ` (API v${data.api_version})` : '';
                statusDiv.innerHTML = `<div class="success-message"><i class="fas fa-check-circle"></i> GPT-SoVITS${apiInfo} 连接正常 [${data.host}:${data.port}]</div>`;
            } else {
                throw new Error(data.message || 'GPT-SoVITS 不可用');
            }
        })
        .catch((err) => {
            // 如果 GPT-SoVITS 失败，尝试 Edge TTS
            fetch('/api/tts/voices')
                .then(response => {
                    if (response.ok) {
                        return response.json();
                    }
                    throw new Error('Edge TTS 不可用');
                })
                .then(data => {
                    if (data.voices && data.voices.length > 0) {
                        statusDiv.innerHTML = '<div class="success-message"><i class="fas fa-check-circle"></i> Edge TTS 连接正常，可用语音: ' + data.voices.length + ' 个</div>';
                    }
                })
                .catch(() => {
                    statusDiv.innerHTML = '<div class="error-message"><i class="fas fa-exclamation-circle"></i> 所有 TTS 引擎均无法连接，请检查配置</div>';
                });
        });
}

function selectEmotionPreset(emotion, element) {
    document.querySelectorAll('.emotion-preset-card').forEach(card => {
        card.classList.remove('active');
    });
    element.classList.add('active');
    document.getElementById('tts-emotion-select').value = emotion;
    const statusDiv = document.getElementById('tts-preview-status');
    statusDiv.innerHTML = '<div class="success-message"><i class="fas fa-check-circle"></i> 已选择情绪: ' + element.querySelector('.emotion-preset-name').textContent + '</div>';
}

