function bgiLoadVisionStatus() {
    fetch('/api/bettergi/vision/status')
        .then(function (r) { return r.json(); })
        .then(function (res) {
            const d = (res && res.data) || {};
            const card = document.getElementById('bgi-vision-status');
            if (!card) return;
            const eng = d.engine || {};
            const color = eng.available ? '#22c55e' : '#f59e0b';
            const last = d.last_recovery || {};
            const ov = d.overlay || {};
            const ovs = ov.status || {};
            card.innerHTML = `
                <div style="color:#4b5563;">OCR 引擎: <b style="color:${color};">${eng.available ? _bgiEsc(eng.kind || '已就绪') : '未安装'}</b>
                    · Python ${_bgiEsc(eng.python || '')}${eng.frozen ? ' · 打包版' : ''}</div>
                <div style="color:#4b5563;margin-top:4px;">尝试次数: <b>${d.attempts || 0} / ${d.max_attempts || 3}</b>
                    · 卡住判定: <b>${d.stall_timeout || 600} 秒</b>
                    · AI 决策: <b>${d.ai_enabled ? '开启' : '关闭'}</b></div>
                <div style="color:#4b5563;margin-top:4px;">红框叠加: <b>${ov.enabled ? '开启' : '关闭'}</b>
                    · 窗口: <b>${ovs.running ? '运行中' : '未启动'}</b>
                    · 缩放: <b>${(ovs.scale || 1).toFixed ? ovs.scale.toFixed(2) : ovs.scale}</b>${ovs.error ? ' · ' + _bgiEsc(ovs.error) : ''}</div>
                <div style="color:#4b5563;margin-top:4px;">图案模板: <b style="color:${eng.opencv ? '#22c55e' : '#f59e0b'};">${eng.opencv ? 'OpenCV 可用' : 'OpenCV 缺失'}</b>
                    · 模板数: <b>${eng.templates || 0}</b>${eng.templates_dir ? ' · ' + _bgiEsc(eng.templates_dir) : ''}</div>
                <div style="color:#4b5563;margin-top:4px;">最近结果: <b>${_bgiEsc(last.message || '—')}</b>${last.ts ? ' · ' + _bgiFmtTime(last.ts) : ''}</div>
                ${eng.hint ? '<div style="color:#f59e0b;font-size:13px;margin-top:4px;">' + _bgiEsc(eng.hint) + '</div>' : ''}
            `;
        })
        .catch(function () {});
}

function bgiVisionTest() {
    const box = document.getElementById('bgi-vision-result');
    if (box) box.textContent = '正在截图并识别…';
    const payload = {};
    const v = function (id) {
        const el = document.getElementById(id);
        const n = el ? Number(el.value) : NaN;
        return isFinite(n) && el.value !== '' ? n : null;
    };
    const x1 = v('bgi-region-x1'), y1 = v('bgi-region-y1'), x2 = v('bgi-region-x2'), y2 = v('bgi-region-y2');
    if (x1 !== null && y1 !== null && x2 !== null && y2 !== null) {
        payload.region = [x1, y1, x2, y2];
    }
    fetch('/api/bettergi/vision/test', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
    })
        .then(function (r) { return r.json(); })
        .then(function (res) {
            const d = (res && res.data) || {};
            if (res.status === 'success') {
                const items = d.items || [];
                const preview = items.slice(0, 12).map(function (i) { return i.text; }).join(' / ');
                const tpl = (d.templates || []).length ? ' · 模板命中 ' + d.templates.join('、') : '';
                if (box) box.textContent = '引擎: ' + (d.engine || '') + ' · 识别到 ' + items.length + ' 条'
                    + (d.boxes_drawn ? ' · 已画 ' + d.boxes_drawn + ' 个红框' : '') + tpl + '：' + preview;
                showToast('识别完成');
            } else if (box) {
                box.textContent = res.message || '识别失败';
                showToast(res.message || '识别失败', 'error');
            }
            bgiLoadVisionStatus();
        })
        .catch(function () { if (box) box.textContent = '识别请求失败'; });
}

