// ===== 异常判定与模式 =====

function bgiLoadErrorsStatus() {
    fetch('/api/bettergi/errors/status')
        .then(function (r) { return r.json(); })
        .then(function (res) {
            const d = (res && res.data) || {};
            const card = document.getElementById('bgi-errors-status');
            if (!card) return;
            const daily = d.daily || {};
            const counts = daily.counts || {};
            const map = d.action_map || {};
            const mapText = Object.keys(map).map(function (k) { return k + '→' + map[k]; }).join(' · ');
            const win = d.active_window || {};
            const winText = (win.start && win.end)
                ? (win.start + ' - ' + win.end + '（' + (win.inside ? '当前在区间内' : '当前不在区间') + '）')
                : '未设置';
            const last = d.last_error || {};
            const modeText = d.mode === 'strict' ? '严格' : '宽松';
            let countsText = Object.keys(counts).map(function (k) { return k + ' ' + counts[k]; }).join(' · ');
            if (!countsText) countsText = '无';
            card.innerHTML = `
                <div style="color:#4b5563;">异常守护: <b>${d.enabled ? '开启' : '关闭'}</b>
                    · 模式: <b>${modeText}</b>
                    · 连续无响应: <b>${d.miss_streak || 0} / ${d.miss_limit || 25}</b>
                    · 原神存活上限: <b>${d.game_alive_shutdown_hours || 12} 小时</b></div>
                <div style="color:#4b5563;margin-top:4px;">今日报错: <b>${(daily.counts && daily.counts.bgi_error) || 0} / ${d.daily_limit || 3}</b>
                    · 明细: ${_bgiEsc(countsText)}</div>
                <div style="color:#4b5563;margin-top:4px;">规定时间段: <b>${_bgiEsc(winText)}</b></div>
                <div style="color:#4b5563;margin-top:4px;">动作映射: <b>${_bgiEsc(mapText)}</b></div>
                ${last.ts ? '<div style="color:#f59e0b;margin-top:4px;">最近异常: ' + _bgiEsc((last.name || last.kind) + ' · ' + (last.detail || '')) + ' · 动作 ' + _bgiEsc(last.action || '') + ' · ' + _bgiFmtTime(last.ts) + '</div>' : ''}
            `;
        })
        .catch(function () {});
}

