// ===== 健康检查与自愈 =====

function bgiLoadHealthStatus() {
    fetch('/api/bettergi/health/status')
        .then(function (r) { return r.json(); })
        .then(function (res) {
            const d = (res && res.data) || {};
            const card = document.getElementById('bgi-health-status');
            if (!card) return;
            const last = d.last || {};
            const checks = last.checks || [];
            const okCount = checks.filter(function (c) { return c.ok; }).length;
            const head = checks.length
                ? '<b style="color:' + (last.ok ? '#22c55e' : '#ef4444') + ';">' + okCount + ' / ' + checks.length + ' 项正常</b>'
                : '<b style="color:#6b7280;">尚未体检</b>';
            const rows = checks.map(function (c) {
                const color = c.ok ? '#22c55e' : '#ef4444';
                return '<div style="color:#4b5563;">' + _bgiEsc(c.name || c.key) + ': <b style="color:' + color + ';">'
                    + (c.ok ? '正常' : '异常') + '</b> · ' + _bgiEsc(c.detail || '') + '</div>';
            }).join('');
            card.innerHTML = `
                <div style="color:#4b5563;">自愈: <b>${d.enabled ? '开启' : '关闭'}</b>
                    · 重试: <b>${d.retries || 0} / ${d.retry_max || 2}</b>
                    · 间隔: <b>${d.retry_interval || 60} 秒</b>
                    · 网络恢复: <b>${d.network_recover ? '开启' : '关闭'}</b></div>
                <div style="margin-top:4px;">${head}${last.ts ? ' · ' + _bgiFmtTime(last.ts) : ''}</div>
                ${rows}
                ${last.problems && last.problems.length ? '<div style="color:#ef4444;font-size:13px;margin-top:4px;">待处理: ' + _bgiEsc(last.problem_names.join('、')) + '</div>' : ''}
            `;
        })
        .catch(function () {});
}

function bgiHealthCheck() {
    const box = document.getElementById('bgi-health-result');
    if (box) box.textContent = '正在执行健康检查…';
    fetch('/api/bettergi/health/check', { method: 'POST' })
        .then(function (r) { return r.json(); })
        .then(function (res) {
            const d = (res && res.data) || {};
            if (box) {
                const rows = (d.checks || []).map(function (c) {
                    return (c.ok ? '✓ ' : '✗ ') + (c.name || c.key) + '：' + (c.detail || '');
                });
                box.innerHTML = rows.join('<br>') || (res.message || '检查完成');
            }
            bgiLoadHealthStatus();
        })
        .catch(function () { if (box) box.textContent = '健康检查请求失败'; });
}

function bgiHealthRecover() {
    if (!confirm('将按顺序执行自愈：重启 BetterGI → 拉起游戏 → 关闭无响应窗口 → 刷新 DNS（若已开启）→ 放弃。继续？')) return;
    const box = document.getElementById('bgi-health-result');
    if (box) box.textContent = '正在执行自愈链…';
    fetch('/api/bettergi/health/recover', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ reason: '页面手动触发' })
    })
        .then(function (r) { return r.json(); })
        .then(function (res) {
            const d = (res && res.data) || {};
            if (box) {
                const rows = (d.steps || []).map(function (s) {
                    return (s.ok ? '✓ ' : '✗ ') + s.step + '：' + (s.message || '');
                });
                box.innerHTML = rows.length ? rows.join('<br>') : (res.message || '未执行任何动作');
            }
            showToast(res.message || '已执行', res.status === 'success' ? 'success' : 'error');
            bgiLoadHealthStatus();
            bgiLoadStatus();
        })
        .catch(function () { if (box) box.textContent = '自愈请求失败'; });
}

