// ===== 更新流程与开机计划 =====

function bgiLoadFlowStatus() {
    Promise.all([
        fetch('/api/bettergi/update/flows').then(function (r) { return r.json(); }),
        fetch('/api/bettergi/boot-plan/status').then(function (r) { return r.json(); })
    ]).then(function (res) {
        const d = (res[0] && res[0].data) || {};
        const boot = (res[1] && res[1].data) || {};
        const card = document.getElementById('bgi-flow-status');
        if (!card) return;
        const last = d.last || {};
        const flows = d.flows || {};
        const gameSteps = ((flows.game || {}).steps || []).length;
        const bgiSteps = ((flows.bgi || {}).steps || []).length;
        const reasonMap = {
            task_error: '任务异常中止', done: '任务完成', manual: '手动结束', canceled: '任务取消'
        };
        card.innerHTML = `
            <div style="color:#4b5563;">流程: 原神 <b>${gameSteps}</b> 步 · BetterGI <b>${bgiSteps}</b> 步
                · 执行中: <b>${d.running ? '是' : '否'}</b>
                · 完成后启动一条龙: <b>${d.launch_onedragon ? '开' : '关'}</b></div>
            <div style="color:#4b5563;margin-top:4px;">开机计划: <b>${boot.enabled ? '开启' : '关闭'}</b>
                · 延迟 <b>${boot.delay || 0}</b> 秒
                · 执行项 <b>${_bgiEsc((boot.targets || []).join(',')) || '—'}</b>
                · 今日执行: <b>${boot.plan_date || '—'}</b></div>
            <div style="color:#4b5563;margin-top:4px;">上次退出原因: <b>${_bgiEsc(reasonMap[boot.last_exit_reason] || boot.last_exit_reason || '—')}</b>${boot.last_exit_at ? ' · ' + _bgiFmtTime(boot.last_exit_at) : ''}</div>
            ${last.ts ? '<div style="color:' + (last.success ? '#22c55e' : '#ef4444') + ';margin-top:4px;">最近流程: ' + _bgiEsc((last.target === 'game' ? '原神更新' : 'BetterGI 更新') + ' · ' + (last.message || '')) + ' · ' + _bgiFmtTime(last.ts) + '</div>' : ''}
        `;
    }).catch(function () {});
}

function bgiRunUpdateFlow(target) {
    const label = target === 'game' ? '原神更新' : 'BetterGI 更新';
    if (!confirm('将执行「' + label + '」步骤机：程序会截图识别并模拟点击，期间自动关机与续跑会被屏蔽。继续？')) return;
    const box = document.getElementById('bgi-flow-result');
    if (box) box.textContent = '正在执行' + label + '流程…';
    fetch('/api/bettergi/update/flow', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ target: target })
    })
        .then(function (r) { return r.json(); })
        .then(function (res) {
            const d = (res && res.data) || {};
            const steps = d.steps || [];
            if (box) {
                box.innerHTML = steps.map(function (s) {
                    return (s.ok ? '✓ ' : '✗ ') + _bgiEsc(s.name || '') + (s.matched ? '（' + _bgiEsc(s.matched) + '）' : '') + (s.message ? '：' + _bgiEsc(s.message) : '');
                }).join('<br>') || _bgiEsc(res.message || '');
            }
            showToast(res.message || '已执行', res.status === 'success' ? 'success' : 'error');
            bgiLoadFlowStatus();
            bgiLoadStatus();
        })
        .catch(function () { if (box) box.textContent = '流程请求失败'; });
}

function bgiBootPlanNow() {
    if (!confirm('将按开机计划立即执行一次更新检查（每天最多一次）。继续？')) return;
    const box = document.getElementById('bgi-flow-result');
    if (box) box.textContent = '正在执行开机计划…';
    fetch('/api/bettergi/boot-plan/run', { method: 'POST' })
        .then(function (r) { return r.json(); })
        .then(function (res) {
            if (box) box.textContent = res.message || '已执行';
            showToast(res.message || '已执行', res.status === 'success' ? 'success' : 'error');
            bgiLoadFlowStatus();
        })
        .catch(function () { if (box) box.textContent = '开机计划请求失败'; });
}

function _bgiDaysPreset(days) {
    if (!Array.isArray(days) || !days.length) return 'all';
    const s = days.map(Number).sort().join(',');
    if (s === '0,1,2,3,4') return 'workday';
    if (s === '5,6') return 'weekend';
    return 'custom';
}

function _bgiDaysFromRow(row) {
    const preset = row.querySelector('.bgi-sch-days').value;
    if (preset === 'all') return [];
    if (preset === 'workday') return [0, 1, 2, 3, 4];
    if (preset === 'weekend') return [5, 6];
    return (row.querySelector('.bgi-sch-custom-days').value || '')
        .split(/[,，]/).map(function (x) { return x.trim(); })
        .filter(Boolean).map(Number)
        .filter(function (n) { return n >= 0 && n <= 6; });
}

function bgiRenderSchedules(list) {
    const box = document.getElementById('bgi-schedule-list');
    if (!box) return;
    box.innerHTML = '';
    (list || []).forEach(function (s) { bgiScheduleRow(s); });
}

function bgiScheduleRow(s) {
    const box = document.getElementById('bgi-schedule-list');
    if (!box) return;
    s = s || {};
    const row = document.createElement('div');
    row.className = 'bgi-schedule-row';
    row.dataset.id = s.id || ('sch-' + Date.now() + '-' + Math.floor(Math.random() * 1000));
    row.setAttribute('style', 'border:1px solid #e5e7eb;border-radius:10px;padding:10px;margin-bottom:8px;');
    const days = Array.isArray(s.days) ? s.days : [];
    const preset = _bgiDaysPreset(days);
    const mode = s.mode || 'onedragon';
    row.innerHTML = `
        <div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center;">
            <label class="toggle-label"><input type="checkbox" class="bgi-sch-enabled" ${s.enabled === false ? '' : 'checked'}> 启用</label>
            <input type="time" class="input-lg bgi-sch-time" value="${_bgiEsc(s.time || '04:00')}">
            <select class="input-lg bgi-sch-mode">
                <option value="normal" ${mode === 'normal' ? 'selected' : ''}>普通启动</option>
                <option value="onedragon" ${mode === 'onedragon' ? 'selected' : ''}>一条龙</option>
                <option value="groups" ${mode === 'groups' ? 'selected' : ''}>配置组</option>
                <option value="task_progress" ${mode === 'task_progress' ? 'selected' : ''}>任务进度</option>
            </select>
            <select class="input-lg bgi-sch-days">
                <option value="all" ${preset === 'all' ? 'selected' : ''}>每天</option>
                <option value="workday" ${preset === 'workday' ? 'selected' : ''}>工作日</option>
                <option value="weekend" ${preset === 'weekend' ? 'selected' : ''}>周末</option>
                <option value="custom" ${preset === 'custom' ? 'selected' : ''}>自定义</option>
            </select>
            <input type="text" class="input-lg bgi-sch-custom-days" placeholder="0-6，逗号分隔（0=周一）" value="${preset === 'custom' ? _bgiEsc(days.join(',')) : ''}">
            <button class="btn btn-sm" onclick="bgiRemoveSchedule(this)"><i class="fas fa-trash"></i> 删除</button>
        </div>
        <div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:8px;">
            <input type="text" class="input-lg bgi-sch-config" placeholder="一条龙配置名（可选）" value="${_bgiEsc(s.config_name || '')}">
            <input type="text" class="input-lg bgi-sch-groups" placeholder="配置组名（逗号分隔）" value="${_bgiEsc(s.group_names || '')}">
        </div>
    `;
    box.appendChild(row);
}

function bgiAddSchedule() {
    bgiScheduleRow({ enabled: true, time: '04:00', mode: 'onedragon', days: [] });
}

function bgiRemoveSchedule(btn) {
    const row = btn.closest('.bgi-schedule-row');
    if (row) row.remove();
}

function bgiCollectSchedules() {
    return Array.prototype.map.call(document.querySelectorAll('.bgi-schedule-row'), function (row) {
        return {
            id: row.dataset.id,
            enabled: row.querySelector('.bgi-sch-enabled').checked,
            time: row.querySelector('.bgi-sch-time').value,
            mode: row.querySelector('.bgi-sch-mode').value,
            days: _bgiDaysFromRow(row),
            config_name: row.querySelector('.bgi-sch-config').value.trim(),
            group_names: row.querySelector('.bgi-sch-groups').value.trim()
        };
    }).filter(function (s) { return !!s.time; });
}

function bgiKill() {
    if (!confirm('确定结束所有 BetterGI 进程？')) return;
    fetch('/api/bettergi/kill', { method: 'POST' })
        .then(function (r) { return r.json(); })
        .then(function (res) {
            showToast(res.message || '已执行', res.status === 'success' ? 'success' : 'error');
            bgiLoadStatus();
        })
        .catch(function () { bgiLoadStatus(); });
}

function bgiClearEvents() {
    fetch('/api/bettergi/clear-events', { method: 'POST' })
        .then(function () { showToast('事件日志已清空'); bgiLoadStatus(); })
        .catch(function () {});
}

// ============= 主动交互 =============

function loadProactiveStatus() {
    fetch('/api/proactive/status')
        .then(r => r.json())
        .then(data => {
            if (data.error) return;
            document.getElementById('proactive-toggle').checked = data.enabled || false;
            document.getElementById('last-interaction').textContent = data.last_interaction 
                ? new Date(data.last_interaction).toLocaleString('zh-CN') : '暂无';
            document.getElementById('bond-level-display').textContent = data.bond_level || 1;
            document.getElementById('sent-count').textContent = data.sent_count || 0;
        })
        .catch(e => console.error('加载主动交互状态失败:', e));
}

function toggleProactive() {
    const enabled = document.getElementById('proactive-toggle').checked;
    fetch('/api/proactive/toggle', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ enabled })
    })
    .then(r => r.json())
    .then(data => {
        if (data.status === 'success') {
            showToast(enabled ? '主动交互已启用' : '主动交互已禁用');
        }
    })
    .catch(e => console.error('切换主动交互状态失败:', e));
}

function generateProactiveMessage() {
    const container = document.getElementById('generated-message');
    container.classList.remove('hidden');
    container.innerHTML = '<div class="loading-spinner"><i class="fas fa-spinner fa-spin"></i> 生成中...</div>';

    fetch('/api/proactive/generate', { method: 'POST' })
        .then(r => r.json())
        .then(data => {
            container.innerHTML = '<div class="message-bubble">' + (data.message || '暂时没有想说的~') + '</div>';
        })
        .catch(e => {
            container.innerHTML = '<div class="error-message">生成失败: ' + e.message + '</div>';
        });
}

function loadTasks() {
    fetch('/api/proactive/tasks')
        .then(r => r.json())
        .then(data => {
            const list = document.getElementById('tasks-list');
            if (!data.tasks || data.tasks.length === 0) {
                list.innerHTML = '<div class="empty-state">暂无定时任务</div>';
                return;
            }
            list.innerHTML = data.tasks.map(task => {
                const nextRun = task.next_run ? new Date(task.next_run).toLocaleString('zh-CN') : '未设置';
                return '<div class="task-item' + (task.enabled ? '' : ' disabled') + '">' +
                    '<div class="task-info">' +
                        '<div class="task-name">' + sanitizeHtml(task.name) + '</div>' +
                        '<div class="task-meta">' +
                            '<span class="task-type">' + (task.task_type === 'cron' ? '⏰ Cron' : '📅 一次性') + '</span>' +
                            '<span class="task-next">下次: ' + nextRun + '</span>' +
                        '</div>' +
                        '<div class="task-message">' + sanitizeHtml(task.message) + '</div>' +
                    '</div>' +
                    '<div class="task-actions">' +
                        '<button class="btn btn-xs ' + (task.enabled ? 'btn-secondary' : 'btn-primary') + '" onclick="toggleTask(\'' + task.id + '\', ' + !task.enabled + ')">' +
                            (task.enabled ? '禁用' : '启用') +
                        '</button>' +
                        '<button class="btn btn-xs btn-danger" onclick="deleteTask(\'' + task.id + '\')">删除</button>' +
                    '</div>' +
                '</div>';
            }).join('');
        })
        .catch(e => console.error('加载任务列表失败:', e));
}

function toggleTask(taskId, enabled) {
    fetch('/api/proactive/tasks/' + taskId, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ enabled })
    })
    .then(r => r.json())
    .then(data => {
        if (data.status === 'success') {
            loadTasks();
            showToast(enabled ? '任务已启用' : '任务已禁用');
        }
    })
    .catch(e => console.error('切换任务状态失败:', e));
}

function deleteTask(taskId) {
    if (!confirm('确定要删除此定时任务吗？')) return;
    fetch('/api/proactive/tasks/' + taskId, { method: 'DELETE' })
        .then(r => r.json())
        .then(data => {
            if (data.status === 'success') {
                loadTasks();
                showToast('任务已删除');
            }
        })
        .catch(e => console.error('删除任务失败:', e));
}

function showAddTaskModal() {
    document.getElementById('add-task-modal').classList.remove('hidden');
    document.getElementById('task-name').value = '';
    document.getElementById('task-cron').value = '';
    document.getElementById('task-run-at').value = '';
    document.getElementById('task-message').value = '';
    onTaskTypeChange();
}

function hideAddTaskModal() {
    document.getElementById('add-task-modal').classList.add('hidden');
}

function onTaskTypeChange() {
    const type = document.getElementById('task-type').value;
    document.getElementById('cron-expr-group').classList.toggle('hidden', type !== 'cron');
    document.getElementById('run-at-group').classList.toggle('hidden', type !== 'once');
}

function addTask() {
    const name = document.getElementById('task-name').value.trim();
    const type = document.getElementById('task-type').value;
    const message = document.getElementById('task-message').value.trim();
    const cronExpr = document.getElementById('task-cron').value.trim();
    const runAt = document.getElementById('task-run-at').value;

    if (!name) { showToast('请输入任务名称', 'error'); return; }
    if (!message) { showToast('请输入消息内容', 'error'); return; }
    if (type === 'cron' && !cronExpr) { showToast('请输入 Cron 表达式', 'error'); return; }
    if (type === 'once' && !runAt) { showToast('请选择执行时间', 'error'); return; }

    fetch('/api/proactive/tasks', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name, task_type: type, message, cron_expr: cronExpr, run_at: runAt })
    })
    .then(r => r.json())
    .then(data => {
        if (data.status === 'success') {
            hideAddTaskModal();
            loadTasks();
            showToast('任务已创建');
        } else {
            showToast('创建失败: ' + (data.detail || '未知错误'), 'error');
        }
    })
    .catch(e => showToast('创建失败: ' + e.message, 'error'));
}

// ============= 插件管理 =============

let currentPluginTab = 'installed';
let pluginFilter = 'all';
let pluginPlatform = 'all';
let pluginData = []; // 缓存插件数据用于搜索过滤

function switchPluginTab(tab) {
    currentPluginTab = tab;
    document.getElementById('plugin-tab-installed').classList.toggle('hidden', tab !== 'installed');
    document.getElementById('plugin-tab-marketplace').classList.toggle('hidden', tab !== 'marketplace');
    document.getElementById('plugin-tab-conflicts').classList.toggle('hidden', tab !== 'conflicts');
    document.getElementById('plugin-tab-installed-btn').classList.toggle('btn-primary', tab === 'installed');
    document.getElementById('plugin-tab-marketplace-btn').classList.toggle('btn-primary', tab === 'marketplace');
    document.getElementById('plugin-tab-conflicts-btn').classList.toggle('btn-primary', tab === 'conflicts');
    if (tab === 'marketplace') {
        loadPluginMarketplace();
    } else if (tab === 'conflicts') {
        loadCommandConflicts();
    } else {
        document.getElementById('plugins-search-input').value = '';
        pluginFilter = 'all';
        pluginPlatform = 'all';
        document.querySelectorAll('.plugins-filter-btn[data-filter]').forEach(b => b.classList.toggle('active', b.dataset.filter === 'all'));
        document.querySelectorAll('.plugins-filter-btn[data-platform]').forEach(b => b.classList.toggle('active', b.dataset.platform === 'all'));
        filterPlugins();
    }
}

function setPluginFilter(filter, btn) {
    pluginFilter = filter;
    document.querySelectorAll('.plugins-filter-btn[data-filter]').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    filterPlugins();
}

function setPluginPlatform(platform, btn) {
    pluginPlatform = platform;
    document.querySelectorAll('.plugins-filter-btn[data-platform]').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    filterPlugins();
}

function filterPlugins() {
    const search = (document.getElementById('plugins-search-input').value || '').toLowerCase().trim();
    const list = document.getElementById('plugins-list');
    const cards = list.querySelectorAll('.plugin-card');
    let visibleCount = 0;

    cards.forEach(card => {
        const name = (card.dataset.name || '').toLowerCase();
        const author = (card.dataset.author || '').toLowerCase();
        const desc = (card.dataset.desc || '').toLowerCase();
        const isActive = card.dataset.active === 'true';
        const hasError = card.dataset.error === 'true';

        // 搜索匹配
        let show = true;
        if (search) {
            show = name.includes(search) || author.includes(search) || desc.includes(search);
        }

        // 状态过滤
        if (show && pluginFilter !== 'all') {
            if (pluginFilter === 'active') show = isActive && !hasError;
            else if (pluginFilter === 'inactive') show = !isActive && !hasError;
            else if (pluginFilter === 'error') show = hasError;
        }

        // 平台过滤
        if (show && pluginPlatform !== 'all') {
            const plats = (card.dataset.platform || 'all-platforms').split(',');
            show = plats.indexOf(pluginPlatform) !== -1;
        }

        card.style.display = show ? '' : 'none';
        if (show) visibleCount++;
    });

    document.getElementById('plugins-count').textContent = visibleCount + ' / ' + cards.length;
}

function getPluginAccent(name) {
    // 根据插件名生成一个固定的颜色索引
    let hash = 0;
    for (let i = 0; i < name.length; i++) {
        hash = ((hash << 5) - hash) + name.charCodeAt(i);
        hash |= 0;
    }
    return Math.abs(hash) % 5;
}

function loadPlugins() {
    const list = document.getElementById('plugins-list');
    list.innerHTML = '<div class="empty-state"><i class="fas fa-spinner fa-spin"></i> 加载中...</div>';

    fetch('/api/plugins/')
        .then(r => r.json())
        .then(data => {
            pluginData = data.plugins || [];
            if (!pluginData || pluginData.length === 0) {
                list.innerHTML = '<div class="empty-state"><i class="fas fa-puzzle-piece"></i> 暂无插件</div>';
                document.getElementById('plugins-count').textContent = '0';
                return;
            }
            list.innerHTML = pluginData.map(p => {
                const hasError = p.error ? true : false;
                const name = sanitizeHtml(p.name || p.root_dir_name);
                const author = sanitizeHtml(p.author || 'unknown');
                const version = sanitizeHtml(p.version || '1.0.0');
                const desc = p.desc ? sanitizeHtml(p.desc) : '';
                const accentIdx = getPluginAccent(name);
                const cardClass = (!p.activated ? ' disabled' : '') + (hasError ? ' has-error' : '');
                // 平台筛选数据：由 platform_tags 反推 qq / webchat / all-platforms
                const platTags = p.platform_tags || [];
                let platData = 'all-platforms';
                if (platTags.length === 1) {
                    platData = platTags[0] === 'QQ' ? 'qq' : (platTags[0] === '网页' ? 'webchat' : 'all-platforms');
                } else if (platTags.length > 1) {
                    const parts = [];
                    if (platTags.indexOf('QQ') !== -1) parts.push('qq');
                    if (platTags.indexOf('网页') !== -1) parts.push('webchat');
                    platData = parts.length ? parts.join(',') : 'all-platforms';
                }

                return '<div class="plugin-card' + cardClass + '"' +
                    ' data-name="' + name.toLowerCase() + '"' +
                    ' data-author="' + author.toLowerCase() + '"' +
                    ' data-desc="' + desc.toLowerCase() + '"' +
                    ' data-active="' + p.activated + '"' +
                    ' data-error="' + hasError + '"' +
                    ' data-platform="' + platData + '">' +
                    '<div class="plugin-header">' +
                        '<div class="plugin-icon" data-accent="' + accentIdx + '"><i class="fas fa-cube"></i></div>' +
                        '<div class="plugin-info">' +
                            '<div class="plugin-name-row">' +
                                '<div class="plugin-name">' + name + '</div>' +
                                '<span class="plugin-version">v' + version + '</span>' +
                                (p.platform_tags || []).map(function (t) {
                                    const cls = t === 'QQ' ? 'tag-qq' : (t === '网页' ? 'tag-web' : 'tag-all');
                                    return '<span class="plugin-platform-tag ' + cls + '">' + sanitizeHtml(t) + '</span>';
                                }).join('') +
                                '<span class="plugin-status-badge ' + (hasError ? 'error' : (p.activated ? 'active' : 'inactive')) + '">' +
                                    '<span class="status-dot ' + (hasError ? 'inactive' : (p.activated ? 'active' : 'inactive')) + '"></span>' +
                                    (hasError ? '异常' : (p.activated ? '已启用' : '已禁用')) +
                                '</span>' +
                            '</div>' +
                            '<div class="plugin-meta">' +
                                '<span><i class="fas fa-user"></i> ' + author + '</span>' +
                                (p.reserved ? '<span><i class="fas fa-shield-alt"></i> 内置</span>' : '') +
                            '</div>' +
                        '</div>' +
                    '</div>' +
                    (desc ? '<div class="plugin-body"><div class="plugin-desc">' + desc + '</div></div>' : '') +
                    (hasError ? '<div class="plugin-body"><div class="plugin-error"><i class="fas fa-exclamation-triangle"></i> ' + sanitizeHtml(p.error) + '</div></div>' : '') +
                    '<div class="plugin-body">' +
                    '<div class="plugin-actions">' +
                        (p.activated
                            ? '<button class="btn btn-sm btn-secondary" onclick="disablePlugin(\'' + name + '\')"><i class="fas fa-pause"></i> 禁用</button>'
                            : (!hasError ? '<button class="btn btn-sm btn-primary" onclick="enablePlugin(\'' + name + '\')"><i class="fas fa-play"></i> 启用</button>' : '')
                        ) +
                        (!hasError ? '<button class="btn btn-sm" onclick="showPluginConfig(\'' + name + '\')"><i class="fas fa-cog"></i> 配置</button>' : '') +
                        '<button class="btn btn-sm" onclick="showPluginDetail(\'' + name + '\')"><i class="fas fa-info-circle"></i> 详情</button>' +
                        '<button class="btn btn-sm" onclick="reloadPlugin(\'' + name + '\')"><i class="fas fa-sync-alt"></i> 重载</button>' +
                        (!p.reserved ? '<button class="btn btn-sm btn-danger" onclick="uninstallPlugin(\'' + name + '\')"><i class="fas fa-trash-alt"></i> 卸载</button>' : '') +
                    '</div>' +
                    '</div>' +
                '</div>';
            }).join('');
            filterPlugins();
        })
        .catch(e => {
            list.innerHTML = '<div class="empty-state"><i class="fas fa-exclamation-triangle"></i> 加载失败: ' + e.message + '</div>';
            document.getElementById('plugins-count').textContent = '0';
        });
}

function loadPluginMarketplace() {
    const list = document.getElementById('plugin-marketplace-list');
    list.innerHTML = '<div class="empty-state"><i class="fas fa-spinner fa-spin"></i> 加载中...</div>';

    fetch('/api/plugins/marketplace')
        .then(r => r.json())
        .then(data => {
            if (!data.marketplace || data.marketplace.length === 0) {
                list.innerHTML = '<div class="empty-state"><i class="fas fa-store"></i> 暂无可用插件</div>';
                return;
            }
            list.innerHTML = data.marketplace.map(p => {
                const name = sanitizeHtml(p.display_name || p.name);
                const author = sanitizeHtml(p.author || 'unknown');
                const version = sanitizeHtml(p.version || '1.0.0');
                const desc = p.desc ? sanitizeHtml(p.desc) : '';
                const accentIdx = getPluginAccent(name);
                return '<div class="plugin-card">' +
                    '<div class="plugin-header">' +
                        '<div class="plugin-icon" data-accent="' + accentIdx + '"><i class="fas fa-cube"></i></div>' +
                        '<div class="plugin-info">' +
                            '<div class="plugin-name-row">' +
                                '<div class="plugin-name">' + name + '</div>' +
                                '<span class="plugin-version">v' + version + '</span>' +
                                '<span class="plugin-status-badge active"><span class="status-dot system"></span> ' + sanitizeHtml(p.source || '') + '</span>' +
                            '</div>' +
                            '<div class="plugin-meta">' +
                                '<span><i class="fas fa-user"></i> ' + author + '</span>' +
                            '</div>' +
                        '</div>' +
                    '</div>' +
                    (desc ? '<div class="plugin-body"><div class="plugin-desc">' + desc + '</div></div>' : '') +
                    '<div class="plugin-body">' +
                    '<div class="plugin-actions">' +
                        '<button class="btn btn-sm btn-primary" onclick="installMarketplacePlugin(\'' + sanitizeHtml(p.repo) + '\')">' +
                            '<i class="fas fa-download"></i> 安装' +
                        '</button>' +
                    '</div>' +
                    '</div>' +
                '</div>';
            }).join('');
        })
        .catch(e => {
            list.innerHTML = '<div class="empty-state"><i class="fas fa-exclamation-triangle"></i> 加载失败: ' + e.message + '</div>';
        });
}

function installPlugin() {
    const input = document.getElementById('plugin-install-input');
    const source = input.value.trim();
    if (!source) {
        showToast('请输入 GitHub 仓库 URL', 'warning');
        return;
    }

    const btn = document.querySelector('.plugin-install-bar .btn-primary');
    btn.disabled = true;
    btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> 安装中...';
    showToast('正在安装插件: ' + source, 'info');

    fetch('/api/plugins/install', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ source })
    })
    .then(r => r.json())
    .then(data => {
        if (data.status === 'success') {
            showToast(data.message || '安装成功', 'success');
            input.value = '';
            loadPlugins();
        } else {
            showToast('安装失败: ' + (data.detail || '未知错误'), 'error');
        }
    })
    .catch(e => showToast('安装失败: ' + e.message, 'error'))
    .finally(() => {
        btn.disabled = false;
        btn.innerHTML = '<i class="fas fa-download"></i> 安装';
    });
}

// ============= 命令冲突管理 =============

let conflictData = [];

function loadCommandConflicts() {
    const list = document.getElementById('conflicts-list');
    list.innerHTML = '<div class="empty-state"><i class="fas fa-spinner fa-spin"></i> 加载中...</div>';

    fetch('/api/plugins/commands')
        .then(r => r.json())
        .then(data => {
            conflictData = data.data || [];
            renderConflicts(conflictData);
        })
        .catch(e => {
            list.innerHTML = '<div class="empty-state"><i class="fas fa-exclamation-triangle"></i> 加载失败: ' + e.message + '</div>';
            document.getElementById('conflicts-count').textContent = '0';
        });
}

function renderConflicts(commands) {
    const list = document.getElementById('conflicts-list');
    document.getElementById('conflicts-count').textContent = commands.length;

    if (!commands || commands.length === 0) {
        list.innerHTML = '<div class="empty-state"><i class="fas fa-check-circle"></i> 暂无命令冲突</div>';
        return;
    }

    // 统计冲突数
    const conflictCount = commands.filter(c => c.is_conflict).length;

    list.innerHTML = commands.map(cmd => {
        const isConflict = cmd.is_conflict;
        const isResolved = cmd.resolved;
        const owner = cmd.owner;

        let conflictBadge = '';
        if (isConflict) {
            if (isResolved) {
                conflictBadge = '<span class="plugin-status-badge" style="background:rgba(34,197,94,0.12);color:#22c55e"><i class="fas fa-check-circle"></i> 已解决</span>';
            } else {
                conflictBadge = '<span class="plugin-status-badge" style="background:rgba(239,68,68,0.12);color:#ef4444"><i class="fas fa-exclamation-triangle"></i> 冲突</span>';
            }
        }

        const pluginDetails = (cmd.plugin_details || []).map(pd => {
            const isOwner = pd.is_owner || pd.plugin_name === owner;
            return '<div class="conflict-plugin-item' + (isOwner ? ' is-owner' : '') + '">' +
                '<div class="conflict-plugin-info">' +
                    '<span class="conflict-plugin-name">' + escapeHtml(pd.plugin_display_name || pd.plugin_name) + '</span>' +
                    (pd.description ? '<span class="conflict-plugin-desc">' + escapeHtml(pd.description) + '</span>' : '') +
                    '<span class="conflict-plugin-priority">优先级: ' + (pd.priority || 0) + '</span>' +
                '</div>' +
                (isConflict && !isResolved
                    ? '<button class="btn btn-sm btn-primary" onclick="resolveConflict(\'' + escapeHtml(cmd.command) + '\', \'' + escapeHtml(pd.plugin_name) + '\')">优先使用</button>'
                    : ''
                ) +
                (isOwner && isResolved
                    ? '<span class="conflict-owner-badge"><i class="fas fa-crown"></i> 当前处理</span>'
                    : ''
                ) +
            '</div>';
        }).join('');

        return '<div class="plugin-card' + (isConflict ? ' conflict-card' : '') + '">' +
            '<div class="plugin-header">' +
                '<div class="plugin-icon" style="background:var(--primary-color-alpha);color:var(--primary-color)"><i class="fas fa-terminal"></i></div>' +
                '<div class="plugin-info">' +
                    '<div class="plugin-name-row">' +
                        '<div class="plugin-name">/' + escapeHtml(cmd.command) + '</div>' +
                        conflictBadge +
                    '</div>' +
                    '<div class="plugin-meta">' +
                        '<span><i class="fas fa-plug"></i> ' + cmd.plugin_count + ' 个插件注册</span>' +
                        (owner ? '<span><i class="fas fa-crown"></i> 当前: ' + escapeHtml(owner) + '</span>' : '') +
                    '</div>' +
                '</div>' +
            '</div>' +
            '<div class="plugin-body">' +
                '<div class="conflict-plugin-list">' + pluginDetails + '</div>' +
            '</div>' +
            (isConflict && isResolved
                ? '<div class="plugin-body"><div class="conflict-actions">' +
                    '<button class="btn btn-sm" onclick="resetConflict(\'' + escapeHtml(cmd.command) + '\')"><i class="fas fa-undo"></i> 重置为自动选择</button>' +
                  '</div></div>'
                : ''
            ) +
        '</div>';
    }).join('') +

    // 冲突摘要
    (conflictCount > 0
        ? '<div class="empty-state" style="margin-top:16px;font-size:13px;color:var(--text-muted)">' +
            '<i class="fas fa-info-circle"></i> 共 ' + conflictCount + ' 个命令存在冲突，' +
            commands.filter(c => c.resolved).length + ' 个已手动解决。' +
            '未解决的冲突将按优先级自动选择处理插件。' +
          '</div>'
        : ''
    );
}

function filterConflicts() {
    const query = document.getElementById('conflicts-search-input').value.toLowerCase().trim();
    if (!query) {
        renderConflicts(conflictData);
        return;
    }
    const filtered = conflictData.filter(c => c.command.toLowerCase().includes(query));
    renderConflicts(filtered);
}

function resolveConflict(command, plugin) {
    fetch('/api/plugins/commands/conflicts/resolve', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ command: command, winning_plugin: plugin }),
    })
    .then(r => r.json())
    .then(data => {
        if (data.success) {
            showToast('命令 /' + command + ' 已由 ' + plugin + ' 处理', 'success');
            loadCommandConflicts();
        } else {
            showToast(data.message || '解决失败', 'error');
        }
    })
    .catch(e => showToast('请求失败: ' + e.message, 'error'));
}

function resetConflict(command) {
    fetch('/api/plugins/commands/conflicts/reset', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ command: command }),
    })
    .then(r => r.json())
    .then(data => {
        if (data.success) {
            showToast('命令 /' + command + ' 的冲突解决已重置', 'success');
            loadCommandConflicts();
        } else {
            showToast(data.message || '重置失败', 'error');
        }
    })
    .catch(e => showToast('请求失败: ' + e.message, 'error'));
}

function installMarketplacePlugin(repo) {
    document.getElementById('plugin-install-input').value = repo;
    switchPluginTab('marketplace');
    setTimeout(() => {
        document.getElementById('plugin-install-input').focus();
    }, 100);
}

function uninstallPlugin(name) {
    if (!confirm('确定要卸载插件 "' + name + '" 吗？\n此操作不可撤销。')) {
        return;
    }

    fetch('/api/plugins/' + encodeURIComponent(name) + '/uninstall', { method: 'POST' })
        .then(r => r.json())
        .then(data => {
            if (data.status === 'success') {
                showToast('插件 ' + name + ' 已卸载', 'success');
                loadPlugins();
            } else {
                showToast('卸载失败: ' + (data.detail || '未知错误'), 'error');
            }
        })
        .catch(e => showToast('卸载失败: ' + e.message, 'error'));
}

function enablePlugin(name) {
    fetch('/api/plugins/' + encodeURIComponent(name) + '/enable', { method: 'POST' })
        .then(r => r.json())
        .then(data => {
            if (data.status === 'success') {
                loadPlugins();
                showToast('插件 ' + name + ' 已启用');
            } else {
                showToast('启用失败: ' + (data.detail || '未知错误'), 'error');
            }
        })
        .catch(e => showToast('启用失败: ' + e.message, 'error'));
}

function disablePlugin(name) {
    fetch('/api/plugins/' + encodeURIComponent(name) + '/disable', { method: 'POST' })
        .then(r => r.json())
        .then(data => {
            if (data.status === 'success') {
                loadPlugins();
                showToast('插件 ' + name + ' 已禁用');
            } else {
                showToast('禁用失败: ' + (data.detail || '未知错误'), 'error');
            }
        })
        .catch(e => showToast('禁用失败: ' + e.message, 'error'));
}

function reloadPlugin(name) {
    fetch('/api/plugins/' + encodeURIComponent(name) + '/reload', { method: 'POST' })
        .then(r => r.json())
        .then(data => {
            if (data.status === 'success') {
                loadPlugins();
                showToast('插件 ' + name + ' 已重载');
            } else {
                showToast('重载结果: ' + (data.message || '部分失败'), 'warning');
            }
        })
        .catch(e => showToast('重载失败: ' + e.message, 'error'));
}

function reloadAllPlugins() {
    fetch('/api/plugins/reload-all', { method: 'POST' })
        .then(r => r.json())
        .then(data => {
            loadPlugins();
            showToast(data.status === 'success' ? '所有插件已重载' : '重载完成（部分失败）');
        })
        .catch(e => showToast('重载失败: ' + e.message, 'error'));
}

// ===== 插件配置动态表单 =====

function showPluginConfig(name) {
    const modal = document.getElementById('plugin-config-modal');
    modal.classList.remove('hidden');
    const body = document.getElementById('plugin-config-body');
    body.innerHTML = '<div class="empty-state"><i class="fas fa-spinner fa-spin"></i> 加载配置...</div>';
    document.getElementById('plugin-config-modal').dataset.pluginName = name;

    fetch('/api/plugins/' + encodeURIComponent(name) + '/config')
        .then(r => r.json())
        .then(data => {
            const config = data.config || {};
            const schema = data.conf_schema || null;
            if (schema && Object.keys(schema).length > 0) {
                // 有 schema，渲染动态表单
                body.innerHTML = renderPluginConfigForm(config, schema, '');
            } else if (Object.keys(config).length > 0) {
                // 无 schema 但有配置，回退到 JSON 编辑器
                body.innerHTML = '<div class="form-tips" style="margin-bottom:12px;padding:8px 12px;background:var(--bg-secondary);border-radius:8px;">'
                    + '<i class="fas fa-info-circle"></i> 该插件未提供配置模式，使用 JSON 编辑器</div>'
                    + '<textarea id="plugin-config-json-editor" class="plugin-config-json-textarea" spellcheck="false">'
                    + JSON.stringify(config, null, 2) + '</textarea>';
                document.getElementById('plugin-config-json-editor').addEventListener('input', function() {
                    try { JSON.parse(this.value); this.style.borderColor = 'var(--success-color)'; }
                    catch(e) { this.style.borderColor = 'var(--danger-color)'; }
                });
            } else {
                body.innerHTML = '<div class="empty-state">该插件暂无配置</div>';
            }
        })
        .catch(e => {
            body.innerHTML = '<div class="empty-state">加载失败: ' + e.message + '</div>';
        });
}

function renderPluginConfigForm(config, schema, prefix) {
    let html = '<div class="plugin-config-form">';
    for (const [key, fieldSchema] of Object.entries(schema)) {
        // 跳过内部字段
        if (key === 'ui:widget' || key === 'hint' || key === 'description' || key === 'options' || key === 'enum' || key === 'items' || key === 'default' || key === 'obvious_hint') continue;
        if (typeof fieldSchema !== 'object' || fieldSchema === null) continue;
        
        const fieldName = prefix ? prefix + '.' + key : key;
        const fieldType = fieldSchema.type || 'string';
        const fieldDesc = fieldSchema.description || key;
        const fieldHint = fieldSchema.hint || '';
        const fieldDefault = fieldSchema.hasOwnProperty('default') ? fieldSchema.default : null;
        const currentValue = config.hasOwnProperty(key) ? config[key] : fieldDefault;
        const fieldId = 'plugin-cfg-' + fieldName.replace(/\./g, '-');
        const isObviousHint = fieldSchema.obvious_hint === true;

        if (fieldType === 'object' && fieldSchema.items && Object.keys(fieldSchema.items).length > 0) {
            // 嵌套对象 - 渲染折叠区域
            html += '<div class="plugin-config-group">';
            html += '<div class="plugin-config-group-header" onclick="togglePluginConfigGroup(this)">';
            html += '<i class="fas fa-chevron-right"></i> ';
            html += '<span class="plugin-config-group-title">' + escapeHtml(fieldDesc) + '</span>';
            if (fieldHint) html += '<span class="plugin-config-hint-icon" title="' + escapeHtml(fieldHint) + '"><i class="fas fa-question-circle"></i></span>';
            html += '</div>';
            html += '<div class="plugin-config-group-body">';
            // 递归渲染子字段
            const subConfig = (currentValue && typeof currentValue === 'object') ? currentValue : {};
            html += renderPluginConfigForm(subConfig, fieldSchema.items, fieldName);
            html += '</div></div>';
            continue;
        }

        // 普通字段
        html += '<div class="plugin-config-field">';
        html += '<label class="plugin-config-label" for="' + fieldId + '">';
        html += '<span class="plugin-config-label-text">' + escapeHtml(fieldDesc) + '</span>';
        if (fieldHint && !isObviousHint) {
            html += '<span class="plugin-config-hint-icon" title="' + escapeHtml(fieldHint) + '"><i class="fas fa-question-circle"></i></span>';
        }
        html += '</label>';

        // 渲染输入控件
        html += renderPluginConfigInput(fieldId, fieldType, fieldName, currentValue, fieldSchema, fieldHint);

        // 明显的提示文本
        if (isObviousHint && fieldHint) {
            html += '<div class="plugin-config-obvious-hint">' + escapeHtml(fieldHint).replace(/\n/g, '<br>') + '</div>';
        }

        html += '</div>';
    }
    html += '</div>';
    return html;
}

function renderPluginConfigInput(fieldId, fieldType, fieldName, currentValue, fieldSchema, fieldHint) {
    // 支持 enum 字段（带 value/label 的对象数组）
    const enumOptions = fieldSchema.enum;
    // 支持 options 字段（字符串数组）
    const options = fieldSchema.options;

    if (enumOptions && Array.isArray(enumOptions) && enumOptions.length > 0) {
        // 枚举下拉框
        let html = '<select id="' + fieldId + '" class="plugin-config-select" data-field-name="' + fieldName + '">';
        for (const opt of enumOptions) {
            const val = opt.value || opt;
            const label = opt.label || opt;
            const selected = String(currentValue) === String(val) ? ' selected' : '';
            html += '<option value="' + escapeHtml(String(val)) + '"' + selected + '>' + escapeHtml(label) + '</option>';
        }
        html += '</select>';
        return html;
    }

    if (options && Array.isArray(options) && options.length > 0) {
        // 选项下拉框
        let html = '<select id="' + fieldId + '" class="plugin-config-select" data-field-name="' + fieldName + '">';
        for (const opt of options) {
            const selected = String(currentValue) === String(opt) ? ' selected' : '';
            html += '<option value="' + escapeHtml(String(opt)) + '"' + selected + '>' + escapeHtml(opt) + '</option>';
        }
        html += '</select>';
        return html;
    }

    switch (fieldType) {
        case 'bool':
            return '<div class="plugin-config-toggle-wrap">'
                + '<input type="checkbox" id="' + fieldId + '" class="plugin-config-toggle" data-field-name="' + fieldName + '"'
                + (currentValue ? ' checked' : '') + '>'
                + '<label class="plugin-config-toggle-label" for="' + fieldId + '"></label>'
                + '</div>';

        case 'int':
            return '<input type="number" id="' + fieldId + '" class="plugin-config-input" data-field-name="' + fieldName + '"'
                + ' step="1" value="' + (currentValue != null ? currentValue : '') + '">';

        case 'float':
            return '<input type="number" id="' + fieldId + '" class="plugin-config-input" data-field-name="' + fieldName + '"'
                + ' step="0.01" value="' + (currentValue != null ? currentValue : '') + '">';

        case 'list':
            // 列表用 textarea，每行一个
            const listVal = (Array.isArray(currentValue) ? currentValue.join('\n') : '');
            return '<textarea id="' + fieldId + '" class="plugin-config-textarea plugin-config-list-input" data-field-name="' + fieldName + '"'
                + ' placeholder="每行一个项目" rows="4">' + escapeHtml(listVal) + '</textarea>'
                + '<div class="form-tips">每行一个项目</div>';

        case 'string':
        default:
            return '<input type="text" id="' + fieldId + '" class="plugin-config-input" data-field-name="' + fieldName + '"'
                + ' value="' + escapeHtml(currentValue != null ? String(currentValue) : '') + '">';
    }
}

function togglePluginConfigGroup(headerEl) {
    const body = headerEl.nextElementSibling;
    const icon = headerEl.querySelector('.fa-chevron-right');
    if (body) {
        body.classList.toggle('plugin-config-group-collapsed');
        if (icon) icon.classList.toggle('fa-chevron-down');
    }
}

function hidePluginConfigModal() {
    document.getElementById('plugin-config-modal').classList.add('hidden');
}

function savePluginConfig() {
    const name = document.getElementById('plugin-config-modal').dataset.pluginName;
    const body = document.getElementById('plugin-config-body');

    // 检查是否有 JSON 编辑器（回退模式）
    const jsonEditor = document.getElementById('plugin-config-json-editor');
    if (jsonEditor) {
        try {
            const config = JSON.parse(jsonEditor.value);
            submitPluginConfig(name, config);
        } catch (e) {
            showToast('JSON 格式错误: ' + e.message, 'error');
        }
        return;
    }

    // 动态表单模式 - 从表单控件收集配置
    const config = collectPluginConfigFromForm(body, '');
    submitPluginConfig(name, config);
}

function collectPluginConfigFromForm(container, prefix) {
    const config = {};

    // 收集输入控件
    const inputs = container.querySelectorAll('[data-field-name]');
    for (const input of inputs) {
        const fieldName = input.dataset.fieldName;
        // 从 fieldName 中提取 key（去掉前缀）
        const key = prefix ? fieldName.substring(prefix.length + 1) : fieldName;
        if (!key) continue;

        let value;
        if (input.type === 'checkbox') {
            value = input.checked;
        } else if (input.type === 'number') {
            value = input.value === '' ? null : (input.step && parseFloat(input.step) < 1 ? parseFloat(input.value) : parseInt(input.value, 10));
            if (isNaN(value)) value = null;
        } else if (input.tagName === 'TEXTAREA' && input.classList.contains('plugin-config-list-input')) {
            // list 类型：按行分割
            value = input.value.split('\n').filter(line => line.trim() !== '');
        } else if (input.tagName === 'SELECT') {
            value = input.value;
        } else {
            value = input.value;
        }

        // 处理嵌套key（如 "base_setting.base_url"）
        setNestedConfigValue(config, key, value);
    }

    return config;
}

function setNestedConfigValue(obj, path, value) {
    const keys = path.split('.');
    let current = obj;
    for (let i = 0; i < keys.length - 1; i++) {
        const k = keys[i];
        if (!current.hasOwnProperty(k) || typeof current[k] !== 'object') {
            current[k] = {};
        }
        current = current[k];
    }
    current[keys[keys.length - 1]] = value;
}

function submitPluginConfig(name, config) {
    fetch('/api/plugins/' + encodeURIComponent(name) + '/config', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ config })
    })
    .then(r => r.json())
    .then(data => {
        if (data.status === 'success') {
            hidePluginConfigModal();
            showToast('配置已保存');
        } else {
            showToast('保存失败: ' + (data.detail || '未知错误'), 'error');
        }
    })
    .catch(e => showToast('保存失败: ' + e.message, 'error'));
}

function showPluginDetail(name) {
    const modal = document.getElementById('plugin-detail-modal');
    modal.classList.remove('hidden');
    const body = document.getElementById('plugin-detail-body');
    body.innerHTML = '<div class="empty-state"><i class="fas fa-spinner fa-spin"></i> 加载中...</div>';

    fetch('/api/plugins/' + encodeURIComponent(name) + '/detail')
        .then(r => r.json())
        .then(data => {
            let html = '<div class="plugin-detail">';
            html += '<div class="detail-section">';
            html += '<h3><i class="fas fa-tag"></i> 基本信息</h3>';
            html += '<table class="detail-table">';
            html += '<tr><td>名称</td><td>' + sanitizeHtml(data.display_name || data.name) + '</td></tr>';
            html += '<tr><td>插件 ID</td><td><code>' + sanitizeHtml(data.plugin_id) + '</code></td></tr>';
            html += '<tr><td>作者</td><td>' + sanitizeHtml(data.author) + '</td></tr>';
            html += '<tr><td>版本</td><td>v' + sanitizeHtml(data.version) + '</td></tr>';
            html += '<tr><td>状态</td><td><span class="status-dot ' + (data.activated ? 'active' : 'inactive') + '"></span> ' + (data.activated ? '已启用' : '已禁用') + '</td></tr>';
            html += '<tr><td>类型</td><td>' + (data.reserved ? '内置插件' : '用户插件') + '</td></tr>';
            if (data.desc) html += '<tr><td>描述</td><td>' + sanitizeHtml(data.desc) + '</td></tr>';
            if (data.short_desc) html += '<tr><td>简介</td><td>' + sanitizeHtml(data.short_desc) + '</td></tr>';
            if (data.repo) html += '<tr><td>仓库</td><td><a href="' + sanitizeHtml(data.repo) + '" target="_blank">' + sanitizeHtml(data.repo) + '</a></td></tr>';
            html += '</table>';
            html += '</div>';

            if (data.handlers && data.handlers.length > 0) {
                html += '<div class="detail-section">';
                html += '<h3><i class="fas fa-bolt"></i> 注册的命令/Handler</h3>';
                html += '<table class="detail-table">';
                html += '<tr><th>名称</th><th>类型</th><th>命令/正则</th><th>描述</th></tr>';
                data.handlers.forEach(h => {
                    const cmdOrRegex = h.command ? '/' + sanitizeHtml(h.command) : (h.regex ? sanitizeHtml(h.regex) : '-');
                    html += '<tr><td>' + sanitizeHtml(h.name) + '</td><td>' + sanitizeHtml(h.event_type) + '</td><td><code>' + cmdOrRegex + '</code></td><td>' + sanitizeHtml(h.desc || '-') + '</td></tr>';
                });
                html += '</table>';
                html += '</div>';
            }

            if (data.files && data.files.length > 0) {
                html += '<div class="detail-section">';
                html += '<h3><i class="fas fa-file"></i> 文件列表</h3>';
                html += '<ul class="file-list">';
                data.files.forEach(f => {
                    html += '<li><code>' + sanitizeHtml(f.name) + '</code> <span class="file-size">(' + (f.size / 1024).toFixed(1) + ' KB)</span></li>';
                });
                html += '</ul>';
                html += '</div>';
            }

            // 第三方依赖区块（异步加载）
            html += '<div class="detail-section" id="plugin-deps-section">';
            html += '<h3><i class="fas fa-boxes"></i> 第三方依赖</h3>';
            html += '<div class="plugin-deps-body"><span class="ws-loading">检测中...</span></div>';
            html += '</div>';

            if (data.conf_schema) {
                html += '<div class="detail-section">';
                html += '<h3><i class="fas fa-cog"></i> 配置模式</h3>';
                html += '<pre class="config-json">' + JSON.stringify(data.conf_schema, null, 2) + '</pre>';
                html += '</div>';
            }

            html += '</div>';
            body.innerHTML = html;
            loadPluginDeps(name);
        })
        .catch(e => {
            body.innerHTML = '<div class="empty-state">加载失败: ' + e.message + '</div>';
        });
}

// 加载插件依赖状态（展示已安装/缺失并支持一键安装）
function loadPluginDeps(name) {
    const section = document.getElementById('plugin-deps-section');
    if (!section) return;
    const body = section.querySelector('.plugin-deps-body');
    fetch('/api/plugins/' + encodeURIComponent(name) + '/deps')
        .then(r => r.json())
        .then(data => {
            if (data.error) {
                body.innerHTML = '<span class="plugin-deps-hint">' + sanitizeHtml(data.error) + '</span>';
                return;
            }
            const hasDecl = data.requirements_file || data._deps_file || data.total > 0;
            if (!hasDecl) {
                body.innerHTML = '<span class="plugin-deps-hint"><i class="fas fa-check-circle"></i> 该插件未声明第三方依赖</span>';
                return;
            }
            const missing = data.missing || [];
            let html = '<div class="plugin-deps-status">' +
                '<span class="ws-status' + (missing.length ? ' ws-warn' : '') + '">' +
                    '<i class="fas ' + (data.running ? 'fa-spinner fa-spin' : (missing.length ? 'fa-exclamation-circle' : 'fa-check-circle')) + '"></i> ' +
                    '已安装 ' + (data.installed || 0) + ' / 共 ' + (data.total || 0) +
                '</span>' +
                '</div>';
            if (data.last && data.last.status) {
                const ls = data.last;
                html += '<div class="plugin-deps-last"><i class="fas fa-history"></i> 最近一次: ' +
                    sanitizeHtml(ls.message || ls.status) +
                    (ls.time ? ' ' + sanitizeHtml(ls.time) : '') + '</div>';
            }
            if (missing.length > 0) {
                html += '<ul class="plugin-deps-missing">';
                missing.forEach(m => {
                    html += '<li><code>' + sanitizeHtml(m.name) + '</code>' +
                        (m.version ? ' <span class="file-size">' + sanitizeHtml(m.version) + '</span>' : '') + '</li>';
                });
                html += '</ul>';
                html += '<button class="btn btn-sm btn-primary" onclick="installPluginDeps(\'' + sanitizeHtml(name) + '\')" ' +
                    (data.running ? 'disabled' : '') + '>' +
                    (data.running ? '<i class="fas fa-spinner fa-spin"></i> 安装中...' : '<i class="fas fa-download"></i> 安装缺失依赖(' + missing.length + ')') +
                    '</button>';
            } else if (data.total > 0) {
                html += '<span class="plugin-deps-ok"><i class="fas fa-check-circle"></i> 依赖完整</span>';
            } else if (data.requirements_file || data._deps_file) {
                html += '<span class="plugin-deps-hint">已声明依赖文件，但解析为空（可能均为注释）</span>';
            }
            body.innerHTML = html;
        })
        .catch(e => {
            body.innerHTML = '<span class="plugin-deps-hint">依赖状态加载失败: ' + sanitizeHtml(e.message) + '</span>';
        });
}

// 手动安装插件缺失依赖
function installPluginDeps(name) {
    const section = document.getElementById('plugin-deps-section');
    const body = section ? section.querySelector('.plugin-deps-body') : null;
    if (body) body.innerHTML = '<span class="ws-loading">正在安装依赖...</span>';
    showToast('正在安装插件依赖: ' + name, 'info');
    fetch('/api/plugins/' + encodeURIComponent(name) + '/deps/install', { method: 'POST' })
        .then(r => r.json())
        .then(data => {
            if (data.status === 'success') {
                showToast(data.message || '依赖安装完成', 'success');
            } else {
                const part = (data.detail || []).map(d =>
                    (d.success ? '' : '[' + d.name + ' 失败]') + (d.output ? ' ' + d.output : '')
                ).join('');
                showToast((data.message || '部分依赖安装失败') + (part ? ': ' + part : ''), 'error');
            }
            loadPluginDeps(name);
        })
        .catch(e => {
            showToast('依赖安装失败: ' + e.message, 'error');
            loadPluginDeps(name);
        });
}

function hidePluginDetailModal() {
    document.getElementById('plugin-detail-modal').classList.add('hidden');
}

// ============= 工具函数 =============

function sanitizeHtml(str) {
    if (!str) return '';
    const div = document.createElement('div');
    div.textContent = str;
    return div.innerHTML;
}

// ============= 命令提示符功能 =============

let cmdPromptSessionId = null;
let cmdPromptEventSource = null;
let cmdPollInterval = null;


// Agent 命令行工具执行完成：在工具卡片中内联展示命令与输出（不再弹出独立 cmd 终端窗口）
function _handleCmdToolResult(data, lastCard) {
    // 后端 tool_result 现在带完整 output，优先用它解析命令与状态
    const preview = data.output || data.preview || data.result || '';
    let parsed = null;
    try { parsed = JSON.parse(preview); } catch (e) { parsed = null; }

    let sessionId = parsed && parsed.session_id ? parsed.session_id : '';
    let cmdText = (parsed && parsed.command) || '';
    let status = parsed && parsed.status ? parsed.status : '';
    if (!sessionId) {
        // preview 可能被截断导致 JSON 解析失败：正则兜底提取 session_id
        const m = String(preview).match(/"session_id"\s*:\s*"([^"]+)"/);
        if (m) sessionId = m[1];
        const mc = String(preview).match(/"command"\s*:\s*"([^"]*)"/);
        if (mc) cmdText = mc[1].replace(/\\"/g, '"');
        const ms = String(preview).match(/"status"\s*:\s*"([^"]*)"/);
        if (ms) status = ms[1];
    }

    // 待用户确认：打开命令提示符面板（含确认按钮），但不弹独立终端窗口
    if (status === 'pending_approval') {
        const panel = document.getElementById('cmd-prompt-panel');
        if (panel && panel.classList.contains('hidden')) toggleCmdPromptPanel();
        pollPendingCommands();
        return;
    }

    // 在工具卡片中内联渲染 cmd 终端输出块（替代独立弹窗）
    if (lastCard) {
        _renderInlineCmdBlock(lastCard, cmdText, sessionId, preview, parsed);
    }
}

// 在工具卡片 body 中追加一个 cmd 终端风格的内联输出块
function _renderInlineCmdBlock(card, command, sessionId, preview, parsed) {
    const body = card.querySelector('.dsh-tool-body');
    if (!body) return;

    // 避免重复追加
    if (card.querySelector('.cmd-inline')) return;

    const block = document.createElement('div');
    block.className = 'cmd-inline';
    block.innerHTML =
        '<div class="cmd-inline-header">' +
            '<span class="cmd-inline-title">' +
                '<span class="cmd-inline-prompt">$</span>' +
                '<span class="cmd-inline-cmd">' + (command ? escapeHtml(command) : '命令执行') + '</span>' +
            '</span>' +
            '<span class="cmd-inline-status" id="cmd-inline-status">执行中…</span>' +
        '</div>' +
        '<div class="cmd-inline-output" id="cmd-inline-output"></div>';
    body.appendChild(block);

    const outputEl = block.querySelector('.cmd-inline-output');
    const statusEl = block.querySelector('.cmd-inline-status');

    // 回显命令提示行
    if (command) {
        const promptLine = document.createElement('div');
        promptLine.className = 'cmd-line cmd-prompt-line';
        promptLine.textContent = 'C:\\> ' + command;
        outputEl.appendChild(promptLine);
    }

    const appendLine = function (text, cls) {
        const div = document.createElement('div');
        div.className = 'cmd-line ' + (cls || 'cmd-stdout');
        div.textContent = text;
        outputEl.appendChild(div);
        outputEl.scrollTop = outputEl.scrollHeight;
    };

    // 有会话：流式拉取完整输出；否则直接展示已有的 preview 文本
    if (sessionId) {
        if (cmdPromptEventSource) {
            cmdPromptEventSource.close();
            cmdPromptEventSource = null;
        }
        cmdPromptEventSource = new EventSource('/api/command-prompt/stream/' + sessionId);
        cmdPromptEventSource.addEventListener('stdout', function (e) {
            try {
                const d = JSON.parse(e.data);
                appendLine(d.data, 'cmd-stdout');
            } catch (_) {}
        });
        cmdPromptEventSource.addEventListener('stderr', function (e) {
            try {
                const d = JSON.parse(e.data);
                appendLine(d.data, 'cmd-stderr');
            } catch (_) {}
        });
        cmdPromptEventSource.addEventListener('done', function (e) {
            const d = JSON.parse(e.data);
            const status = d.status;
            let statusText = '已完成';
            if (status === 'completed') statusText = '完成 (exit ' + d.returncode + ')';
            else if (status === 'failed') statusText = '失败 (exit ' + d.returncode + ')';
            else if (status === 'timeout') statusText = '超时';
            else if (status === 'cancelled') statusText = '已取消';
            else statusText = '状态: ' + status;
            statusEl.textContent = statusText;
            statusEl.classList.add(status === 'completed' ? 'ok' : status === 'failed' ? 'err' : '');
            if (cmdPromptEventSource) {
                cmdPromptEventSource.close();
                cmdPromptEventSource = null;
            }
        });
        cmdPromptEventSource.addEventListener('error', function (e) {
            if (e.data) {
                try {
                    const d = JSON.parse(e.data);
                    appendLine('错误: ' + (d.message || '未知错误'), 'cmd-stderr');
                } catch (_) {}
            }
            statusEl.textContent = '连接断开';
            statusEl.classList.add('err');
            if (cmdPromptEventSource) {
                cmdPromptEventSource.close();
                cmdPromptEventSource = null;
            }
        });
    } else if (preview && preview.trim()) {
        // 无会话（已完成的静态输出）：解析并展示
        let outputText = preview;
        if (parsed && parsed.output) {
            outputText = parsed.output;
        } else {
            // 尝试从 JSON 提取 output 字段
            const mo = String(preview).match(/"output"\s*:\s*"([\s\S]*?)(?<!\\)"\s*(?:,|\})/);
            if (mo) outputText = mo[1].replace(/\\n/g, '\n').replace(/\\"/g, '"');
        }
        if (typeof outputText === 'string') {
            outputText.split('\n').forEach(function (line) {
                appendLine(line, 'cmd-stdout');
            });
        }
        statusEl.textContent = '完成';
        statusEl.classList.add('ok');
    }
}

function toggleCmdPromptPanel() {
    const panel = document.getElementById('cmd-prompt-panel');
    const btn = document.getElementById('cmd-prompt-toggle-btn');
    panel.classList.toggle('hidden');
    btn.classList.toggle('active', !panel.classList.contains('hidden'));
    if (!panel.classList.contains('hidden')) {
        pollPendingCommands();
        cmdPollInterval = setInterval(pollPendingCommands, 3000);
    } else {
        if (cmdPollInterval) {
            clearInterval(cmdPollInterval);
            cmdPollInterval = null;
        }
    }
}

function pollPendingCommands() {
    fetch('/api/command-prompt/pending')
        .then(r => r.json())
        .then(data => {
            const pending = data.data || [];
            const badge = document.getElementById('cmd-prompt-badge');
            if (badge) badge.textContent = pending.length + ' 待确认';
            renderPendingCommands(pending);
        })
        .catch(() => {});
    
    fetch('/api/command-prompt/active')
        .then(r => r.json())
        .then(data => {
            const active = data.data || [];
            renderActiveCommands(active);
        })
        .catch(() => {});
}

function renderPendingCommands(pending) {
    const list = document.getElementById('cmd-pending-list');
    if (!pending.length) {
        list.innerHTML = '<div class="cmd-empty">暂无待确认命令</div>';
        return;
    }
    list.innerHTML = pending.map(s => {
        const riskColor = s.risk_level === 'high' ? '#ef4444' : s.risk_level === 'normal' ? '#f59e0b' : '#22c55e';
        const riskLabel = s.risk_level === 'high' ? '高危' : s.risk_level === 'normal' ? '需确认' : '安全';
        return '<div class="cmd-pending-item" data-session="' + s.session_id + '">' +
            '<div class="cmd-pending-cmd"><code>' + escapeHtml(s.command) + '</code></div>' +
            '<div class="cmd-pending-meta">' +
                '<span class="cmd-risk-badge" style="background:' + riskColor + '20;color:' + riskColor + '">' + riskLabel + '</span>' +
                (s.description ? '<span class="cmd-pending-desc">' + escapeHtml(s.description) + '</span>' : '') +
            '</div>' +
            '<div class="cmd-pending-actions">' +
                '<button class="btn btn-sm btn-primary" onclick="showCmdConfirm(\'' + s.session_id + '\')"><i class="fas fa-check"></i> 确认</button>' +
                '<button class="btn btn-sm btn-cmd-cancel-btn" onclick="cancelCmd(\'' + s.session_id + '\')"><i class="fas fa-times"></i> 取消</button>' +
            '</div>' +
        '</div>';
    }).join('');
}

function renderActiveCommands(active) {
    const list = document.getElementById('cmd-active-list');
    const running = active.filter(s => s.status === 'running');
    if (!running.length) {
        list.innerHTML = '<div class="cmd-empty">暂无活跃命令</div>';
        return;
    }
    list.innerHTML = running.map(s => {
        return '<div class="cmd-active-item" data-session="' + s.session_id + '">' +
            '<div class="cmd-active-cmd"><code>' + escapeHtml(s.command) + '</code></div>' +
            '<div class="cmd-active-meta">' +
                '<span class="cmd-active-spinner"><i class="fas fa-spinner fa-spin"></i> 执行中</span>' +
                '<span class="cmd-active-time">' + Math.round((Date.now()/1000 - s.updated_at)) + 's</span>' +
            '</div>' +
            '<div class="cmd-active-actions">' +
                '<button class="btn btn-sm" onclick="viewCmdOutput(\'' + s.session_id + '\', \'' + escapeHtml(s.command) + '\')"><i class="fas fa-eye"></i> 查看输出</button>' +
                '<button class="btn btn-sm btn-danger" onclick="cancelCmd(\'' + s.session_id + '\')"><i class="fas fa-stop"></i> 终止</button>' +
            '</div>' +
        '</div>';
    }).join('');
}

// ─── 确认弹窗 ───

let _confirmSessionId = null;

function showCmdConfirm(sessionId) {
    _confirmSessionId = sessionId;
    fetch('/api/command-prompt/session/' + sessionId)
        .then(r => r.json())
        .then(data => {
            const s = data.data;
            if (!s) { showToast('会话不存在', 'error'); return; }
            document.getElementById('cmd-confirm-command-text').textContent = s.command;
            document.getElementById('cmd-confirm-desc-text').textContent = s.description || '（无说明）';
            const riskEl = document.getElementById('cmd-confirm-risk');
            if (s.risk_level === 'high') {
                riskEl.className = 'cmd-confirm-risk risk-high';
                document.getElementById('cmd-confirm-risk-text').textContent = '⚠ 高危命令！请确认操作安全后谨慎执行';
            } else if (s.risk_level === 'normal') {
                riskEl.className = 'cmd-confirm-risk risk-normal';
                document.getElementById('cmd-confirm-risk-text').textContent = '该命令不在白名单中，请确认后执行';
            }
            document.getElementById('cmd-confirm-overlay').classList.remove('hidden');
        })
        .catch(e => showToast('获取会话信息失败: ' + e.message, 'error'));
}

function confirmCmdExecution() {
    if (!_confirmSessionId) return;
    fetch('/api/command-prompt/confirm', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ session_id: _confirmSessionId }),
    })
    .then(r => r.json())
    .then(data => {
        if (data.success) {
            showToast('命令已确认执行', 'success');
            document.getElementById('cmd-confirm-overlay').classList.add('hidden');
            pollPendingCommands();
            // 打开终端查看输出
            viewCmdOutput(_confirmSessionId, '');
        } else {
            showToast(data.error || '确认失败', 'error');
        }
    })
    .catch(e => showToast('请求失败: ' + e.message, 'error'));
}

function cancelCmdConfirm() {
    _confirmSessionId = null;
    document.getElementById('cmd-confirm-overlay').classList.add('hidden');
}

function cancelCmd(sessionId) {
    fetch('/api/command-prompt/cancel', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ session_id: sessionId }),
    })
    .then(r => r.json())
    .then(data => {
        showToast(data.success ? '命令已取消' : (data.error || '取消失败'), data.success ? 'success' : 'error');
        pollPendingCommands();
        if (cmdPromptSessionId === sessionId) {
            closeCmdTerminal();
        }
    })
    .catch(e => showToast('请求失败: ' + e.message, 'error'));
}

// ─── 终端输出 ───

function viewCmdOutput(sessionId, command) {
    cmdPromptSessionId = sessionId;
    const overlay = document.getElementById('cmd-terminal-overlay');
    overlay.classList.remove('hidden');
    document.getElementById('cmd-terminal-title').textContent = command ? '命令: ' + command : '命令执行';
    const output = document.getElementById('cmd-terminal-output');
    output.innerHTML = '';
    document.getElementById('cmd-terminal-status').textContent = '连接中...';
    document.getElementById('cmd-terminal-time').textContent = '';
    document.getElementById('cmd-terminal-cancel-btn').style.display = 'inline-flex';

    // 原生 cmd 风格：先回显 C:\> 提示行 + 闪烁光标
    if (command) {
        const promptLine = document.createElement('div');
        promptLine.className = 'cmd-line cmd-prompt-line';
        promptLine.textContent = 'C:\\> ' + command;
        output.appendChild(promptLine);
    }
    const cursor = document.createElement('span');
    cursor.className = 'cmd-cursor';
    cursor.id = 'cmd-stream-cursor';
    output.appendChild(cursor);
    output.scrollTop = output.scrollHeight;

    // 关闭旧 SSE
    if (cmdPromptEventSource) {
        cmdPromptEventSource.close();
    }

    cmdPromptEventSource = new EventSource('/api/command-prompt/stream/' + sessionId);

    function removeCursor() {
        const c = document.getElementById('cmd-stream-cursor');
        if (c) c.remove();
    }

    cmdPromptEventSource.addEventListener('stdout', function(e) {
        const data = JSON.parse(e.data);
        const line = document.createElement('div');
        line.className = 'cmd-line cmd-stdout';
        line.textContent = data.data;
        output.appendChild(line);
        output.scrollTop = output.scrollHeight;
    });

    cmdPromptEventSource.addEventListener('stderr', function(e) {
        const data = JSON.parse(e.data);
        const line = document.createElement('div');
        line.className = 'cmd-line cmd-stderr';
        line.textContent = data.data;
        output.appendChild(line);
        output.scrollTop = output.scrollHeight;
    });

    cmdPromptEventSource.addEventListener('done', function(e) {
        const data = JSON.parse(e.data);
        const status = data.status;
        const rc = data.returncode;
        const dur = data.duration;
        removeCursor();
        document.getElementById('cmd-terminal-cancel-btn').style.display = 'none';
        let statusText = '已完成';
        if (status === 'completed') statusText = '✅ 完成 (exit ' + rc + ')';
        else if (status === 'failed') statusText = '❌ 失败 (exit ' + rc + ')';
        else if (status === 'timeout') statusText = '⏰ 超时';
        else if (status === 'cancelled') statusText = '⛔ 已取消';
        else statusText = '状态: ' + status;
        document.getElementById('cmd-terminal-status').textContent = statusText;
        document.getElementById('cmd-terminal-time').textContent = '耗时: ' + dur + 's';
        cmdPromptEventSource.close();
        cmdPromptEventSource = null;
        pollPendingCommands();
    });

    cmdPromptEventSource.addEventListener('error', function(e) {
        removeCursor();
        if (e.data) {
            try {
                const data = JSON.parse(e.data);
                const line = document.createElement('div');
                line.className = 'cmd-line cmd-stderr';
                line.textContent = '错误: ' + (data.message || '未知错误');
                output.appendChild(line);
            } catch(_) {}
        }
        document.getElementById('cmd-terminal-status').textContent = '连接断开';
        document.getElementById('cmd-terminal-cancel-btn').style.display = 'none';
    });
}

function closeCmdTerminal() {
    if (cmdPromptEventSource) {
        cmdPromptEventSource.close();
        cmdPromptEventSource = null;
    }
    cmdPromptSessionId = null;
    document.getElementById('cmd-terminal-overlay').classList.add('hidden');
}

function cancelCmdSession() {
    if (cmdPromptSessionId) {
        cancelCmd(cmdPromptSessionId);
    }
}

// ─── 手动输入命令 ───

function sendCmdCommand() {
    const input = document.getElementById('cmd-input');
    const command = input.value.trim();
    if (!command) return;
    input.value = '';

    fetch('/api/command-prompt/request', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ command: command, description: '用户手动输入', requester: 'user' }),
    })
    .then(r => r.json())
    .then(data => {
        if (data.success) {
            if (data.risk_level === 'safe') {
                // 白名单命令，直接执行
                showToast('命令已自动执行', 'success');
                viewCmdOutput(data.session_id, command);
            } else if (data.risk_level === 'forbidden') {
                showToast('命令被禁止执行', 'error');
            } else {
                // 需要确认
                showCmdConfirm(data.session_id);
            }
        } else {
            showToast(data.error || '请求失败', 'error');
        }
    })
    .catch(e => showToast('请求失败: ' + e.message, 'error'));
}

// ============= 技能管理系统 =============
var skillsState = { data: [], filter: 'all', search: '' };

function loadSkillsPage() {
    fetch('/api/skills/stats').then(r => r.json()).then(d => {
        if (d.success) renderSkillsStats(d.data || {});
    }).catch(() => {});
    Promise.all([
        fetch('/api/skills/list').then(r => r.json()),
        fetch('/api/skills/meta').then(r => r.json())
    ]).then(([list, meta]) => {
        if (list.success) {
            skillsState.data = list.data || [];
            renderSkills();
        }
        if (meta && meta.success && meta.consent_required) {
            showSkillConsent();
        }
    }).catch(() => {
        const el = document.getElementById('skills-list');
        if (el) el.innerHTML = '<div class="empty-state">加载失败</div>';
    });
}

function renderSkillsStats(s) {
    const set = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = v; };
    const levels = s.security_levels || {};
    const secure = (levels.A || 0) + (levels.B || 0);
    set('skill-stat-total', s.total || 0);
    set('skill-stat-active', s.active || 0);
    set('skill-stat-secure', secure);
    set('skill-stat-exec', s.total_executions || s.total_exec || 0);
}

function refreshSkills() { loadSkillsPage(); }

function reloadSkills() {
    fetch('/api/skills/reload', { method: 'POST' })
        .then(r => r.json())
        .then(d => { if (d.success) showToast('技能已重载', 'success'); refreshSkills(); })
        .catch(() => showToast('重载技能失败', 'error'));
}

function switchSkillTab(tab) {
    ['installed', 'market', 'security', 'logs'].forEach(t => {
        const c = document.getElementById('skill-tab-' + t);
        if (c) c.classList.toggle('hidden', t !== tab);
        const b = document.getElementById('skill-tab-' + t + '-btn');
        if (b) b.classList.toggle('active', t === tab);
    });
    if (tab === 'security') renderSkillSecurity();
    if (tab === 'logs') refreshSkillLogs();
}

function skillLevelInfo(level) {
    const map = { A: ['#22c55e', '完全安全'], B: ['#3b82f6', '低风险'], C: ['#f59e0b', '中风险'], D: ['#ef4444', '高风险'] };
    const m = map[level] || ['#6b7280', '未评估'];
    return { color: m[0], label: m[1] };
}

function skillLevelBadge(level) {
    const info = skillLevelInfo(level);
    return '<span class="skill-sec-badge" style="background:' + info.color + '" title="安全评级">' + (level || '?') + '</span><span class="skill-sec-label" style="color:' + info.color + '">' + info.label + '</span>';
}

function renderSkills() {
    const el = document.getElementById('skills-list');
    if (!el) return;
    let list = skillsState.data.slice();
    const q = skillsState.search.toLowerCase();
    if (q) list = list.filter(s => (s.name || '').toLowerCase().includes(q) || (s.description || '').toLowerCase().includes(q) || (s.author || '').toLowerCase().includes(q));
    if (skillsState.filter === 'active') list = list.filter(s => s.enabled);
    else if (skillsState.filter === 'inactive') list = list.filter(s => !s.enabled);
    else if (skillsState.filter === 'pending') list = list.filter(s => s.review_status === 'pending');
    const countEl = document.getElementById('skills-count');
    if (countEl) countEl.textContent = list.length + ' 个技能';
    if (!list.length) {
        el.innerHTML = '<div class="empty-state">' + (skillsState.data.length ? '没有匹配的技能' : '暂无已安装技能。可在"技能市场"中检索并安装。') + '</div>';
        return;
    }
    el.innerHTML = list.map(skillCardHtml).join('');
}

function filterSkills() {
    skillsState.search = (document.getElementById('skills-search-input') || {}).value || '';
    renderSkills();
}

function setSkillFilter(f, btn) {
    skillsState.filter = f;
    document.querySelectorAll('.plugins-filter-btn[data-filter]').forEach(b => {
        if (b.closest('#skill-tab-installed')) b.classList.toggle('active', b === btn);
    });
    renderSkills();
}

function skillCardHtml(s) {
    const sec = skillLevelBadge(s.security_level);
    const activeCls = s.enabled ? 'skill-enabled' : 'skill-disabled';
    const reviewBadge = s.review_status === 'pending'
        ? '<span class="skill-review-badge pending">待审核</span>'
        : (s.review_status === 'rejected' ? '<span class="skill-review-badge rejected">已拒绝</span>'
            : (s.review_status === 'whitelisted' ? '<span class="skill-review-badge whitelisted">白名单</span>' : ''));
    const srcLabel = s.installed_from === 'openclaw' ? 'OpenClaw' : (s.installed_from === 'takoapi' ? 'Tako' : '本地');
    const ver = s.version || '1.0.0';
    const res = s.resource || {};
    const perm = (s.permissions && s.permissions.length) ? s.permissions.join(', ') : '无';
    return '<div class="skill-card ' + activeCls + '" data-name="' + (s.name || '').replace(/"/g, '&quot;') + '">'
        + '<div class="skill-card-head">'
        + '<div class="skill-card-icon"><i class="fas fa-wand-magic-sparkles"></i></div>'
        + '<div class="skill-card-titles"><div class="skill-card-name">' + escapeHtml(s.name || '') + ' <span class="skill-ver">v' + escapeHtml(ver) + '</span> ' + reviewBadge + '</div>'
        + '<div class="skill-card-desc">' + escapeHtml(s.description || '暂无描述') + '</div></div>'
        + '<div class="skill-sec-wrap">' + sec + '</div>'
        + '</div>'
        + '<div class="skill-card-meta"><span class="skill-meta-chip"><i class="fas fa-user"></i> ' + escapeHtml(s.author || '未知') + '</span>'
        + '<span class="skill-meta-chip"><i class="fas fa-bookmark"></i> ' + srcLabel + '</span>'
        + (s.tags && s.tags.length ? '<span class="skill-meta-chip"><i class="fas fa-tags"></i> ' + escapeHtml(s.tags.join(', ')) + '</span>' : '')
        + '</div>'
        + '<div class="skill-card-body">'
        + '<div class="skill-card-res"><span><i class="fas fa-play-circle"></i> 调用 ' + (res.exec_count || 0) + ' 次</span>'
        + '<span><i class="fas fa-clock"></i> 平均 ' + (res.avg_exec_time || 0) + 's</span>'
        + '<span><i class="fas fa-weight-hanging"></i> 最大 ' + fmtSize(res.max_result_chars || 0) + '</span></div>'
        + (perm !== '无' ? '<div class="skill-card-perm"><i class="fas fa-shield-alt"></i> 权限: ' + escapeHtml(perm) + '</div>' : '')
        + '</div>'
        + '<div class="skill-card-foot">'
        + '<button class="btn btn-sm ' + (s.enabled ? 'btn-danger' : 'btn-success') + '" onclick="skillSetEnabled(this,' + (s.enabled ? 'false' : 'true') + ')"><i class="fas fa-power-off"></i> ' + (s.enabled ? '禁用' : '启用') + '</button>'
        + '<button class="btn btn-sm" onclick="skillSetPriority(this)"><i class="fas fa-sort-amount-down"></i> 优先级</button>'
        + '<button class="btn btn-sm" onclick="skillEditConfig(this)"><i class="fas fa-sliders-h"></i> 参数</button>'
        + '<button class="btn btn-sm" onclick="skillRescan(this)"><i class="fas fa-bolt"></i> 重扫</button>'
        + '<button class="btn btn-sm" onclick="skillExecuteTest(this)"><i class="fas fa-play"></i> 调用</button>'
        + '<button class="btn btn-sm btn-danger" onclick="skillUninstall(this)"><i class="fas fa-trash"></i></button>'
        + '</div>'
        + '</div>';
}

function fmtSize(n) { return n > 1048576 ? (n / 1048576).toFixed(1) + 'MB' : (n > 1024 ? (n / 1024).toFixed(1) + 'KB' : n + 'B'); }

function skillCardBtn(btn) {
    const card = btn.closest('.skill-card');
    return card ? card.getAttribute('data-name') : '';
}

function skillSetEnabled(btn, val) {
    const name = skillCardBtn(btn);
    if (!name) return;
    const url = '/api/skills/' + encodeURIComponent(name) + (val ? '/enable' : '/disable');
    fetch(url, { method: 'POST' }).then(r => r.json()).then(d => {
        if (d.success) { showToast((val ? '已启用' : '已禁用') + ' ' + name, 'success'); refreshSkills(); }
        else showToast(d.error || '操作失败', 'error');
    }).catch(() => showToast('操作失败', 'error'));
}

function skillSetPriority(btn) {
    const name = skillCardBtn(btn);
    if (!name) return;
    showDialog('设置优先级: ' + escapeHtml(name),
        '<div style="font-size:12px;color:var(--text-muted);margin-bottom:8px;">优先级越高，Agent 越优先调用该技能。当前优先级：</div>'
        + '<input id="skill-priority-input" type="number" placeholder="0" style="width:100%;padding:8px 10px;border:1px solid var(--border-color);border-radius:6px;background:var(--bg-secondary);color:var(--text-primary);font-size:13px;outline:none;">',
        function () {
            const v = document.getElementById('skill-priority-input');
            const val = parseInt(v ? v.value : '0', 10) || 0;
            fetch('/api/skills/' + encodeURIComponent(name) + '/priority', {
                method: 'POST', headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ priority: val })
            }).then(r => r.json()).then(d => {
                if (d.success) { showToast('优先级已设为 ' + d.priority, 'success'); refreshSkills(); }
                else showToast(d.error || '设置失败', 'error');
            }).catch(() => showToast('设置失败', 'error'));
        });
}

function skillEditConfig(btn) {
    const name = skillCardBtn(btn);
    if (!name) return;
    const skill = skillsState.data.find(s => s.name === name);
    const cur = JSON.stringify(skill && skill.config ? skill.config : {}, null, 2);
    showDialog('参数配置: ' + escapeHtml(name),
        '<div style="font-size:12px;color:var(--text-muted);margin-bottom:8px;">以 JSON 格式配置技能参数（会作为技能调用的默认参数）。</div>'
        + '<textarea id="skill-config-input" spellcheck="false" style="width:100%;height:160px;padding:10px;border:1px solid var(--border-color);border-radius:6px;background:var(--bg-secondary);color:var(--text-primary);font-size:12px;font-family:monospace;outline:none;resize:vertical;white-space:pre;">' + escapeHtml(cur) + '</textarea>',
        function () {
            const ta = document.getElementById('skill-config-input');
            let cfg = {};
            try { cfg = JSON.parse(ta ? ta.value : '{}'); } catch (e) { showToast('JSON 格式错误', 'error'); return; }
            fetch('/api/skills/' + encodeURIComponent(name) + '/config', {
                method: 'POST', headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ config: cfg })
            }).then(r => r.json()).then(d => {
                if (d.success) { showToast('参数已保存', 'success'); refreshSkills(); }
                else showToast(d.error || '保存失败', 'error');
            }).catch(() => showToast('保存失败', 'error'));
        });
}

function skillRescan(btn) {
    const name = skillCardBtn(btn);
    if (!name) return;
    fetch('/api/skills/' + encodeURIComponent(name) + '/rescan', { method: 'POST' }).then(r => r.json()).then(d => {
        if (d.success) { const lv = d.security && d.security.level; showToast('已重新扫描，安全评级: ' + (lv || '?'), 'success'); refreshSkills(); }
        else showToast(d.error || '扫描失败', 'error');
    }).catch(() => showToast('扫描失败', 'error'));
}

function skillExecuteTest(btn) {
    const name = skillCardBtn(btn);
    if (!name) return;
    const skill = skillsState.data.find(s => s.name === name);
    const params = (skill && skill.parameters && skill.parameters.length) ? skill.parameters.map(p => p.name + (p.required ? ' (必填)' : '')).join(', ') : '无参数';
    showDialog('调用技能: ' + escapeHtml(name),
        '<div style="font-size:12px;color:var(--text-muted);margin-bottom:8px;">参数: ' + escapeHtml(params) + '<br>以 JSON 传入参数对象，如 {"key":"value"}</div>'
        + '<textarea id="skill-exec-input" spellcheck="false" placeholder="{}" style="width:100%;height:90px;padding:10px;border:1px solid var(--border-color);border-radius:6px;background:var(--bg-secondary);color:var(--text-primary);font-size:12px;font-family:monospace;outline:none;resize:vertical;">{}</textarea>',
        function () {
            let paramsObj = {};
            try { paramsObj = JSON.parse(document.getElementById('skill-exec-input').value || '{}'); } catch (e) { showToast('JSON 格式错误', 'error'); return; }
            fetch('/api/skills/' + encodeURIComponent(name) + '/execute', {
                method: 'POST', headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ params: paramsObj })
            }).then(r => r.json()).then(d => {
                if (d.success) { showToast('已触发调用', 'success'); refreshSkills(); }
                else showToast(d.error || '调用失败', 'error');
            }).catch(() => showToast('调用失败', 'error'));
        });
}

function skillSetReview(btn, status) {
    const name = skillCardBtn(btn);
    if (!name) return;
    fetch('/api/skills/' + encodeURIComponent(name) + '/review', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: status })
    }).then(r => r.json()).then(d => {
        if (d.success) { showToast('审核状态已更新', 'success'); renderSkillSecurity(); }
        else showToast(d.error || '操作失败', 'error');
    }).catch(() => showToast('操作失败', 'error'));
}

function skillToggleWhitelist(btn, val) {
    const name = skillCardBtn(btn);
    if (!name) return;
    fetch('/api/skills/' + encodeURIComponent(name) + '/whitelist', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ whitelist: val, reason: '手动加入白名单' })
    }).then(r => r.json()).then(d => {
        if (d.success) { showToast(val ? '已加入白名单' : '已移出白名单', 'success'); renderSkillSecurity(); }
        else showToast(d.error || '操作失败', 'error');
    }).catch(() => showToast('操作失败', 'error'));
}

function skillUninstall(btn) {
    const name = skillCardBtn(btn);
    if (!name) return;
    showDialog('卸载技能: ' + escapeHtml(name),
        '<div style="font-size:12px;color:var(--text-muted);margin-bottom:8px;">将删除该技能的全部文件与配置，是否继续？</div>',
        function () {
            fetch('/api/skills/' + encodeURIComponent(name) + '/uninstall', { method: 'POST' }).then(r => r.json()).then(d => {
                if (d.success) { showToast('已卸载', 'success'); refreshSkills(); }
                else showToast(d.error || '卸载失败', 'error');
            }).catch(() => showToast('卸载失败', 'error'));
        });
}

// ---- 首用安全风险提示 ----
function showSkillConsent() {
    const ov = document.getElementById('skill-consent-overlay');
    if (ov) ov.classList.remove('hidden');
}
function closeSkillConsent(action) {
    const ov = document.getElementById('skill-consent-overlay');
    if (ov) ov.classList.add('hidden');
    if (action === 'confirm') {
        fetch('/api/skills/community/consent', {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ confirm: true })
        }).then(() => showToast('已确认安全风险提示', 'success')).catch(() => {});
    }
}

// ---- 社区（openclawskills）技能 ----
function searchCommunitySkills() {
    const q = (document.getElementById('skill-market-search') || {}).value || '';
    const source = (document.getElementById('skill-community-source') || { value: 'openclaw' }).value;
    const list = document.getElementById('skill-market-list');
    if (!list) return;
    list.innerHTML = '<div class="empty-state"><i class="fas fa-spinner fa-spin"></i> 正在检索社区技能...</div>';
    fetch('/api/skills/community/search?source=' + encodeURIComponent(source) + '&q=' + encodeURIComponent(q))
        .then(r => r.json())
        .then(d => {
            if (d.consent_required) {
                showSkillConsent();
                list.innerHTML = '<div class="empty-state">首次使用社区技能前，请先阅读并确认安全风险提示。</div>';
                return;
            }
            if (!d.success || !d.data || !d.data.length) {
                list.innerHTML = '<div class="empty-state">未检索到技能，可尝试更换关键词或市场源。</div>';
                return;
            }
            list.innerHTML = d.data.map(s => {
                return '<div class="skill-card"><div class="skill-card-head">'
                    + '<div class="skill-card-icon"><i class="fas fa-cloud-download-alt"></i></div>'
                    + '<div class="skill-card-titles"><div class="skill-card-name">' + escapeHtml(s.name || '') + ' <span class="skill-ver">v' + escapeHtml(s.version || '') + '</span>' + (s.source === 'takoapi' ? ' <span class="skill-review-badge whitelisted">Tako</span>' : '') + '</div>'
                    + '<div class="skill-card-desc">' + escapeHtml(s.description || '暂无描述') + '</div></div></div>'
                    + '<div class="skill-card-meta">'
                    + '<span class="skill-meta-chip"><i class="fas fa-user"></i> ' + escapeHtml(s.author || 'unknown') + '</span>'
                    + '<span class="skill-meta-chip"><i class="fas fa-download"></i> ' + (s.downloads || 0) + ' 下载</span>'
                    + '<span class="skill-meta-chip"><i class="fas fa-star"></i> ' + (s.rating || 0) + '</span>'
                    + '<span class="skill-meta-chip"><i class="fas fa-folder"></i> ' + escapeHtml(s.category || '未分类') + '</span></div>'
                    + '<div class="skill-card-foot">'
                    + '<button class="btn btn-sm" data-preview="' + (s.id || '').replace(/"/g, '&quot;') + '" data-src="' + (s.source || source) + '" data-name="' + (s.name || '').replace(/"/g, '&quot;') + '" onclick="previewCommunitySkill(this)"><i class="fas fa-eye"></i> 预览</button>'
                    + '<button class="btn btn-sm btn-primary" data-install="' + (s.id || '').replace(/"/g, '&quot;') + '" data-src="' + (s.source || source) + '" data-name="' + (s.name || '').replace(/"/g, '&quot;') + '" onclick="installCommunitySkill(this)"><i class="fas fa-download"></i> 安装</button>'
                    + '</div></div>';
            }).join('');
        })
        .catch(() => list.innerHTML = '<div class="empty-state">检索失败，请检查网络或稍后再试。</div>');
}

function previewCommunitySkill(btn) {
    const id = btn.getAttribute('data-preview'), src = btn.getAttribute('data-src'), name = btn.getAttribute('data-name');
    fetch('/api/skills/community/preview?source=' + encodeURIComponent(src) + '&skill_id=' + encodeURIComponent(id))
        .then(r => r.json()).then(d => {
            if (!d.success) { showToast(d.message || '预览失败', 'error'); return; }
            const meta = d.data;
            showDialog('技能预览: ' + escapeHtml(meta.name),
                '<div style="font-size:12px;color:var(--text-muted);margin-bottom:8px;">'
                + '版本: ' + escapeHtml(meta.version || '') + ' · 作者: ' + escapeHtml(meta.author || '') + ' · ' + meta.size + ' 字节</div>'
                + '<div style="font-size:13px;margin-bottom:8px;">' + escapeHtml(meta.description || '') + '</div>'
                + '<pre style="max-height:300px;overflow:auto;background:var(--bg-tertiary);padding:12px;border-radius:8px;font-size:12px;line-height:1.5;white-space:pre-wrap;word-break:break-all;margin:0;">' + escapeHtml(meta.body_preview || '') + '</pre>');
        })
        .catch(() => showToast('预览失败', 'error'));
}

function installCommunitySkill(btn) {
    const id = btn.getAttribute('data-install'), src = btn.getAttribute('data-src'), name = btn.getAttribute('data-name');
    fetch('/api/skills/community/install', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ source: src, skill_id: id })
    }).then(r => r.json()).then(d => {
        if (!d.success) {
            if (d.code === 'CONSENT_REQUIRED') { showSkillConsent(); return; }
            showToast(d.message || d.error || '安装失败', 'error'); return;
        }
        showToast('技能 ' + (d.name || name) + ' 安装成功，已自动扫描评级 ' + (d.security ? d.security.level : '?'), 'success');
        refreshSkills();
    }).catch(() => showToast('安装失败', 'error'));
}

// ---- 安全管理视图 ----
function renderSkillSecurity() {
    const el = document.getElementById('skill-security-content');
    if (!el) return;
    el.innerHTML = '<div class="empty-state"><i class="fas fa-spinner fa-spin"></i> 加载中...</div>';
    fetch('/api/skills/list').then(r => r.json()).then(d => {
        if (!d.success || !d.data) { el.innerHTML = '<div class="empty-state">暂无数据</div>'; return; }
        el.innerHTML = d.data.map(s => {
            const sec = s.security || {};
            const findings = sec.findings || [];
            const nm = s.name || '';
            const reviewSel = '<select class="skills-select" style="width:auto;padding:4px 6px;" onchange="skillSetReview(this,' + "'" + nm + "'" + ')">'
                + ['approved', 'rejected', 'pending', 'whitelisted'].map(st =>
                    '<option value="' + st + '"' + (s.review_status === st ? ' selected' : '') + '>' + st + '</option>').join('')
                + '</select>';
            return '<div class="skill-card" data-name="' + nm.replace(/"/g, '&quot;') + '">'
                + '<div class="skill-card-head"><div class="skill-card-icon"><i class="fas fa-shield-alt"></i></div>'
                + '<div class="skill-card-titles"><div class="skill-card-name">' + escapeHtml(nm) + '</div>'
                + '<div class="skill-card-desc">安全评级: ' + skillLevelBadge(s.security_level) + ' · 分: ' + (sec.score || 0) + ' · 扫描文件: ' + ((sec.scanned_files || []).length) + '</div></div></div>'
                + '<div class="skill-card-body"><div class="skill-card-frame">权限: ' + escapeHtml((s.permissions && s.permissions.length ? s.permissions.join(', ') : '无')) + '</div>'
                + (findings.length ? '<div class="skill-findings">' + findings.slice(0, 8).map(f =>
                    '<div class="skill-finding"><span class="skill-finding-icon ' + (f.severity === 'critical' ? 'crit' : (f.severity === 'high' ? 'high' : 'low')) + '"></span>'
                    + '[' + escapeHtml(f.code || '?') + '] ' + escapeHtml(f.message || '') + (f.node ? ' <code>' + escapeHtml(f.node) + '</code>' : '') + ' <em>' + escapeHtml(f.file || '') + '</em></div>').join('')
                    : '<div class="skill-finding-none"><i class="fas fa-check-circle"></i> 未发现风险项</div>') + '</div>'
                + '<div class="skill-card-foot"><span style="font-size:12px;color:var(--text-muted);">审核: </span>' + reviewSel
                + '<button class="btn btn-sm" onclick="skillRescan(this)"><i class="fas fa-bolt"></i> 重新扫描</button>'
                + '<button class="btn btn-sm ' + (s.review_status === 'whitelisted' ? 'btn-danger' : '') + '" onclick="skillToggleWhitelist(this,' + (s.review_status === 'whitelisted' ? 'false' : 'true') + ')"><i class="fas fa-shield-halved"></i> ' + (s.review_status === 'whitelisted' ? '移出白名单' : '加入白名单') + '</button>'
                + '</div></div>';
        }).join('');
    }).catch(() => el.innerHTML = '<div class="empty-state">加载失败</div>');
}

// ---- 技能日志 ----
function refreshSkillLogs() {
    const el = document.getElementById('skill-logs');
    if (!el) return;
    el.innerHTML = '<div class="empty-state"><i class="fas fa-spinner fa-spin"></i> 加载中...</div>';
    fetch('/api/skills/logs?limit=300').then(r => r.json()).then(d => {
        if (!d.success || !d.data || !d.data.length) { el.innerHTML = '<div class="empty-state">暂无日志</div>'; return; }
        const evColor = { install: '#22c55e', update: '#2F7FD6', use: '#3FA9F5', uninstall: '#ef4444', enable: '#22c55e', disable: '#6b7280', priority: '#f59e0b', config: '#0ea5e9', security_scan: '#14b8a6', whitelist: '#06b6d4', review: '#e11d48', approval_required: '#f43f5e' };
        el.innerHTML = d.data.slice().reverse().map(r => {
            const c = evColor[r.event] || '#6b7280';
            const dataStr = r.data ? ' <span class="skill-log-data">' + escapeHtml(typeof r.data === 'string' ? r.data : JSON.stringify(r.data)) + '</span>' : '';
            const ts = r.ts || '';
            return '<div class="skill-log-row"><span class="skill-log-time">' + escapeHtml(ts) + '</span>'
                + '<span class="skill-log-badge" style="background:' + c + '">' + escapeHtml(r.event || '') + '</span>'
                + '<span class="skill-log-name">' + escapeHtml(r.skill || '') + '</span>'
                + dataStr + '</div>';
        }).join('');
    }).catch(() => el.innerHTML = '<div class="empty-state">加载失败</div>');
}

// ============= 代码操作面板（文件预览区） =============
var codeOpState = { path: '', filename: '' };

function chatOperationToggle() {
    const panel = document.getElementById('code-operation-panel');
    const btn = document.getElementById('chat-filetree-codepane-btn');
    if (!panel) return;
    const showing = panel.style.display !== 'none';
    panel.style.display = showing ? 'none' : 'flex';
    if (btn) btn.style.color = showing ? '' : 'var(--primary-color)';
}

function chatOperationOpenFile(path) {
    if (!path) return;
    const panel = document.getElementById('code-operation-panel');
    if (panel) panel.style.display = 'flex';
    const body = document.getElementById('code-op-body');
    const nameEl = document.getElementById('code-op-filename');
    const copyBar = document.getElementById('code-op-copy-bar');
    const pathInput = document.getElementById('code-op-path-input');
    if (nameEl) nameEl.textContent = path.split('/').pop() || path.split('\\').pop() || path;
    if (pathInput) pathInput.value = path;
    if (copyBar) copyBar.style.display = 'flex';
    codeOpState.path = path;
    const isImg = /\.(png|jpe?g|gif|webp|svg|bmp|ico)$/i.test(path);
    const editorBtn = document.getElementById('code-op-open-editor-btn');
    // 文本/二进制均可打开编辑器，图片也可（编辑器用 base64）；但二进制图片直接预览
    if (editorBtn) editorBtn.style.display = 'inline-flex';
    if (body) body.innerHTML = '<div class="code-op-loading"><i class="fas fa-spinner fa-spin"></i> 读取中...</div>';
    fetch('/api/editor/files/read?project=' + encodeURIComponent(chatFileTreeProject || '') + '&path=' + encodeURIComponent(path))
        .then(r => r.json())
        .then(d => {
            if (!d.success) {
                if (body) body.innerHTML = '<div class="code-op-error"><i class="fas fa-exclamation-circle"></i> 读取失败: ' + escapeHtml(d.error || '') + '</div>';
                return;
            }
            const data = d.data || {};
            if (data.encoding === 'base64' || isImg) {
                const b64 = data.encoding === 'base64' && data.content ? data.content : '';
                if (isImg) {
                    const ext = (path.split('.').pop() || 'png').toLowerCase();
                    const mime = ext === 'svg' ? 'svg+xml' : ext;
                    if (b64) {
                        chatOperationRenderImage('data:image/' + mime + ';base64,' + b64, path);
                    } else {
                        // 尝试原始字节接口（如有）
                        chatOperationRenderImage('/api/editor/files/raw?project=' + encodeURIComponent(chatFileTreeProject || '') + '&path=' + encodeURIComponent(path), path, true);
                    }
                } else {
                    if (body) body.innerHTML = '<div class="code-op-error"><i class="fas fa-file"></i> 二进制文件，无法直接预览文本内容。</div>';
                }
            } else {
                chatOperationRenderText(data.content || '', path, data.language || '');
            }
        })
        .catch(() => {
            if (body) body.innerHTML = '<div class="code-op-error"><i class="fas fa-exclamation-circle"></i> 读取文件失败。</div>';
        });
}

function chatOperationRenderImage(src, path, isUrl) {
    const body = document.getElementById('code-op-body');
    if (!body) return;
    body.innerHTML = '<div class="code-op-image-wrap"><img src="' + src + '" alt="' + escapeHtml(path) + '" class="code-op-image" onerror="this.parentElement.innerHTML=\'<div class=code-op-error><i class=fas fa-exclamation-circle></i> 图片加载失败</div>\';"></div>';
}

function chatOperationRenderText(text, path, lang) {
    const body = document.getElementById('code-op-body');
    if (!body) return;
    const size = text.length;
    const preview = size > 200000 ? text.substring(0, 200000) + '\n... (内容过长已截断)' : text;
    body.innerHTML = '<div class="code-op-info">' + escapeHtml(path || '') + ' · ' + size + ' 字符' + (lang ? ' · ' + escapeHtml(lang) : '') + '</div>'
        + '<pre class="code-op-code"><code>' + escapeHtml(preview) + '</code></pre>';
}

function chatOperationOpenInEditor() {
    if (!codeOpState.path) return;
    openFileInEditor(chatFileTreeProject, codeOpState.path);
}

function chatOperationCopyPath() {
    const inp = document.getElementById('code-op-path-input');
    if (!inp || !inp.value) return;
    chatFileTreeFallbackCopy(inp.value);
}

function showToast(message, type) {
    type = type || 'success';
    const toast = document.createElement('div');
    toast.className = 'toast toast-' + type;
    toast.innerHTML = message;
    document.body.appendChild(toast);
    setTimeout(() => { toast.classList.add('show'); }, 10);
    setTimeout(() => {
        toast.classList.remove('show');
        setTimeout(() => toast.remove(), 300);
    }, 3000);
}

