function showTtsHelp(helpKey) {
    const data = ttsHelpData[helpKey];
    if (!data) return;
    
    const popup = document.getElementById('tts-help-popup');
    const title = document.getElementById('tts-help-title');
    const body = document.getElementById('tts-help-body');
    
    title.textContent = data.title + ' 设置说明';
    body.innerHTML = `<div class="tts-help-item">
        <div class="tts-help-item-title">${data.title}</div>
        <div class="tts-help-item-desc">${data.desc}</div>
    </div>`;
    
    popup.classList.add('active');
}

function closeTtsHelp(event) {
    if (event && event.target !== event.currentTarget) return;
    const popup = document.getElementById('tts-help-popup');
    popup.classList.remove('active');
}

// 绑定 TTS 帮助图标点击事件
document.addEventListener('DOMContentLoaded', function() {
    document.querySelectorAll('.tts-help-icon').forEach(function(icon) {
        icon.addEventListener('click', function(e) {
            e.stopPropagation();
            const helpKey = this.getAttribute('data-help');
            showTtsHelp(helpKey);
        });
    });
    
    // ESC 键关闭帮助弹窗
    document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape') {
            closeTtsHelp();
        }
    });
});

// ============= 项目群聊管理 =============

let _currentProjectId = 'default';

function loadProjectSwitcher() {
    fetch('/api/projects/list')
        .then(r => r.json())
        .then(data => {
            if (!data.success || !data.data) return;
            const sel = document.getElementById('project-select');
            if (!sel) return;
            sel.innerHTML = '';
            data.data.forEach(p => {
                const opt = document.createElement('option');
                opt.value = p.project_id;
                opt.textContent = p.name;
                if (p.is_current) {
                    opt.selected = true;
                    _currentProjectId = p.project_id;
                }
                sel.appendChild(opt);
            });
        })
        .catch(() => {});
}

function onProjectChange(projectId) {
    if (projectId === _currentProjectId) return;
    _currentProjectId = projectId;
    fetch('/api/projects/switch/' + projectId, { method: 'POST' })
        .then(r => r.json())
        .then(data => {
            if (data.success && data.data) {
                // 清空聊天并加载新项目的历史
                const container = document.getElementById('chat-messages');
                container.innerHTML = '';
                if (data.data.history && data.data.history.length > 0) {
                    data.data.history.forEach(msg => {
                        if (msg.role === 'user' || msg.role === 'assistant') {
                            addMessage(msg);
                        }
                    });
                } else {
                    // 添加默认欢迎消息
                    const welcome = document.createElement('div');
                    welcome.className = 'message system';
                    welcome.innerHTML = '<div class="message-avatar"><div class="avatar-fallback">🎯</div></div><div class="message-body"><div class="message-content"><span>已切换到项目: ' + data.data.project.name + '</span></div></div>';
                    container.appendChild(welcome);
                }
                showToast('已切换到: ' + data.data.project.name);
                loadProjectSwitcher();
            }
        })
        .catch(() => showToast('切换项目失败', 'error'));
}

function refreshProjectList() {
    const list = document.getElementById('project-list');
    if (!list) return;
    list.innerHTML = '<div class="empty-state">加载中...</div>';

    fetch('/api/projects/list')
        .then(r => r.json())
        .then(data => {
            if (!data.success || !data.data || data.data.length === 0) {
                list.innerHTML = '<div class="empty-state">暂无项目</div>';
                return;
            }
            list.innerHTML = '';
            data.data.forEach(p => {
                const card = document.createElement('div');
                card.className = 'project-card' + (p.is_current ? ' active' : '');
                const memberHtml = (p.agents || []).map(a => '<span class="project-card-member">' + a + '</span>').join('');
                card.innerHTML = `
                    <div class="project-card-header">
                        <span class="project-card-name">${escapeHtml(p.name)}</span>
                        ${p.is_current ? '<span class="project-card-badge">当前</span>' : ''}
                    </div>
                    ${p.description ? '<div class="project-card-desc">' + escapeHtml(p.description) + '</div>' : ''}
                    <div class="project-card-members">${memberHtml}</div>
                    <div class="project-card-actions">
                        ${p.project_id !== 'default' ? '<button class="btn btn-sm btn-danger" onclick="deleteProject(\'' + p.project_id + '\')"><i class="fas fa-trash"></i> 删除</button>' : ''}
                        ${!p.is_current ? '<button class="btn btn-sm" onclick="switchProjectDirect(\'' + p.project_id + '\')">切换到此项目</button>' : ''}
                    </div>
                `;
                list.appendChild(card);
            });
        })
        .catch(() => list.innerHTML = '<div class="empty-state">加载失败</div>');
}

function switchProjectDirect(projectId) {
    fetch('/api/projects/switch/' + projectId, { method: 'POST' })
        .then(r => r.json())
        .then(data => {
            if (data.success) {
                showToast('已切换到项目');
                onProjectChange(projectId);
                refreshProjectList();
            }
        })
        .catch(() => showToast('切换失败', 'error'));
}

function showCreateProjectDialog() {
    showDialog('新建项目', `
        <div class="form-group">
            <label>项目名称</label>
            <input type="text" id="dialog-project-name" placeholder="输入项目名称" value="新项目">
        </div>
        <div class="form-group">
            <label>项目描述</label>
            <textarea id="dialog-project-desc" placeholder="项目描述（可选）"></textarea>
        </div>
    `, () => {
        const name = document.getElementById('dialog-project-name').value.trim();
        const desc = document.getElementById('dialog-project-desc').value.trim();
        if (!name) { showToast('请输入项目名称', 'error'); return; }
        fetch('/api/projects/create', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ name, description: desc }),
        })
        .then(r => r.json())
        .then(data => {
            if (data.success) {
                showToast('项目创建成功');
                refreshProjectList();
                loadProjectSwitcher();
                closeDialog();
            } else {
                showToast('创建失败: ' + (data.message || ''), 'error');
            }
        })
        .catch(() => showToast('创建失败', 'error'));
    });
}

function deleteProject(projectId) {
    if (!confirm('确定要删除此项目吗？')) return;
    fetch('/api/projects/' + projectId, { method: 'DELETE' })
        .then(r => r.json())
        .then(data => {
            if (data.success) {
                showToast('项目已删除');
                refreshProjectList();
                loadProjectSwitcher();
            } else {
                showToast('删除失败: ' + (data.message || ''), 'error');
            }
        })
        .catch(() => showToast('删除失败', 'error'));
}

// ============= Agent 管理 =============

function refreshAgentList() {
    const list = document.getElementById('agent-list');
    if (!list) return;
    list.innerHTML = '<div class="empty-state">加载中...</div>';

    fetch('/api/agents/list')
        .then(r => r.json())
        .then(data => {
            if (!data.success || !data.data || data.data.length === 0) {
                list.innerHTML = '<div class="empty-state">暂无 Agent</div>';
                return;
            }
            list.innerHTML = '';
            data.data.forEach(a => {
                const card = document.createElement('div');
                card.className = 'agent-card';
                const roleClass = a.role === 'coordinator' ? 'coordinator' : 'worker';
                const roleLabel = a.role === 'coordinator' ? '🎯 项目经理' : '🔧 Worker';
                const promptPreview = a.system_prompt ? a.system_prompt.substring(0, 120) + (a.system_prompt.length > 120 ? '...' : '') : '（无系统提示词）';
                const modelTag = (a.model || a.provider)
                    ? `<span class="agent-card-model" title="模型">${escapeHtml(a.model || a.provider)}</span>`
                    : '';
                const enabledBadge = a.enabled === false
                    ? '<span class="agent-card-badge disabled">已禁用</span>'
                    : '<span class="agent-card-badge enabled">已启用</span>';
                card.innerHTML = `
                    <div class="agent-card-header">
                        <div class="agent-card-avatar">${a.avatar || '🤖'}</div>
                        <div>
                            <div style="display:flex;align-items:center;gap:8px;font-weight:600;font-size:15px;color:var(--text-primary);">${escapeHtml(a.name)} ${enabledBadge}</div>
                            <div><span class="agent-card-role ${roleClass}">${roleLabel}</span> ${modelTag}</div>
                        </div>
                    </div>
                    <div class="agent-card-body">${escapeHtml(promptPreview)}</div>
                    <div class="agent-card-footer">
                        <button class="btn btn-sm" onclick="showEditAgentDialog('${a.agent_id}')"><i class="fas fa-edit"></i> 编辑</button>
                        ${a.role !== 'coordinator' ? '<button class="btn btn-sm btn-danger" onclick="deleteAgent(\'' + a.agent_id + '\')"><i class="fas fa-trash"></i> 删除</button>' : ''}
                    </div>
                `;
                list.appendChild(card);
            });
        })
        .catch(() => list.innerHTML = '<div class="empty-state">加载失败</div>');
}

function agentProviderOptions(selected) {
    const presets = _llmPresets || {};
    let opts = '<option value="">-- 跟随全局默认 --</option>';
    const known = {
        deepseek: 'DeepSeek（官方）', openai: 'OpenAI', zhipu: '智谱 GLM',
        qwen: 'Qwen 千问', moonshot: 'Moonshot (Kimi)', doubao: '字节豆包',
        minimax: 'MiniMax', hunyuan: '腾讯混元', ernie: '百度文心', spark: '讯飞星火',
        siliconflow: 'SiliconFlow', together: 'Together AI', gemini: 'Google Gemini',
        anthropic: 'Anthropic Claude', xai: 'xAI Grok', mistral: 'Mistral AI',
        groq: 'Groq', openrouter: 'OpenRouter',
    };
    const keys = Object.keys(presets).length ? Object.keys(presets) : Object.keys(known);
    keys.forEach(k => {
        const label = presets[k] && presets[k].name ? presets[k].name : (known[k] || k);
        opts += `<option value="${k}" ${k === selected ? 'selected' : ''}>${escapeHtml(label)}</option>`;
    });
    return opts;
}

function agentModelOptions(provider, selected) {
    if (!provider) return '';
    const preset = _llmPresets && _llmPresets[provider];
    if (preset && Array.isArray(preset.models) && preset.models.length) {
        const deprecated = preset.deprecated_models || [];
        let opts = '<option value="">-- 跟随提供商默认 --</option>';
        preset.models.forEach(m => { opts += `<option value="${escapeHtml(m)}" ${m === selected ? 'selected' : ''}>${escapeHtml(m)}</option>`; });
        // 已弃用模型名仅作旧配置兼容，排在最后并明确标注，避免误选
        deprecated.forEach(m => { opts += `<option value="${escapeHtml(m)}" ${m === selected ? 'selected' : ''}>${escapeHtml(m)}（已弃用）</option>`; });
        return opts;
    }
    return '';
}

function onAgentProviderChange() {
    const sel = document.getElementById('dialog-agent-model');
    const prov = document.getElementById('dialog-agent-provider');
    if (!sel || !prov) return;
    sel.innerHTML = agentModelOptions(prov.value, undefined) || '<option value="">-- 跟随提供商默认 --</option>';
}

function showCreateAgentDialog() {
    showDialog('新建 Agent', `
        <div class="form-group">
            <label>名称</label>
            <input type="text" id="dialog-agent-name" placeholder="Agent 名称">
        </div>
        <div class="form-group">
            <label>头像（emoji）</label>
            <input type="text" id="dialog-agent-avatar" placeholder="🤖" value="🤖">
        </div>
        <div class="form-group">
            <label>角色</label>
            <select id="dialog-agent-role">
                <option value="worker">Worker (执行者)</option>
                <option value="observer">Observer (观察者)</option>
            </select>
        </div>
        <div class="form-group">
            <label>系统提示词</label>
            <textarea id="dialog-agent-prompt" placeholder="描述这个 Agent 的角色定位和能力..."></textarea>
        </div>
        <div class="agent-dlg-grid">
            <div class="form-group">
                <label>提供商</label>
                <select id="dialog-agent-provider" onchange="onAgentProviderChange('new')">${agentProviderOptions('')}</select>
            </div>
            <div class="form-group">
                <label>模型</label>
                <select id="dialog-agent-model"><option value="">-- 跟随提供商默认 --</option></select>
            </div>
        </div>
        <div class="agent-dlg-grid">
            <div class="form-group">
                <label>temperature (0.1-2.0)</label>
                <input type="number" id="dialog-agent-temp" step="0.1" min="0.1" max="2.0" value="0.7">
            </div>
            <div class="form-group">
                <label>max_tokens</label>
                <input type="number" id="dialog-agent-maxtokens" step="128" min="128" value="2048">
            </div>
        </div>
    `, () => {
        const name = document.getElementById('dialog-agent-name').value.trim();
        if (!name) { showToast('请输入名称', 'error'); return; }
        fetch('/api/agents/create', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                name,
                avatar: document.getElementById('dialog-agent-avatar').value.trim() || '🤖',
                role: document.getElementById('dialog-agent-role').value,
                system_prompt: document.getElementById('dialog-agent-prompt').value.trim(),
                provider: document.getElementById('dialog-agent-provider').value,
                model: document.getElementById('dialog-agent-model').value,
                temperature: parseFloat(document.getElementById('dialog-agent-temp').value) || 0.7,
                max_tokens: parseInt(document.getElementById('dialog-agent-maxtokens').value, 10) || 2048,
            }),
        })
        .then(r => r.json())
        .then(data => {
            if (data.success) {
                showToast('Agent 创建成功');
                refreshAgentList();
                closeDialog();
            } else {
                showToast('创建失败: ' + (data.message || ''), 'error');
            }
        })
        .catch(() => showToast('创建失败', 'error'));
    });
}

function showEditAgentDialog(agentId) {
    fetch('/api/agents/' + agentId)
        .then(r => r.json())
        .then(data => {
            if (!data.success || !data.data) {
                showToast('获取 Agent 信息失败', 'error');
                return;
            }
            const a = data.data;
            const isCoordinator = a.role === 'coordinator';
            showDialog('编辑 Agent: ' + a.name, `
                <div class="agent-dlg-grid">
                    <div class="form-group">
                        <label>名称</label>
                        <input type="text" id="dialog-agent-name" value="${escapeHtml(a.name)}">
                    </div>
                    <div class="form-group">
                        <label>头像（emoji）</label>
                        <input type="text" id="dialog-agent-avatar" value="${a.avatar || '🤖'}">
                    </div>
                </div>
                <div class="form-group">
                    <label>系统提示词</label>
                    <textarea id="dialog-agent-prompt" rows="4">${escapeHtml(a.system_prompt || '')}</textarea>
                </div>
                ${isCoordinator ? '' : `
                <div class="agent-dlg-grid">
                    <div class="form-group">
                        <label>提供商</label>
                        <select id="dialog-agent-provider" onchange="onAgentProviderChange('edit')">${agentProviderOptions(a.provider)}</select>
                    </div>
                    <div class="form-group">
                        <label>模型</label>
                        <select id="dialog-agent-model">${agentModelOptions(a.provider, a.model) || '<option value="">' + escapeHtml(a.model || '-- 跟随提供商默认 --') + '</option>'}</select>
                    </div>
                </div>
                <details class="agent-dlg-adv">
                    <summary><i class="fas fa-sliders-h"></i> 高级设置（API / 温度 / Token）</summary>
                    <div class="agent-dlg-adv-body">
                        <div class="agent-dlg-grid">
                            <div class="form-group">
                                <label>API Key</label>
                                <input type="password" id="dialog-agent-apikey" value="${escapeHtml(a.api_key || '')}" placeholder="留空则使用全局密钥">
                            </div>
                            <div class="form-group">
                                <label>API URL</label>
                                <input type="text" id="dialog-agent-apiurl" value="${escapeHtml(a.api_url || '')}" placeholder="留空则使用提供商默认地址">
                            </div>
                        </div>
                        <div class="agent-dlg-grid">
                            <div class="form-group">
                                <label>temperature (0.1-2.0)</label>
                                <input type="number" id="dialog-agent-temp" step="0.1" min="0.1" max="2.0" value="${a.temperature || 0.7}">
                            </div>
                            <div class="form-group">
                                <label>max_tokens</label>
                                <input type="number" id="dialog-agent-maxtokens" step="128" min="128" value="${a.max_tokens || 2048}">
                            </div>
                        </div>
                        <div class="form-group">
                            <label>启用状态</label>
                            <label class="toggle-row">
                                <input type="checkbox" id="dialog-agent-enabled" ${a.enabled === false ? '' : 'checked'}>
                                <span>启用此 Agent（禁用后不参与协作）</span>
                            </label>
                        </div>
                    </div>
                </details>`
                }
            `, () => {
                const name = document.getElementById('dialog-agent-name').value.trim();
                if (!name) { showToast('请输入名称', 'error'); return; }
                const payload = {
                    name,
                    avatar: document.getElementById('dialog-agent-avatar').value.trim() || '🤖',
                    system_prompt: document.getElementById('dialog-agent-prompt').value.trim(),
                };
                if (!isCoordinator) {
                    payload.provider = document.getElementById('dialog-agent-provider').value;
                    payload.model = document.getElementById('dialog-agent-model').value;
                    payload.temperature = parseFloat(document.getElementById('dialog-agent-temp').value) || 0.7;
                    if (document.getElementById('dialog-agent-maxtokens')) payload.max_tokens = parseInt(document.getElementById('dialog-agent-maxtokens').value, 10) || 2048;
                    if (document.getElementById('dialog-agent-apikey')) payload.api_key = document.getElementById('dialog-agent-apikey').value;
                    if (document.getElementById('dialog-agent-apiurl')) payload.api_url = document.getElementById('dialog-agent-apiurl').value;
                    if (document.getElementById('dialog-agent-enabled')) payload.enabled = document.getElementById('dialog-agent-enabled').checked;
                }
                fetch('/api/agents/' + agentId, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(payload),
                })
                .then(r => r.json())
                .then(data => {
                    if (data.success) {
                        showToast('Agent 更新成功');
                        refreshAgentList();
                        closeDialog();
                    } else {
                        showToast('更新失败: ' + (data.message || ''), 'error');
                    }
                })
                .catch(() => showToast('更新失败', 'error'));
            });
        })
        .catch(() => showToast('获取 Agent 信息失败', 'error'));
}

function deleteAgent(agentId) {
    if (!confirm('确定要删除此 Agent 吗？')) return;
    fetch('/api/agents/' + agentId, { method: 'DELETE' })
        .then(r => r.json())
        .then(data => {
            if (data.success) {
                showToast('Agent 已删除');
                refreshAgentList();
            } else {
                showToast('删除失败: ' + (data.message || ''), 'error');
            }
        })
        .catch(() => showToast('删除失败', 'error'));
}

// ============= 通用对话框 =============

let _dialogCallback = null;

function showDialog(title, bodyHtml, onConfirm) {
    document.getElementById('dialog-title').textContent = title;
    document.getElementById('dialog-body').innerHTML = bodyHtml;
    document.getElementById('dialog-overlay').classList.add('active');
    _dialogCallback = onConfirm || null;
    const confirmBtn = document.getElementById('dialog-confirm-btn');
    if (onConfirm) {
        confirmBtn.style.display = 'inline-block';
    } else {
        confirmBtn.style.display = 'none';
    }
    // 恢复默认按钮区（本地目录选择器会临时隐藏它）
    const actions = document.getElementById('dialog-actions');
    if (actions) actions.style.display = '';
}

function closeDialog(event) {
    if (event && event.target !== event.currentTarget) return;
    document.getElementById('dialog-overlay').classList.remove('active');
    _dialogCallback = null;
}

function dialogConfirm() {
    if (_dialogCallback) {
        _dialogCallback();
    }
}

// ============= 增强消息显示（支持 Agent 标识） =============

// 保存原版的 addMessage 引用
const _originalAddMessage = addMessage;

// 重写 addMessage 以支持 agent_id 参数
function addMessage(message) {
    const container = document.getElementById('chat-messages');
    if (!container) return null;
    if (!message) {
        console.warn('addMessage: 消息对象为空');
        return null;
    }
    // 历史里的工具调用：重建一张工具卡片（和在线时的样式一致）
    if (message.role === 'tool_call') {
        if (message.name && _SOURCE_TOOL_RE.test(message.name)) {
            _mergeSources(_pendingSources, _extractSourceUrls(message.output || ''));
        }
        const wrap = document.createElement('div');
        wrap.className = 'message-tool-call';
        let card = null;
        try {
            card = _createToolCard(message.name || '', message.args || {}, false);
            _updateToolCardResult(card, message.name || '', message.output || '', true, message);
        } catch (e) {
            card = document.createElement('div');
            card.className = 'dsh-tool-row';
            card.textContent = (message.name || '工具') + ' 调用记录';
        }
        wrap.appendChild(card);
        const host = document.getElementById('chat-messages');
        if (host) host.appendChild(wrap);
        return wrap;
    }

    const messageDiv = document.createElement('div');
    messageDiv.className = 'message ' + (message.role || 'user');
    messageDiv.dataset.timestamp = message.time || new Date().toISOString();
    messageDiv.dataset.msgId = 'msg-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8);
    
    const isUser = message.role === 'user';
    const isAgent = message.agent_id && message.agent_id !== 'user';
    
    // 确定头像、名称和标识
    let avatarUrl, avatarEmoji, roleLabel, roleBadge;
    
    if (isUser) {
        avatarUrl = '/static/assets/user_avatar.png';
        avatarEmoji = '🧑';
        roleLabel = '你';
        roleBadge = '';
    } else if (isAgent) {
        avatarUrl = '';
        avatarEmoji = message.agent_avatar || '🤖';
        roleLabel = '<span class="agent-label">' + (message.agent_avatar || '') + ' ' + escapeHtml(message.agent_name || message.agent_id) + '</span>';
        roleBadge = '<span class="role-badge">' + escapeHtml(message.agent_role || 'Agent') + '</span>';
        messageDiv.classList.add('agent-message');
    } else {
        avatarUrl = '/api/avatar/zhiyan';
        avatarEmoji = '🌊';
        if (message.agent_id === 'zhiyan' || message.agent_id === 'coordinator') {
            roleLabel = '<span class="agent-label">' + (message.agent_avatar || '🌊') + ' ' + escapeHtml(message.agent_name || '芙宁娜') + '</span>';
            roleBadge = '<span class="role-badge">' + escapeHtml(message.agent_role || '水神 芙宁娜') + '</span>';
            messageDiv.classList.add('agent-message');
        } else {
            roleLabel = '芙宁娜';
            roleBadge = '<span class="role-badge">水神 芙宁娜</span>';
        }
    }
    
    const contentHtml = isUser ? renderUserContent(message.content) : renderMarkdown(message.content);
    // 历史消息里的思考过程：渲染成可展开的「思考」行（默认折叠）
    const reasoningHtml = (!isUser && message.reasoning_content)
        ? _historyReasoningRowHtml(message.reasoning_content, message.think_ms)
        : '';
    // 原文留底：编辑重发要用（DOM 里是渲染后的 HTML，不能反推）
    if (isUser) messageDiv.dataset.rawContent = String(message.content || '');
    
    messageDiv.innerHTML = `
        <div class="message-avatar">
            ${avatarUrl ? '<img src="' + avatarUrl + '" alt="avatar" onerror="this.style.display=\'none\'; this.nextElementSibling.style.display=\'flex\';" class="avatar-img">' : ''}
            <div class="avatar-fallback" style="${avatarUrl ? 'display:none' : 'display:flex'}">${avatarEmoji}</div>
        </div>
        <div class="message-body">
            <div class="message-meta">
                <span class="message-role-label">${roleLabel}</span>
                ${roleBadge}
                <span class="message-time">${formatTime(message.time)}</span>
            </div>
            ${reasoningHtml}
            <div class="message-content">${contentHtml}${(!isUser && _pendingSources.length) ? _sourcesBlockHtml(_pendingSources.splice(0)) : ''}</div>
            ${(!isUser && message.think_ms && !reasoningHtml) ? '<div class="agent-think-timer"><i class="fas fa-clock"></i><span class="think-timer-text">思考耗时 ' + (Number(message.think_ms) / 1000).toFixed(1) + 's</span></div>' : ''}
            <div class="message-actions">
                <button class="msg-action-btn" onclick="copyMessage(this)" title="复制">
                    <i class="fas fa-copy"></i>
                </button>
                <button class="msg-action-btn" onclick="quoteReplyMessage(this)" title="引用回复">
                    <i class="fas fa-quote-right"></i>
                </button>
                <button class="msg-action-btn" onclick="deleteMessage(this)" title="删除">
                    <i class="fas fa-trash-alt"></i>
                </button>
                ${isUser
                    ? '<button class="msg-action-btn" onclick="editUserMessage(this)" title="编辑并重发"><i class="fas fa-pen"></i></button>'
                    : '<button class="msg-action-btn" onclick="resendMessage(this)" title="重新发送"><i class="fas fa-redo"></i></button>' +
                      '<button class="msg-action-btn" onclick="forkFromMessage(this)" title="从这条消息分支出新会话"><i class="fas fa-code-branch"></i></button>'}
            </div>
        </div>
    `;
    
    if (isUser) {
        const aiPlaceholder = document.getElementById('ai-typing');
        if (aiPlaceholder) {
            container.insertBefore(messageDiv, aiPlaceholder);
        } else {
            container.appendChild(messageDiv);
        }
    } else {
        container.appendChild(messageDiv);
    }
    
    // 右键 / 长按唤出气泡操作菜单（复制、引用回复、转发、删除）
    // 历史消息里的公式/图表 + 角标
    try { enhanceRichContent(messageDiv); } catch (e) { console.warn(e); }
    try { _linkifyCitations(messageDiv); } catch (e) { console.warn(e); }

    messageDiv.addEventListener('contextmenu', function (e) {
        e.preventDefault();
        showMessageContextMenu(e, this);
    });
    let _msgPressTimer = null;
    messageDiv.addEventListener('touchstart', function (e) {
        this._touchEvt = e.touches[0];
        this.classList.add('long-pressing');
        _msgPressTimer = setTimeout(() => {
            this.classList.remove('long-pressing');
            const t = this._touchEvt;
            if (t) showMessageContextMenu({ clientX: t.clientX, clientY: t.clientY, preventDefault: function () {} }, this);
        }, 500);
    }, { passive: true });
    messageDiv.addEventListener('touchmove', function () {
        this.classList.remove('long-pressing');
        if (_msgPressTimer) { clearTimeout(_msgPressTimer); _msgPressTimer = null; }
    }, { passive: true });
    messageDiv.addEventListener('touchend', function () {
        this.classList.remove('long-pressing');
        if (_msgPressTimer) { clearTimeout(_msgPressTimer); _msgPressTimer = null; }
    }, { passive: true });
    
    _syncChatBlankState();
    scrollToBottom();
}

