/**
 * 显示新建任务输入对话框
 */
function showAgentTaskInput() {
    showDialog('新建任务计划', `
        <div class="form-group">
            <label>任务目标</label>
            <input type="text" id="agent-task-goal" placeholder="描述你想要完成的任务目标..." style="width:100%">
        </div>
        <div class="form-group">
            <label>子任务（每行一个，可选）</label>
            <textarea id="agent-task-items" rows="5" placeholder="例如:&#10;1. 读取配置文件&#10;2. 分析数据&#10;3. 生成报告" style="width:100%"></textarea>
        </div>
        <div class="form-group" style="font-size:12px;color:var(--text-muted);">
            <i class="fas fa-info-circle"></i> 留空子任务将由系统自动分解
        </div>
    `, async () => {
        const goal = document.getElementById('agent-task-goal').value.trim();
        if (!goal) { showToast('请输入任务目标', 'error'); return; }
        closeDialog();

        const taskLines = document.getElementById('agent-task-items').value.trim().split('\n').filter(l => l.trim());
        const tasks = taskLines.length > 0 ? taskLines.map((line, i) => ({
            title: line.replace(/^\d+[\.\、\s]*/, '').trim(),
            description: '',
            depends_on: [],
            estimated_minutes: 0,
        })) : [];

        showToast('正在创建任务计划...', 'info');
        try {
            const res = await fetch('/api/planner/plan/create', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ goal, tasks }),
            });
            const data = await res.json();
            if (data.success) {
                showToast('任务计划创建成功');
                agentRefreshTasks();
            } else {
                showToast('创建失败: ' + (data.error || ''), 'error');
            }
        } catch (e) {
            showToast('请求失败: ' + e.message, 'error');
        }
    });
}

/**
 * 刷新任务列表
 */
async function agentRefreshTasks() {
    const taskList = document.getElementById('agent-task-list');
    if (!taskList) return;
    taskList.innerHTML = '<div class="agent-empty"><i class="fas fa-spinner fa-spin"></i> 加载中...</div>';

    try {
        const res = await fetch('/api/planner/plan/list');
        const data = await res.json();
        if (!data.success || !data.data || data.data.length === 0) {
            taskList.innerHTML = '<div class="agent-empty">暂无任务计划</div>';
            return;
        }
        taskList.innerHTML = '';
        data.data.forEach(plan => {
            // 显示计划摘要
            const planItem = document.createElement('div');
            planItem.className = 'agent-task-item';
            const progress = plan.progress || 0;
            const statusIcon = plan.status === 'completed' ? 'fa-check-circle' : 
                              (plan.status === 'paused' ? 'fa-pause-circle' :
                              (progress > 0 ? 'fa-spinner fa-spin' : 'fa-clock'));
            const statusClass = plan.status === 'completed' ? 'completed' : 
                               (plan.status === 'paused' ? 'pending' :
                               (progress > 0 ? 'running' : 'pending'));
            const taskCount = plan.total_tasks || (plan.tasks ? plan.tasks.length : 0);
            const remaining = plan.estimated_remaining_minutes || 0;
            planItem.innerHTML = `
                <div class="agent-task-status ${statusClass}"><i class="fas ${statusIcon}"></i></div>
                <div class="agent-task-info">
                    <div class="agent-task-title" title="${escapeHtml(plan.goal)}">${escapeHtml(plan.goal)}</div>
                    <div class="agent-task-desc">${taskCount} 个子任务 · 进度 ${progress}%${remaining ? ` · 剩余约 ${remaining} 分钟` : ''}</div>
                </div>
                <div class="agent-task-actions">
                    <button class="agent-task-btn" onclick="agentViewPlan('${plan.plan_id}')" title="查看详情"><i class="fas fa-eye"></i></button>
                    ${plan.status === 'active' && progress < 100 ? `<button class="agent-task-btn" onclick="agentPausePlan('${plan.plan_id}')" title="暂停"><i class="fas fa-pause"></i></button>` : ''}
                    ${plan.status === 'paused' ? `<button class="agent-task-btn" onclick="agentResumePlan('${plan.plan_id}')" title="恢复"><i class="fas fa-play"></i></button>` : ''}
                    <button class="agent-task-btn" onclick="agentCancelPlan('${plan.plan_id}')" title="取消"><i class="fas fa-times"></i></button>
                    <button class="agent-task-btn" onclick="agentDeletePlan('${plan.plan_id}')" title="删除" style="color:#dc3545"><i class="fas fa-trash"></i></button>
                </div>
            `;
            taskList.appendChild(planItem);
        });
    } catch (e) {
        taskList.innerHTML = '<div class="agent-empty">加载失败</div>';
    }
}

/**
 * 查看任务计划详情
 */
async function agentViewPlan(planId) {
    try {
        const res = await fetch('/api/planner/plan/' + planId);
        const data = await res.json();
        if (!data.success || !data.data) {
            showToast('获取计划详情失败', 'error');
            return;
        }
        const plan = data.data;
        let tasksHtml = '';
        if (plan.tasks && plan.tasks.length > 0) {
            plan.tasks.forEach((t, i) => {
                const statusMap = { pending: '⏳ 待执行', running: '🔄 执行中', completed: '✅ 已完成', failed: '❌ 失败', cancelled: '🚫 已取消', skipped: '⏭ 已跳过' };
                tasksHtml += `<div style="padding:8px;margin:4px 0;background:var(--glass-bg-hover);border-radius:6px;font-size:13px;">
                    <div><strong>#${i + 1}</strong> ${escapeHtml(t.title)} <span style="float:right;color:var(--text-muted);font-size:12px;">${statusMap[t.status] || t.status}</span></div>
                    ${t.description ? '<div style="color:var(--text-muted);font-size:12px;margin-top:2px;">' + escapeHtml(t.description) + '</div>' : ''}
                    ${t.error ? '<div style="color:#dc3545;font-size:12px;margin-top:2px;">错误: ' + escapeHtml(t.error) + '</div>' : ''}
                </div>`;
            });
        } else {
            tasksHtml = '<div style="color:var(--text-muted);padding:12px;">暂无子任务</div>';
        }
        showDialog('任务计划详情', `
            <div class="form-group">
                <label>目标</label>
                <div style="font-size:14px;font-weight:500;color:var(--text-primary);">${escapeHtml(plan.goal)}</div>
            </div>
            <div class="form-group">
                <label>进度: ${plan.progress || 0}%</label>
                <div style="height:6px;background:var(--glass-bg-hover);border-radius:3px;overflow:hidden;">
                    <div style="height:100%;width:${plan.progress || 0}%;background:linear-gradient(90deg,var(--primary-color),#818cf8);border-radius:3px;transition:width 0.3s;"></div>
                </div>
            </div>
            <div class="form-group">
                <label>子任务列表</label>
                ${tasksHtml}
            </div>
        `);
    } catch (e) {
        showToast('请求失败: ' + e.message, 'error');
    }
}

