// ============= Agent / DSH 模式切换 =============

// 模式状态：普通 / Agent / DSH 内核
window._agentMode = false;
window._dshMode = false;
// DSH 会话 id 持久化：重启后继续同一段内核会话（后端插件会从 JSONL 恢复上下文）
window._dshSessionId = (function () {
    try { return localStorage.getItem('dshSessionId') || null; } catch (e) { return null; }
})();

// 更新输入区的模式徽标
function _setChatModeBadge(mode) {
    const bAgent = document.getElementById('agent-mode-badge');
    const bDsh = document.getElementById('dsh-mode-badge');
    if (bAgent) bAgent.style.display = (mode === 'agent') ? 'flex' : 'none';
    if (bDsh) bDsh.style.display = (mode === 'dsh') ? 'flex' : 'none';
}

// 当前生效的回复引擎：'normal' | 'agent' | 'dsh'
function getReplyEngine() {
    if (window._dshMode) return 'dsh';
    if (window._agentMode) return 'agent';
    return 'normal';
}

// 统一应用回复引擎：更新前端状态 + 界面 +（可选）持久化到后端设置
// opts: { toast: bool, persist: bool }
function applyReplyEngine(mode, opts) {
    opts = opts || {};
    window._dshMode = (mode === 'dsh');
    window._agentMode = (mode === 'agent');
    // 切换模式不丢弃 DSH 会话 id，下次进入 DSH 模式继续原会话

    const toggleBtn = document.getElementById('agent-toggle-btn');
    if (toggleBtn) {
        if (mode === 'agent') {
            toggleBtn.classList.add('active'); toggleBtn.classList.remove('dsh');
            toggleBtn.title = 'Agent 模式已开启（自动调用工具）点击切换';
        } else if (mode === 'dsh') {
            toggleBtn.classList.add('active', 'dsh');
            toggleBtn.title = 'DSH 内核模式已开启（DeepSeek Harness）点击切换';
        } else {
            toggleBtn.classList.remove('active', 'dsh');
            toggleBtn.title = '切换模式（Agent / DSH 内核）';
        }
    }
    _setChatModeBadge(mode);

    // 同步设置面板下拉框
    const sel = document.getElementById('reply-engine');
    if (sel) sel.value = mode;

    if (opts.toast) {
        const names = { dsh: 'DSH 内核', agent: '内置 Agent', normal: '普通模式' };
        showToast('已切换为 ' + (names[mode] || mode) + ' 对话引擎', 'info');
    }
    if (opts.persist !== false) {
        persistReplyEngine(mode);
    }
}

// 把引擎选择持久化到后端 settings.json（实时生效，无需重启）
function persistReplyEngine(mode) {
    fetch('/api/settings', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ reply_engine: mode })
    }).then(r => r.json()).then(d => {
        if (d.status !== 'success') console.warn('reply_engine 保存失败', d);
    }).catch(() => {});
}

// 聊天区切换按钮：三态循环（普通 → Agent → DSH → 普通），并持久化
function cycleReplyEngine() {
    const order = ['normal', 'agent', 'dsh'];
    const cur = getReplyEngine();
    const next = order[(order.indexOf(cur) + 1) % order.length];
    applyReplyEngine(next, { toast: true, persist: true });
}

// 初始化模式切换按钮（三态循环：普通 → Agent → DSH → 普通）
document.addEventListener('DOMContentLoaded', function() {
    const toggleBtn = document.getElementById('agent-toggle-btn');
    if (toggleBtn) {
        toggleBtn.addEventListener('click', cycleReplyEngine);
    }
    // 设置面板下拉框切换 → 立即生效并保存
    const sel = document.getElementById('reply-engine');
    if (sel) {
        sel.addEventListener('change', function() {
            applyReplyEngine(sel.value, { toast: true, persist: true });
        });
    }
});

// ============= 聊天页项目文件树 =============

let chatFileTreeProject = '';
const chatFileTreeState = {
    search: '',
    expanded: new Set(),      // 已展开的目录路径
    selected: new Set(),      // 已选择的路径
    files: 0,
    folders: 0,
    ctxPath: null,            // 上下文菜单目标路径
    ctxType: null,
    lastSelected: null,       // 用于 shift 范围选择
    searchSeq: 0,             // 搜索请求序号（防竞态）
    dragPath: null,
    searchCache: null,        // {project, flat} 全量索引缓存
    pendingRestore: null,     // 待恢复的持久化状态 {project, expanded[], selected[]}
    restoreRetries: 0,        // 恢复展开的重试计数（防死循环）
};

// ═══════════ 文件树状态持久化（保留历史打开记录） ═══════════
const CHAT_FILETREE_STATE_KEY = 'zhiyan_chat_filetree_state';

function chatFileTreeSaveState() {
    try {
        localStorage.setItem(CHAT_FILETREE_STATE_KEY, JSON.stringify({
            project: chatFileTreeProject || '',
            expanded: Array.from(chatFileTreeState.expanded),
            selected: Array.from(chatFileTreeState.selected),
        }));
    } catch (e) {}
}

function chatFileTreeLoadSavedState() {
    try {
        const raw = localStorage.getItem(CHAT_FILETREE_STATE_KEY);
        if (!raw) return null;
        const data = JSON.parse(raw);
        if (!data || typeof data !== 'object') return null;
        return {
            project: typeof data.project === 'string' ? data.project : '',
            expanded: Array.isArray(data.expanded) ? data.expanded.filter(function(p) { return typeof p === 'string'; }) : [],
            selected: Array.isArray(data.selected) ? data.selected.filter(function(p) { return typeof p === 'string'; }) : [],
        };
    } catch (e) {
        return null;
    }
}

// 按 dataset.path 查找树节点（避免 CSS 转义问题）
function chatFileTreeFindNode(path) {
    const nodes = document.querySelectorAll('#chat-filetree-body .file-tree-node');
    for (let i = 0; i < nodes.length; i++) {
        if (nodes[i].dataset.path === path) return nodes[i];
    }
    return null;
}

// 应用持久化的展开/选中状态（子目录为异步加载，需在每次渲染后调用，幂等）
function chatFileTreeApplyRestore() {
    const saved = chatFileTreeState.pendingRestore;
    if (!saved) return;
    if (chatFileTreeProject !== saved.project) {
        chatFileTreeState.pendingRestore = null;
        return;
    }

    // 1. 按深度升序展开保存的目录（父目录先展开，子目录节点才会出现）
    const expanded = saved.expanded.slice().sort(function(a, b) {
        return a.split(/[\\/]/).length - b.split(/[\\/]/).length;
    });
    expanded.forEach(function(path) {
        if (chatFileTreeState.expanded.has(path)) return;
        const node = chatFileTreeFindNode(path);
        if (!node || node.dataset.type !== 'directory') return;
        const children = node.nextElementSibling;
        if (children && children.classList.contains('file-tree-children')) {
            // 已渲染但折叠
            children.style.display = '';
            const caret = node.querySelector('.node-caret');
            if (caret) caret.classList.add('expanded');
            const icon = node.querySelector('.node-icon i');
            if (icon) icon.className = 'fas fa-folder-open';
            chatFileTreeState.expanded.add(path);
        } else {
            // 懒加载展开（深度按路径层级计算，保证缩进正确）
            const segs = path.split(/[\\/]/).length;
            chatFileTreeToggleDir(node, { path: path, type: 'directory' }, Math.max(0, segs - 1));
        }
    });

    // 2. 尚未全部展开：子目录仍在异步加载，等待下次渲染
    const allKnown = saved.expanded.every(function(path) {
        return chatFileTreeState.expanded.has(path);
    });
    if (!allKnown) {
        chatFileTreeState.restoreRetries = (chatFileTreeState.restoreRetries || 0) + 1;
        if (chatFileTreeState.restoreRetries > 25) {
            // 超过重试次数（目录可能已被删除/移动）：放弃未恢复的部分，避免死循环
            saved.expanded = saved.expanded.filter(function(p) {
                return chatFileTreeState.expanded.has(p);
            });
        } else {
            return; // 等待子目录渲染完成后再次尝试
        }
    }

    // 3. 全部展开完成：恢复选中并收尾
    saved.selected.forEach(function(path) {
        if (chatFileTreeState.selected.has(path)) return;
        const node = chatFileTreeFindNode(path);
        if (!node) return;
        chatFileTreeState.selected.add(path);
        node.classList.add('selected');
    });
    if (saved.selected.length) {
        chatFileTreeState.lastSelected = saved.selected[saved.selected.length - 1];
    }
    chatFileTreeState.pendingRestore = null;
    updateChatFileTreeBatchBar();
    chatFileTreeSaveState();
    // 4. 自动打开最后一个选中的文件（恢复"打开"记录）
    const last = chatFileTreeState.lastSelected;
    if (last) {
        const node = chatFileTreeFindNode(last);
        if (node && node.dataset.type === 'file') chatOperationOpenFile(last);
    }
}

// 文件类型图标映射（视觉区分）
const CHAT_FILE_ICON_MAP = {
    img:     { icon: 'fas fa-file-image',  color: '#10b981' },
    audio:   { icon: 'fas fa-file-audio',  color: '#f59e0b' },
    video:   { icon: 'fas fa-file-video',  color: '#ef4444' },
    archive: { icon: 'fas fa-file-zipper', color: '#3FA9F5' },
    code:    { icon: 'fas fa-file-code',   color: '#3b82f6' },
    doc:     { icon: 'fas fa-file-lines',  color: '#0ea5e9' },
    data:    { icon: 'fas fa-file-csv',    color: '#06b6d4' },
    config:  { icon: 'fas fa-gear',        color: '#64748b' },
    file:    { icon: 'far fa-file',        color: '' },
};

const CHAT_FILE_EXT_MAP = {
    img: ['png','jpg','jpeg','gif','webp','svg','bmp','ico','avif','heic','tiff'],
    audio: ['mp3','wav','flac','ogg','aac','m4a','wma','opus'],
    video: ['mp4','mkv','avi','mov','wmv','flv','webm','m4v'],
    archive: ['zip','rar','7z','tar','gz','bz2','xz','iso','cab'],
    code: ['py','js','ts','jsx','tsx','java','c','cpp','h','hpp','cs','go','rs','php','rb','swift','kt','scala','lua','pl','sh','bash','bat','cmd','html','css','scss','less','vue','svelte'],
    doc: ['md','markdown','txt','doc','docx','pdf','xls','xlsx','ppt','pptx','rtf','odt'],
    data: ['csv','json','xml','yaml','yml','toml','ini','sql','db','sqlite','log'],
    config: ['env','cfg','conf','gitignore','dockerfile','makefile'],
};

function chatFileTreeGetIcon(name) {
    const lower = name.toLowerCase();
    if (lower === '.env' || lower === 'dockerfile' || lower === 'makefile' || lower === 'gitignore') {
        return { icon: 'fas fa-gear', color: '#64748b' };
    }
    const ext = (name.split('.').pop() || '').toLowerCase();
    if (!ext || ext === lower) {
        return { icon: 'far fa-file', color: '' };
    }
    for (const kind of Object.keys(CHAT_FILE_EXT_MAP)) {
        if (CHAT_FILE_EXT_MAP[kind].includes(ext)) {
            return CHAT_FILE_ICON_MAP[kind];
        }
    }
    return CHAT_FILE_ICON_MAP.file;
}

// ═══════════ 本地目录浏览（电脑目录） ═══════════
// 提供文件夹导航选择器，可选中电脑上的任意目录作为文件树项目根目录。

function openLocalDirPicker(onSelect) {
    var current = null;          // 当前浏览的绝对路径，null 表示盘符根视图
    var selDir = null;           // 当前选中的目录
    var listEl, pathEl;

    function join(a, b) {
        if (!a) return b;
        return a.replace(/[\\/]+$/, '') + '\\' + b;
    }
    function parentOf(p) {
        if (!p) return null;
        p = p.replace(/[\\/]+$/, '');
        if (p.length === 2 && /^[A-Za-z]:$/.test(p)) return null; // 盘符根 -> 我的电脑
        var idx = Math.max(p.lastIndexOf('\\'), p.lastIndexOf('/'));
        if (idx <= 0) return null;
        return p.slice(0, idx);
    }
    function makeRow(name, icon) {
        var row = document.createElement('div');
        row.className = 'local-dir-item';
        row.innerHTML = '<i class="' + icon + '"></i><span>' + escapeHtml(name) + '</span>';
        row.addEventListener('click', function () {
            listEl.querySelectorAll('.local-dir-item').forEach(function (x) { x.classList.remove('active'); });
            row.classList.add('active');
            selDir = join(current, name); // 始终存绝对路径，避免回退成工作区项目
            var openBtn = document.getElementById('ld-open');
            if (openBtn) openBtn.disabled = false;
        });
        row.addEventListener('dblclick', function () {
            navigate(join(current, name));
        });
        return row;
    }
    function renderFolder(entries) {
        listEl.innerHTML = '';
        var dirs = entries.filter(function (e) { return e.type === 'directory'; });
        if (!dirs.length) { listEl.innerHTML = '<div class="local-dir-empty">此文件夹为空</div>'; return; }
        dirs.forEach(function (e) { listEl.appendChild(makeRow(e.name, 'fas fa-folder')); });
    }
    function navigate(dir) {
        current = dir;
        selDir = null;
        pathEl.textContent = dir ? dir : '电脑目录';
        var openBtn = document.getElementById('ld-open');
        if (openBtn) openBtn.disabled = true;
        listEl.innerHTML = '<div class="local-dir-loading">加载中...</div>';
        if (!dir) {
            fetch('/api/editor/drives')
                .then(function (r) { return r.json(); })
                .then(function (d) {
                    if (!d.success) { listEl.innerHTML = '<div class="local-dir-empty">无法获取盘符</div>'; return; }
                    listEl.innerHTML = '';
                    d.data.drives.forEach(function (drv) {
                        listEl.appendChild(makeRow(drv, 'fas fa-hard-drive'));
                    });
                })
                .catch(function () { listEl.innerHTML = '<div class="local-dir-empty">无法获取盘符</div>'; });
            return;
        }
        fetch('/api/editor/files?project=' + encodeURIComponent(dir) + '&path=')
            .then(function (r) { return r.json(); })
            .then(function (data) {
                if (!data.success) { listEl.innerHTML = '<div class="local-dir-empty">' + escapeHtml(data.error || '无法访问，可能无权读取') + '</div>'; return; }
                renderFolder(data.data.entries);
            })
            .catch(function () { listEl.innerHTML = '<div class="local-dir-empty">无法访问</div>'; });
    }

    var html = ''
        + '<div class="local-dir-picker">'
        + '<div class="local-dir-path" id="ld-path">电脑目录</div>'
        + '<div class="local-dir-toolbar">'
        + '<button type="button" class="btn btn-sm" onclick="window._localDirUp && _localDirUp()">向上</button>'
        + '<button type="button" class="btn btn-sm" onclick="window._localDirRefresh && _localDirRefresh()">刷新</button>'
        + '</div>'
        + '<div class="local-dir-list" id="ld-list"></div>'
        + '<div class="local-dir-footer">'
        + '<button type="button" class="btn btn-sm" onclick="closeDialog()">取消</button>'
        + '<button type="button" class="btn btn-sm btn-primary" id="ld-open" disabled>在此目录打开文件树</button>'
        + '</div>'
        + '</div>';

    showDialog('浏览电脑目录', html, null);
    var actions = document.getElementById('dialog-actions');
    if (actions) actions.style.display = 'none';

    listEl = document.getElementById('ld-list');
    pathEl = document.getElementById('ld-path');

    window._localDirUp = function () { navigate(parentOf(current)); };
    window._localDirRefresh = function () { navigate(current); };
    document.getElementById('ld-open').onclick = function () {
        var dir = selDir || current;
        if (!dir) { showToast('请选择一个目录', 'error'); return; }
        closeDialog();
        onSelect(dir);
    };

    navigate(null);
}

function editorOpenLocalDir() {
    openLocalDirPicker(function (dir) {
        editorCurrentProject = dir;
        document.getElementById('editor-project-select').value = '';
        editorRefreshFileTree();
        editorRefreshTemplates();
        showToast('已打开本地目录: ' + dir, 'success');
    });
}

function chatFileTreeOpenLocalDir() {
    openLocalDirPicker(function (dir) {
        chatFileTreeProject = dir;
        chatFileTreeState.expanded.clear();
        chatFileTreeState.selected.clear();
        updateChatFileTreeBatchBar();
        chatFileTreeRefresh();
        chatFileTreeSaveState();
        showToast('已打开本地目录: ' + dir, 'success');
    });
}

// 初始化文件树（加载项目列表）
function initChatFileTree() {
    const select = document.getElementById('chat-filetree-project');
    if (!select) return;
    fetch('/api/editor/projects')
        .then(r => r.json())
        .then(data => {
            if (!data.success) return;
            select.innerHTML = '<option value="">-- 选择项目 --</option>';
            (data.data.projects || []).forEach(proj => {
                const opt = document.createElement('option');
                opt.value = proj.name;
                opt.textContent = proj.display_name + ' (' + (proj.language || 'mixed') + ') · ' + proj.file_count + ' 文件';
                select.appendChild(opt);
            });
            // 搜索框绑定
            const input = document.getElementById('chat-filetree-search-input');
            if (input) {
                input.addEventListener('input', function() {
                    chatFileTreeScheduleSearch(this.value);
                });
            }
            // 全局点击关闭上下文菜单
            document.addEventListener('click', function() {
                const menu = document.getElementById('filetree-context-menu');
                if (menu) menu.style.display = 'none';
            });
            document.addEventListener('keydown', function(e) {
                if (e.key === 'Escape') {
                    const menu = document.getElementById('filetree-context-menu');
                    if (menu) menu.style.display = 'none';
                    chatFileTreeClearSelection(true);
                }
            });
            // 恢复历史打开记录（上次的项目 + 展开目录 + 选中文件）
            const saved = chatFileTreeLoadSavedState();
            if (saved && saved.project) {
                const isKnown = Array.prototype.some.call(select.options, function(o) {
                    return o.value === saved.project;
                });
                if (isKnown) {
                    select.value = saved.project;
                } else {
                    // 本地目录路径不在项目选项里，直接作为根目录加载
                    chatFileTreeProject = saved.project;
                }
                chatFileTreeState.pendingRestore = saved;
                chatFileTreeState.restoreRetries = 0;
                chatFileTreeSwitchProject(saved.project);
            }
        })
        .catch(() => {});
}

// 切换项目
function chatFileTreeSwitchProject(project) {
    chatFileTreeProject = project;
    chatFileTreeState.expanded.clear();
    chatFileTreeState.selected.clear();
    chatFileTreeState.search = '';
    chatFileTreeState.searchCache = null;
    const input = document.getElementById('chat-filetree-search-input');
    if (input) { input.value = ''; }
    const clearBtn = document.getElementById('chat-filetree-search-clear');
    if (clearBtn) clearBtn.classList.add('hidden');
    updateChatFileTreeBatchBar();
    const body = document.getElementById('chat-filetree-body');
    if (!body) return;
    if (!project) {
        body.innerHTML = '<div class="chat-filetree-empty"><i class="fas fa-folder-open"></i><p>请选择项目以查看文件结构</p></div>';
        updateChatFileTreeCount();
        chatFileTreeSaveState();
        return;
    }
    chatFileTreeRefresh();
    chatFileTreeSaveState();
}

// 刷新文件树
function chatFileTreeRefresh() {
    const body = document.getElementById('chat-filetree-body');
    if (!body || !chatFileTreeProject) return;

    if (chatFileTreeState.search) {
        chatFileTreeDoSearch(chatFileTreeState.search);
        return;
    }

    body.innerHTML = '<div class="chat-filetree-loading"><i class="fas fa-spinner fa-spin"></i> 加载中...</div>';
    chatFileTreeState.files = 0;
    chatFileTreeState.folders = 0;

    fetch('/api/editor/files?project=' + encodeURIComponent(chatFileTreeProject) + '&path=')
        .then(r => r.json())
        .then(data => {
            if (!data.success) {
                body.innerHTML = '<div class="chat-filetree-empty"><i class="fas fa-exclamation-circle"></i><p>加载失败</p></div>';
                return;
            }
            body.innerHTML = '';
            chatFileTreeRenderEntries(data.data.entries, body, '', 0);
            updateChatFileTreeCount();
        })
        .catch(() => {
            body.innerHTML = '<div class="chat-filetree-empty"><i class="fas fa-exclamation-circle"></i><p>加载失败</p></div>';
        });
}

// 渲染目录项（大目录分帧渲染，避免阻塞 UI）
function chatFileTreeRenderEntries(entries, container, basePath, depth) {
    const chunk = 200;
    if (entries.length > chunk) {
        let i = 0;
        function renderNext() {
            const slice = entries.slice(i, i + chunk);
            slice.forEach(function(entry) {
                container.appendChild(chatFileTreeCreateNode(entry, depth));
            });
            i += chunk;
            if (i < entries.length) {
                requestAnimationFrame(renderNext);
            } else {
                updateChatFileTreeCount();
                chatFileTreeApplyRestore();
            }
        }
        requestAnimationFrame(renderNext);
    } else {
        entries.forEach(function(entry) {
            container.appendChild(chatFileTreeCreateNode(entry, depth));
        });
        updateChatFileTreeCount();
        chatFileTreeApplyRestore();
    }
}

// 创建单个节点
function chatFileTreeCreateNode(entry, depth) {
    const node = document.createElement('div');
    node.className = 'file-tree-node';
    node.dataset.path = entry.path;
    node.dataset.type = entry.type;
    node.style.setProperty('--node-depth', depth);
    node.draggable = true;

    if (entry.type === 'directory') {
        const isExpanded = chatFileTreeState.expanded.has(entry.path);
        const iconCls = isExpanded ? 'fa-folder-open' : 'fa-folder';
        node.innerHTML = '<span class="node-caret' + (isExpanded ? ' expanded' : '') + '"><i class="fas fa-chevron-right"></i></span>'
            + '<span class="node-icon folder" style="color:#f59e0b;"><i class="fas ' + iconCls + '"></i></span>'
            + '<span class="node-name">' + escapeHtml(entry.name) + '</span>';
        chatFileTreeState.folders++;
        if (isExpanded) {
            const children = document.createElement('div');
            children.className = 'file-tree-children';
            children.dataset.dirpath = entry.path;
            node.after(children);
            chatFileTreeLoadDir(entry.path, children, depth + 1, true);
        }
        node.addEventListener('click', function(e) {
            e.stopPropagation();
            if (e.ctrlKey || e.metaKey) {
                chatFileTreeToggleSelection(node, entry);
                return;
            }
            chatFileTreeToggleDir(node, entry, depth);
        });
        node.addEventListener('contextmenu', function(e) {
            e.preventDefault();
            e.stopPropagation();
            chatFileTreeShowContextMenu(e, entry);
        });
        // 拖放：目录是放置目标
        node.addEventListener('dragover', function(e) {
            if (!chatFileTreeState.dragPath || chatFileTreeState.dragPath === entry.path) return;
            e.preventDefault();
            e.stopPropagation();
            node.classList.add('drop-target');
        });
        node.addEventListener('dragleave', function() {
            node.classList.remove('drop-target');
        });
        node.addEventListener('drop', function(e) {
            e.preventDefault();
            e.stopPropagation();
            node.classList.remove('drop-target');
            chatFileTreeMoveNode(chatFileTreeState.dragPath, entry.path);
        });
    } else {
        const gi = chatFileTreeGetIcon(entry.name);
        const styleColor = gi.color ? ' style="color:' + gi.color + ';"' : '';
        node.innerHTML = '<span class="node-caret"></span>'
            + '<span class="node-icon file"' + styleColor + '><i class="' + gi.icon + '"></i></span>'
            + '<span class="node-name">' + escapeHtml(entry.name) + '</span>';
        chatFileTreeState.files++;
        node.addEventListener('click', function(e) {
            e.stopPropagation();
            if (e.ctrlKey || e.metaKey) {
                chatFileTreeToggleSelection(node, entry);
                return;
            }
            if (e.shiftKey && chatFileTreeState.lastSelected) {
                chatFileTreeRangeSelect(node, entry);
                return;
            }
            chatFileTreeSelectSingle(node, entry);
            chatOperationOpenFile(entry.path);
        });
        node.addEventListener('contextmenu', function(e) {
            e.preventDefault();
            e.stopPropagation();
            chatFileTreeShowContextMenu(e, entry);
        });
        // 拖放：文件可拖拽
        node.addEventListener('dragstart', function(e) {
            chatFileTreeState.dragPath = entry.path;
            e.dataTransfer.effectAllowed = 'move';
            node.classList.add('dragging');
        });
        node.addEventListener('dragend', function() {
            chatFileTreeState.dragPath = null;
            node.classList.remove('dragging');
            document.querySelectorAll('.chat-filetree-body .file-tree-node.drop-target').forEach(function(n) {
                n.classList.remove('drop-target');
            });
        });
    }
    return node;
}

// 加载子目录
function chatFileTreeLoadDir(path, container, depth, keepExpanded) {
    if (!keepExpanded) {
        container.innerHTML = '<div class="chat-filetree-loading" style="padding:8px 12px;"><i class="fas fa-spinner fa-spin"></i> 加载中...</div>';
    }
    fetch('/api/editor/files?project=' + encodeURIComponent(chatFileTreeProject) + '&path=' + encodeURIComponent(path))
        .then(r => r.json())
        .then(data => {
            if (!data.success) {
                container.innerHTML = '<div class="chat-filetree-empty" style="padding:12px;"><p>加载失败</p></div>';
                showToast('目录加载失败: ' + (data.error || ''), 'error');
                return;
            }
            container.innerHTML = '';
            chatFileTreeRenderEntries(data.data.entries, container, path, depth);
        })
        .catch(() => {
            container.innerHTML = '<div class="chat-filetree-empty" style="padding:12px;"><p>加载失败</p></div>';
        });
}

// 展开/折叠目录
function chatFileTreeToggleDir(node, entry, depth) {
    const caret = node.querySelector('.node-caret');
    const icon = node.querySelector('.node-icon i');
    let children = node.nextElementSibling;
    if (children && children.classList.contains('file-tree-children')) {
        if (children.style.display === 'none') {
            children.style.display = '';
            caret.classList.add('expanded');
            icon.className = 'fas fa-folder-open';
            chatFileTreeState.expanded.add(entry.path);
        } else {
            children.style.display = 'none';
            caret.classList.remove('expanded');
            icon.className = 'fas fa-folder';
            chatFileTreeState.expanded.delete(entry.path);
        }
        chatFileTreeSaveState();
        return;
    }
    // 首次展开，懒加载
    caret.classList.add('expanded');
    icon.className = 'fas fa-folder-open';
    chatFileTreeState.expanded.add(entry.path);
    const childrenWrap = document.createElement('div');
    childrenWrap.className = 'file-tree-children';
    childrenWrap.dataset.dirpath = entry.path;
    node.after(childrenWrap);
    chatFileTreeLoadDir(entry.path, childrenWrap, depth + 1, false);
    chatFileTreeSaveState();
}

// 单选
function chatFileTreeSelectSingle(node, entry) {
    document.querySelectorAll('#chat-filetree-body .file-tree-node.selected').forEach(function(n) {
        n.classList.remove('selected');
    });
    chatFileTreeState.selected.clear();
    if (entry) {
        chatFileTreeState.selected.add(entry.path);
        chatFileTreeState.lastSelected = entry.path;
    }
    if (node) node.classList.add('selected');
    updateChatFileTreeBatchBar();
    chatFileTreeSaveState();
}

// 多选切换
function chatFileTreeToggleSelection(node, entry) {
    if (chatFileTreeState.selected.has(entry.path)) {
        chatFileTreeState.selected.delete(entry.path);
        node.classList.remove('selected');
    } else {
        chatFileTreeState.selected.add(entry.path);
        node.classList.add('selected');
        chatFileTreeState.lastSelected = entry.path;
    }
    updateChatFileTreeBatchBar();
    chatFileTreeSaveState();
}

// shift 范围选择
function chatFileTreeRangeSelect(node, entry) {
    const nodes = Array.from(document.querySelectorAll('#chat-filetree-body .file-tree-node'));
    const idxCurrent = nodes.indexOf(node);
    const lastNode = nodes.find(n => n.dataset.path === chatFileTreeState.lastSelected) || node;
    const idxLast = nodes.indexOf(lastNode);
    const start = Math.min(idxCurrent, idxLast);
    const end = Math.max(idxCurrent, idxLast);
    for (let i = start; i <= end; i++) {
        const n = nodes[i];
        if (!n) continue;
        chatFileTreeState.selected.add(n.dataset.path);
        n.classList.add('selected');
    }
    chatFileTreeState.lastSelected = entry.path;
    updateChatFileTreeBatchBar();
    chatFileTreeSaveState();
}

// 打开预览
function chatFileTreeOpenPreview(path) {
    fetch('/api/editor/files/read?project=' + encodeURIComponent(chatFileTreeProject) + '&path=' + encodeURIComponent(path))
        .then(r => r.json())
        .then(data => {
            if (!data.success) {
                showToast('读取文件失败: ' + (data.error || ''), 'error');
                return;
            }
            const filename = path.split('/').pop() || path.split('\\').pop() || path;
            const content = data.data.content || '';
            const preview = content.length > 5000 ? content.substring(0, 5000) + '\n... (内容已截断)' : content;
            showDialog('文件预览: ' + escapeHtml(filename),
                '<div style="font-size:12px;color:var(--text-muted);margin-bottom:8px;">路径: ' + escapeHtml(path) + ' · 共 ' + content.length + ' 字符</div>'
                + '<pre style="max-height:380px;overflow:auto;background:var(--bg-tertiary);padding:12px;border-radius:8px;font-size:12px;line-height:1.6;white-space:pre-wrap;word-break:break-all;margin:0;">' + escapeHtml(preview) + '</pre>',
                function() {
                    openFileInEditor(chatFileTreeProject, path);
                }
            );
        })
        .catch(() => showToast('读取文件失败', 'error'));
}

// 新建文件/文件夹（isFile=true 为文件）
function chatFileTreeCreate(isFile) {
    if (!chatFileTreeProject) {
        showToast('请先选择项目', 'error');
        return;
    }
    const label = isFile ? '文件' : '文件夹';
    const placeholder = isFile ? '如: new_file.py' : '如: new_folder';
    showDialog('新建' + label,
        '<div style="font-size:12px;color:var(--text-muted);margin-bottom:8px;">创建位置: ' + escapeHtml(chatFileTreeState.ctxPath || '项目根目录') + '</div>'
        + '<input id="chat-filetree-create-name" type="text" placeholder="' + placeholder + '" style="width:100%;padding:8px 10px;border:1px solid var(--border-color);border-radius:6px;background:var(--bg-secondary);color:var(--text-primary);font-size:13px;outline:none;">',
        function() {
            const nameInput = document.getElementById('chat-filetree-create-name');
            const name = (nameInput ? nameInput.value : '').trim();
            if (!name) { showToast('名称不能为空', 'error'); return; }
            const target = chatFileTreeState.ctxPath || '';
            const fullPath = target ? target + '/' + name : name;
            const url = isFile ? '/api/editor/files/create' : '/api/editor/files/folder';
            fetch(url, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ project: chatFileTreeProject, path: fullPath })
            })
                .then(r => r.json())
                .then(data => {
                    if (!data.success) {
                        showToast((data.error || '创建失败'), 'error');
                        return;
                    }
                    showToast((isFile ? '文件' : '文件夹') + '创建成功', 'success');
                    if (target) chatFileTreeState.expanded.add(target);
                    chatFileTreeRefresh();
                })
                .catch(() => showToast('创建失败', 'error'));
        }
    );
    setTimeout(function() {
        const inp = document.getElementById('chat-filetree-create-name');
        if (inp) inp.focus();
    }, 100);
}

// 重命名
function chatFileTreeRename(path, name) {
    const defaultName = name || (path.split('/').pop() || path);
    showDialog('重命名',
        '<input id="chat-filetree-rename-input" type="text" value="' + escapeHtml(defaultName) + '" style="width:100%;padding:8px 10px;border:1px solid var(--border-color);border-radius:6px;background:var(--bg-secondary);color:var(--text-primary);font-size:13px;outline:none;">',
        function() {
            const input = document.getElementById('chat-filetree-rename-input');
            const newName = (input ? input.value : '').trim();
            if (!newName) { showToast('名称不能为空', 'error'); return; }
            if (newName === defaultName) { showToast('名称未变化', 'info'); return; }
            fetch('/api/editor/files/rename', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ project: chatFileTreeProject, path: path, new_name: newName })
            })
                .then(r => r.json())
                .then(data => {
                    if (!data.success) {
                        showToast((data.error || '重命名失败'), 'error');
                        return;
                    }
                    showToast('重命名成功', 'success');
                    const parent = path.split('/').slice(0, -1).join('/');
                    if (parent) chatFileTreeState.expanded.add(parent);
                    chatFileTreeRefresh();
                })
                .catch(() => showToast('重命名失败', 'error'));
        }
    );
    setTimeout(function() {
        const inp = document.getElementById('chat-filetree-rename-input');
        if (inp) { inp.focus(); inp.select(); }
    }, 100);
}

// 删除确认
function chatFileTreeConfirmDelete(paths) {
    const count = paths.length;
    const desc = count === 1 ? paths[0] : '选中的 ' + count + ' 个项目';
    showDialog('确认删除',
        '<div style="font-size:13px;color:var(--text-primary);line-height:1.7;">确定要删除 <strong>' + escapeHtml(desc) + '</strong> 吗？<br><span style="color:#ef4444;font-size:12px;">此操作不可恢复！</span></div>',
        function() {
            let done = 0;
            const total = paths.length;
            paths.forEach(function(p) {
                fetch('/api/editor/files/delete', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ project: chatFileTreeProject, path: p })
                })
                    .then(r => r.json())
                    .then(data => {
                        done++;
                        if (!data.success) showToast('删除失败: ' + (data.error || ''), 'error');
                        if (done === total) {
                            showToast('删除完成', 'success');
                            paths.forEach(function(pp) { chatFileTreeState.selected.delete(pp); });
                            updateChatFileTreeBatchBar();
                            chatFileTreeRefresh();
                        }
                    })
                    .catch(function() {
                        done++;
                        if (done === total) chatFileTreeRefresh();
                    });
            });
        }
    );
}

// 批量删除
function chatFileTreeBatchDelete() {
    if (chatFileTreeState.selected.size === 0) {
        showToast('请先选择项目', 'info');
        return;
    }
    chatFileTreeConfirmDelete(Array.from(chatFileTreeState.selected));
}

// 清除选择
function chatFileTreeClearSelection(silent) {
    chatFileTreeState.selected.clear();
    chatFileTreeState.lastSelected = null;
    document.querySelectorAll('#chat-filetree-body .file-tree-node.selected').forEach(function(n) {
        n.classList.remove('selected');
    });
    updateChatFileTreeBatchBar();
    chatFileTreeSaveState();
}

// 更新批量操作栏
function updateChatFileTreeBatchBar() {
    const bar = document.getElementById('chat-filetree-batchbar');
    const count = document.getElementById('chat-filetree-batch-count');
    if (!bar || !count) return;
    const n = chatFileTreeState.selected.size;
    if (n > 0) {
        bar.style.display = '';
        count.textContent = '已选 ' + n + ' 项';
    } else {
        bar.style.display = 'none';
    }
}

// ---- 搜索与过滤 ----

let _chatFileTreeSearchTimer = null;
function chatFileTreeScheduleSearch(value) {
    chatFileTreeState.search = value.trim();
    const clearBtn = document.getElementById('chat-filetree-search-clear');
    if (clearBtn) clearBtn.classList.toggle('hidden', !chatFileTreeState.search);
    if (_chatFileTreeSearchTimer) clearTimeout(_chatFileTreeSearchTimer);
    _chatFileTreeSearchTimer = setTimeout(function() {
        if (!chatFileTreeProject) return;
        if (chatFileTreeState.search) {
            chatFileTreeDoSearch(chatFileTreeState.search);
        } else {
            chatFileTreeRefresh();
        }
    }, 250);
}

function chatFileTreeClearSearch() {
    const input = document.getElementById('chat-filetree-search-input');
    if (input) input.value = '';
    chatFileTreeState.search = '';
    const clearBtn = document.getElementById('chat-filetree-search-clear');
    if (clearBtn) clearBtn.classList.add('hidden');
    if (chatFileTreeProject) chatFileTreeRefresh();
}

// 执行搜索（使用全量树缓存）
function chatFileTreeDoSearch(query) {
    const body = document.getElementById('chat-filetree-body');
    if (!body) return;
    const q = query.toLowerCase();
    const seq = ++chatFileTreeState.searchSeq;

    body.innerHTML = '<div class="chat-filetree-loading"><i class="fas fa-spinner fa-spin"></i> 搜索中...</div>';

    const loadCache = function() {
        if (chatFileTreeState.searchCache && chatFileTreeState.searchCache.project === chatFileTreeProject) {
            return Promise.resolve(chatFileTreeState.searchCache.flat);
        }
        return fetch('/api/editor/files/tree?project=' + encodeURIComponent(chatFileTreeProject))
            .then(r => r.json())
            .then(data => {
                if (!data.success) throw new Error(data.error || '加载失败');
                chatFileTreeState.searchCache = { project: chatFileTreeProject, flat: data.data.flat };
                return data.data.flat;
            });
    };

    loadCache().then(function(flat) {
        if (seq !== chatFileTreeState.searchSeq) return; // 竞态丢弃
        const matched = flat.filter(function(item) {
            return item.name.toLowerCase().includes(q);
        });
        chatFileTreeState.files = 0;
        chatFileTreeState.folders = 0;
        body.innerHTML = '';
        if (matched.length === 0) {
            body.innerHTML = '<div class="chat-filetree-search-empty"><i class="fas fa-search-minus"></i><p>未找到与 "' + escapeHtml(query) + '" 匹配的文件</p></div>';
            updateChatFileTreeCount();
            return;
        }
        // 分帧渲染
        const chunk = 200;
        let i = 0;
        function renderNext() {
            const slice = matched.slice(i, i + chunk);
            slice.forEach(function(item) {
                const node = chatFileTreeCreateNode(item, 0);
                const pathSpan = document.createElement('span');
                pathSpan.className = 'node-path';
                pathSpan.textContent = item.path;
                node.appendChild(pathSpan);
                body.appendChild(node);
            });
            i += chunk;
            if (i < matched.length) {
                requestAnimationFrame(renderNext);
            } else {
                updateChatFileTreeCount();
            }
        }
        requestAnimationFrame(renderNext);
    }).catch(function(err) {
        if (seq !== chatFileTreeState.searchSeq) return;
        body.innerHTML = '<div class="chat-filetree-empty"><i class="fas fa-exclamation-circle"></i><p>搜索失败</p></div>';
        showToast('搜索失败: ' + (err.message || err), 'error');
    });
}

// ---- 上下文菜单 ----

function chatFileTreeShowContextMenu(e, entry) {
    chatFileTreeState.ctxPath = entry.path;
    chatFileTreeState.ctxType = entry.type;
    // 若该节点不在选择集中，则单选它
    if (!chatFileTreeState.selected.has(entry.path)) {
        const nodes = Array.from(document.querySelectorAll('#chat-filetree-body .file-tree-node[data-path="' + entry.path.replace(/"/g, '\\"') + '"]'));
        chatFileTreeSelectSingle(nodes[0] || null, entry);
    }
    const menu = document.getElementById('filetree-context-menu');
    if (!menu) return;
    const openItem = menu.querySelector('[data-ctx-action="open"]');
    const openEditorItem = menu.querySelector('[data-ctx-action="open-editor"]');
    if (openItem) openItem.style.display = entry.type === 'directory' ? 'none' : '';
    if (openEditorItem) openEditorItem.style.display = entry.type === 'directory' ? 'none' : '';
    menu.style.display = '';
    const rect = menu.getBoundingClientRect();
    const x = Math.min(e.clientX, window.innerWidth - rect.width - 8);
    const y = Math.min(e.clientY, window.innerHeight - rect.height - 8);
    menu.style.left = x + 'px';
    menu.style.top = y + 'px';
}

function chatFileTreeCtxOpen() {
    if (chatFileTreeState.ctxPath) chatFileTreeOpenPreview(chatFileTreeState.ctxPath);
}

function chatFileTreeCtxOpenEditor() {
    if (chatFileTreeState.ctxPath) openFileInEditor(chatFileTreeProject, chatFileTreeState.ctxPath);
}

function chatFileTreeCtxCreate(isFile) {
    chatFileTreeCreate(isFile);
}

function chatFileTreeCtxRename() {
    if (!chatFileTreeState.ctxPath) return;
    const name = chatFileTreeState.ctxPath.split('/').pop() || chatFileTreeState.ctxPath;
    chatFileTreeRename(chatFileTreeState.ctxPath, name);
}

function chatFileTreeCtxDelete() {
    if (!chatFileTreeState.ctxPath) return;
    chatFileTreeConfirmDelete([chatFileTreeState.ctxPath]);
}

function chatFileTreeCtxCopyPath() {
    if (!chatFileTreeState.ctxPath) return;
    const path = chatFileTreeState.ctxPath;
    if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(path)
            .then(function() { showToast('路径已复制', 'success'); })
            .catch(function() { chatFileTreeFallbackCopy(path); });
    } else {
        chatFileTreeFallbackCopy(path);
    }
}

function chatFileTreeFallbackCopy(text) {
    const ta = document.createElement('textarea');
    ta.value = text;
    ta.style.position = 'fixed';
    ta.style.opacity = '0';
    document.body.appendChild(ta);
    ta.select();
    try {
        document.execCommand('copy');
        showToast('路径已复制', 'success');
    } catch (e) {
        showToast('复制失败', 'error');
    }
    document.body.removeChild(ta);
}

// ---- 拖放移动 ----

function chatFileTreeMoveNode(path, targetDir) {
    if (!path || !targetDir) return;
    if (path === targetDir) return;
    fetch('/api/editor/files/move', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ project: chatFileTreeProject, path: path, target_dir: targetDir })
    })
        .then(r => r.json())
        .then(data => {
            if (!data.success) {
                showToast('移动失败: ' + (data.error || ''), 'error');
                return;
            }
            showToast('已移动到: ' + targetDir, 'success');
            chatFileTreeState.expanded.add(targetDir);
            chatFileTreeRefresh();
        })
        .catch(function() { showToast('移动失败', 'error'); });
}

// 在代码编辑器中打开文件
function openFileInEditor(project, path) {
    const select = document.getElementById('editor-project-select');
    if (select) select.value = project;
    editorCurrentProject = project;
    const headerProject = document.getElementById('editor-header-project');
    if (headerProject) headerProject.textContent = '项目: ' + project;
    editorRefreshFileTree();
    switchView('code-editor');
    setTimeout(function() {
        if (editorOpenedFiles[path]) {
            editorSwitchToTab(path);
        } else {
            editorOpenFile(path);
        }
    }, 400);
}

// 更新文件树统计
function updateChatFileTreeCount() {
    const el = document.getElementById('chat-filetree-count');
    if (el) el.textContent = chatFileTreeState.files + ' 个文件 · ' + chatFileTreeState.folders + ' 个文件夹';
}

