// ============= 文件格式转换器 =============

let converterState = {
    selectedFile: null,
    fileInfo: null,
    convertType: 'audio',
    targetFormat: null,
    audioBitrate: 192,
    formats: { audio: [], video: [] },
    history: [],
};

// 初始化转换器
function initConverter() {
    converterCheckStatus();
    converterLoadFormats();
    converterLoadHistory();
}

// 视图切换时初始化
const _origConverterSwitchView = window.switchView;
window.switchView = function (viewName) {
    if (viewName === 'converter') {
        initConverter();
    }
    return _origConverterSwitchView ? _origConverterSwitchView(viewName) : undefined;
};

// 检查 FFmpeg 状态
function converterCheckStatus() {
    fetch('/api/ffmpeg/status')
        .then(function (r) { return r.json(); })
        .then(function (data) {
            var dot = document.getElementById('converter-status-dot');
            var text = document.getElementById('converter-status-text');
            var ffmpegStatus = document.getElementById('converter-ffmpeg-status');
            if (data.available) {
                if (dot) dot.style.background = '#22c55e';
                if (text) text.textContent = 'FFmpeg 可用';
                if (ffmpegStatus) { ffmpegStatus.textContent = '可用'; ffmpegStatus.style.color = '#22c55e'; }
            } else {
                if (dot) dot.style.background = '#ef4444';
                if (text) text.textContent = 'FFmpeg 不可用';
                if (ffmpegStatus) { ffmpegStatus.textContent = '不可用'; ffmpegStatus.style.color = '#ef4444'; }
            }
        })
        .catch(function () {
            var dot = document.getElementById('converter-status-dot');
            var text = document.getElementById('converter-status-text');
            if (dot) dot.style.background = '#ef4444';
            if (text) text.textContent = '检测失败';
        });
}

// 加载格式列表
function converterLoadFormats() {
    fetch('/api/ffmpeg/formats')
        .then(function (r) { return r.json(); })
        .then(function (data) {
            if (data.success) {
                converterState.formats = data.formats;
                document.getElementById('converter-audio-count').textContent = data.formats.audio.length + ' 种';
                document.getElementById('converter-video-count').textContent = data.formats.video.length + ' 种';
                converterSetType('audio', document.querySelector('.converter-type-btn.active'));
            }
        })
        .catch(function () {});
}

// 设置转换类型
function converterSetType(type, btn) {
    converterState.convertType = type;
    document.querySelectorAll('.converter-type-btn').forEach(function (b) { b.classList.remove('active'); });
    if (btn) btn.classList.add('active');

    var grid = document.getElementById('converter-format-grid');
    var startBtn = document.getElementById('converter-start-btn');
    var extractBtn = document.getElementById('converter-extract-btn');
    var bitrateGroup = document.getElementById('converter-bitrate-group');

    if (type === 'extract') {
        // 提取音频 - 不需要选择格式
        grid.innerHTML = '<div class="converter-format-hint"><i class="fas fa-info-circle"></i> 从视频中提取音频，输出为 MP3 格式</div>';
        if (startBtn) startBtn.style.display = 'none';
        if (extractBtn) { extractBtn.style.display = 'inline-flex'; extractBtn.disabled = !converterState.selectedFile; }
        if (bitrateGroup) bitrateGroup.style.display = 'block';
        converterState.targetFormat = 'mp3';
        return;
    }

    if (startBtn) startBtn.style.display = 'inline-flex';
    if (extractBtn) extractBtn.style.display = 'none';
    if (bitrateGroup) bitrateGroup.style.display = type === 'audio' ? 'block' : 'none';

    var formats = type === 'audio' ? converterState.formats.audio : converterState.formats.video;
    if (!formats || formats.length === 0) {
        grid.innerHTML = '<div class="converter-empty">暂无可用格式</div>';
        return;
    }

    grid.innerHTML = '';
    formats.forEach(function (fmt) {
        var btn = document.createElement('button');
        btn.className = 'converter-format-btn' + (fmt.ext === 'mp3' || fmt.ext === 'mp4' ? ' active' : '');
        btn.dataset.ext = fmt.ext;
        btn.innerHTML = '<span class="converter-format-ext">.' + fmt.ext + '</span><span class="converter-format-name">' + fmt.name + '</span>';
        btn.onclick = function () {
            document.querySelectorAll('.converter-format-btn').forEach(function (b) { b.classList.remove('active'); });
            btn.classList.add('active');
            converterState.targetFormat = fmt.ext;
            converterUpdateStartBtn();
        };
        grid.appendChild(btn);

        // 默认选中第一个常见格式
        if (!converterState.targetFormat && (fmt.ext === 'mp3' || fmt.ext === 'mp4')) {
            converterState.targetFormat = fmt.ext;
        }
    });
    converterUpdateStartBtn();
}

// 更新比特率显示
function converterUpdateBitrate(value) {
    converterState.audioBitrate = parseInt(value);
    document.getElementById('converter-bitrate-value').textContent = value + ' kbps';
}

// 更新开始按钮状态
function converterUpdateStartBtn() {
    var btn = document.getElementById('converter-start-btn');
    var extractBtn = document.getElementById('converter-extract-btn');
    btn.disabled = !converterState.selectedFile || !converterState.targetFormat;
    extractBtn.disabled = !converterState.selectedFile;
}

// 选择文件
function converterSelectFile() {
    // 使用 fetch 传输文件选择（通过桌面桥接或原生对话框）
    // 先尝试桌面桥接
    if (window.pywebview && window.pywebview.api) {
        pywebview.api.open_file_dialog().then(function (path) {
            if (path) converterLoadFile(path);
        }).catch(function () {
            converterUseFileInput();
        });
    } else {
        converterUseFileInput();
    }
}

function converterUseFileInput() {
    var input = document.createElement('input');
    input.type = 'file';
    input.accept = 'audio/*,video/*';
    input.onchange = function (e) {
        var file = e.target.files[0];
        if (file) {
            // 通过 API 上传并获取路径
            var formData = new FormData();
            formData.append('file', file);
            fetch('/api/ffmpeg/upload', { method: 'POST', body: formData })
                .then(function (r) { return r.json(); })
                .then(function (data) {
                    if (data.success) {
                        converterLoadFile(data.path);
                    } else {
                        showToast('上传文件失败', 'error');
                    }
                })
                .catch(function () { showToast('上传文件失败', 'error'); });
        }
    };
    input.click();
}

// 加载文件信息
function converterLoadFile(path) {
    if (!path) return;
    converterState.selectedFile = path;
    document.getElementById('converter-file-path').value = path;

    fetch('/api/ffmpeg/file-info?path=' + encodeURIComponent(path))
        .then(function (r) { return r.json(); })
        .then(function (data) {
            if (data.success) {
                converterState.fileInfo = data;
                var infoEl = document.getElementById('converter-file-info');
                infoEl.style.display = 'block';
                document.getElementById('converter-info-filename').textContent = path.split(/[/\\]/).pop() || path;
                document.getElementById('converter-info-format').textContent = (data.format && data.format.format_name) || '未知';
                document.getElementById('converter-info-size').textContent = data.size ? converterFormatSize(data.size) : '未知';
                document.getElementById('converter-info-duration').textContent = data.duration ? converterFormatDuration(data.duration) : '未知';

                // 添加到最近文件
                converterAddRecent(path);
                converterUpdateStartBtn();
            } else {
                showToast('获取文件信息失败: ' + (data.error || '未知错误'), 'error');
            }
        })
        .catch(function () { showToast('获取文件信息失败', 'error'); });
}

// 格式化文件大小
function converterFormatSize(bytes) {
    if (bytes < 1024) return bytes + ' B';
    if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
    if (bytes < 1024 * 1024 * 1024) return (bytes / 1024 / 1024).toFixed(1) + ' MB';
    return (bytes / 1024 / 1024 / 1024).toFixed(2) + ' GB';
}

// 格式化时长
function converterFormatDuration(seconds) {
    var h = Math.floor(seconds / 3600);
    var m = Math.floor((seconds % 3600) / 60);
    var s = Math.floor(seconds % 60);
    if (h > 0) return h + ':' + (m < 10 ? '0' : '') + m + ':' + (s < 10 ? '0' : '') + s;
    return m + ':' + (s < 10 ? '0' : '') + s;
}

// 添加最近文件
function converterAddRecent(path) {
    var list = document.getElementById('converter-recent-list');
    var items = list.querySelectorAll('.converter-recent-item');
    // 检查是否已存在
    for (var i = 0; i < items.length; i++) {
        if (items[i].dataset.path === path) {
            list.insertBefore(items[i], list.firstChild);
            return;
        }
    }

    var item = document.createElement('div');
    item.className = 'converter-recent-item';
    item.dataset.path = path;
    var filename = path.split(/[/\\]/).pop() || path;
    var ext = (filename.split('.').pop() || '').toUpperCase();
    var icon = ['mp3', 'wav', 'flac', 'aac', 'ogg', 'm4a'].indexOf(ext.toLowerCase()) >= 0 ? 'fa-music' : 'fa-video';
    item.innerHTML = '<i class="fas ' + icon + '"></i><span class="converter-recent-name">' + escapeHtml(filename) + '</span><span class="converter-recent-ext">.' + ext.toLowerCase() + '</span>';
    item.onclick = function () { converterLoadFile(path); };
    item.title = path;

    var empty = list.querySelector('.converter-empty');
    if (empty) empty.remove();
    list.insertBefore(item, list.firstChild);

    // 最多保留 10 个
    while (list.children.length > 10) {
        list.removeChild(list.lastChild);
    }
}

// 开始转换
function converterStart() {
    if (!converterState.selectedFile || !converterState.targetFormat) {
        showToast('请先选择文件和目标格式', 'warning');
        return;
    }

    var progressArea = document.getElementById('converter-progress-area');
    var progressFill = document.getElementById('converter-progress-fill');
    var progressText = document.getElementById('converter-progress-text');
    var progressPercent = document.getElementById('converter-progress-percent');
    var detailEl = document.getElementById('converter-progress-detail');
    var startBtn = document.getElementById('converter-start-btn');

    progressArea.style.display = 'block';
    progressFill.style.width = '0%';
    progressText.textContent = '正在转换...';
    progressPercent.textContent = '0%';
    detailEl.textContent = '';
    startBtn.disabled = true;
    startBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> 转换中...';

    fetch('/api/ffmpeg/convert', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            input_path: converterState.selectedFile,
            output_ext: converterState.targetFormat,
            audio_bitrate: converterState.convertType === 'audio' ? converterState.audioBitrate : null,
        }),
    })
    .then(function (r) { return r.json(); })
    .then(function (data) {
        progressFill.style.width = '100%';
        progressPercent.textContent = '100%';
        startBtn.disabled = false;
        startBtn.innerHTML = '<i class="fas fa-play"></i> 开始转换';

        if (data.success) {
            progressText.textContent = '转换完成！';
            detailEl.innerHTML = '<span class="converter-success"><i class="fas fa-check-circle"></i> ' + escapeHtml(data.message) + '</span>';
            converterAddHistory(data);
            showToast('转换完成！', 'success');
        } else {
            progressText.textContent = '转换失败';
            detailEl.innerHTML = '<span class="converter-error"><i class="fas fa-exclamation-circle"></i> ' + escapeHtml(data.error || '未知错误') + '</span>';
            showToast('转换失败: ' + (data.error || '未知错误'), 'error');
        }
    })
    .catch(function (err) {
        progressFill.style.width = '0%';
        progressText.textContent = '转换失败';
        detailEl.innerHTML = '<span class="converter-error"><i class="fas fa-exclamation-circle"></i> 网络错误</span>';
        startBtn.disabled = false;
        startBtn.innerHTML = '<i class="fas fa-play"></i> 开始转换';
        showToast('转换请求失败', 'error');
    });
}

// 提取音频
function converterExtractAudio() {
    if (!converterState.selectedFile) {
        showToast('请先选择文件', 'warning');
        return;
    }

    var progressArea = document.getElementById('converter-progress-area');
    var progressFill = document.getElementById('converter-progress-fill');
    var progressText = document.getElementById('converter-progress-text');
    var progressPercent = document.getElementById('converter-progress-percent');
    var detailEl = document.getElementById('converter-progress-detail');
    var extractBtn = document.getElementById('converter-extract-btn');

    progressArea.style.display = 'block';
    progressFill.style.width = '0%';
    progressText.textContent = '正在提取音频...';
    progressPercent.textContent = '0%';
    detailEl.textContent = '';
    extractBtn.disabled = true;
    extractBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> 提取中...';

    fetch('/api/ffmpeg/extract-audio', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            input_path: converterState.selectedFile,
            output_ext: 'mp3',
            audio_bitrate: converterState.audioBitrate,
        }),
    })
    .then(function (r) { return r.json(); })
    .then(function (data) {
        progressFill.style.width = '100%';
        progressPercent.textContent = '100%';
        extractBtn.disabled = false;
        extractBtn.innerHTML = '<i class="fas fa-volume-up"></i> 提取音频';

        if (data.success) {
            progressText.textContent = '提取完成！';
            detailEl.innerHTML = '<span class="converter-success"><i class="fas fa-check-circle"></i> ' + escapeHtml(data.message) + '</span>';
            converterAddHistory(data);
            showToast('音频提取完成！', 'success');
        } else {
            progressText.textContent = '提取失败';
            detailEl.innerHTML = '<span class="converter-error"><i class="fas fa-exclamation-circle"></i> ' + escapeHtml(data.error || '未知错误') + '</span>';
            showToast('提取失败: ' + (data.error || '未知错误'), 'error');
        }
    })
    .catch(function () {
        progressFill.style.width = '0%';
        progressText.textContent = '提取失败';
        detailEl.innerHTML = '<span class="converter-error"><i class="fas fa-exclamation-circle"></i> 网络错误</span>';
        extractBtn.disabled = false;
        extractBtn.innerHTML = '<i class="fas fa-volume-up"></i> 提取音频';
        showToast('提取请求失败', 'error');
    });
}

// 添加转换历史
function converterAddHistory(data) {
    converterState.history.unshift(data);
    converterRenderHistory();
}

// 渲染转换历史
function converterRenderHistory() {
    var list = document.getElementById('converter-history-list');
    if (converterState.history.length === 0) {
        list.innerHTML = '<div class="converter-empty">暂无转换记录</div>';
        return;
    }
    list.innerHTML = '';
    converterState.history.forEach(function (item) {
        var div = document.createElement('div');
        div.className = 'converter-history-item ' + (item.success ? 'success' : 'error');
        var filename = (item.output_path || item.input_path || '').split(/[/\\]/).pop() || '未知';
        div.innerHTML = '<div class="converter-history-info"><span class="converter-history-name">' + escapeHtml(filename) + '</span><span class="converter-history-status">' + (item.success ? '✓ 成功' : '✗ 失败') + '</span></div>';
        if (item.output_size) {
            div.innerHTML += '<div class="converter-history-size">' + converterFormatSize(item.output_size) + '</div>';
        }
        list.appendChild(div);
    });
}

// 清空转换历史
function converterClearHistory() {
    converterState.history = [];
    converterRenderHistory();
}

// 加载转换历史（从 localStorage）
function converterLoadHistory() {
    try {
        var saved = localStorage.getItem('converter_history');
        if (saved) {
            converterState.history = JSON.parse(saved);
            converterRenderHistory();
        }
    } catch (e) {}
}

// 保存转换历史到 localStorage
function converterSaveHistory() {
    try {
        localStorage.setItem('converter_history', JSON.stringify(converterState.history.slice(0, 50)));
    } catch (e) {}
}

// 覆写 addHistory 以保存到 localStorage
var _origConverterAddHistory = converterAddHistory;
converterAddHistory = function (data) {
    _origConverterAddHistory(data);
    converterSaveHistory();
};

// ==================== AI 教辅（edu） ====================
// 第一期：课件解析入库 / 题库检索 / 解题讲解
// 第二期：随机组卷 / 错题本 / 推题练习

var EDU_QTYPE_LABEL = { choice: '选择题', fill: '填空题', judge: '判断题', answer: '解答题' };
var EDU_STATUS_LABEL = { open: '待复习', reviewing: '复习中', mastered: '已掌握' };

var _eduState = {
    tab: 'questions',
    page: 1,
    pageSize: 20,
    total: 0,
    mistakePage: 1,
    mistakePageSize: 10,
    mistakeTotal: 0,
    lastPaper: null,
    busy: false
};

function eduApi(path, options) {
    return fetch('/api/edu' + path, options).then(function (r) { return r.json(); });
}

function loadEduView() {
    loadEduStats();
    loadEduTags();
    eduLoadSubjects();
    eduSwitchTab(_eduState.tab || 'questions');
}

// ---------- 统计 / 标签 / 学科 ----------

function loadEduStats() {
    var box = document.getElementById('edu-stats');
    if (!box) return;
    eduApi('/stats').then(function (res) {
        var d = (res && res.data) || {};
        var cards = [
            { label: '题库总量', value: d.question_total || 0, unit: '题', icon: 'fa-layer-group' },
            { label: '已含答案', value: d.with_answer || 0, unit: '题', icon: 'fa-circle-check' },
            { label: '课件资料', value: d.course_total || 0, unit: '份', icon: 'fa-file-lines' },
            { label: '知识点', value: d.knowledge_points || 0, unit: '个', icon: 'fa-tags' }
        ];
        var html = '';
        cards.forEach(function (c) {
            html += '<div class="edu-stat-card">' +
                '<i class="fas ' + c.icon + '"></i>' +
                '<div class="edu-stat-value">' + c.value + '<span>' + c.unit + '</span></div>' +
                '<div class="edu-stat-label">' + c.label + '</div>' +
                '</div>';
        });
        box.innerHTML = html;
        var note = (d.by_subject || []).map(function (s) { return s.name + ' ' + s.count; }).join(' · ');
        if (note) {
            box.innerHTML += '<div class="edu-stat-note">学科分布：' + escapeHtml(note) + '</div>';
        }
    }).catch(function () {
        box.innerHTML = '<div class="edu-stat-note">统计加载失败</div>';
    });
}

function loadEduTags() {
    var box = document.getElementById('edu-tags');
    if (!box) return;
    eduApi('/tags?limit=40').then(function (res) {
        var tags = (res && res.data) || [];
        if (!tags.length) { box.innerHTML = ''; return; }
        box.innerHTML = tags.map(function (t) {
            return '<span class="tag" onclick="eduSearchTag(\'' +
                escapeHtml(String(t.name)).replace(/'/g, "\\'") + '\')">' +
                escapeHtml(String(t.name)) + ' (' + t.count + ')</span>';
        }).join('');
    }).catch(function () { box.innerHTML = ''; });
}

function eduSearchTag(name) {
    var input = document.getElementById('edu-search');
    if (input) input.value = name;
    _eduState.page = 1;
    loadEduQuestions();
}

function eduLoadSubjects() {
    var sel = document.getElementById('edu-filter-subject');
    eduApi('/subjects').then(function (res) {
        var list = (res && res.data) || [];
        var html = '<option value="">全部学科</option>';
        list.forEach(function (name) {
            html += '<option value="' + escapeHtml(String(name)) + '">' + escapeHtml(String(name)) + '</option>';
        });
        if (sel) {
            var current = sel.value;
            sel.innerHTML = html;
            if (current) sel.value = current;
        }
        var examSel = document.getElementById('edu-exam-subject');
        if (examSel) {
            var examCurrent = examSel.value;
            examSel.innerHTML = html;
            if (examCurrent) examSel.value = examCurrent;
        }
        var misSel = document.getElementById('edu-mistake-subject');
        if (misSel) {
            var misCurrent = misSel.value;
            misSel.innerHTML = html;
            if (misCurrent) misSel.value = misCurrent;
        }
    }).catch(function () {});
}

// ---------- Tab 切换 ----------

function eduSwitchTab(tab) {
    _eduState.tab = tab || 'questions';
    var tabs = ['questions', 'courses', 'exams', 'mistakes'];
    var panels = {
        questions: document.getElementById('edu-list'),
        courses: document.getElementById('edu-course-list'),
        exams: document.getElementById('edu-exam-panel'),
        mistakes: document.getElementById('edu-mistake-panel')
    };
    tabs.forEach(function (name) {
        var btn = document.getElementById('edu-tab-' + name);
        if (btn) btn.classList.toggle('active', _eduState.tab === name);
        var panel = panels[name];
        if (panel) panel.style.display = _eduState.tab === name ? '' : 'none';
    });
    var pageBar = document.getElementById('edu-page-bar');
    if (pageBar) pageBar.style.display = _eduState.tab === 'questions' ? '' : 'none';
    var filterBar = document.getElementById('edu-filter-bar');
    if (filterBar) filterBar.style.display = _eduState.tab === 'questions' ? '' : 'none';
    var tags = document.getElementById('edu-tags');
    if (tags) tags.style.display = _eduState.tab === 'questions' ? '' : 'none';

    if (_eduState.tab === 'courses') {
        loadEduCourses();
    } else if (_eduState.tab === 'exams') {
        loadEduExams();
    } else if (_eduState.tab === 'mistakes') {
        loadEduMistakeStats();
        loadEduMistakes(1);
    } else {
        loadEduQuestions();
    }
}

// ---------- 题库列表 ----------

function loadEduQuestions(page) {
    if (typeof page === 'number') _eduState.page = page;
    if (_eduState.page < 1) _eduState.page = 1;
    var box = document.getElementById('edu-list');
    if (!box) return;

    var subject = (document.getElementById('edu-filter-subject') || {}).value || '';
    var qtype = (document.getElementById('edu-filter-type') || {}).value || '';
    var difficulty = (document.getElementById('edu-filter-difficulty') || {}).value || '';
    var keyword = (document.getElementById('edu-search') || {}).value || '';

    var params = new URLSearchParams();
    if (subject) params.set('subject', subject);
    if (qtype) params.set('qtype', qtype);
    if (difficulty) params.set('difficulty', difficulty);
    if (keyword.trim()) params.set('keyword', keyword.trim());
    params.set('limit', _eduState.pageSize);
    params.set('offset', (_eduState.page - 1) * _eduState.pageSize);

    box.innerHTML = '<div class="edu-empty">加载中...</div>';
    eduApi('/questions?' + params.toString()).then(function (res) {
        var items = (res && res.data) || [];
        _eduState.total = (res && res.total) || 0;
        renderEduQuestions(items);
        renderEduPageBar();
    }).catch(function () {
        box.innerHTML = '<div class="edu-empty">题库加载失败</div>';
    });
}

function renderEduQuestions(items) {
    var box = document.getElementById('edu-list');
    if (!box) return;
    if (!items.length) {
        box.innerHTML = '<div class="edu-empty">题库暂无题目，可在上方导入课件/作业，或点「手动加题」。</div>';
        return;
    }
    var html = '';
    items.forEach(function (q) {
        var typeLabel = EDU_QTYPE_LABEL[q.qtype] || '解答题';
        var stars = '★'.repeat(q.difficulty) + '☆'.repeat(Math.max(0, 5 - q.difficulty));
        var opts = (q.options || []).map(function (o) {
            return '<div class="edu-option">' + escapeHtml(String(o)) + '</div>';
        }).join('');
        var points = (q.knowledge_points || []).map(function (p) {
            return '<span class="edu-chip">' + escapeHtml(String(p)) + '</span>';
        }).join('');
        html += '<div class="edu-card" id="edu-q-' + q.id + '">' +
            '<div class="edu-card-head">' +
                '<span class="edu-badge">' + typeLabel + '</span>' +
                '<span class="edu-stars" title="难度">' + stars + '</span>' +
                (q.subject ? '<span class="edu-badge soft">' + escapeHtml(String(q.subject)) + '</span>' : '') +
                '<span class="edu-card-spacer"></span>' +
                '<button class="btn btn-sm" onclick="eduSolveQuestion(' + q.id + ')"><i class="fas fa-lightbulb"></i> 讲解</button>' +
                '<button class="btn btn-sm" onclick="eduAddMistake(' + q.id + ')"><i class="fas fa-bookmark"></i> 记错题</button>' +
                '<button class="btn btn-sm" onclick="eduEditQuestion(' + q.id + ')"><i class="fas fa-pen"></i> 编辑</button>' +
                '<button class="btn btn-sm btn-danger" onclick="eduDeleteQuestion(' + q.id + ')"><i class="fas fa-trash"></i></button>' +
            '</div>' +
            '<div class="edu-stem">' + escapeHtml(String(q.stem || '')).replace(/\n/g, '<br>') + '</div>' +
            (opts ? '<div class="edu-options">' + opts + '</div>' : '') +
            (q.answer ? '<div class="edu-answer"><b>答案：</b>' + escapeHtml(String(q.answer)) + '</div>' : '') +
            (q.analysis ? '<details class="edu-details"><summary>解析</summary><div>' +
                escapeHtml(String(q.analysis)).replace(/\n/g, '<br>') + '</div></details>' : '') +
            (points ? '<div class="edu-chips">' + points + '</div>' : '') +
            '</div>';
    });
    box.innerHTML = html;
}

function renderEduPageBar() {
    var bar = document.getElementById('edu-page-bar');
    if (!bar) return;
    var pages = Math.max(1, Math.ceil(_eduState.total / _eduState.pageSize));
    if (_eduState.page > pages) _eduState.page = pages;
    bar.innerHTML = '<span class="edu-page-info">共 ' + _eduState.total + ' 题，第 ' +
        _eduState.page + '/' + pages + ' 页</span>' +
        '<button class="btn btn-sm" onclick="loadEduQuestions(' + (_eduState.page - 1) + ')"' +
        (_eduState.page <= 1 ? ' disabled' : '') + '>上一页</button>' +
        '<button class="btn btn-sm" onclick="loadEduQuestions(' + (_eduState.page + 1) + ')"' +
        (_eduState.page >= pages ? ' disabled' : '') + '>下一页</button>';
}

// ---------- 课件列表 ----------

function loadEduCourses() {
    var box = document.getElementById('edu-course-list');
    if (!box) return;
    box.innerHTML = '<div class="edu-empty">加载中...</div>';
    eduApi('/courses').then(function (res) {
        var items = (res && res.data) || [];
        if (!items.length) {
            box.innerHTML = '<div class="edu-empty">还没有导入过课件，可在上方填本地路径或选择文件导入。</div>';
            return;
        }
        box.innerHTML = items.map(function (c) {
            return '<div class="edu-card">' +
                '<div class="edu-card-head">' +
                    '<span class="edu-badge">' + escapeHtml(String(c.file_type || 'file').toUpperCase()) + '</span>' +
                    (c.subject ? '<span class="edu-badge soft">' + escapeHtml(String(c.subject)) + '</span>' : '') +
                    (c.grade ? '<span class="edu-badge soft">' + escapeHtml(String(c.grade)) + '</span>' : '') +
                    '<span class="edu-card-spacer"></span>' +
                    '<span class="edu-hint">' + (c.question_count || 0) + ' 题</span>' +
                    '<button class="btn btn-sm" onclick="eduDeleteCourse(' + c.id + ')"><i class="fas fa-trash"></i> 删除</button>' +
                '</div>' +
                '<div class="edu-stem">' + escapeHtml(String(c.title || '')) + '</div>' +
                '<div class="edu-hint">' + escapeHtml(String(c.created_at || '')) + ' · ' +
                    escapeHtml(String(c.filename || '')) + '</div>' +
                '</div>';
        }).join('');
    }).catch(function () {
        box.innerHTML = '<div class="edu-empty">课件列表加载失败</div>';
    });
}

// ---------- 导入 ----------

function eduPickFile() {
    var input = document.getElementById('edu-file-input');
    if (input) input.value = '';
    if (input) input.click();
}

function eduImportPath() {
    if (_eduState.busy) return;
    var pathInput = document.getElementById('edu-import-path');
    var path = pathInput ? pathInput.value.trim() : '';
    if (!path) {
        showToast('请先填写课件文件路径，或点「选择文件」', 'error');
        return;
    }
    eduDoImport('/courses/import-path', {
        path: path,
        subject: (document.getElementById('edu-import-subject') || {}).value || '',
        grade: (document.getElementById('edu-import-grade') || {}).value || '',
        max_questions: parseInt((document.getElementById('edu-import-max') || {}).value || '30', 10) || 30
    });
}

function eduUploadFile() {
    if (_eduState.busy) return;
    var input = document.getElementById('edu-file-input');
    if (!input || !input.files || !input.files.length) return;
    var file = input.files[0];
    var form = new FormData();
    form.append('file', file);
    form.append('subject', (document.getElementById('edu-import-subject') || {}).value || '');
    form.append('grade', (document.getElementById('edu-import-grade') || {}).value || '');
    form.append('max_questions', (document.getElementById('edu-import-max') || {}).value || '30');
    eduDoImport('/courses/import', form);
}

function eduDoImport(url, body) {
    _eduState.busy = true;
    var hint = document.getElementById('edu-import-hint');
    if (hint) hint.textContent = '正在解析并抽取题目，请稍候...';
    var options = { method: 'POST' };
    if (body instanceof FormData) {
        options.body = body;
    } else {
        options.headers = { 'Content-Type': 'application/json' };
        options.body = JSON.stringify(body);
    }
    eduApi(url, options).then(function (res) {
        _eduState.busy = false;
        var msg = (res && res.message) || '导入完成';
        if (res && res.success) {
            showToast(msg, 'success');
            if (hint) hint.textContent = msg;
            loadEduStats();
            loadEduTags();
            eduLoadSubjects();
            loadEduQuestions(1);
        } else {
            showToast(msg, 'error');
            if (hint) hint.textContent = msg;
        }
    }).catch(function (e) {
        _eduState.busy = false;
        if (hint) hint.textContent = '导入失败：' + e;
        showToast('导入失败', 'error');
    });
}

// ---------- 手动加题 / 编辑 ----------

function eduShowAddQuestion() {
    var html =
        '<div class="edu-form">' +
        '<label>题干</label><textarea id="edu-new-stem" rows="4" placeholder="粘贴题目内容"></textarea>' +
        '<label>选项（每行一个，非选择题可留空）</label><textarea id="edu-new-options" rows="3" placeholder="A. 选项一\nB. 选项二"></textarea>' +
        '<label>答案</label><input type="text" id="edu-new-answer" placeholder="如 B / 42 / 正确">' +
        '<label>解析（可留空，稍后可用「讲解」生成）</label><textarea id="edu-new-analysis" rows="3"></textarea>' +
        '<div class="edu-form-row">' +
        '<div><label>题型</label><select id="edu-new-type">' +
        '<option value="choice">选择题</option><option value="fill">填空题</option>' +
        '<option value="judge">判断题</option><option value="answer" selected>解答题</option></select></div>' +
        '<div><label>难度</label><select id="edu-new-difficulty">' +
        '<option value="1">1</option><option value="2">2</option><option value="3" selected>3</option>' +
        '<option value="4">4</option><option value="5">5</option></select></div>' +
        '<div><label>学科</label><input type="text" id="edu-new-subject" placeholder="数学"></div>' +
        '</div>' +
        '<label>知识点（逗号分隔）</label><input type="text" id="edu-new-points" placeholder="一元二次方程,判别式">' +
        '</div>';
    showDialog('手动添加题目', html, function () {
        eduSubmitNewQuestion();
    });
}

function eduSubmitNewQuestion() {
    var stem = (document.getElementById('edu-new-stem') || {}).value || '';
    if (!stem.trim()) {
        showToast('题干不能为空', 'error');
        return;
    }
    var options = ((document.getElementById('edu-new-options') || {}).value || '')
        .split('\n').map(function (s) { return s.trim(); }).filter(function (s) { return s; });
    var points = ((document.getElementById('edu-new-points') || {}).value || '')
        .split(/[,，、]/).map(function (s) { return s.trim(); }).filter(function (s) { return s; });
    var payload = {
        stem: stem.trim(),
        options: options,
        answer: (document.getElementById('edu-new-answer') || {}).value || '',
        analysis: (document.getElementById('edu-new-analysis') || {}).value || '',
        qtype: (document.getElementById('edu-new-type') || {}).value || 'answer',
        difficulty: parseInt((document.getElementById('edu-new-difficulty') || {}).value || '3', 10),
        subject: (document.getElementById('edu-new-subject') || {}).value || '',
        knowledge_points: points
    };
    closeDialog();
    eduApi('/questions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
    }).then(function (res) {
        if (res && res.success) {
            showToast('题目已添加', 'success');
            loadEduStats();
            loadEduTags();
            eduLoadSubjects();
            loadEduQuestions(1);
        } else {
            showToast((res && res.message) || '添加失败', 'error');
        }
    }).catch(function () { showToast('添加失败', 'error'); });
}

function eduEditQuestion(id) {
    eduApi('/questions/' + id).then(function (res) {
        var q = (res && res.data) || {};
        if (!q.id) { showToast('题目不存在', 'error'); return; }
        var typeOptions = '';
        Object.keys(EDU_QTYPE_LABEL).forEach(function (k) {
            typeOptions += '<option value="' + k + '"' + (q.qtype === k ? ' selected' : '') + '>' +
                EDU_QTYPE_LABEL[k] + '</option>';
        });
        var diffOptions = '';
        for (var d = 1; d <= 5; d++) {
            diffOptions += '<option value="' + d + '"' + (q.difficulty === d ? ' selected' : '') + '>' + d + '</option>';
        }
        var html =
            '<div class="edu-form">' +
            '<label>题干</label><textarea id="edu-edit-stem" rows="4">' + escapeHtml(String(q.stem || '')) + '</textarea>' +
            '<label>选项（每行一个）</label><textarea id="edu-edit-options" rows="3">' +
                escapeHtml((q.options || []).join('\n')) + '</textarea>' +
            '<label>答案</label><input type="text" id="edu-edit-answer" value="' + escapeHtml(String(q.answer || '')) + '">' +
            '<label>解析</label><textarea id="edu-edit-analysis" rows="4">' + escapeHtml(String(q.analysis || '')) + '</textarea>' +
            '<div class="edu-form-row">' +
            '<div><label>题型</label><select id="edu-edit-type">' + typeOptions + '</select></div>' +
            '<div><label>难度</label><select id="edu-edit-difficulty">' + diffOptions + '</select></div>' +
            '<div><label>学科</label><input type="text" id="edu-edit-subject" value="' + escapeHtml(String(q.subject || '')) + '"></div>' +
            '</div>' +
            '<label>知识点（逗号分隔）</label><input type="text" id="edu-edit-points" value="' +
                escapeHtml((q.knowledge_points || []).join(',')) + '">' +
            '</div>';
        showDialog('编辑题目 #' + id, html, function () {
            var patch = {
                stem: (document.getElementById('edu-edit-stem') || {}).value || '',
                options: ((document.getElementById('edu-edit-options') || {}).value || '')
                    .split('\n').map(function (s) { return s.trim(); }).filter(function (s) { return s; }),
                answer: (document.getElementById('edu-edit-answer') || {}).value || '',
                analysis: (document.getElementById('edu-edit-analysis') || {}).value || '',
                qtype: (document.getElementById('edu-edit-type') || {}).value || 'answer',
                difficulty: parseInt((document.getElementById('edu-edit-difficulty') || {}).value || '3', 10),
                subject: (document.getElementById('edu-edit-subject') || {}).value || '',
                knowledge_points: ((document.getElementById('edu-edit-points') || {}).value || '')
                    .split(/[,，、]/).map(function (s) { return s.trim(); }).filter(function (s) { return s; })
            };
            closeDialog();
            eduApi('/questions/' + id, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(patch)
            }).then(function (r2) {
                if (r2 && r2.success) {
                    showToast('题目已更新', 'success');
                    loadEduTags();
                    eduLoadSubjects();
                    loadEduQuestions();
                } else {
                    showToast((r2 && r2.message) || '更新失败', 'error');
                }
            }).catch(function () { showToast('更新失败', 'error'); });
        });
    }).catch(function () { showToast('读取题目失败', 'error'); });
}

// ---------- 解题讲解 ----------

function eduSolveQuestion(id, save) {
    showToast('正在生成讲解...', 'info');
    eduApi('/solve', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ question_id: id, save: !!save })
    }).then(function (res) {
        eduShowSolveResult('题目 #' + id + ' 讲解', res);
        if (res && res.success && res.saved) {
            loadEduQuestions();
        }
    }).catch(function () { showToast('讲解失败', 'error'); });
}

function eduShowSolveText() {
    var html = '<div class="edu-form">' +
        '<label>粘贴题目（可含选项）</label>' +
        '<textarea id="edu-solve-text" rows="6" placeholder="把题目直接粘进来，点确定即出讲解"></textarea>' +
        '<label>学科（可留空）</label><input type="text" id="edu-solve-subject" placeholder="数学">' +
        '</div>';
    showDialog('随手解题', html, function () {
        var text = (document.getElementById('edu-solve-text') || {}).value || '';
        if (!text.trim()) { showToast('请输入题目', 'error'); return; }
        var subject = (document.getElementById('edu-solve-subject') || {}).value || '';
        closeDialog();
        showToast('正在生成讲解...', 'info');
        eduApi('/solve', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ text: text, subject: subject })
        }).then(function (res) {
            eduShowSolveResult('解题讲解', res);
        }).catch(function () { showToast('讲解失败', 'error'); });
    });
}

function eduShowSolveResult(title, res) {
    if (!res || !res.success) {
        showDialog(title, '<div class="edu-empty">' + escapeHtml((res && res.message) || '讲解失败') + '</div>');
        return;
    }
    var html = '';
    if (res.answer) {
        html += '<div class="edu-result-block"><div class="edu-result-title">参考答案</div><div>' +
            escapeHtml(String(res.answer)).replace(/\n/g, '<br>') + '</div></div>';
    }
    if (res.steps && res.steps.length) {
        html += '<div class="edu-result-block"><div class="edu-result-title">解题步骤</div><ol class="edu-steps">' +
            res.steps.map(function (s) { return '<li>' + escapeHtml(String(s)) + '</li>'; }).join('') + '</ol></div>';
    }
    if (res.analysis) {
        html += '<div class="edu-result-block"><div class="edu-result-title">讲解</div><div>' +
            escapeHtml(String(res.analysis)).replace(/\n/g, '<br>') + '</div></div>';
    }
    if (res.knowledge_points && res.knowledge_points.length) {
        html += '<div class="edu-result-block"><div class="edu-result-title">知识点</div><div class="edu-chips">' +
            res.knowledge_points.map(function (k) { return '<span class="edu-chip">' + escapeHtml(String(k)) + '</span>'; }).join('') +
            '</div></div>';
    }
    if (res.mistakes) {
        html += '<div class="edu-result-block"><div class="edu-result-title">易错点</div><div>' +
            escapeHtml(String(res.mistakes)).replace(/\n/g, '<br>') + '</div></div>';
    }
    if (!html) {
        html = '<div class="edu-empty">模型未返回可用内容：' + escapeHtml(String(res.message || '')) + '</div>';
    }
    showDialog(title, html);
}

// ---------- 删除 ----------

function eduDeleteQuestion(id) {
    showDialog('删除题目', '<div>确定删除题目 #' + id + ' 吗？此操作不可恢复。</div>', function () {
        closeDialog();
        eduApi('/questions/' + id, { method: 'DELETE' }).then(function (res) {
            if (res && res.success) {
                showToast('题目已删除', 'success');
                loadEduStats();
                loadEduTags();
                loadEduQuestions();
            } else {
                showToast((res && res.message) || '删除失败', 'error');
            }
        }).catch(function () { showToast('删除失败', 'error'); });
    });
}

function eduDeleteCourse(id) {
    showDialog('删除课件', '<div>删除课件 #' + id + ' 会同时删除它导入的题目，确定继续吗？</div>', function () {
        closeDialog();
        eduApi('/courses/' + id, { method: 'DELETE' }).then(function (res) {
            if (res && res.success) {
                showToast((res && res.message) || '课件已删除', 'success');
                loadEduStats();
                loadEduTags();
                eduLoadSubjects();
                loadEduCourses();
            } else {
                showToast((res && res.message) || '删除失败', 'error');
            }
        }).catch(function () { showToast('删除失败', 'error'); });
    });
}

// ==================== 第二期：通用渲染 ====================

function eduStars(level) {
    var n = parseInt(level || 3, 10) || 3;
    n = Math.max(1, Math.min(5, n));
    return '★'.repeat(n) + '☆'.repeat(5 - n);
}

function eduRenderQuestionCard(q, extraButtons) {
    var typeLabel = EDU_QTYPE_LABEL[q.qtype] || '解答题';
    var opts = (q.options || []).map(function (o) {
        return '<div class="edu-option">' + escapeHtml(String(o)) + '</div>';
    }).join('');
    var points = (q.knowledge_points || []).map(function (p) {
        return '<span class="edu-chip">' + escapeHtml(String(p)) + '</span>';
    }).join('');
    return '<div class="edu-card">' +
        '<div class="edu-card-head">' +
            '<span class="edu-badge">' + typeLabel + '</span>' +
            '<span class="edu-stars" title="难度">' + eduStars(q.difficulty) + '</span>' +
            (q.score ? '<span class="edu-badge soft">' + q.score + ' 分</span>' : '') +
            (q.subject ? '<span class="edu-badge soft">' + escapeHtml(String(q.subject)) + '</span>' : '') +
            '<span class="edu-card-spacer"></span>' +
            (extraButtons || '') +
        '</div>' +
        '<div class="edu-stem">' + escapeHtml(String(q.stem || '')).replace(/\n/g, '<br>') + '</div>' +
        (opts ? '<div class="edu-options">' + opts + '</div>' : '') +
        (q.answer ? '<div class="edu-answer"><b>答案：</b>' + escapeHtml(String(q.answer)) + '</div>' : '') +
        (q.analysis ? '<details class="edu-details"><summary>解析</summary><div>' +
            escapeHtml(String(q.analysis)).replace(/\n/g, '<br>') + '</div></details>' : '') +
        (points ? '<div class="edu-chips">' + points + '</div>' : '') +
        '</div>';
}

// ==================== 第二期：错题本 ====================

function loadEduMistakeStats() {
    var box = document.getElementById('edu-mistake-stats');
    eduApi('/mistakes/stats').then(function (res) {
        var d = (res && res.data) || {};
        if (box) {
            var cards = [
                { label: '错题总量', value: d.mistake_total || 0, unit: '题', icon: 'fa-bookmark' },
                { label: '待复习', value: d.open_total || 0, unit: '题', icon: 'fa-clock' },
                { label: '复习中', value: d.reviewing_total || 0, unit: '题', icon: 'fa-rotate' },
                { label: '已掌握', value: d.mastered_total || 0, unit: '题', icon: 'fa-circle-check' },
                { label: '掌握率', value: d.mastery_rate || 0, unit: '%', icon: 'fa-chart-line' }
            ];
            box.innerHTML = cards.map(function (c) {
                return '<div class="edu-stat-card"><i class="fas ' + c.icon + '"></i>' +
                    '<div class="edu-stat-value">' + c.value + '<span>' + c.unit + '</span></div>' +
                    '<div class="edu-stat-label">' + c.label + '</div></div>';
            }).join('');
        }
        loadEduWeakPoints();
    }).catch(function () { if (box) box.innerHTML = '<div class="edu-stat-note">统计加载失败</div>'; });
}

function loadEduWeakPoints() {
    var box = document.getElementById('edu-weak-points');
    if (!box) return;
    var subject = (document.getElementById('edu-mistake-subject') || {}).value || '';
    var params = new URLSearchParams();
    if (subject) params.set('subject', subject);
    params.set('limit', 20);
    eduApi('/mistakes/weak-points?' + params.toString()).then(function (res) {
        var list = (res && res.data) || [];
        if (!list.length) { box.innerHTML = ''; return; }
        box.innerHTML = '<span class="edu-hint">薄弱知识点：</span>' + list.map(function (w) {
            return '<span class="tag" onclick="eduFilterByPoint(\'' +
                escapeHtml(String(w.name)).replace(/'/g, "\\'") + '\')">' +
                escapeHtml(String(w.name)) + ' (' + w.count + ')</span>';
        }).join('');
    }).catch(function () { box.innerHTML = ''; });
}

function eduFilterByPoint(name) {
    var input = document.getElementById('edu-mistake-search');
    if (input) input.value = name;
    loadEduMistakes(1);
}

function loadEduMistakes(page) {
    if (typeof page === 'number') _eduState.mistakePage = page;
    if (_eduState.mistakePage < 1) _eduState.mistakePage = 1;
    var box = document.getElementById('edu-mistake-list');
    if (!box) return;

    var params = new URLSearchParams();
    var subject = (document.getElementById('edu-mistake-subject') || {}).value || '';
    var status = (document.getElementById('edu-mistake-status') || {}).value || '';
    var keyword = ((document.getElementById('edu-mistake-search') || {}).value || '').trim();
    if (subject) params.set('subject', subject);
    if (status) params.set('status', status);
    if (keyword) params.set('keyword', keyword);
    params.set('limit', _eduState.mistakePageSize);
    params.set('offset', (_eduState.mistakePage - 1) * _eduState.mistakePageSize);

    box.innerHTML = '<div class="edu-empty">加载中...</div>';
    eduApi('/mistakes?' + params.toString()).then(function (res) {
        var items = (res && res.data) || [];
        _eduState.mistakeTotal = (res && res.total) || 0;
        renderEduMistakes(items);
        renderEduMistakePageBar();
    }).catch(function () {
        box.innerHTML = '<div class="edu-empty">错题本加载失败</div>';
    });
}

function renderEduMistakes(items) {
    var box = document.getElementById('edu-mistake-list');
    if (!box) return;
    if (!items.length) {
        box.innerHTML = '<div class="edu-empty">错题本还是空的。可在「题库」里点题目的「记错题」，或做完练习后把错题标记进来。</div>';
        return;
    }
    var html = '';
    items.forEach(function (m) {
        var status = m.status || 'open';
        var statusLabel = EDU_STATUS_LABEL[status] || '待复习';
        var cls = status === 'mastered' ? 'edu-badge ok' : (status === 'reviewing' ? 'edu-badge warn' : 'edu-badge');
        var points = (m.knowledge_points || []).map(function (p) {
            return '<span class="edu-chip">' + escapeHtml(String(p)) + '</span>';
        }).join('');
        var buttons =
            (status !== 'mastered'
                ? '<button class="btn btn-sm btn-primary" onclick="eduReviewMistake(' + m.id + ', \'correct\')"><i class="fas fa-check"></i> 做对了</button>' +
                  '<button class="btn btn-sm" onclick="eduReviewMistake(' + m.id + ', \'wrong\')"><i class="fas fa-xmark"></i> 又错了</button>'
                : '<button class="btn btn-sm" onclick="eduReviewMistake(' + m.id + ', \'wrong\')"><i class="fas fa-rotate-left"></i> 重练</button>') +
            (m.question_id ? '<button class="btn btn-sm" onclick="eduSolveQuestion(' + m.question_id + ')"><i class="fas fa-lightbulb"></i> 讲解</button>' : '') +
            '<button class="btn btn-sm" onclick="eduEditMistake(' + m.id + ')"><i class="fas fa-pen"></i> 编辑</button>' +
            '<button class="btn btn-sm btn-danger" onclick="eduDeleteMistake(' + m.id + ')"><i class="fas fa-trash"></i></button>';

        html += '<div class="edu-card">' +
            '<div class="edu-card-head">' +
                '<span class="' + cls + '">' + statusLabel + '</span>' +
                '<span class="edu-badge soft">' + (EDU_QTYPE_LABEL[m.qtype] || '解答题') + '</span>' +
                '<span class="edu-stars" title="难度">' + eduStars(m.difficulty) + '</span>' +
                (m.subject ? '<span class="edu-badge soft">' + escapeHtml(String(m.subject)) + '</span>' : '') +
                '<span class="edu-card-spacer"></span>' + buttons +
            '</div>' +
            '<div class="edu-stem">' + escapeHtml(String(m.stem || '')).replace(/\n/g, '<br>') + '</div>' +
            ((m.options || []).length
                ? '<div class="edu-options">' + m.options.map(function (o) {
                    return '<div class="edu-option">' + escapeHtml(String(o)) + '</div>';
                  }).join('') + '</div>'
                : '') +
            (m.wrong_answer ? '<div class="edu-answer wrong"><b>我的错答：</b>' + escapeHtml(String(m.wrong_answer)) + '</div>' : '') +
            (m.correct_answer ? '<div class="edu-answer"><b>正确答案：</b>' + escapeHtml(String(m.correct_answer)) + '</div>' : '') +
            (m.analysis ? '<details class="edu-details"><summary>解析</summary><div>' +
                escapeHtml(String(m.analysis)).replace(/\n/g, '<br>') + '</div></details>' : '') +
            (points ? '<div class="edu-chips">' + points + '</div>' : '') +
            '<div class="edu-hint">复习 ' + (m.review_count || 0) + ' 次 · 连对 ' + (m.correct_streak || 0) +
                (m.note ? ' · 备注：' + escapeHtml(String(m.note)) : '') + '</div>' +
            '</div>';
    });
    box.innerHTML = html;
}

function renderEduMistakePageBar() {
    var bar = document.getElementById('edu-mistake-page-bar');
    if (!bar) return;
    var pages = Math.max(1, Math.ceil(_eduState.mistakeTotal / _eduState.mistakePageSize));
    if (_eduState.mistakePage > pages) _eduState.mistakePage = pages;
    bar.innerHTML = '<span class="edu-page-info">共 ' + _eduState.mistakeTotal + ' 道错题，第 ' +
        _eduState.mistakePage + '/' + pages + ' 页</span>' +
        '<button class="btn btn-sm" onclick="loadEduMistakes(' + (_eduState.mistakePage - 1) + ')"' +
        (_eduState.mistakePage <= 1 ? ' disabled' : '') + '>上一页</button>' +
        '<button class="btn btn-sm" onclick="loadEduMistakes(' + (_eduState.mistakePage + 1) + ')"' +
        (_eduState.mistakePage >= pages ? ' disabled' : '') + '>下一页</button>';
}

function eduAddMistake(qid) {
    var html = '<div class="edu-form">' +
        '<label>我的错答（可留空）</label><input type="text" id="edu-mis-wrong" placeholder="例如选了 C，正确答案是 B">' +
        '<label>备注（错在哪，可留空）</label><textarea id="edu-mis-note" rows="3" placeholder="概念混淆 / 计算失误 / 审题不清"></textarea>' +
        '</div>';
    showDialog('把题目 #' + qid + ' 记入错题本', html, function () {
        var wrong = (document.getElementById('edu-mis-wrong') || {}).value || '';
        var note = (document.getElementById('edu-mis-note') || {}).value || '';
        closeDialog();
        eduApi('/mistakes/from-question', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ question_id: qid, wrong_answer: wrong, note: note })
        }).then(function (res) {
            if (res && res.success) {
                showToast(res.message || '已加入错题本', 'success');
                if (_eduState.tab === 'mistakes') { loadEduMistakeStats(); loadEduMistakes(1); }
            } else {
                showToast((res && res.message) || '加入失败', 'error');
            }
        }).catch(function () { showToast('加入失败', 'error'); });
    });
}

function eduReviewMistake(id, result) {
    eduApi('/mistakes/' + id + '/review', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ result: result })
    }).then(function (res) {
        if (res && res.success) {
            showToast(res.message || '已记录', 'success');
            loadEduMistakeStats();
            loadEduMistakes();
        } else {
            showToast((res && res.message) || '打卡失败', 'error');
        }
    }).catch(function () { showToast('打卡失败', 'error'); });
}

function eduEditMistake(id) {
    eduApi('/mistakes/' + id).then(function (res) {
        var m = (res && res.data) || {};
        if (!m.id) { showToast('错题不存在', 'error'); return; }
        var statusOptions = '';
        ['open', 'reviewing', 'mastered'].forEach(function (k) {
            statusOptions += '<option value="' + k + '"' + (m.status === k ? ' selected' : '') + '>' +
                EDU_STATUS_LABEL[k] + '</option>';
        });
        var html = '<div class="edu-form">' +
            '<label>题干</label><textarea id="edu-mis-edit-stem" rows="3">' + escapeHtml(String(m.stem || '')) + '</textarea>' +
            '<label>我的错答</label><input type="text" id="edu-mis-edit-wrong" value="' + escapeHtml(String(m.wrong_answer || '')) + '">' +
            '<label>正确答案</label><input type="text" id="edu-mis-edit-right" value="' + escapeHtml(String(m.correct_answer || '')) + '">' +
            '<label>解析</label><textarea id="edu-mis-edit-analysis" rows="4">' + escapeHtml(String(m.analysis || '')) + '</textarea>' +
            '<div class="edu-form-row">' +
            '<div><label>状态</label><select id="edu-mis-edit-status">' + statusOptions + '</select></div>' +
            '<div><label>学科</label><input type="text" id="edu-mis-edit-subject" value="' + escapeHtml(String(m.subject || '')) + '"></div>' +
            '<div><label>难度</label><select id="edu-mis-edit-diff">' +
            [1, 2, 3, 4, 5].map(function (d) {
                return '<option value="' + d + '"' + (m.difficulty === d ? ' selected' : '') + '>' + d + '</option>';
            }).join('') + '</select></div>' +
            '</div>' +
            '<label>知识点（逗号分隔）</label><input type="text" id="edu-mis-edit-points" value="' +
                escapeHtml((m.knowledge_points || []).join(',')) + '">' +
            '<label>备注</label><textarea id="edu-mis-edit-note" rows="2">' + escapeHtml(String(m.note || '')) + '</textarea>' +
            '</div>';
        showDialog('编辑错题 #' + id, html, function () {
            var patch = {
                stem: (document.getElementById('edu-mis-edit-stem') || {}).value || '',
                wrong_answer: (document.getElementById('edu-mis-edit-wrong') || {}).value || '',
                correct_answer: (document.getElementById('edu-mis-edit-right') || {}).value || '',
                analysis: (document.getElementById('edu-mis-edit-analysis') || {}).value || '',
                subject: (document.getElementById('edu-mis-edit-subject') || {}).value || '',
                status: (document.getElementById('edu-mis-edit-status') || {}).value || 'open',
                difficulty: parseInt((document.getElementById('edu-mis-edit-diff') || {}).value || '3', 10),
                knowledge_points: ((document.getElementById('edu-mis-edit-points') || {}).value || '')
                    .split(/[,，、]/).map(function (s) { return s.trim(); }).filter(function (s) { return s; }),
                note: (document.getElementById('edu-mis-edit-note') || {}).value || ''
            };
            closeDialog();
            eduApi('/mistakes/' + id, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(patch)
            }).then(function (r2) {
                if (r2 && r2.success) {
                    showToast('错题已更新', 'success');
                    loadEduMistakeStats();
                    loadEduMistakes();
                } else {
                    showToast((r2 && r2.message) || '更新失败', 'error');
                }
            }).catch(function () { showToast('更新失败', 'error'); });
        });
    }).catch(function () { showToast('读取错题失败', 'error'); });
}

function eduDeleteMistake(id) {
    showDialog('删除错题', '<div>确定从错题本删除记录 #' + id + ' 吗？</div>', function () {
        closeDialog();
        eduApi('/mistakes/' + id, { method: 'DELETE' }).then(function (res) {
            if (res && res.success) {
                showToast('错题已删除', 'success');
                loadEduMistakeStats();
                loadEduMistakes();
            } else {
                showToast((res && res.message) || '删除失败', 'error');
            }
        }).catch(function () { showToast('删除失败', 'error'); });
    });
}

// ==================== 第二期：推题练习 ====================

function eduShowPractice() {
    var subject = (document.getElementById('edu-mistake-subject') || {}).value || '';
    var params = new URLSearchParams();
    if (subject) params.set('subject', subject);
    params.set('limit', 5);
    showToast('正在生成针对性练习...', 'info');
    eduApi('/practice?' + params.toString(), { method: 'POST' }).then(function (res) {
        if (!res || !res.success) {
            showDialog('推题练习', '<div class="edu-empty">' + escapeHtml((res && res.message) || '推题失败') + '</div>');
            return;
        }
        var items = res.items || [];
        var html = '';
        if (res.summary) {
            html += '<div class="edu-result-block"><div class="edu-result-title">学情点评</div><div>' +
                escapeHtml(String(res.summary)) + '</div></div>';
        }
        if ((res.focus_points || []).length) {
            html += '<div class="edu-result-block"><div class="edu-result-title">优先攻克</div><div class="edu-chips">' +
                res.focus_points.map(function (p) {
                    return '<span class="edu-chip">' + escapeHtml(String(p)) + '</span>';
                }).join('') + '</div></div>';
        }
        if ((res.advice || []).length) {
            html += '<div class="edu-result-block"><div class="edu-result-title">学习建议</div><ol class="edu-steps">' +
                res.advice.map(function (a) { return '<li>' + escapeHtml(String(a)) + '</li>'; }).join('') + '</ol></div>';
        }
        if ((res.weak_points || []).length) {
            html += '<div class="edu-result-block"><div class="edu-result-title">薄弱知识点</div><div class="edu-chips">' +
                res.weak_points.map(function (w) {
                    return '<span class="edu-chip">' + escapeHtml(String(w.name)) + ' ×' + w.count + '</span>';
                }).join('') + '</div></div>';
        }
        html += '<div class="edu-result-block"><div class="edu-result-title">针对性练习（' + items.length + ' 题）</div>' +
            (items.length
                ? items.map(function (q) {
                    return eduRenderQuestionCard(q,
                        '<button class="btn btn-sm" onclick="eduSolveQuestion(' + q.id + ')"><i class="fas fa-lightbulb"></i> 讲解</button>' +
                        '<button class="btn btn-sm" onclick="eduAddMistake(' + q.id + ')"><i class="fas fa-bookmark"></i> 记错题</button>');
                  }).join('')
                : '<div class="edu-empty">题库中暂时没有可推的新题，先导入更多课件吧。</div>') +
            '</div>';
        showDialog('推题练习', html);
    }).catch(function () { showToast('推题失败', 'error'); });
}

// ==================== 掌握度概览 / 针对性推题 ====================

function eduLoadMastery() {
    var box = document.getElementById('edu-mastery-out');
    if (!box) return;
    var subject = ((document.getElementById('edu-rec-subject') || {}).value || '').trim();
    var params = new URLSearchParams();
    if (subject) params.set('subject', subject);
    box.innerHTML = '<div class="edu-empty">正在统计掌握度...</div>';
    eduApi('/mastery?' + params.toString()).then(function (res) {
        if (!res || !res.success) {
            box.innerHTML = '<div class="edu-hint is-error">' + escapeHtml((res && res.message) || '获取掌握度失败') + '</div>';
            return;
        }
        var d = res.data || {};
        var cards = [
            { label: '错题总量', value: d.mistake_total || 0, unit: '题', icon: 'fa-bookmark' },
            { label: '待复习', value: d.open_total || 0, unit: '题', icon: 'fa-clock' },
            { label: '已掌握', value: d.mastered_total || 0, unit: '题', icon: 'fa-circle-check' },
            { label: '掌握率', value: d.mastery_rate || 0, unit: '%', icon: 'fa-chart-line' }
        ];
        var html = '<div class="edu-stats">';
        cards.forEach(function (c) {
            html += '<div class="edu-stat-card"><i class="fas ' + c.icon + '"></i>' +
                '<div class="edu-stat-value">' + c.value + '<span>' + c.unit + '</span></div>' +
                '<div class="edu-stat-label">' + c.label + '</div></div>';
        });
        html += '</div>';
        var bySubject = d.by_subject || [];
        if (bySubject.length) {
            html += '<div class="edu-result-block"><div class="edu-result-title">分学科掌握度</div>' +
                bySubject.map(function (s) {
                    var rate = Math.max(0, Math.min(100, parseInt(s.mastery_rate || 0, 10) || 0));
                    return '<div class="edu-mastery-row">' +
                        '<span class="edu-mastery-name">' + escapeHtml(String(s.subject || '未分类')) + '</span>' +
                        '<div class="edu-mastery-bar"><i style="width:' + rate + '%"></i></div>' +
                        '<span class="edu-mastery-val">' + rate + '% · ' + (s.mastered || 0) + '/' + (s.total || 0) + '</span>' +
                        '</div>';
                }).join('') + '</div>';
        }
        var weak = d.weak_points || [];
        if (weak.length) {
            html += '<div class="edu-result-block"><div class="edu-result-title">薄弱知识点</div><div class="edu-chips">' +
                weak.map(function (w) {
                    return '<span class="edu-chip" onclick="eduFilterByPoint(\'' +
                        escapeHtml(String(w.name)).replace(/'/g, "\\'") + '\')">' +
                        escapeHtml(String(w.name)) + ' ×' + (w.count || 0) + '</span>';
                }).join('') + '</div></div>';
        }
        box.innerHTML = html;
    }).catch(function () {
        box.innerHTML = '<div class="edu-hint is-error">获取掌握度失败</div>';
    });
}

function eduLoadRecommend() {
    var box = document.getElementById('edu-recommend-out');
    if (!box) return;
    var subject = ((document.getElementById('edu-rec-subject') || {}).value || '').trim();
    var limit = parseInt((document.getElementById('edu-rec-limit') || {}).value || '5', 10) || 5;
    var params = new URLSearchParams();
    if (subject) params.set('subject', subject);
    params.set('limit', limit);
    box.innerHTML = '<div class="edu-empty">正在挑题...</div>';
    eduApi('/recommend?' + params.toString()).then(function (res) {
        if (!res || !res.success) {
            box.innerHTML = '<div class="edu-hint is-error">' + escapeHtml((res && res.message) || '推题失败') + '</div>';
            return;
        }
        var items = res.data || [];
        var html = '';
        if (res.reason) {
            html += '<div class="edu-hint">' + escapeHtml(String(res.reason)) + '</div>';
        }
        if ((res.focus_points || []).length) {
            html += '<div class="edu-chips">' + res.focus_points.map(function (p) {
                return '<span class="edu-chip">' + escapeHtml(String(p)) + '</span>';
            }).join('') + '</div>';
        }
        html += items.length
            ? items.map(function (q) {
                return eduRenderQuestionCard(q,
                    '<button class="btn btn-sm" onclick="eduSolveQuestion(' + q.id + ')"><i class="fas fa-lightbulb"></i> 讲解</button>' +
                    '<button class="btn btn-sm" onclick="eduAddMistake(' + q.id + ')"><i class="fas fa-bookmark"></i> 记错题</button>');
              }).join('')
            : '<div class="edu-empty">暂时没有可推的新题，先导入更多课件，或减少错题重复。</div>';
        box.innerHTML = html;
    }).catch(function () {
        box.innerHTML = '<div class="edu-hint is-error">推题失败</div>';
    });
}

// ==================== 解析预览（只抽取不入库） ====================

function eduPreviewExtract() {
    var box = document.getElementById('edu-preview-out');
    if (!box) return;
    var path = ((document.getElementById('edu-import-path') || {}).value || '').trim();
    if (!path) {
        showToast('请先填写本地文件路径', 'error');
        return;
    }
    var payload = {
        path: path,
        subject: (document.getElementById('edu-import-subject') || {}).value || '',
        grade: (document.getElementById('edu-import-grade') || {}).value || '',
        max_questions: parseInt((document.getElementById('edu-import-max') || {}).value || '30', 10) || 30
    };
    box.innerHTML = '<div class="edu-empty">正在解析预览，不会写入题库...</div>';
    eduApi('/extract-preview', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
    }).then(function (res) {
        if (!res || !res.success) {
            box.innerHTML = '<div class="edu-hint is-error">' + escapeHtml((res && res.message) || '解析失败') + '</div>';
            return;
        }
        var items = res.questions || [];
        if (!items.length) {
            box.innerHTML = '<div class="edu-empty">没有抽到题目，换个文件或调整导出格式再试。</div>';
            return;
        }
        var head = '<div class="edu-result-block"><div class="edu-result-title">解析预览：抽到 ' + items.length +
            ' 题（未入库）</div>' +
            (res.engine ? '<div class="edu-hint">抽取方式：' +
                (res.engine === 'llm' ? 'AI 模型抽取' : '题号启发式抽取') + '</div>' : '');
        box.innerHTML = head + items.map(function (q) {
            return eduRenderQuestionCard(q, '');
        }).join('') + '</div>';
    }).catch(function () {
        box.innerHTML = '<div class="edu-hint is-error">解析失败</div>';
    });
}

// ==================== 手动加错题 ====================

function eduShowAddMistake() {
    var typeOptions = '<option value="choice">选择题</option><option value="fill">填空题</option>' +
        '<option value="judge">判断题</option><option value="answer" selected>解答题</option>';
    var diffOptions = [1, 2, 3, 4, 5].map(function (d) {
        return '<option value="' + d + '"' + (d === 3 ? ' selected' : '') + '>' + d + '</option>';
    }).join('');
    var html =
        '<div class="edu-form">' +
        '<label>题干</label><textarea id="edu-mis-new-stem" rows="4" placeholder="粘贴错题内容"></textarea>' +
        '<label>选项（每行一个，非选择题可留空）</label><textarea id="edu-mis-new-options" rows="3"></textarea>' +
        '<label>我的错答</label><input type="text" id="edu-mis-new-wrong" placeholder="如选了 C">' +
        '<label>正确答案</label><input type="text" id="edu-mis-new-right" placeholder="如 B">' +
        '<label>解析（可留空，稍后可用「讲解」生成）</label><textarea id="edu-mis-new-analysis" rows="3"></textarea>' +
        '<div class="edu-form-row">' +
        '<div><label>学科</label><input type="text" id="edu-mis-new-subject" placeholder="数学"></div>' +
        '<div><label>难度</label><select id="edu-mis-new-difficulty">' + diffOptions + '</select></div>' +
        '<div><label>题型</label><select id="edu-mis-new-type">' + typeOptions + '</select></div>' +
        '</div>' +
        '<label>知识点（逗号分隔）</label><input type="text" id="edu-mis-new-points" placeholder="一元二次方程,判别式">' +
        '<label>备注</label><textarea id="edu-mis-new-note" rows="2" placeholder="概念混淆 / 计算失误 / 审题不清"></textarea>' +
        '</div>';
    showDialog('手动添加错题', html, function () {
        var stem = ((document.getElementById('edu-mis-new-stem') || {}).value || '').trim();
        if (!stem) {
            showToast('题干不能为空', 'error');
            return;
        }
        var payload = {
            stem: stem,
            options: ((document.getElementById('edu-mis-new-options') || {}).value || '')
                .split('\n').map(function (s) { return s.trim(); }).filter(function (s) { return s; }),
            wrong_answer: (document.getElementById('edu-mis-new-wrong') || {}).value || '',
            correct_answer: (document.getElementById('edu-mis-new-right') || {}).value || '',
            analysis: (document.getElementById('edu-mis-new-analysis') || {}).value || '',
            qtype: (document.getElementById('edu-mis-new-type') || {}).value || 'answer',
            difficulty: parseInt((document.getElementById('edu-mis-new-difficulty') || {}).value || '3', 10),
            subject: (document.getElementById('edu-mis-new-subject') || {}).value || '',
            knowledge_points: ((document.getElementById('edu-mis-new-points') || {}).value || '')
                .split(/[,，、]/).map(function (s) { return s.trim(); }).filter(function (s) { return s; }),
            note: (document.getElementById('edu-mis-new-note') || {}).value || '',
            source: 'manual'
        };
        closeDialog();
        eduApi('/mistakes', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        }).then(function (res) {
            if (res && res.success) {
                showToast(res.message || '已加入错题本', 'success');
                loadEduMistakeStats();
                loadEduMistakes(1);
            } else {
                showToast((res && res.message) || '添加失败', 'error');
            }
        }).catch(function () { showToast('添加失败', 'error'); });
    });
}

// ==================== 第二期：组卷 ====================

function eduGenerateExam() {
    if (_eduState.busy) return;
    var points = ((document.getElementById('edu-exam-points') || {}).value || '')
        .split(/[,，、]/).map(function (s) { return s.trim(); }).filter(function (s) { return s; });
    var type = (document.getElementById('edu-exam-type') || {}).value || '';
    var difficulty = (document.getElementById('edu-exam-difficulty') || {}).value || '';
    var payload = {
        title: (document.getElementById('edu-exam-title') || {}).value || '',
        subject: (document.getElementById('edu-exam-subject') || {}).value || '',
        question_count: parseInt((document.getElementById('edu-exam-count') || {}).value || '10', 10) || 10,
        duration: parseInt((document.getElementById('edu-exam-duration') || {}).value || '60', 10) || 60,
        total_score: parseInt((document.getElementById('edu-exam-score') || {}).value || '100', 10) || 100,
        qtypes: type ? [type] : [],
        difficulty: difficulty ? parseInt(difficulty, 10) : null,
        knowledge_points: points,
        include_mistakes: !!(document.getElementById('edu-exam-mistakes') || {}).checked,
        save: !!(document.getElementById('edu-exam-save') || {}).checked
    };
    var hint = document.getElementById('edu-exam-hint');
    _eduState.busy = true;
    if (hint) hint.textContent = '正在抽题组卷...';
    eduApi('/exams/generate', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
    }).then(function (res) {
        _eduState.busy = false;
        if (res && res.success && res.paper) {
            _eduState.lastPaper = res.paper;
            renderEduPaper(res.paper);
            if (hint) hint.textContent = res.message || '组卷完成';
            showToast(res.message || '组卷完成', 'success');
            loadEduExams();
        } else {
            if (hint) hint.textContent = (res && res.message) || '组卷失败';
            showToast((res && res.message) || '组卷失败', 'error');
        }
    }).catch(function (e) {
        _eduState.busy = false;
        if (hint) hint.textContent = '组卷失败：' + e;
        showToast('组卷失败', 'error');
    });
}

function renderEduPaper(paper) {
    var box = document.getElementById('edu-exam-result');
    if (!box || !paper) return;
    var questions = paper.questions || [];
    var savedTag = paper.id ? '<span class="edu-badge ok">已保存 #' + paper.id + '</span>' : '';
    var html = '<div class="edu-panel">' +
        '<div class="edu-panel-title"><i class="fas fa-file-lines"></i> ' + escapeHtml(String(paper.title || '')) + '</div>' +
        '<div class="edu-hint">共 ' + questions.length + ' 题 · 满分 ' + (paper.total_score || 0) + ' 分 · 建议 ' +
            (paper.duration || 0) + ' 分钟 · ' + escapeHtml(String(paper.created_at || '')) + ' ' + savedTag + '</div>' +
        '<div class="edu-import-row" style="margin-top:8px">' +
            '<button class="btn btn-sm" onclick="eduExportPaper(false)"><i class="fas fa-file-arrow-down"></i> 导出试卷</button>' +
            '<button class="btn btn-sm" onclick="eduExportPaper(true)"><i class="fas fa-file-circle-check"></i> 导出（含答案）</button>' +
            (paper.id ? '' : '<button class="btn btn-sm" onclick="eduSaveGeneratedExam()"><i class="fas fa-floppy-disk"></i> 存入我的试卷</button>') +
            '<span class="edu-hint">导出为网页，浏览器中可直接打印成 PDF</span>' +
        '</div>' +
        (paper.notice ? '<div class="edu-hint" style="color:var(--warn,#d08700)">' + escapeHtml(String(paper.notice)) + '</div>' : '') +
        '</div>' +
        questions.map(function (q) {
            return eduRenderQuestionCard(q,
                '<button class="btn btn-sm" onclick="eduSolveQuestion(' + q.id + ')"><i class="fas fa-lightbulb"></i> 讲解</button>' +
                '<button class="btn btn-sm" onclick="eduAddMistake(' + q.id + ')"><i class="fas fa-bookmark"></i> 记错题</button>');
        }).join('');
    box.innerHTML = html;
}

function eduSaveGeneratedExam() {
    var paper = _eduState.lastPaper;
    if (!paper) { showToast('还没有生成试卷', 'error'); return; }
    eduApi('/exams', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(paper)
    }).then(function (res) {
        if (res && res.success) {
            paper.id = res.id;
            showToast('试卷已保存', 'success');
            renderEduPaper(paper);
            loadEduExams();
        } else {
            showToast((res && res.message) || '保存失败', 'error');
        }
    }).catch(function () { showToast('保存失败', 'error'); });
}

function eduExportPaper(withAnswer) {
    var paper = _eduState.lastPaper;
    if (!paper) { showToast('还没有生成试卷', 'error'); return; }
    var suffix = withAnswer ? '?with_answer=1' : '';
    if (paper.id) {
        window.open('/api/edu/exams/' + paper.id + '/export' + suffix, '_blank');
        return;
    }
    eduApi('/exams', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(paper)
    }).then(function (res) {
        if (res && res.success) {
            paper.id = res.id;
            renderEduPaper(paper);
            loadEduExams();
            window.open('/api/edu/exams/' + res.id + '/export' + suffix, '_blank');
        } else {
            showToast('导出失败，请先保存试卷', 'error');
        }
    }).catch(function () { showToast('导出失败', 'error'); });
}

function loadEduExams() {
    var box = document.getElementById('edu-exam-list');
    if (!box) return;
    eduApi('/exams').then(function (res) {
        var items = (res && res.data) || [];
        if (!items.length) {
            box.innerHTML = '<div class="edu-empty">还没有保存过试卷，在上方设置好题量后点「生成试卷」。</div>';
            return;
        }
        box.innerHTML = items.map(function (e) {
            return '<div class="edu-card">' +
                '<div class="edu-card-head">' +
                    '<span class="edu-badge">' + (e.question_count || 0) + ' 题</span>' +
                    '<span class="edu-badge soft">' + (e.total_score || 0) + ' 分</span>' +
                    '<span class="edu-badge soft">' + (e.duration || 0) + ' 分钟</span>' +
                    (e.subject ? '<span class="edu-badge soft">' + escapeHtml(String(e.subject)) + '</span>' : '') +
                    '<span class="edu-card-spacer"></span>' +
                    '<button class="btn btn-sm" onclick="eduViewExam(' + e.id + ')"><i class="fas fa-eye"></i> 预览</button>' +
                    '<button class="btn btn-sm" onclick="eduExportExam(' + e.id + ', false)"><i class="fas fa-file-arrow-down"></i> 试卷</button>' +
                    '<button class="btn btn-sm" onclick="eduExportExam(' + e.id + ', true)"><i class="fas fa-file-circle-check"></i> 答案</button>' +
                    '<button class="btn btn-sm btn-danger" onclick="eduDeleteExam(' + e.id + ')"><i class="fas fa-trash"></i></button>' +
                '</div>' +
                '<div class="edu-stem">' + escapeHtml(String(e.title || '')) + '</div>' +
                '<div class="edu-hint">' + escapeHtml(String(e.created_at || '')) + '</div>' +
                '</div>';
        }).join('');
    }).catch(function () { box.innerHTML = '<div class="edu-empty">试卷列表加载失败</div>'; });
}

function eduViewExam(id) {
    eduApi('/exams/' + id).then(function (res) {
        var exam = (res && res.data) || {};
        if (!exam.id) { showToast('试卷不存在', 'error'); return; }
        _eduState.lastPaper = {
            id: exam.id, title: exam.title, subject: exam.subject, grade: exam.grade,
            duration: exam.duration, total_score: exam.total_score,
            question_count: exam.question_count, questions: exam.questions,
            config: exam.config, created_at: exam.created_at
        };
        renderEduPaper(_eduState.lastPaper);
        var box = document.getElementById('edu-exam-result');
        if (box) box.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }).catch(function () { showToast('读取试卷失败', 'error'); });
}

function eduExportExam(id, withAnswer) {
    window.open('/api/edu/exams/' + id + '/export' + (withAnswer ? '?with_answer=1' : ''), '_blank');
}

function eduDeleteExam(id) {
    showDialog('删除试卷', '<div>确定删除试卷 #' + id + ' 吗？</div>', function () {
        closeDialog();
        eduApi('/exams/' + id, { method: 'DELETE' }).then(function (res) {
            if (res && res.success) {
                showToast('试卷已删除', 'success');
                loadEduExams();
            } else {
                showToast((res && res.message) || '删除失败', 'error');
            }
        }).catch(function () { showToast('删除失败', 'error'); });
    });
}
// ============================================================================
// AI 授课子系统（teaching）
// 幻灯片创作 / 授课流程 / 随机点名 / 快捷目录 / 网络试题 / 实时问答 / 连续记忆 / 对话
// ============================================================================

var _teachState = {
    tab: 'slides',
    slides: [],
    flows: [],
    groups: [],
    members: [],
    catalogs: [],
    record: null,
    busy: false,
    recording: false,
    mediaRecorder: null,
    audioChunks: [],
    chatMessages: []
};

function teachApi(path, options) {
    return fetch('/api/edu/teach' + path, options).then(function (r) { return r.json(); });
}

function loadTeachView() {
    teachLoadStatus();
    teachSwitchTab(_teachState.tab || 'slides');
    teachChatLoad();
}

// ---------- 状态 ----------

function teachLoadStatus() {
    var box = document.getElementById('teach-status');
    if (!box) return;
    teachApi('/status').then(function (res) {
        var d = (res && res.data) || {};
        var ocr = d.ocr || {};
        var asr = d.asr || {};
        function yn(v) { return v ? '<span style="color:#16a34a">可用</span>' : '<span style="color:#9aa9bc">不可用</span>'; }
        box.innerHTML =
            '<div class="edu-stat-note">' +
            'PPTX 生成：' + yn(d.pptx) + '　·　' +
            '本地 OCR：' + yn(ocr.local) + '　·　多模态 OCR：' + yn(ocr.vision) + '　·　' +
            '本地 ASR：' + yn(asr.local) + '　·　云端 ASR：' + yn(asr.cloud) +
            '</div>';
    }).catch(function () {
        box.innerHTML = '<div class="edu-stat-note">状态加载失败</div>';
    });
}

function teachSwitchTab(tab) {
    _teachState.tab = tab || 'slides';
    var tabs = ['slides', 'flow', 'rollcall', 'catalog', 'questions', 'voice', 'memory', 'chat'];
    tabs.forEach(function (name) {
        var btn = document.getElementById('teach-tab-' + name);
        if (btn) btn.classList.toggle('active', _teachState.tab === name);
        var panel = document.getElementById('teach-panel-' + name);
        if (panel) panel.style.display = _teachState.tab === name ? '' : 'none';
    });
    if (tab === 'slides') loadTeachSlides();
    else if (tab === 'flow') loadTeachFlows();
    else if (tab === 'rollcall') { loadTeachGroups(); loadTeachHistory(); }
    else if (tab === 'catalog') loadTeachCatalogs();
    else if (tab === 'questions') loadTeachWqRecords();
    else if (tab === 'voice') teachVoiceInfo();
    else if (tab === 'memory') teachLoadMemory();
    else if (tab === 'chat') teachChatLoad();
}

function teachPickFile(inputId) {
    if (window.DesktopBridge && DesktopBridge.isDesktop && DesktopBridge.isDesktop()) {
        DesktopBridge.openFileDialog([
            ['课件文件', '*.pdf;*.pptx;*.docx;*.xlsx;*.xlsm;*.txt;*.md;*.csv;*.png;*.jpg;*.jpeg'],
            ['所有文件', '*.*']
        ]).then(function (path) {
            if (path) {
                var el = document.getElementById(inputId);
                if (el) el.value = path;
            }
        });
        return;
    }
    showToast('浏览器模式无法读取本地路径，请手动粘贴完整文件路径', 'warn');
}

// ================= 幻灯片创作 =================

function teachGenerateSlides() {
    if (_teachState.busy) return;
    var topic = (document.getElementById('teach-slide-topic').value || '').trim();
    if (!topic) { showToast('请填写教学主题', 'error'); return; }
    var payload = {
        topic: topic,
        subject: (document.getElementById('teach-slide-subject').value || '').trim(),
        grade: (document.getElementById('teach-slide-grade').value || '').trim(),
        objectives: (document.getElementById('teach-slide-objectives').value || '').trim(),
        outline: (document.getElementById('teach-slide-outline').value || '').trim(),
        content: (document.getElementById('teach-slide-content').value || '').trim(),
        slide_count: parseInt(document.getElementById('teach-slide-count').value, 10) || 12,
        export_pptx: document.getElementById('teach-slide-pptx').checked,
        export_html: document.getElementById('teach-slide-html').checked
    };
    _teachState.busy = true;
    showToast('正在生成教学幻灯片，请稍候…', 'info');
    teachApi('/slides/generate', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
    }).then(function (res) {
        _teachState.busy = false;
        if (res && res.success) {
            showToast(res.message || '生成完成', 'success');
            loadTeachSlides();
        } else {
            showToast((res && res.message) || '生成失败', 'error');
        }
    }).catch(function (e) {
        _teachState.busy = false;
        showToast('生成失败：' + e, 'error');
    });
}

function loadTeachSlides() {
    var box = document.getElementById('teach-slide-list');
    if (!box) return;
    teachApi('/slides').then(function (res) {
        var list = (res && res.data) || [];
        _teachState.slides = list;
        if (!list.length) { box.innerHTML = '<div class="edu-stat-note">还没有幻灯片，填写主题后点击「生成幻灯片」。</div>'; return; }
        box.innerHTML = list.map(function (s) {
            var files = [];
            if (s.html_path) files.push('<button class="btn btn-sm" onclick="teachOpenSlide(' + s.id + ',\'html\')"><i class="fas fa-tv"></i> 放映</button>');
            if (s.pptx_path) files.push('<button class="btn btn-sm" onclick="teachDownloadSlide(' + s.id + ',\'pptx\')"><i class="fas fa-file-powerpoint"></i> PPTX</button>');
            if (s.seewo_path) files.push('<button class="btn btn-sm" onclick="teachDownloadSlide(' + s.id + ',\'seewo\')"><i class="fas fa-file"></i> 希沃框架</button>');
            files.push('<button class="btn btn-sm" onclick="teachViewSlide(' + s.id + ')"><i class="fas fa-eye"></i> 大纲</button>');
            files.push('<button class="btn btn-sm" onclick="teachEditSlide(' + s.id + ')"><i class="fas fa-pen"></i> 编辑</button>');
            files.push('<button class="btn btn-sm" onclick="teachExportSlide(' + s.id + ')"><i class="fas fa-rotate"></i> 再导出</button>');
            files.push('<button class="btn btn-sm" onclick="teachDeleteSlide(' + s.id + ')"><i class="fas fa-trash"></i></button>');
            return '<div class="edu-card">' +
                '<div class="edu-card-title">' + escapeHtml(s.title || '未命名') + '</div>' +
                '<div class="edu-card-meta">' + escapeHtml(s.subject || '') + ' ' + escapeHtml(s.grade || '') +
                ' · ' + (s.slide_count || 0) + ' 页 · ' + escapeHtml(s.created_at || '') + '</div>' +
                '<div class="edu-card-actions">' + files.join(' ') + '</div>' +
                '</div>';
        }).join('');
    }).catch(function () { box.innerHTML = '<div class="edu-stat-note">加载失败</div>'; });
}

function teachOpenSlide(id, kind) {
    window.open('/api/edu/teach/slides/' + id + '/file?kind=' + kind, '_blank');
}

function teachDownloadSlide(id, kind) {
    window.open('/api/edu/teach/slides/' + id + '/file?kind=' + kind, '_blank');
}

function teachDeleteSlide(id) {
    showDialog('删除幻灯片', '<div>确定删除幻灯片 #' + id + ' 吗？</div>', function () {
        closeDialog();
        teachApi('/slides/' + id + '?remove_files=true', { method: 'DELETE' }).then(function (res) {
            showToast((res && res.message) || '已删除', res && res.success ? 'success' : 'error');
            loadTeachSlides();
        });
    });
}

function teachViewSlide(id) {
    teachApi('/slides/' + id).then(function (res) {
        var s = (res && res.data) || {};
        var outline = s.outline || {};
        var html = '<div class="edu-panel"><div class="edu-panel-title">' + escapeHtml(s.title || '') + '</div>';
        var objs = outline.objectives || [];
        if (objs.length) html += '<div class="teach-outline-block"><b>教学目标</b><ul>' + objs.map(function (o) { return '<li>' + escapeHtml(o) + '</li>'; }).join('') + '</ul></div>';
        (outline.slides || []).forEach(function (p) {
            html += '<div class="teach-outline-slide">' +
                '<div class="teach-outline-title">' + (p.index || '') + '. ' + escapeHtml(p.title || '') +
                ' <span class="edu-hint">[' + escapeHtml(p.type || '') + ']</span></div>';
            if (p.bullets && p.bullets.length) {
                html += '<ul>' + p.bullets.map(function (b) { return '<li>' + escapeHtml(b) + '</li>'; }).join('') + '</ul>';
            }
            if (p.example) {
                html += '<div class="teach-outline-ex">' + escapeHtml(p.example.question || '') +
                    (p.example.answer ? '<div class="teach-ans">答案：' + escapeHtml(p.example.answer) + '</div>' : '') +
                    (p.example.analysis ? '<div class="edu-hint">解析：' + escapeHtml(p.example.analysis) + '</div>' : '') + '</div>';
            }
            if (p.notes) html += '<div class="edu-hint">讲稿：' + escapeHtml(p.notes) + '</div>';
            html += '</div>';
        });
        html += '</div>';
        document.getElementById('teach-slide-list').innerHTML = html +
            '<button class="btn btn-sm" onclick="loadTeachSlides()"><i class="fas fa-arrow-left"></i> 返回列表</button>';
    });
}

// ================= 授课流程 =================

function teachSummarizeFlow() {
    var path = (document.getElementById('teach-flow-path').value || '').trim();
    if (!path) { showToast('请填写课件路径', 'error'); return; }
    var payload = {
        path: path,
        subject: (document.getElementById('teach-flow-subject').value || '').trim(),
        grade: (document.getElementById('teach-flow-grade').value || '').trim(),
        auto_answer: document.getElementById('teach-flow-autoanswer').checked,
        save_file: document.getElementById('teach-flow-save').checked
    };
    showToast('正在读取课件并总结授课流程…', 'info');
    teachApi('/flows/summarize', {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload)
    }).then(function (res) {
        if (res && res.success) {
            showToast(res.message || '总结完成', 'success');
            loadTeachFlows();
            teachViewFlow(res.id);
        } else {
            showToast((res && res.message) || '总结失败', 'error');
        }
    }).catch(function (e) { showToast('总结失败：' + e, 'error'); });
}

function loadTeachFlows() {
    var box = document.getElementById('teach-flow-list');
    if (!box) return;
    teachApi('/flows').then(function (res) {
        var list = (res && res.data) || [];
        _teachState.flows = list;
        if (!list.length) { box.innerHTML = '<div class="edu-stat-note">还没有授课流程记录。</div>'; return; }
        box.innerHTML = list.map(function (f) {
            var btns = '<button class="btn btn-sm" onclick="teachViewFlow(' + f.id + ')"><i class="fas fa-eye"></i> 查看</button>';
            if (f.file_path) btns += ' <button class="btn btn-sm" onclick="window.open(\'/api/edu/teach/flows/' + f.id + '/markdown\',\'_blank\')"><i class="fas fa-file-lines"></i> Markdown</button>';
            btns += ' <button class="btn btn-sm" onclick="teachDeleteFlow(' + f.id + ')"><i class="fas fa-trash"></i></button>';
            return '<div class="edu-card"><div class="edu-card-title">' + escapeHtml(f.title || '') + '</div>' +
                '<div class="edu-card-meta">' + escapeHtml(f.subject || '') + ' ' + escapeHtml(f.grade || '') +
                ' · 试题 ' + (f.question_count || 0) + ' 道（AI 补答 ' + (f.answered_count || 0) + '） · ' + escapeHtml(f.created_at || '') + '</div>' +
                '<div class="edu-card-actions">' + btns + '</div></div>';
        }).join('');
    }).catch(function () { box.innerHTML = '<div class="edu-stat-note">加载失败</div>'; });
}

function teachViewFlow(id) {
    var box = document.getElementById('teach-flow-detail');
    if (!box) return;
    teachApi('/flows/' + id).then(function (res) {
        var d = (res && res.data) || {};
        var sum = d.summary || {};
        var html = '<div class="edu-panel"><div class="edu-panel-title">' + escapeHtml(d.title || '授课流程') + '</div>';
        if (sum.overview) html += '<p>' + escapeHtml(sum.overview) + '</p>';
        html += '<div class="edu-hint">建议时长：' + (sum.duration_minutes || 45) + ' 分钟</div>';
        (sum.steps || []).forEach(function (s, i) {
            html += '<div class="teach-flow-step"><b>' + (i + 1) + '. ' + escapeHtml(s.stage || '') + '</b>（约 ' + (s.minutes || 0) + ' 分钟）' +
                '<div>' + escapeHtml(s.action || '') + '</div>';
            if (s.key_points && s.key_points.length) html += '<div class="edu-hint">知识点：' + escapeHtml(s.key_points.join('、')) + '</div>';
            if (s.tips) html += '<div class="edu-hint">提示：' + escapeHtml(s.tips) + '</div>';
            html += '</div>';
        });
        if ((sum.key_points || []).length) html += '<div><b>教学重点：</b>' + escapeHtml(sum.key_points.join('、')) + '</div>';
        if ((sum.difficulties || []).length) html += '<div><b>教学难点：</b>' + escapeHtml(sum.difficulties.join('、')) + '</div>';
        if (sum.homework) html += '<div><b>作业建议：</b>' + escapeHtml(sum.homework) + '</div>';

        var qs = sum.questions || [];
        if (qs.length) {
            html += '<div class="edu-panel-title" style="margin-top:14px">课件试题（' + qs.length + '）</div>';
            qs.forEach(function (q, i) {
                html += '<div class="teach-outline-ex"><b>' + (i + 1) + '. ' + escapeHtml(q.stem || '') + '</b>';
                (q.options || []).forEach(function (o, k) { html += '<div>' + "ABCDEFGH"[k] + '. ' + escapeHtml(o) + '</div>'; });
                html += '<div class="teach-ans">答案：' + escapeHtml(q.answer || '（无）') + (q.ai_answered ? ' <span class="edu-hint">（AI 补答）</span>' : '') + '</div>';
                if (q.analysis) html += '<div class="edu-hint">解析：' + escapeHtml(q.analysis) + '</div>';
                html += '</div>';
            });
        }
        html += '<button class="btn btn-sm" onclick="document.getElementById(\'teach-flow-detail\').innerHTML=\'\'"><i class="fas fa-xmark"></i> 收起</button></div>';
        box.innerHTML = html;
    });
}

function teachDeleteFlow(id) {
    showDialog('删除授课流程', '<div>确定删除 #' + id + ' 吗？</div>', function () {
        closeDialog();
        teachApi('/flows/' + id + '?remove_file=true', { method: 'DELETE' }).then(function () { loadTeachFlows(); });
    });
}

// ================= 随机点名 =================

function loadTeachGroups() {
    var sel = document.getElementById('teach-rc-group');
    if (!sel) return;
    teachApi('/rollcall/groups').then(function (res) {
        var list = (res && res.data) || [];
        _teachState.groups = list;
        var cur = sel.value;
        sel.innerHTML = '<option value="">选择名单</option>' + list.map(function (g) {
            return '<option value="' + g.id + '">' + escapeHtml(g.name) + '（' + (g.member_count || 0) + '人）</option>';
        }).join('');
        if (cur) sel.value = cur;
        if (!cur && list.length) { sel.value = String(list[0].id); teachLoadMembers(); }
    });
}

function teachCreateGroup() {
    var name = (document.getElementById('teach-rc-newgroup').value || '').trim();
    if (!name) { showToast('请输入名单名称', 'error'); return; }
    teachApi('/rollcall/groups', {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name: name })
    }).then(function (res) {
        if (res && res.success) {
            document.getElementById('teach-rc-newgroup').value = '';
            showToast('名单已创建', 'success');
            loadTeachGroups();
        } else { showToast((res && res.message) || '创建失败', 'error'); }
    });
}

function teachDeleteGroup() {
    var gid = document.getElementById('teach-rc-group').value;
    if (!gid) { showToast('请先选择名单', 'error'); return; }
    showDialog('删除名单', '<div>删除名单会同时删除其成员与记录，确定？</div>', function () {
        closeDialog();
        teachApi('/rollcall/groups/' + gid, { method: 'DELETE' }).then(function () {
            loadTeachGroups(); document.getElementById('teach-rc-members').innerHTML = '';
        });
    });
}

function teachLoadMembers() {
    var gid = document.getElementById('teach-rc-group').value;
    var box = document.getElementById('teach-rc-members');
    if (!gid) { if (box) box.innerHTML = ''; return; }
    teachApi('/rollcall/groups/' + gid + '/members').then(function (res) {
        var list = (res && res.data) || [];
        _teachState.members = list;
        if (!box) return;
        if (!list.length) { box.innerHTML = '<div class="edu-stat-note">名单为空，粘贴姓名后点「追加导入」。</div>'; return; }
        box.innerHTML = list.map(function (m) {
            return '<div class="edu-card teach-member">' +
                '<div class="edu-card-title">' + escapeHtml(m.name) +
                (m.active ? '' : ' <span class="edu-hint">（停用）</span>') + '</div>' +
                '<div class="edu-card-meta">权重 ' + m.weight + ' · 已抽中 ' + (m.drawn_count || 0) + ' 次</div>' +
                '<div class="edu-card-actions">' +
                '<input type="number" min="0.1" max="20" step="0.1" value="' + m.weight + '" style="width:70px" onchange="teachUpdateWeight(' + m.id + ', this.value)">' +
                '<button class="btn btn-sm" onclick="teachToggleMember(' + m.id + ',' + (m.active ? 'false' : 'true') + ')">' + (m.active ? '停用' : '启用') + '</button>' +
                '<button class="btn btn-sm" onclick="teachDeleteMember(' + m.id + ')"><i class="fas fa-trash"></i></button>' +
                '</div></div>';
        }).join('');
    });
}

function teachBulkMembers(replace) {
    var gid = document.getElementById('teach-rc-group').value;
    if (!gid) { showToast('请先选择名单', 'error'); return; }
    var text = (document.getElementById('teach-rc-bulk').value || '').trim();
    if (!text) { showToast('请粘贴姓名', 'error'); return; }
    teachApi('/rollcall/members/bulk', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ group_id: parseInt(gid, 10), text: text, replace: replace })
    }).then(function (res) {
        showToast((res && res.message) || '导入完成', res && res.success ? 'success' : 'error');
        if (res && res.success) { document.getElementById('teach-rc-bulk').value = ''; loadTeachGroups(); teachLoadMembers(); }
    });
}

function teachUpdateWeight(mid, val) {
    teachApi('/rollcall/members/' + mid, {
        method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ weight: parseFloat(val) })
    }).then(function () { showToast('权重已更新', 'success'); });
}

function teachToggleMember(mid, active) {
    teachApi('/rollcall/members/' + mid, {
        method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ active: active })
    }).then(function () { teachLoadMembers(); });
}

function teachDeleteMember(mid) {
    teachApi('/rollcall/members/' + mid, { method: 'DELETE' }).then(function () { teachLoadMembers(); });
}

function teachDraw() {
    var gid = document.getElementById('teach-rc-group').value;
    if (!gid) { showToast('请先选择名单', 'error'); return; }
    var payload = {
        group_id: parseInt(gid, 10),
        count: parseInt(document.getElementById('teach-rc-count').value, 10) || 1,
        no_repeat_window: parseInt(document.getElementById('teach-rc-window').value, 10),
        algorithm: document.getElementById('teach-rc-algo').value
    };
    var anim = document.getElementById('teach-rc-anim').value;
    var resultBox = document.getElementById('teach-rc-result');
    var members = _teachState.members.filter(function (m) { return m.active; });

    var finish = function (res) {
        if (!res || !res.success) {
            if (resultBox) resultBox.textContent = (res && res.message) || '抽取失败';
            showToast((res && res.message) || '抽取失败', 'error');
            return;
        }
        if (resultBox) resultBox.innerHTML = '<span class="teach-draw-name">' + escapeHtml((res.names || []).join(' · ')) + '</span>' +
            '<div class="edu-hint">种子 ' + escapeHtml(res.seed || '') + (res.relaxed ? ' · 已放宽去重' : '') + '</div>';
        loadTeachGroups(); teachLoadMembers(); loadTeachHistory();
    };

    if (anim === 'spin' && members.length) {
        var spinTimer = setInterval(function () {
            var name = members[Math.floor(Math.random() * members.length)].name;
            if (resultBox) resultBox.textContent = name;
        }, 90);
        teachApi('/rollcall/draw', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) })
            .then(function (res) {
                setTimeout(function () { clearInterval(spinTimer); finish(res); }, 2200);
            })
            .catch(function (e) {
                clearInterval(spinTimer);
                finish({ success: false, message: '抽取失败：' + e });
            });
    } else {
        teachApi('/rollcall/draw', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) }).then(finish);
    }
}

function teachResetLogs() {
    var gid = document.getElementById('teach-rc-group').value;
    if (!gid) return;
    teachApi('/rollcall/groups/' + gid + '/reset', { method: 'POST' }).then(function () { loadTeachHistory(); teachLoadMembers(); showToast('记录已清空', 'success'); });
}

function loadTeachHistory() {
    var gid = document.getElementById('teach-rc-group').value;
    var box = document.getElementById('teach-rc-history');
    if (!box) return;
    if (!gid) { box.innerHTML = ''; return; }
    teachApi('/rollcall/groups/' + gid + '/history?limit=30').then(function (res) {
        var list = (res && res.data) || [];
        if (!list.length) { box.innerHTML = '<div class="edu-stat-note">还没有抽取记录。</div>'; return; }
        box.innerHTML = list.map(function (h) {
            return '<div class="edu-card-meta">' + escapeHtml(h.created_at || '') + ' · <b>' + escapeHtml(h.name || '') + '</b> · ' + escapeHtml(h.algorithm || '') + ' · 种子 ' + escapeHtml(h.seed || '') + '</div>';
        }).join('');
    });
}

// ================= 快捷目录 / 悬浮球 =================

function teachBuildCatalog() {
    var path = (document.getElementById('teach-catalog-path').value || '').trim();
    if (!path) { showToast('请填写课件路径', 'error'); return; }
    showToast('正在解析课件并生成目录…', 'info');
    teachApi('/catalog/build', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ path: path, with_ocr: document.getElementById('teach-catalog-ocr').checked })
    }).then(function (res) {
        if (res && res.success) { showToast(res.message || '目录已生成', 'success'); loadTeachCatalogs(); teachViewCatalog(res.id); }
        else { showToast((res && res.message) || '生成失败', 'error'); }
    }).catch(function (e) { showToast('生成失败：' + e, 'error'); });
}

function loadTeachCatalogs() {
    var box = document.getElementById('teach-catalog-list');
    var sel = document.getElementById('teach-ball-catalog');
    if (!box && !sel) return;
    teachApi('/catalog/list').then(function (res) {
        var list = (res && res.data) || [];
        _teachState.catalogs = list;
        if (sel) {
            var cur = sel.value;
            sel.innerHTML = '<option value="">选择目录</option>' + list.map(function (c) {
                return '<option value="' + c.id + '">' + escapeHtml(c.title) + '（' + (c.page_count || 0) + '页）</option>';
            }).join('');
            if (cur) sel.value = cur;
            if (!cur && list.length) sel.value = String(list[0].id);
        }
        if (!box) return;
        if (!list.length) { box.innerHTML = '<div class="edu-stat-note">还没有目录，填写课件路径后点击「生成目录」。</div>'; return; }
        box.innerHTML = list.map(function (c) {
            return '<div class="edu-card"><div class="edu-card-title">' + escapeHtml(c.title || '') + '</div>' +
                '<div class="edu-card-meta">' + (c.page_count || 0) + ' 页 · ' + escapeHtml(c.file_type || '') + ' · ' + escapeHtml(c.created_at || '') + '</div>' +
                '<div class="edu-card-actions">' +
                '<button class="btn btn-sm" onclick="teachViewCatalog(' + c.id + ')"><i class="fas fa-eye"></i> 查看</button>' +
                '<button class="btn btn-sm" onclick="teachMatchScreen(' + c.id + ')"><i class="fas fa-camera"></i> 识别当前页</button>' +
                '<button class="btn btn-sm" onclick="teachDeleteCatalog(' + c.id + ')"><i class="fas fa-trash"></i></button>' +
                '</div></div>';
        }).join('');
    });
}

function teachViewCatalog(id) {
    teachApi('/catalog/' + id).then(function (res) {
        var c = (res && res.data) || {};
        var html = '<div class="edu-panel"><div class="edu-panel-title">' + escapeHtml(c.title || '') + ' · 目录</div>';
        (c.outline || []).forEach(function (p) {
            html += '<div class="teach-outline-slide"><div class="teach-outline-title">第 ' + (p.page || '') + ' 页：' + escapeHtml(p.title || '') + '</div>';
            if (p.elements && p.elements.length) html += '<ul>' + p.elements.map(function (e) { return '<li>' + escapeHtml(e) + '</li>'; }).join('') + '</ul>';
            html += '</div>';
        });
        html += '<button class="btn btn-sm" onclick="document.getElementById(\'teach-catalog-detail\').innerHTML=\'\'"><i class="fas fa-xmark"></i> 收起</button></div>';
        document.getElementById('teach-catalog-detail').innerHTML = html;
    });
}

function teachDeleteCatalog(id) {
    teachApi('/catalog/' + id, { method: 'DELETE' }).then(function () { loadTeachCatalogs(); });
}

function teachMatchScreen(catalogId) {
    var cid = catalogId || document.getElementById('teach-ball-catalog').value;
    if (!cid) { showToast('请先选择目录', 'error'); return; }
    var box = document.getElementById('teach-catalog-match');
    if (box) box.textContent = '正在截屏识别…';
    teachApi('/catalog/match-screen', {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ catalog_id: parseInt(cid, 10) })
    }).then(function (res) {
        if (!res || !res.success) { if (box) box.textContent = (res && res.message) || '识别失败'; return; }
        var txt = '识别结果：第 ' + res.page + ' 页（' + escapeHtml(res.title || '') + '）· 匹配度 ' + res.score + (res.matched ? '' : ' · 低于阈值');
        if (box) box.textContent = txt;
        showToast(txt, res.matched ? 'success' : 'warn');
    }).catch(function (e) { if (box) box.textContent = '识别失败：' + e; });
}

function teachOpenBall() {
    teachApi('/config').then(function (res) {
        var cat = ((res && res.data) || {}).catalog || {};
        if (cat.floating_ball === false) {
            showToast('悬浮球已在「设置 → AI 授课」中关闭', 'warn');
            return;
        }
        var size = parseInt(cat.ball_size, 10) || 84;
        var cid = document.getElementById('teach-ball-catalog') ? document.getElementById('teach-ball-catalog').value : '';
        if (window.DesktopBridge && DesktopBridge.isDesktop && DesktopBridge.isDesktop()) {
            var url = window.location.origin + '/float_ball' + (cid ? ('?catalog_id=' + cid) : '');
            DesktopBridge.openFloatBall(url, size, size).then(function (r) {
                showToast((r && r.message) || '已打开悬浮球', 'success');
            });
        } else {
            // 浏览器模式：新开一个页面作为预览
            window.open('/float_ball' + (cid ? ('?catalog_id=' + cid) : ''), '_blank', 'width=380,height=560');
            showToast('浏览器模式为预览窗口；悬浮在 WPS/希沃上方需在桌面版运行', 'info');
        }
    }).catch(function () {
        showToast('读取授课配置失败', 'error');
    });
}

function teachHideBall() {
    if (window.DesktopBridge && DesktopBridge.isDesktop && DesktopBridge.isDesktop()) {
        DesktopBridge.hideFloatBall().then(function () {
            showToast('悬浮球已隐藏，点「打开悬浮球」可恢复', 'success');
        });
    } else {
        showToast('浏览器模式不支持隐藏，悬浮球仅桌面版可用', 'warn');
    }
}

function teachCloseBall() {
    if (window.DesktopBridge && DesktopBridge.isDesktop && DesktopBridge.isDesktop()) {
        DesktopBridge.closeFloatBall().then(function () { showToast('悬浮球已关闭', 'success'); });
    } else {
        showToast('浏览器模式无需关闭，直接关掉预览窗口即可', 'info');
    }
}

// 收集「设置 → AI 授课」配置（saveSettings 调用）
function collectEduTeaching() {
    if (!document.getElementById('teach-cfg-ball-size')) return null;
    var out = {
        catalog: {
            floating_ball: document.getElementById('teach-cfg-ball-enabled').checked,
            ball_size: parseInt(document.getElementById('teach-cfg-ball-size').value, 10) || 84
        },
        network: {
            api_url: (document.getElementById('teach-cfg-net-api').value || '').trim(),
            default_count: parseInt(document.getElementById('teach-cfg-net-count').value, 10) || 5
        },
        vision: {
            model: (document.getElementById('teach-cfg-vision-model').value || '').trim() || 'qwen-vl-max',
            api_url: (document.getElementById('teach-cfg-vision-url').value || '').trim()
        },
        rollcall: {
            algorithm: document.getElementById('teach-cfg-rc-algo').value
        }
    };
    var threshold = parseFloat(document.getElementById('teach-cfg-ball-threshold').value);
    if (!isNaN(threshold)) out.catalog.match_threshold = Math.min(1, Math.max(0, threshold));
    var rcWindow = parseInt(document.getElementById('teach-cfg-rc-window').value, 10);
    if (!isNaN(rcWindow)) out.rollcall.no_repeat_window = rcWindow;
    // 密钥留空表示保持原值，避免误清空
    var netKey = (document.getElementById('teach-cfg-net-key').value || '').trim();
    if (netKey) out.network.api_key = netKey;
    var visKey = (document.getElementById('teach-cfg-vision-key').value || '').trim();
    if (visKey) out.vision.api_key = visKey;
    return out;
}

// ================= 网络试题 =================

function teachFetchWebQuestions() {
    var payload = {
        mode: document.getElementById('teach-wq-mode').value,
        query: (document.getElementById('teach-wq-query').value || '').trim(),
        subject: (document.getElementById('teach-wq-subject').value || '').trim(),
        grade: (document.getElementById('teach-wq-grade').value || '').trim(),
        qtype: document.getElementById('teach-wq-type').value,
        count: parseInt(document.getElementById('teach-wq-count').value, 10) || 5,
        save_to_bank: document.getElementById('teach-wq-save').checked
    };
    var box = document.getElementById('teach-wq-result');
    if (box) box.innerHTML = '<div class="edu-stat-note">正在获取试题…</div>';
    teachApi('/web-questions/fetch', {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload)
    }).then(function (res) {
        if (!res || !res.success) {
            if (box) box.innerHTML = '<div class="edu-stat-note">' + escapeHtml((res && res.message) || '获取失败') + '</div>';
            return;
        }
        var html = '<div class="edu-panel"><div class="edu-panel-title">获取结果 · ' + escapeHtml(res.message || '') + '</div>';
        (res.questions || []).forEach(function (q, i) {
            html += '<div class="teach-outline-ex"><b>' + (i + 1) + '. ' + escapeHtml(q.stem || '') + '</b>';
            (q.options || []).forEach(function (o, k) { html += '<div>' + "ABCDEFGH"[k] + '. ' + escapeHtml(o) + '</div>'; });
            html += '<div class="teach-ans">答案：' + escapeHtml(q.answer || '（无）') + '</div>';
            if (q.analysis) html += '<div class="edu-hint">解析：' + escapeHtml(q.analysis) + '</div>';
            html += '</div>';
        });
        html += '</div>';
        if (box) box.innerHTML = html;
        loadTeachWqRecords();
    }).catch(function (e) { if (box) box.innerHTML = '<div class="edu-stat-note">获取失败：' + e + '</div>'; });
}

function loadTeachWqRecords() {
    var box = document.getElementById('teach-wq-records');
    if (!box) return;
    teachApi('/web-questions/records?limit=30').then(function (res) {
        var list = (res && res.data) || [];
        if (!list.length) { box.innerHTML = '<div class="edu-stat-note">还没有获取记录。</div>'; return; }
        box.innerHTML = list.map(function (r) {
            var saved = (r.saved_ids || []).length;
            return '<div class="edu-card"><div class="edu-card-title">' + escapeHtml(r.query || r.subject || '—') + '</div>' +
                '<div class="edu-card-meta">' + escapeHtml(r.source_type || '') + ' · 入库 ' + saved + ' 道 · ' + escapeHtml(r.created_at || '') + '</div>' +
                '<div class="edu-card-actions"><button class="btn btn-sm" onclick="teachViewRecord(' + r.id + ')"><i class="fas fa-eye"></i> 查看</button>' +
                '<button class="btn btn-sm" onclick="teachDeleteRecord(' + r.id + ')"><i class="fas fa-trash"></i></button></div></div>';
        }).join('');
    });
}

function teachViewRecord(id) {
    teachApi('/web-questions/records/' + id).then(function (res) {
        var r = (res && res.data) || {};
        var html = '<div class="edu-panel"><div class="edu-panel-title">' + escapeHtml(r.query || '') + '</div>';
        (r.payload || []).forEach(function (q, i) {
            html += '<div class="teach-outline-ex"><b>' + (i + 1) + '. ' + escapeHtml(q.stem || '') + '</b>';
            (q.options || []).forEach(function (o, k) { html += '<div>' + "ABCDEFGH"[k] + '. ' + escapeHtml(o) + '</div>'; });
            html += '<div class="teach-ans">答案：' + escapeHtml(q.answer || '（无）') + '</div></div>';
        });
        html += '<button class="btn btn-sm" onclick="document.getElementById(\'teach-wq-result\').innerHTML=\'\'">收起</button></div>';
        document.getElementById('teach-wq-result').innerHTML = html;
    });
}

function teachDeleteRecord(id) {
    teachApi('/web-questions/records/' + id, { method: 'DELETE' }).then(function () { loadTeachWqRecords(); });
}

// ================= 实时问答 =================

function teachVoiceInfo() {
    teachApi('/voice/info').then(function (res) {
        var d = (res && res.data) || {};
        var e = d.asr_engines || {};
        var hint = document.getElementById('teach-voice-hint');
        if (hint) {
            hint.textContent = '本地 ASR：' + (e.local ? '可用' : '未安装') + '　云端 ASR：' + (e.cloud ? '可用' : '未配置') + '　浏览器 ASR：可用';
        }
    });
}

function teachVoiceToggle() {
    var engine = document.getElementById('teach-voice-engine').value;
    if (engine === 'browser') {
        teachBrowserRecognize();
        return;
    }
    var btn = document.getElementById('teach-voice-btn');
    if (_teachState.recording) {
        try { _teachState.mediaRecorder.stop(); } catch (e) {}
        _teachState.recording = false;
        if (btn) btn.innerHTML = '<i class="fas fa-microphone"></i> 开始录音';
        return;
    }
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
        showToast('当前环境不支持录音，请改用文字提问或浏览器 ASR', 'error');
        return;
    }
    navigator.mediaDevices.getUserMedia({ audio: true }).then(function (stream) {
        var mr = new MediaRecorder(stream);
        _teachState.mediaRecorder = mr;
        _teachState.audioChunks = [];
        mr.ondataavailable = function (ev) { if (ev.data && ev.data.size) _teachState.audioChunks.push(ev.data); };
        mr.onstop = function () {
            stream.getTracks().forEach(function (t) { t.stop(); });
            var blob = new Blob(_teachState.audioChunks, { type: mr.mimeType || 'audio/webm' });
            var reader = new FileReader();
            reader.onloadend = function () {
                var b64 = String(reader.result).split(',')[1] || '';
                teachVoiceAsk({ audio_base64: b64 });
            };
            reader.readAsDataURL(blob);
        };
        mr.start();
        _teachState.recording = true;
        if (btn) btn.innerHTML = '<i class="fas fa-stop"></i> 结束录音';
    }).catch(function (e) { showToast('无法访问麦克风：' + e, 'error'); });
}

function teachBrowserRecognize() {
    var SR = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SR) { showToast('当前浏览器不支持语音识别，请改用其它引擎', 'error'); return; }
    var rec = new SR();
    rec.lang = 'zh-CN';
    rec.interimResults = false;
    var btn = document.getElementById('teach-voice-btn');
    if (btn) btn.innerHTML = '<i class="fas fa-ear-listen"></i> 识别中…';
    rec.onresult = function (ev) {
        var text = ev.results[0][0].transcript || '';
        if (btn) btn.innerHTML = '<i class="fas fa-microphone"></i> 开始录音';
        if (text) teachVoiceAsk({ text: text });
    };
    rec.onerror = function () { if (btn) btn.innerHTML = '<i class="fas fa-microphone"></i> 开始录音'; showToast('浏览器语音识别失败', 'error'); };
    rec.onend = function () { if (btn) btn.innerHTML = '<i class="fas fa-microphone"></i> 开始录音'; };
    rec.start();
}

function teachVoiceAskText() {
    var text = (document.getElementById('teach-voice-text').value || '').trim();
    if (!text) return;
    document.getElementById('teach-voice-text').value = '';
    teachVoiceAsk({ text: text });
}

function teachVoiceAsk(payload) {
    var box = document.getElementById('teach-voice-result');
    if (box) box.innerHTML = '<div class="edu-stat-note">正在作答…</div>';
    payload = payload || {};
    payload.engine = document.getElementById('teach-voice-engine').value;
    payload.subject = (document.getElementById('teach-voice-subject').value || '').trim();
    payload.speak = document.getElementById('teach-voice-speak').checked;
    payload.session_id = document.getElementById('teach-mem-session') ? document.getElementById('teach-mem-session').value : 'default';
    teachApi('/voice/ask', {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload)
    }).then(function (res) {
        if (!res || !res.success) {
            if (box) box.innerHTML = '<div class="edu-stat-note">' + escapeHtml((res && res.message) || '问答失败') + '</div>';
            return;
        }
        var html = '';
        if (res.asr && res.asr.text) html += '<div class="edu-hint">语音识别：' + escapeHtml(res.asr.text) + '</div>';
        html += '<div class="teach-qa-q"><b>问：</b>' + escapeHtml(res.question || '') + '</div>';
        html += '<div class="teach-qa-a"><b>答：</b>' + escapeHtml(res.answer || '').replace(/\n/g, '<br>') + '</div>';
        if (res.audio_url) html += '<audio controls src="' + res.audio_url + '" style="margin-top:8px;width:100%"></audio>';
        if (box) box.innerHTML = html;
    }).catch(function (e) { if (box) box.innerHTML = '<div class="edu-stat-note">问答失败：' + e + '</div>'; });
}

// ================= 连续记忆 =================

function teachLoadMemory() {
    var sid = (document.getElementById('teach-mem-session').value || 'default').trim() || 'default';
    var box = document.getElementById('teach-mem-history');
    teachApi('/memory/history?session_id=' + encodeURIComponent(sid) + '&limit=60').then(function (res) {
        var list = (res && res.data) || [];
        if (!box) return;
        if (!list.length) { box.innerHTML = '<div class="edu-stat-note">该会话还没有对话记忆。</div>'; return; }
        box.innerHTML = list.map(function (m) {
            var role = m.role === 'user' ? '学生' : '老师';
            return '<div class="edu-card-meta"><b>' + role + '</b>：' + escapeHtml(String(m.content || '').slice(0, 200)) + '</div>';
        }).join('');
    });
    teachApi('/memory/stats').then(function (res) {
        var d = (res && res.data) || {};
        var el = document.getElementById('teach-mem-stats');
        if (el) el.textContent = '教学会话 ' + (d.sessions || 0) + ' 个 · 长期记忆总量 ' + (d.vector_total || 0) + ' 条';
    });
}

function teachClearMemory() {
    var sid = (document.getElementById('teach-mem-session').value || 'default').trim() || 'default';
    teachApi('/memory/clear', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ session_id: sid }) })
        .then(function (res) { showToast((res && res.message) || '已清空', 'success'); teachLoadMemory(); });
}

function teachRemember() {
    var sid = (document.getElementById('teach-mem-session').value || 'default').trim() || 'default';
    var content = (document.getElementById('teach-mem-content').value || '').trim();
    if (!content) return;
    teachApi('/memory/remember', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ session_id: sid, content: content }) })
        .then(function (res) {
            showToast(res && res.success ? '已写入长期记忆' : '写入失败', res && res.success ? 'success' : 'error');
            if (res && res.success) { document.getElementById('teach-mem-content').value = ''; teachLoadMemory(); }
        });
}

// ================= 对话（豆包式） =================

function teachChatLoad() {
    var sid = (document.getElementById('teach-chat-session').value || 'chat').trim() || 'chat';
    teachApi('/memory/history?session_id=' + encodeURIComponent(sid) + '&limit=100').then(function (res) {
        var list = (res && res.data) || [];
        _teachState.chatMessages = list;
        teachChatRender();
    });
}

function teachChatRender() {
    var box = document.getElementById('teach-chat-list');
    if (!box) return;
    box.innerHTML = _teachState.chatMessages.map(function (m) {
        var role = m.role === 'user' ? 'user' : 'ai';
        return '<div class="teach-msg ' + role + '"><div class="teach-bubble">' +
            escapeHtml(String(m.content || '')).replace(/\n/g, '<br>') + '</div></div>';
    }).join('');
    box.scrollTop = box.scrollHeight;
}

function teachChatKey(e) {
    if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault();
        teachChatSend();
    }
}

function teachChatSend() {
    var input = document.getElementById('teach-chat-text');
    var text = (input.value || '').trim();
    if (!text) return;
    var sid = (document.getElementById('teach-chat-session').value || 'chat').trim() || 'chat';
    input.value = '';
    _teachState.chatMessages.push({ role: 'user', content: text });
    teachChatRender();
    var box = document.getElementById('teach-chat-list');
    var pending = document.createElement('div');
    pending.className = 'teach-msg ai';
    pending.innerHTML = '<div class="teach-bubble">思考中…</div>';
    if (box) { box.appendChild(pending); box.scrollTop = box.scrollHeight; }
    teachApi('/chat', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ text: text, session_id: sid, speak: false })
    }).then(function (res) {
        pending.remove();
        var answer = (res && res.success) ? (res.answer || '') : ((res && res.message) || '回答失败');
        _teachState.chatMessages.push({ role: 'assistant', content: answer });
        teachChatRender();
    }).catch(function (e) {
        pending.remove();
        _teachState.chatMessages.push({ role: 'assistant', content: '回答失败：' + e });
        teachChatRender();
    });
}

function teachChatClear() {
    var sid = (document.getElementById('teach-chat-session').value || 'chat').trim() || 'chat';
    teachApi('/memory/clear', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ session_id: sid }) })
        .then(function () {
            _teachState.chatMessages = [];
            teachChatRender();
            showToast('已开启新会话', 'success');
        });
}

// ================= 幻灯片：再导出 / 编辑 =================

function teachExportSlide(id) {
    showToast('正在重新导出文件…', 'info');
    teachApi('/slides/' + id + '/export', { method: 'POST' }).then(function (res) {
        var ok = res && res.success;
        showToast((res && res.message) || (ok ? '已重新导出' : '导出失败'), ok ? 'success' : 'error');
        if (ok) loadTeachSlides();
    }).catch(function (e) { showToast('导出失败：' + e, 'error'); });
}

function teachEditSlide(id) {
    teachApi('/slides/' + id).then(function (res) {
        var s = (res && res.data) || {};
        showDialog('编辑幻灯片',
            '<div class="edu-form">' +
            '<label>标题</label>' +
            '<input type="text" id="teach-slide-edit-title" value="' + escapeHtml(s.title || '') + '">' +
            '<label>学科</label>' +
            '<input type="text" id="teach-slide-edit-subject" value="' + escapeHtml(s.subject || '') + '">' +
            '<label>年级</label>' +
            '<input type="text" id="teach-slide-edit-grade" value="' + escapeHtml(s.grade || '') + '">' +
            '</div>',
            function () {
                var patch = {
                    title: (document.getElementById('teach-slide-edit-title').value || '').trim(),
                    subject: (document.getElementById('teach-slide-edit-subject').value || '').trim(),
                    grade: (document.getElementById('teach-slide-edit-grade').value || '').trim()
                };
                closeDialog();
                teachApi('/slides/' + id, {
                    method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(patch)
                }).then(function (r) {
                    showToast((r && r.message) || (r && r.success ? '已更新' : '更新失败'), r && r.success ? 'success' : 'error');
                    if (r && r.success) loadTeachSlides();
                }).catch(function (e) { showToast('更新失败：' + e, 'error'); });
            });
    }).catch(function (e) { showToast('读取幻灯片失败：' + e, 'error'); });
}

// ================= 连续记忆：语义检索 =================

function teachSearchMemory() {
    var q = (document.getElementById('teach-mem-query').value || '').trim();
    var box = document.getElementById('teach-mem-search');
    if (!q) { showToast('请输入检索内容', 'error'); return; }
    if (box) { box.textContent = '检索中…'; }
    teachApi('/memory/search?query=' + encodeURIComponent(q) + '&top_k=8').then(function (res) {
        var list = (res && res.data) || [];
        if (!box) return;
        if (!list.length) { box.textContent = '没有命中相关记忆。'; return; }
        box.innerHTML = list.map(function (m, i) {
            var sim = (typeof m.similarity === 'number') ? m.similarity : (typeof m.score === 'number' ? m.score : null);
            var score = (sim !== null) ? ('相似度 ' + sim.toFixed(3)) : '';
            var content = m.content || m.text || '';
            return '<div style="margin-bottom:8px"><b>' + (i + 1) + '.</b> ' + escapeHtml(String(content)) +
                (score ? ' <span class="edu-hint">' + score + '</span>' : '') + '</div>';
        }).join('');
    }).catch(function (e) { if (box) box.textContent = '检索失败：' + e; });
}

// ================= 语音：TTS 试听 =================

function teachSpeakTest() {
    var box = document.getElementById('teach-tts-out');
    var text = (document.getElementById('teach-tts-text').value || '').trim();
    if (!text) {
        // 留空则朗读实时问答里的最新回答
        var qaBox = document.getElementById('teach-voice-result');
        var ans = qaBox ? qaBox.querySelector('.teach-qa-a') : null;
        text = ans ? (ans.textContent || '').replace(/^答：/, '').trim() : '';
    }
    if (!text) { showToast('请输入要朗读的文本，或先生成一条回答', 'error'); return; }
    if (box) box.innerHTML = '<div class="edu-hint">正在合成语音…</div>';
    teachApi('/voice/tts', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ text: text }) })
        .then(function (res) {
            if (!res || !res.success) {
                if (box) box.innerHTML = '<div class="edu-hint is-error">' + escapeHtml((res && res.message) || '合成失败') + '</div>';
                return;
            }
            if (box) {
                box.innerHTML = '<div class="teach-audio"><audio controls autoplay src="' +
                    escapeHtml(res.audio_url || '') + '"></audio></div>';
            }
            var hint = document.getElementById('teach-tts-text');
            if (hint && !hint.value) hint.value = '';
        }).catch(function (e) {
            if (box) box.innerHTML = '<div class="edu-hint is-error">合成失败：' + escapeHtml(String(e)) + '</div>';
        });
}

// ================= OCR 工具 =================

function teachOcrRender(data, label) {
    var box = document.getElementById('teach-ocr-out');
    if (!box) return;
    var html = '<div class="edu-result-title">' + escapeHtml(label) + (data && data.engine ? ('（' + escapeHtml(data.engine) + '）') : '') + '</div>';
    var questions = (data && data.questions) || [];
    if (questions.length) {
        questions.forEach(function (q, i) {
            html += '<div style="margin-bottom:8px"><b>' + (i + 1) + '.</b> ' + escapeHtml(String(q.stem || q.question || '')) + '</div>';
            (q.options || []).forEach(function (o) { html += '<div class="edu-option">' + escapeHtml(String(o)) + '</div>'; });
            if (q.answer) html += '<div class="teach-ans">答案：' + escapeHtml(String(q.answer)) + '</div>';
        });
    } else if (data && data.text) {
        html += escapeHtml(data.text);
    } else {
        html += '<span class="edu-hint">未识别到文字内容。</span>';
    }
    box.innerHTML = html;
}

function teachOcrFail(prefix, res) {
    var box = document.getElementById('teach-ocr-out');
    if (box) box.innerHTML = '<div class="edu-hint is-error">' + escapeHtml(prefix + '：' + ((res && res.message) || '识别失败')) + '</div>';
}

function teachOcrImage() {
    var path = (document.getElementById('teach-ocr-path').value || '').trim();
    if (!path) { showToast('请先选择或填写图片路径', 'error'); return; }
    var box = document.getElementById('teach-ocr-out');
    if (box) box.innerHTML = '<div class="edu-hint">识别中…</div>';
    teachApi('/ocr', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ image_path: path, backend: 'auto' })
    }).then(function (res) {
        if (!res || !res.success) { teachOcrFail('图片识别失败', res); return; }
        teachOcrRender(res, '图片 OCR');
    }).catch(function (e) { teachOcrFail('图片识别失败', { message: String(e) }); });
}

function teachOcrScreen() {
    var box = document.getElementById('teach-ocr-out');
    if (box) box.innerHTML = '<div class="edu-hint">正在截屏识别…</div>';
    teachApi('/ocr/screen', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ backend: 'auto' }) })
        .then(function (res) {
            if (!res || !res.success) { teachOcrFail('屏幕识别失败', res); return; }
            teachOcrRender(res, '屏幕 OCR');
        }).catch(function (e) { teachOcrFail('屏幕识别失败', { message: String(e) }); });
}

function teachOcrQuestion() {
    var path = (document.getElementById('teach-ocr-path').value || '').trim();
    if (!path) { showToast('请先选择或填写图片路径', 'error'); return; }
    var box = document.getElementById('teach-ocr-out');
    if (box) box.innerHTML = '<div class="edu-hint">正在结构化识别题目…</div>';
    teachApi('/ocr/question', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ image_path: path, backend: 'auto' })
    }).then(function (res) {
        if (!res || !res.success) { teachOcrFail('题目识别失败', res); return; }
        teachOcrRender(res, '结构化题目');
    }).catch(function (e) { teachOcrFail('题目识别失败', { message: String(e) }); });
}

// ============= 扩展中心（统一管理原生插件 / 原生技能 / MCP / DSH） =============
// 管理面合并到一页，但执行面各走各的管道，互不影响：
//   原生插件  -> star Handler 命令管道（拦截式，命中即不调用大模型）
//   原生技能  -> Agent 工具（FunctionToolManager）
//   MCP 服务  -> Agent 工具（工具名带 mcp__ 前缀隔离，与技能同名也不冲突）
//   DSH 插件 / DSH 技能 -> DSH 内核子进程内，随内核重启生效

var extState = { cat: 'plugin', mcp: [] };

var EXT_CATS = ['plugin', 'skill', 'mcp', 'dsh-plugin', 'dsh-skill', 'market', 'engine'];

var EXT_OV_DEFS = [
    { key: 'plugin', cat: 'plugin', icon: 'fas fa-puzzle-piece', label: '原生插件' },
    { key: 'skill', cat: 'skill', icon: 'fas fa-wand-magic-sparkles', label: '原生技能' },
    { key: 'mcp', cat: 'mcp', icon: 'fas fa-plug-circle-bolt', label: 'MCP 服务' },
    { key: 'dsh_plugin', cat: 'dsh-plugin', icon: 'fas fa-bolt', label: 'DSH 插件' },
    { key: 'dsh_skill', cat: 'dsh-skill', icon: 'fas fa-feather', label: 'DSH 技能' }
];

function extEsc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
        return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
}

function extFetch(method, url, body) {
    var opt = { method: method };
    if (body !== undefined) {
        opt.headers = { 'Content-Type': 'application/json' };
        opt.body = JSON.stringify(body);
    }
    return fetch(url, opt).then(function (r) {
        return r.json().catch(function () { return {}; });
    });
}

function loadExtensions() {
    loadExtensionsOverview();
    switchExtCategory(extState.cat);
}

function switchExtCategory(cat, btn) {
    if (EXT_CATS.indexOf(cat) < 0) cat = 'plugin';
    extState.cat = cat;
    EXT_CATS.forEach(function (c) {
        var panel = document.getElementById('ext-cat-' + c);
        if (panel) panel.classList.toggle('hidden', c !== cat);
    });
    document.querySelectorAll('.ext-cat-btn').forEach(function (b) {
        b.classList.toggle('active', b.dataset.cat === cat);
    });
    // 按需加载：只在该分类被打开时才请求后端
    if (cat === 'plugin') loadPlugins();
    else if (cat === 'skill') loadSkillsPage();
    else if (cat === 'mcp') loadMcpServers();
    else if (cat === 'dsh-plugin') loadDshPlugins();
    else if (cat === 'dsh-skill') loadDshSkills();
    else if (cat === 'engine') loadEngineExtensions();
}

// ---------- 引擎扩展（子代理 / 工具场景 / 钩子 / 声明式清单） ----------

function loadEngineExtensions() {
    var box = document.getElementById('engine-ext-body');
    if (!box) return;
    box.innerHTML = '<div class="empty-state"><i class="fas fa-spinner fa-spin"></i> 正在加载…</div>';
    // 四块数据并行取：扩展面（/api/extensions/agent）、运行记录、后台任务、场景清单
    Promise.all([
        extFetch('GET', '/api/extensions/agent').catch(function () { return null; }),
        extFetch('GET', '/api/subagent/runs?limit=30').catch(function () { return null; }),
        extFetch('GET', '/api/subagent/jobs?limit=20').catch(function () { return null; }),
        loadSubagentScenarios().catch(function () { })
    ]).then(function (res) {
        var d = res[0];
        if (!d || !d.ok) {
            box.innerHTML = '<div class="empty-state">引擎扩展信息不可用</div>';
            return;
        }
        var runsBlock = (res[1] && res[1].ok) ? res[1] : null;
        var jobsBlock = (res[2] && res[2].ok) ? res[2] : null;
        box.innerHTML = _engineSubagentHtml(d.subagent) +
            _engineRunsHtml(runsBlock) +
            _engineJobsHtml(jobsBlock) +
            _engineScenarioHtml(d.tools) +
            _engineHookHtml(d.hooks) +
            _engineManifestHtml(d.manifests);
    }).catch(function () {
        box.innerHTML = '<div class="empty-state">加载失败</div>';
    });
}

function _engineScenarioHtml(block) {
    var scenarios = (block && block.scenarios) || [];
    var groups = (block && block.groups) || [];
    var html = '<div class="ext-list-title"><i class="fas fa-layer-group"></i> 工具集场景' +
        '<span class="ext-list-count">当前 ' + extEsc((block && block.current) || 'full') + '</span></div>';
    html += '<div class="ext-hint">工具分组共 ' + groups.length +
        ' 类。默认「全部工具」不裁剪；选择其它场景后，只把该场景用得到的工具交给模型，' +
        '可显著减少工具描述占用的 token。设置入口：设置 → 高级配置 → 工具集场景。</div>';
    html += '<div class="ext-card-list">';
    scenarios.forEach(function (s) {
        var isCurrent = block && block.current === s.name;
        html += '<div class="ext-card">' +
            '<div class="ext-card-main">' +
            '<div class="ext-card-title">' + extEsc(s.label) +
            ' <span class="ext-badge ' + (isCurrent ? 'on' : 'off') + '">' + extEsc(s.name) + '</span></div>' +
            '<div class="ext-card-desc">' + extEsc(s.note || '') + '</div>' +
            '<div class="ext-card-meta">' +
            (s.groups && s.groups.length ? '分组：' + extEsc(s.groups.join(' / ')) : '不裁剪（全部放行）') +
            '</div></div></div>';
    });
    html += '</div>';

    html += '<div class="ext-list-title" style="margin-top:16px"><i class="fas fa-tags"></i> 工具分组' +
        '<span class="ext-list-count">' + groups.length + ' 类</span></div>';
    html += '<div class="ext-card-list">';
    groups.forEach(function (g) {
        html += '<div class="ext-card"><div class="ext-card-main">' +
            '<div class="ext-card-title">' + extEsc(g.label) +
            ' <span class="ext-badge off">' + extEsc(g.name) + '</span></div>' +
            '<div class="ext-card-desc">' + extEsc(g.description || '') + '</div>' +
            '<div class="ext-card-meta">匹配：' + extEsc((g.patterns || []).join(', ')) + '</div>' +
            '</div></div>';
    });
    return html + '</div>';
}

function _engineHookHtml(block) {
    var items = (block && block.items) || [];
    var html = '<div class="ext-list-title"><i class="fas fa-code-branch"></i> 生命周期钩子' +
        '<span class="ext-list-count">' + ((block && block.total) || 0) + ' 个</span></div>';
    html += '<div class="ext-hint">钩子可在 智能体开始 / 工具开始 / 工具结束 / 智能体完成 ' +
        '四个时点介入。放在插件目录的 extension.json 里声明即可挂上（class + module 或 path）。' +
        '钩子异常会被吞掉并记日志，不会影响主对话。</div>';
    if (!items.length) {
        return html + '<div class="empty-state">当前没有注册任何钩子</div>';
    }
    html += '<div class="ext-card-list">';
    items.forEach(function (h) {
        html += '<div class="ext-card"><div class="ext-card-main">' +
            '<div class="ext-card-title">' + extEsc(h.name) + '</div>' +
            '<div class="ext-card-desc">' + extEsc(h.doc || '') + '</div>' +
            '<div class="ext-card-meta">' + extEsc(h.module || '') +
            ' · 响应 ' + extEsc((h.events || []).join(', ')) + '</div>' +
            '</div></div>';
    });
    return html + '</div>';
}

function _engineManifestHtml(block) {
    var items = (block && block.items) || [];
    var html = '<div class="ext-list-title"><i class="fas fa-file-code"></i> 声明式扩展清单' +
        '<span class="ext-list-count">' + ((block && block.manifests) || 0) + ' 份</span></div>';
    html += '<div class="ext-hint">插件/技能目录下放 extension.json，即可声明自己贡献的工具分组、' +
        '子代理类型与钩子，不需要改软件代码。改完点右上角「重载清单」即时生效。</div>';
    if (!items.length) {
        return html + '<div class="empty-state">还没有任何扩展清单</div>';
    }
    html += '<div class="ext-card-list">';
    items.forEach(function (m) {
        html += '<div class="ext-card"><div class="ext-card-main">' +
            '<div class="ext-card-title">' + extEsc(m.name) +
            (m.version ? ' <span class="ext-badge off">v' + extEsc(m.version) + '</span>' : '') +
            '</div>' +
            '<div class="ext-card-meta">工具分组 ' + (m.tool_groups || 0) +
            ' · 子代理 ' + (m.subagents || 0) + ' · 钩子 ' + (m.hooks || 0) + '</div>' +
            '<div class="ext-card-meta">' + extEsc(m.source || '') + '</div>' +
            '</div></div>';
    });
    return html + '</div>';
}

function reloadExtensionManifests() {
    extFetch('POST', '/api/extensions/manifests/reload').then(function (d) {
        var res = (d && d.result) || {};
        var n = (res.loaded || []).length;
        showToast('扩展清单已重载：新加载 ' + n + ' 份，跳过 ' + (res.skipped || 0) + ' 份');
        loadEngineExtensions();
        loadExtensionsOverview();
    }).catch(function () {
        showToast('重载扩展清单失败', 'error');
    });
}

// ---------- 子代理：类型管理 / 运行记录 / 后台任务 ----------

var _subagentScenarios = [];
var _subagentGroups = [];
var _subagentTypes = [];

function loadSubagentScenarios() {
    if (_subagentScenarios.length) return Promise.resolve();
    return fetch('/api/subagent/scenarios').then(function (r) { return r.json(); })
        .then(function (d) {
            _subagentScenarios = (d && d.scenarios) || [];
            _subagentGroups = (d && d.groups) || [];
        })
        .catch(function () { });
}

function _engineSubagentHtml(block) {
    var types = (block && block.types) || [];
    _subagentTypes = types;
    var html = '<div class="ext-list-title"><i class="fas fa-robot"></i> 子代理类型' +
        '<span class="ext-list-count">' + types.length + ' 个</span>' +
        '<span class="ext-sub-spacer"></span>' +
        '<button class="btn btn-sm btn-primary" onclick="openSubagentTypeEditor(\'\')">' +
        '<i class="fas fa-plus"></i> 新建类型</button></div>';
    html += '<div class="ext-hint">主 Agent 可以把自包含的子任务派给这些类型执行，' +
        '每个类型有独立上下文、独立工具权限与轮次预算。max_depth 决定它自己还能不能再往下派' +
        '（0 = 叶子）。同名自定义类型会覆盖内置定义。</div>';
    if (!types.length) return html + '<div class="empty-state">暂无子代理类型</div>';
    html += '<div class="ext-card-list">';
    types.forEach(function (t) {
        html += '<div class="ext-card">' +
            '<div class="ext-card-main">' +
            '<div class="ext-card-title">' + extEsc(t.avatar || '') + ' ' + extEsc(t.label) +
            ' <span class="ext-badge on">' + extEsc(t.name) + '</span>' +
            (t.builtin && !t.custom ? ' <span class="ext-badge off">内置</span>' : '') +
            (t.custom ? ' <span class="ext-badge warn">自定义' +
                (t.overridden ? '（覆盖内置）' : '') + '</span>' : '') + '</div>' +
            '<div class="ext-card-desc">' + extEsc(t.description || '') + '</div>' +
            '<div class="ext-card-meta">工具 ' + (t.tool_count || 0) + ' 个 · 场景 ' +
            extEsc(t.scenario) + ' · 最多 ' + (t.max_iterations || 0) + ' 轮 · 嵌套深度 ' +
            (t.max_depth || 0) +
            (t.tool_groups && t.tool_groups.length ? ' · 分组 ' + extEsc(t.tool_groups.join('/')) : '') +
            (t.skills && t.skills.length ? ' · 技能 ' + extEsc(t.skills.join('/')) : '') +
            '</div></div>' +
            '<div class="ext-card-actions">' +
            '<button class="btn btn-sm" onclick="openSubagentTypeEditor(\'' +
            extEsc(t.name) + '\')"><i class="fas fa-pen"></i> 编辑</button>' +
            (t.custom ? '<button class="btn btn-sm btn-danger" onclick="deleteSubagentType(\'' +
                extEsc(t.name) + '\')"><i class="fas fa-trash"></i> 删除</button>' : '') +
            '</div></div>';
    });
    return html + '</div>';
}

function _engineRunsHtml(block) {
    var stats = (block && block.stats) || {};
    var runs = (block && block.runs) || [];
    var html = '<div class="ext-list-title" style="margin-top:16px">' +
        '<i class="fas fa-clock-rotate-left"></i> 子代理运行记录' +
        '<span class="ext-list-count">' + (stats.total || 0) + ' 次 · 成功 ' +
        (stats.ok || 0) + ' · 累计 ' + (stats.tokens || 0) + ' tokens</span></div>';
    html += '<div class="ext-hint">每次子代理运行结束后留档：轮次、工具调用、token 用量、耗时。' +
        '运行中的任务可以在会话里的子代理卡片上点「中断」。</div>';
    if (!runs.length) return html + '<div class="empty-state">还没有运行记录</div>';
    html += '<div class="ext-card-list">';
    runs.slice(0, 20).forEach(function (r) {
        var ok = r.ok;
        var status = r.status === 'cancelled' ? '已中断'
            : (ok ? '成功' : (r.status === 'exhausted' ? '超轮次' : '失败'));
        var when = r.finished_at ? new Date(r.finished_at * 1000).toLocaleString() : '';
        html += '<div class="ext-card"><div class="ext-card-main">' +
            '<div class="ext-card-title">' + extEsc(r.avatar || '🧩') + ' ' + extEsc(r.label || r.name) +
            ' <span class="ext-badge ' + (ok ? 'on' : 'err') + '">' + status + '</span>' +
            (r.background ? ' <span class="ext-badge warn">后台</span>' : '') +
            (r.depth > 1 ? ' <span class="ext-badge off">第 ' + r.depth + ' 层</span>' : '') +
            '</div>' +
            '<div class="ext-card-desc">' + extEsc((r.task || '').slice(0, 120)) + '</div>' +
            '<div class="ext-card-meta">' + (r.iterations || 0) + ' 轮 · ' +
            ((r.tool_calls || []).length) + ' 次工具 · ' + (r.elapsed_sec || 0) + 's · ' +
            (r.total_tokens || 0) + ' tokens' +
            (r.error ? ' · ' + extEsc(r.error.slice(0, 80)) : '') +
            '<br>' + extEsc(when) + '</div>' +
            '</div></div>';
    });
    return html + '</div>';
}

function _engineJobsHtml(block) {
    var stats = (block && block.stats) || {};
    var jobs = (block && block.jobs) || [];
    var html = '<div class="ext-list-title" style="margin-top:16px">' +
        '<i class="fas fa-inbox"></i> 后台任务' +
        '<span class="ext-list-count">运行中 ' + (stats.running || 0) + ' · 已完成 ' +
        (stats.done || 0) + ' · 待回灌 ' + (stats.undelivered || 0) + '</span></div>';
    html += '<div class="ext-hint">spawn_background_subagent 起的长任务：不阻塞对话，' +
        '跑完后结果会在下一轮对话开头自动回灌给主 Agent。</div>';
    if (!jobs.length) return html + '<div class="empty-state">还没有后台任务</div>';
    html += '<div class="ext-card-list">';
    jobs.forEach(function (j) {
        var running = j.status === 'running';
        var label = j.status === 'done' ? '已完成'
            : (j.status === 'running' ? '运行中'
                : (j.status === 'cancelled' ? '已取消' : '失败'));
        html += '<div class="ext-card"><div class="ext-card-main">' +
            '<div class="ext-card-title">' + extEsc(j.agent_type) +
            ' <span class="ext-badge ' + (j.status === 'done' ? 'on' : (running ? 'warn' : 'err')) +
            '">' + label + '</span>' +
            (j.delivered ? ' <span class="ext-badge off">已回灌</span>' : '') + '</div>' +
            '<div class="ext-card-desc">' + extEsc((j.task || '').slice(0, 140)) + '</div>' +
            (j.result ? '<div class="ext-card-meta">结论：' +
                extEsc(j.result.slice(0, 200)) + '</div>' : '') +
            (j.error ? '<div class="ext-card-meta">' + extEsc(j.error) + '</div>' : '') +
            '</div>' +
            (running && j.run_id ? '<div class="ext-card-actions">' +
                '<button class="btn btn-sm btn-danger" onclick="_cancelSubagent(\'' +
                extEsc(j.run_id) + '\')"><i class="fas fa-stop"></i> 中断</button></div>' : '') +
            '</div>';
    });
    return html + '</div>';
}

// ── 类型编辑器 ──

function _subagentTypeField(spec) {
    return {
        name: spec.name || '',
        label: spec.label || '',
        avatar: spec.avatar || '🧩',
        description: spec.description || '',
        system_prompt: spec.system_prompt || '',
        scenario: spec.scenario || 'chat',
        tool_groups: (spec.tool_groups || []).join(', '),
        allow_tools: (spec.allow_tools || []).join(', '),
        deny_tools: (spec.deny_tools || []).join(', '),
        skills: (spec.skills || []).join(', '),
        max_iterations: spec.max_iterations || 24,
        temperature: spec.temperature === undefined ? 0.4 : spec.temperature,
        max_depth: spec.max_depth === undefined ? 2 : spec.max_depth,
    };
}

function openSubagentTypeEditor(name) {
    loadSubagentScenarios().then(function () {
        var hit = null;
        for (var i = 0; i < _subagentTypes.length; i++) {
            if (_subagentTypes[i].name === name) { hit = _subagentTypes[i]; break; }
        }
        var f = _subagentTypeField(hit || {});
        var editing = !!name;
        var scenarioOpts = _subagentScenarios.map(function (s) {
            return '<option value="' + extEsc(s.name) + '"' +
                (s.name === f.scenario ? ' selected' : '') + '>' +
                extEsc(s.label || s.name) + '</option>';
        }).join('');
        var groupHint = _subagentGroups.map(function (g) { return g.name; }).join(' / ');

        showDialog(editing ? ('编辑子代理类型：' + f.label) : '新建子代理类型', ''
            + '<div class="agent-dlg-grid">'
            + '<div class="form-group"><label>标识 name（英文短名，不可改）</label>'
            + '<input type="text" id="sa-t-name" value="' + extEsc(f.name) + '"'
            + (editing ? ' disabled' : '') + ' placeholder="如 code_reviewer"></div>'
            + '<div class="form-group"><label>展示名</label>'
            + '<input type="text" id="sa-t-label" value="' + extEsc(f.label) + '" placeholder="如 代码审查员"></div>'
            + '<div class="form-group"><label>头像 emoji</label>'
            + '<input type="text" id="sa-t-avatar" value="' + extEsc(f.avatar) + '"></div>'
            + '<div class="form-group"><label>工具场景</label>'
            + '<select id="sa-t-scenario">' + scenarioOpts + '</select></div>'
            + '</div>'
            + '<div class="form-group"><label>适用场景描述（决定主 Agent 什么时候派给它）</label>'
            + '<textarea id="sa-t-desc" rows="2">' + extEsc(f.description) + '</textarea></div>'
            + '<div class="form-group"><label>人格与工作方式（system prompt）</label>'
            + '<textarea id="sa-t-prompt" rows="5">' + extEsc(f.system_prompt) + '</textarea></div>'
            + '<div class="agent-dlg-grid">'
            + '<div class="form-group"><label>追加工具分组（逗号分隔）</label>'
            + '<input type="text" id="sa-t-groups" value="' + extEsc(f.tool_groups) + '" placeholder="' + extEsc(groupHint) + '"></div>'
            + '<div class="form-group"><label>技能白名单（逗号分隔，留空=不限）</label>'
            + '<input type="text" id="sa-t-skills" value="' + extEsc(f.skills) + '"></div>'
            + '</div>'
            + '<div class="agent-dlg-grid">'
            + '<div class="form-group"><label>额外允许的工具（逗号分隔）</label>'
            + '<input type="text" id="sa-t-allow" value="' + extEsc(f.allow_tools) + '"></div>'
            + '<div class="form-group"><label>禁止的工具（逗号分隔）</label>'
            + '<input type="text" id="sa-t-deny" value="' + extEsc(f.deny_tools) + '"></div>'
            + '</div>'
            + '<div class="agent-dlg-grid">'
            + '<div class="form-group"><label>最大轮次</label>'
            + '<input type="number" id="sa-t-iters" min="1" max="200" value="' + f.max_iterations + '"></div>'
            + '<div class="form-group"><label>temperature</label>'
            + '<input type="number" id="sa-t-temp" step="0.1" min="0" max="2" value="' + f.temperature + '"></div>'
            + '<div class="form-group"><label>嵌套深度 max_depth（0=不再往下派）</label>'
            + '<input type="number" id="sa-t-depth" min="0" max="5" value="' + f.max_depth + '"></div>'
            + '</div>', function () {
                _saveSubagentType(editing);
            });
    });
}

function _saSplit(id) {
    var el = document.getElementById(id);
    if (!el) return [];
    return String(el.value || '').split(/[,，\n]/)
        .map(function (s) { return s.trim(); }).filter(Boolean);
}

function _saveSubagentType(editing) {
    var nameEl = document.getElementById('sa-t-name');
    var name = nameEl ? nameEl.value.trim() : '';
    if (!name) { showToast('标识 name 不能为空', 'error'); return; }
    var prompt = (document.getElementById('sa-t-prompt') || {}).value || '';
    if (!prompt.trim()) { showToast('人格与工作方式（system prompt）不能为空', 'error'); return; }

    var payload = {
        name: name,
        label: (document.getElementById('sa-t-label') || {}).value || '',
        avatar: (document.getElementById('sa-t-avatar') || {}).value || '🧩',
        description: (document.getElementById('sa-t-desc') || {}).value || '',
        system_prompt: prompt,
        scenario: (document.getElementById('sa-t-scenario') || {}).value || 'chat',
        tool_groups: _saSplit('sa-t-groups'),
        allow_tools: _saSplit('sa-t-allow'),
        deny_tools: _saSplit('sa-t-deny'),
        skills: _saSplit('sa-t-skills'),
        max_iterations: parseInt((document.getElementById('sa-t-iters') || {}).value, 10) || 24,
        temperature: parseFloat((document.getElementById('sa-t-temp') || {}).value) || 0.4,
        max_depth: parseInt((document.getElementById('sa-t-depth') || {}).value, 10) || 0,
    };

    extFetch('POST', '/api/subagent/types', payload).then(function (d) {
        if (d && d.ok) {
            closeDialog();
            showToast('子代理类型已保存：' + name + (d.updated ? '（更新）' : '（新建）'));
            loadEngineExtensions();
        } else {
            showToast('保存失败：' + ((d && d.error) || '未知错误'), 'error');
        }
    }).catch(function () { showToast('保存失败', 'error'); });
}

function deleteSubagentType(name) {
    if (!confirm('确定删除自定义子代理类型「' + name + '」吗？\n如果是覆盖内置的同名类型，删除后会恢复内置定义。')) return;
    extFetch('DELETE', '/api/subagent/types/' + encodeURIComponent(name)).then(function (d) {
        if (d && d.ok) {
            showToast('已删除：' + name);
            loadEngineExtensions();
        } else {
            showToast('删除失败：' + ((d && d.error) || '未知错误'), 'error');
        }
    }).catch(function () { showToast('删除失败', 'error'); });
}

// ---------- 总览 ----------

function loadExtensionsOverview() {
    var box = document.getElementById('ext-overview');
    if (!box) return;
    extFetch('GET', '/api/extensions/overview').then(function (d) {
        var cats = (d && d.categories) || {};
        box.innerHTML = EXT_OV_DEFS.map(function (def) {
            var c = cats[def.key] || {};
            return '<div class="ext-ov-card" data-cat="' + def.cat + '">' +
                '<div class="ext-ov-icon"><i class="' + def.icon + '"></i></div>' +
                '<div class="ext-ov-body">' +
                '<div class="ext-ov-num">' + (c.total || 0) + '</div>' +
                '<div class="ext-ov-label">' + def.label + '</div>' +
                '<div class="ext-ov-sub">' + extOverviewSub(def.key, c) + '</div>' +
                '</div></div>';
        }).join('');
        box.querySelectorAll('.ext-ov-card').forEach(function (el) {
            el.onclick = function () { switchExtCategory(el.dataset.cat); };
        });
    }).catch(function () {
        box.innerHTML = '<div class="empty-state">总览加载失败</div>';
    });
}

function extOverviewSub(key, c) {
    if (key === 'plugin') return '启用 ' + (c.active || 0) + (c.error ? ' · 异常 ' + c.error : '');
    if (key === 'skill') return '启用 ' + (c.active || 0) + (c.pending ? ' · 待审 ' + c.pending : '');
    if (key === 'mcp') return '已连接 ' + (c.connected || 0) + ' · 工具 ' + (c.tools || 0);
    return c.running ? '内核运行中' : '内核未运行';
}

function extReloadAll() {
    showToast('正在重载各类扩展…', 'info');
    Promise.all([
        extFetch('POST', '/api/plugins/reload-all'),
        extFetch('POST', '/api/skills/reload'),
        extFetch('POST', '/api/mcp/reload')
    ]).then(function () {
        showToast('已重载插件 / 技能 / MCP', 'success');
        loadExtensionsOverview();
        switchExtCategory(extState.cat);
    }).catch(function (e) {
        showToast('重载出现异常: ' + e.message, 'error');
    });
}

// ---------- MCP 服务 ----------

function loadMcpServers() {
    var box = document.getElementById('mcp-list');
    if (!box) return;
    box.innerHTML = '<div class="empty-state"><i class="fas fa-spinner fa-spin"></i> 加载中...</div>';
    extFetch('GET', '/api/mcp/servers').then(function (d) {
        var list = (d && d.servers) || [];
        extState.mcp = list;
        if (!list.length) {
            box.innerHTML = '<div class="empty-state">尚未接入 MCP 服务。点击右上角「添加服务」接入本地 stdio 或远程 HTTP/SSE 服务，'
                + '其工具会自动注入 Agent 工具列表（带 mcp__ 前缀，与原生技能互不冲突）。</div>';
            return;
        }
        box.innerHTML = list.map(mcpCardHtml).join('');
        mcpBindCards(box);
    }).catch(function (e) {
        box.innerHTML = '<div class="empty-state">加载失败: ' + extEsc(e.message) + '</div>';
    });
}

function mcpCardHtml(s) {
    var name = s.name || '';
    var active = !!s.active;
    var connected = !!s.connected;
    var transport = s.transport || 'stdio';
    var badge = connected
        ? '<span class="ext-badge on">已连接</span>'
        : (active ? '<span class="ext-badge warn">未连接</span>' : '<span class="ext-badge off">已停用</span>');
    var target = transport === 'stdio'
        ? ((s.command || '') + ' ' + ((s.args || []).join(' '))).trim()
        : (s.url || '');
    return '<div class="ext-card">' +
        '<div class="ext-card-main">' +
        '<div class="ext-card-name">' + extEsc(name) + badge +
        '<span class="ext-badge off">' + extEsc(transport) + '</span></div>' +
        '<div class="ext-card-meta">' + extEsc(target) +
        (connected ? ' · 工具 ' + (s.tool_count || 0) : '') + '</div>' +
        (s.description ? '<div class="ext-card-desc">' + extEsc(s.description) + '</div>' : '') +
        (s.error ? '<div class="ext-card-desc" style="color:#dc2626">' + extEsc(s.error) + '</div>' : '') +
        '</div>' +
        '<div class="ext-card-actions">' +
        '<button class="btn btn-sm" data-mcp-act="tools" data-name="' + extEsc(name) + '"><i class="fas fa-screwdriver-wrench"></i> 工具</button>' +
        '<button class="btn btn-sm" data-mcp-act="toggle" data-name="' + extEsc(name) + '" data-active="' + (active ? '1' : '0') + '">' +
        (active ? '<i class="fas fa-pause"></i> 停用' : '<i class="fas fa-play"></i> 启用') + '</button>' +
        '<button class="btn btn-sm" data-mcp-act="edit" data-name="' + extEsc(name) + '"><i class="fas fa-pen"></i></button>' +
        '<button class="btn btn-sm" data-mcp-act="delete" data-name="' + extEsc(name) + '"><i class="fas fa-trash"></i></button>' +
        '</div></div>';
}

function mcpBindCards(box) {
    box.querySelectorAll('[data-mcp-act]').forEach(function (btn) {
        btn.onclick = function () {
            var act = btn.dataset.mcpAct, name = btn.dataset.name;
            if (act === 'tools') mcpShowTools(name);
            else if (act === 'toggle') mcpToggle(name, btn.dataset.active === '1');
            else if (act === 'edit') mcpOpenEditor(name);
            else if (act === 'delete') mcpDelete(name);
        };
    });
}

function mcpToggle(name, currentlyActive) {
    extFetch('POST', '/api/mcp/servers/' + encodeURIComponent(name) + '/toggle', { active: !currentlyActive })
        .then(function (d) {
            if (d && d.ok === false) { showToast(d.error || '切换失败', 'error'); return; }
            showToast(currentlyActive ? '已停用并注销其工具' : '已启用', 'success');
            loadMcpServers();
            loadExtensionsOverview();
        }).catch(function (e) { showToast('切换失败: ' + e.message, 'error'); });
}

function mcpDelete(name) {
    if (!confirm('确定删除 MCP 服务 "' + name + '" 吗？\n其已注入 Agent 的工具会一并注销。')) return;
    extFetch('DELETE', '/api/mcp/servers/' + encodeURIComponent(name)).then(function (d) {
        if (d && d.ok === false) { showToast(d.error || '删除失败', 'error'); return; }
        showToast('已删除 ' + name, 'success');
        loadMcpServers();
        loadExtensionsOverview();
    }).catch(function (e) { showToast('删除失败: ' + e.message, 'error'); });
}

function mcpShowTools(name) {
    var modal = document.getElementById('mcp-tools-modal');
    if (!modal) return;
    document.getElementById('mcp-tools-title').textContent = 'MCP 工具 · ' + name;
    var body = document.getElementById('mcp-tools-body');
    body.innerHTML = '<div class="empty-state"><i class="fas fa-spinner fa-spin"></i> 正在连接并读取工具列表…</div>';
    modal.classList.remove('hidden');
    extFetch('POST', '/api/mcp/servers/' + encodeURIComponent(name) + '/test').then(function (d) {
        if (!d || !d.ok) {
            body.innerHTML = '<div class="empty-state">读取失败：' + extEsc((d && d.error) || '未知错误') + '</div>';
            return;
        }
        var tools = d.tools || [];
        if (!tools.length) { body.innerHTML = '<div class="empty-state">该服务未暴露任何工具</div>'; return; }
        body.innerHTML = '<div class="ext-hint" style="margin-bottom:10px">共 ' + tools.length +
            ' 个工具，注入 Agent 时统一加 <code>mcp__' + extEsc(name) + '__</code> 前缀。</div>' +
            '<div class="ext-tools-list">' + tools.map(function (t) {
                var props = (t.parameters && t.parameters.properties) ? Object.keys(t.parameters.properties) : [];
                return '<div class="ext-tool-item">' +
                    '<div class="ext-tool-name">mcp__' + extEsc(name) + '__' + extEsc(t.name) + '</div>' +
                    '<div class="ext-tool-desc">' + extEsc(t.description || '（无描述）') +
                    (props.length ? '<br>参数：' + extEsc(props.join(', ')) : '') + '</div></div>';
            }).join('') + '</div>';
        loadMcpServers();
    }).catch(function (e) {
        body.innerHTML = '<div class="empty-state">读取失败：' + extEsc(e.message) + '</div>';
    });
}

function mcpParseLines(text, sep) {
    var out = {};
    (text || '').split('\n').forEach(function (line) {
        var s = line.trim();
        if (!s) return;
        var i = s.indexOf(sep);
        if (i <= 0) return;
        out[s.slice(0, i).trim()] = s.slice(i + 1).trim();
    });
    return out;
}

function mcpSyncTransport() {
    var t = (document.getElementById('mcp-f-transport') || {}).value || 'stdio';
    var stdio = document.getElementById('mcp-f-stdio');
    var remote = document.getElementById('mcp-f-remote');
    if (stdio) stdio.classList.toggle('hidden', t !== 'stdio');
    if (remote) remote.classList.toggle('hidden', t === 'stdio');
}

function mcpOpenEditor(name) {
    var modal = document.getElementById('mcp-edit-modal');
    if (!modal) return;
    var s = null;
    if (name) {
        for (var i = 0; i < extState.mcp.length; i++) {
            if (extState.mcp[i].name === name) { s = extState.mcp[i]; break; }
        }
    }
    document.getElementById('mcp-modal-title').textContent = name ? ('编辑 MCP 服务 · ' + name) : '添加 MCP 服务';
    document.getElementById('mcp-f-name').value = s ? (s.name || '') : '';
    document.getElementById('mcp-f-name').disabled = !!s;
    document.getElementById('mcp-f-transport').value = s ? (s.transport || 'stdio') : 'stdio';
    document.getElementById('mcp-f-command').value = s ? (s.command || '') : '';
    document.getElementById('mcp-f-args').value = s ? ((s.args || []).join('\n')) : '';
    document.getElementById('mcp-f-env').value = s ? Object.keys(s.env || {}).map(function (k) { return k + '=' + s.env[k]; }).join('\n') : '';
    document.getElementById('mcp-f-url').value = s ? (s.url || '') : '';
    document.getElementById('mcp-f-headers').value = s ? Object.keys(s.headers || {}).map(function (k) { return k + '=' + s.headers[k]; }).join('\n') : '';
    document.getElementById('mcp-f-desc').value = s ? (s.description || '') : '';
    document.getElementById('mcp-f-active').checked = s ? !!s.active : true;
    document.getElementById('mcp-modal-msg').className = 'ext-hint';
    document.getElementById('mcp-modal-msg').textContent = '';
    modal.dataset.editing = name || '';
    mcpSyncTransport();
    modal.classList.remove('hidden');
}

function mcpCloseEditor() {
    var modal = document.getElementById('mcp-edit-modal');
    if (modal) modal.classList.add('hidden');
}

function mcpCollectBody() {
    var transport = (document.getElementById('mcp-f-transport') || {}).value || 'stdio';
    var argsText = (document.getElementById('mcp-f-args') || {}).value || '';
    var args = argsText.split('\n').map(function (x) { return x.trim(); }).filter(function (x) { return x; });
    return {
        name: ((document.getElementById('mcp-f-name') || {}).value || '').trim(),
        transport: transport,
        command: ((document.getElementById('mcp-f-command') || {}).value || '').trim(),
        args: args,
        env: mcpParseLines((document.getElementById('mcp-f-env') || {}).value || '', '='),
        url: ((document.getElementById('mcp-f-url') || {}).value || '').trim(),
        headers: mcpParseLines((document.getElementById('mcp-f-headers') || {}).value || '', '='),
        description: ((document.getElementById('mcp-f-desc') || {}).value || '').trim(),
        active: !!(document.getElementById('mcp-f-active') || {}).checked
    };
}

function mcpSaveEditor() {
    var body = mcpCollectBody();
    var editing = (document.getElementById('mcp-edit-modal') || {}).dataset.editing || '';
    if (!body.name) { showToast('请填写服务名称', 'error'); return; }
    if (body.transport === 'stdio' && !body.command) { showToast('stdio 方式必须填写启动命令', 'error'); return; }
    if (body.transport !== 'stdio' && !body.url) { showToast('远程方式必须填写服务地址 URL', 'error'); return; }
    var req = editing
        ? extFetch('PATCH', '/api/mcp/servers/' + encodeURIComponent(editing), body)
        : extFetch('POST', '/api/mcp/servers', body);
    req.then(function (d) {
        if (!d || d.ok === false) { showToast((d && d.error) || '保存失败', 'error'); return; }
        mcpCloseEditor();
        if (d.connect_error) showToast('已保存，但连接失败：' + d.connect_error, 'error');
        else showToast('已保存并连接', 'success');
        loadMcpServers();
        loadExtensionsOverview();
    }).catch(function (e) { showToast('保存失败: ' + e.message, 'error'); });
}

function mcpTestFromEditor() {
    var body = mcpCollectBody();
    var msg = document.getElementById('mcp-modal-msg');
    if (!body.name) { msg.className = 'ext-hint err'; msg.textContent = '请先填写服务名称'; return; }
    msg.className = 'ext-hint';
    msg.textContent = '正在连接测试…（本地 npx 首次拉包可能较慢）';
    var saved = extState.mcp.some(function (s) { return s.name === body.name; });
    var url = '/api/mcp/servers/' + encodeURIComponent(body.name) + '/test';
    var req = saved ? extFetch('POST', url) : extFetch('POST', url, body);
    req.then(function (d) {
        if (d && d.ok) {
            msg.className = 'ext-hint ok';
            msg.textContent = '连接成功，发现 ' + (d.count || 0) + ' 个工具。';
        } else {
            msg.className = 'ext-hint err';
            msg.textContent = '连接失败：' + ((d && d.error) || '未知错误');
        }
    }).catch(function (e) {
        msg.className = 'ext-hint err';
        msg.textContent = '连接失败：' + e.message;
    });
}

function mcpReloadAll() {
    var box = document.getElementById('mcp-list');
    if (box) box.innerHTML = '<div class="empty-state"><i class="fas fa-spinner fa-spin"></i> 正在重连全部 MCP 服务…</div>';
    extFetch('POST', '/api/mcp/reload').then(function (d) {
        if (!d || d.ok === false) { showToast((d && d.error) || '重连失败', 'error'); }
        else if (d.errors && d.errors.length) { showToast('已连接 ' + d.connected + ' 个，' + d.errors.length + ' 个失败', 'error'); }
        else { showToast('已连接 ' + (d.connected || 0) + ' 个服务，注入 ' + (d.tools || 0) + ' 个工具', 'success'); }
        loadMcpServers();
        loadExtensionsOverview();
    }).catch(function (e) {
        showToast('重连失败: ' + e.message, 'error');
        loadMcpServers();
    });
}

// ---------- DSH 插件 / 技能（内核侧） ----------

function loadDshPlugins() {
    var userBox = document.getElementById('dsh-user-plugins');
    var builtinBox = document.getElementById('dsh-builtin-plugins');
    if (!userBox) return;
    extFetch('GET', '/api/dsh/plugins').then(function (d) {
        var user = (d && d.user) || [];
        var builtins = (d && d.builtins) || [];
        var uc = document.getElementById('dsh-user-count');
        var bc = document.getElementById('dsh-builtin-count');
        if (uc) uc.textContent = user.length;
        if (bc) bc.textContent = builtins.length;
        if (!user.length) {
            userBox.innerHTML = '<div class="empty-state">暂无用户插件。可用上方输入框从 npm 安装，或手动内联添加。</div>';
        } else {
            userBox.innerHTML = user.map(dshPluginCardHtml).join('');
            userBox.querySelectorAll('[data-dsh-act]').forEach(function (btn) {
                btn.onclick = function () {
                    if (btn.dataset.dshAct === 'toggle') dshTogglePlugin(btn.dataset.id, btn.dataset.enabled === '1');
                    else if (btn.dataset.dshAct === 'delete') dshDeletePlugin(btn.dataset.id);
                };
            });
        }
        if (builtinBox) {
            builtinBox.innerHTML = builtins.map(function (b) {
                return '<div class="ext-card"><div class="ext-card-main">' +
                    '<div class="ext-card-name">' + extEsc(b.id) +
                    (b.enabled ? '<span class="ext-badge on">启用</span>' : '<span class="ext-badge off">停用</span>') +
                    '</div>' +
                    (b.hint ? '<div class="ext-card-desc">' + extEsc(b.hint) + '</div>' : '') +
                    '</div></div>';
            }).join('') || '<div class="empty-state">无内置行</div>';
        }
    }).catch(function (e) {
        userBox.innerHTML = '<div class="empty-state">加载失败: ' + extEsc(e.message) + '</div>';
    });
}

function dshPluginCardHtml(p) {
    var on = !!p.enabled;
    return '<div class="ext-card"><div class="ext-card-main">' +
        '<div class="ext-card-name">' + extEsc(p.id) +
        (on ? '<span class="ext-badge on">启用</span>' : '<span class="ext-badge off">停用</span>') +
        '</div>' +
        '<div class="ext-card-meta">' + extEsc(p.name || '') + '</div>' +
        (p.note ? '<div class="ext-card-desc">' + extEsc(p.note) + '</div>' : '') +
        '</div><div class="ext-card-actions">' +
        '<button class="btn btn-sm" data-dsh-act="toggle" data-id="' + extEsc(p.id) + '" data-enabled="' + (on ? '1' : '0') + '">' +
        (on ? '<i class="fas fa-pause"></i> 停用' : '<i class="fas fa-play"></i> 启用') + '</button>' +
        '<button class="btn btn-sm" data-dsh-act="delete" data-id="' + extEsc(p.id) + '"><i class="fas fa-trash"></i></button>' +
        '</div></div>';
}

function dshTogglePlugin(id, currentlyEnabled) {
    extFetch('PATCH', '/api/dsh/plugins/' + encodeURIComponent(id), { enabled: !currentlyEnabled })
        .then(function (d) {
            if (d && d.ok === false) { showToast(d.error || '切换失败', 'error'); return; }
            showToast('已更新，需重启内核生效', 'success');
            loadDshPlugins();
            loadExtensionsOverview();
        }).catch(function (e) { showToast('切换失败: ' + e.message, 'error'); });
}

function dshDeletePlugin(id) {
    if (!confirm('确定删除用户插件 "' + id + '" 吗？\n（不会卸载 npm 包，仅移除配置行）')) return;
    extFetch('DELETE', '/api/dsh/plugins/' + encodeURIComponent(id), { uninstall: false })
        .then(function (d) {
            if (d && d.ok === false) { showToast(d.error || '删除失败', 'error'); return; }
            showToast('已删除 ' + id, 'success');
            loadDshPlugins();
            loadExtensionsOverview();
        }).catch(function (e) { showToast('删除失败: ' + e.message, 'error'); });
}

function dshInstallPlugin() {
    var input = document.getElementById('dsh-plug-spec');
    var spec = input ? input.value.trim() : '';
    if (!spec) { showToast('请填写 npm 包名', 'error'); return; }
    if (!confirm('确认从 npm 安装 DSH 插件：\n' + spec + '\n\n将执行 npm install，可能耗时较长。')) return;
    showToast('正在安装 ' + spec + '…', 'info');
    extFetch('POST', '/api/dsh/plugins/install', { spec: spec, enabled: true }).then(function (d) {
        if (d && d.installed) {
            showToast(d.message || '安装成功', 'success');
            if (input) input.value = '';
            loadDshPlugins();
            loadExtensionsOverview();
        } else {
            showToast((d && d.message) || '安装失败', 'error');
        }
    }).catch(function (e) { showToast('安装失败: ' + e.message, 'error'); });
}

function dshRestartCore() {
    var btn = document.getElementById('dsh-core-restart');
    if (btn) btn.disabled = true;
    showToast('正在重启 DSH 内核…', 'info');
    extFetch('POST', '/api/dsh/restart').then(function (d) {
        if (d && d.ok) showToast('内核已重启', 'success');
        else showToast((d && d.error) || '内核重启失败', 'error');
        if (btn) btn.disabled = false;
        loadExtensionsOverview();
    }).catch(function (e) {
        showToast('内核重启失败: ' + e.message, 'error');
        if (btn) btn.disabled = false;
    });
}

function loadDshSkills() {
    var body = document.getElementById('dsh-skill-body');
    var empty = document.getElementById('dsh-skill-empty');
    if (!body) return;
    extFetch('GET', '/api/dsh/skills').then(function (d) {
        var list = (d && d.skills) || [];
        body.innerHTML = list.map(function (s) {
            return '<tr><td>' + extEsc(s.name) + '</td><td>' +
                '<span class="ext-badge off">' + extEsc(s.source || '') + '</span></td><td>' +
                extEsc(s.description || '') + '</td></tr>';
        }).join('');
        if (empty) empty.classList.toggle('hidden', list.length > 0);
    }).catch(function (e) {
        body.innerHTML = '<tr><td colspan="3">加载失败: ' + extEsc(e.message) + '</td></tr>';
    });
}
